def _parse_accounting_cell(value):
    """Parse a small accounting-table cell; dashes/percentages/currency-only cells are ignored."""
    raw = _clean_text(value)
    if not raw or raw in {"—", "–", "-", "$", "€", "£", "n/a", "N/A"}:
        return None
    if "%" in raw:
        return None
    raw = raw.replace("$", "").replace("€", "").replace("£", "").replace(",", "").strip()
    neg = raw.startswith("(") and raw.endswith(")")
    if neg:
        raw = raw[1:-1].strip()
    # Keep this deliberately strict so dates, years and prose are not accepted.
    if not re.fullmatch(r"-?\d+(?:\.\d+)?", raw):
        return None
    try:
        val = float(raw)
    except Exception:
        return None
    return -abs(val) if neg else val


def _html_table_grid(table):
    """Expand a HTML table into a rectangular text grid while honoring basic colspan/rowspan."""
    rows = []
    pending = {}  # col -> [remaining_rows, text]
    max_cols = 0
    for tr in table.find_all("tr"):
        row = []
        col = 0
        cells = tr.find_all(["th", "td"], recursive=False)
        if not cells:
            cells = tr.find_all(["th", "td"])
        for cell in cells:
            while col in pending:
                remaining, value = pending[col]
                row.append(value)
                if remaining <= 1:
                    pending.pop(col, None)
                else:
                    pending[col] = [remaining - 1, value]
                col += 1
            value = _clean_text(cell.get_text(" ", strip=True))
            try:
                colspan = max(1, int(cell.get("colspan") or 1))
            except Exception:
                colspan = 1
            try:
                rowspan = max(1, int(cell.get("rowspan") or 1))
            except Exception:
                rowspan = 1
            for offset in range(colspan):
                row.append(value)
                if rowspan > 1:
                    pending[col + offset] = [rowspan - 1, value]
            col += colspan
        while col in pending:
            remaining, value = pending[col]
            row.append(value)
            if remaining <= 1:
                pending.pop(col, None)
            else:
                pending[col] = [remaining - 1, value]
            col += 1
        max_cols = max(max_cols, len(row))
        rows.append(row)
    for row in rows:
        row.extend([""] * (max_cols - len(row)))
    return rows


def _match_adjustment_rule(row_label):
    low = _clean_text(row_label).lower()
    if not low:
        return None
    for rule in ADJUSTMENT_REVIEW_RULES:
        for pattern in rule.get("patterns") or []:
            if pattern.lower() in low:
                return rule
    return None


def _bridge_row_label(row):
    """Build a conservative row label from cells before the first numeric accounting value."""
    parts = []
    for c, cell in enumerate(row or []):
        if c > 0 and _parse_accounting_cell(cell) is not None:
            break
        cell = _clean_text(cell)
        if cell and not re.fullmatch(r"[$€£—–-]+", cell):
            parts.append(cell)
    return _clean_text(" ".join(dict.fromkeys(parts)))


def _eps_row_kind(label):
    """Return 'gaap', 'adjusted' or None for EPS bridge boundary rows."""
    low = _clean_text(label).lower()
    if not low:
        return None
    eps_signal = any(x in low for x in [
        "earnings per diluted share", "loss per diluted share", "diluted earnings per share",
        "diluted loss per share", "diluted eps",
    ])
    if not eps_signal:
        return None
    if "adjusted" in low or "non-gaap" in low or "non gaap" in low:
        return "adjusted"
    # Rows that merely describe the EPS impact of an adjustment are not the GAAP baseline.
    if any(x in low for x in [
        "non-comparable", "noncomparable", "impact on", "effect on", "adjustment",
        "excluding", "exclude", "restructuring", "impairment", "acquisition", "divestiture",
    ]):
        return None
    return "gaap"


def _accounting_value_for_target_col(row, headers, col, target_year):
    """Read one per-share value from a selected target-year column, allowing split currency cells."""
    if col < len(row):
        value = _parse_accounting_cell(row[col])
        if value is not None and abs(value) < 100:
            return value
    if (
        col + 1 < len(row)
        and col + 1 < len(headers)
        and str(target_year) in headers[col + 1]
    ):
        value = _parse_accounting_cell(row[col + 1])
        if value is not None and abs(value) < 100:
            return value
    return None


def _bridge_value_matches(observed, expected):
    observed = safe_float(observed)
    expected = safe_float(expected)
    if observed is None or expected is None:
        return False
    return abs(observed - expected) <= max(0.08, abs(expected) * 0.035)


def _extract_adjustment_components_from_html(html, target_year=None, bridge_values=None):
    """
    V2.20.32 Bridge Component Evidence Gate.

    A row is accepted as an EPS adjustment component only when it lies inside the
    same target-year GAAP-to-adjusted EPS reconciliation bounded by a GAAP EPS row
    and an adjusted EPS row. When validated bridge values are available, those
    boundary values must numerically match the already validated bridge.

    Text mentions elsewhere in the release are deliberately excluded here and are
    handled separately as context hints. This prevents guidance, margin bridges,
    acquisition notes or spin-off prose from becoming EPS adjustments by proximity.
    """
    if not html or target_year is None:
        return []
    try:
        soup = BeautifulSoup(html, "html.parser")
    except Exception:
        return []

    target_year = int(target_year)
    bridge = bridge_values if isinstance(bridge_values, dict) else {}
    expected_gaap = safe_float(bridge.get("gaap_eps"))
    expected_adjusted = safe_float(bridge.get("adjusted_eps"))
    best_components = []
    best_score = -1

    for table in soup.find_all("table"):
        table_text = _clean_text(table.get_text(" ", strip=True))
        low_table = table_text.lower()
        if "adjusted" not in low_table:
            continue
        if not any(x in low_table for x in ["earnings per diluted share", "loss per diluted share", "diluted eps"]):
            continue
        if "non-comparable" not in low_table and "noncomparable" not in low_table:
            continue

        grid = _html_table_grid(table)
        if len(grid) < 3:
            continue

        # Header rows end at the first true GAAP/adjusted EPS boundary row.
        data_start = None
        row_labels = []
        for i, row in enumerate(grid):
            label = _bridge_row_label(row)
            row_labels.append(label)
            if _eps_row_kind(label) in {"gaap", "adjusted"}:
                data_start = i
                break
        if data_start is None or data_start <= 0:
            continue

        header_rows = grid[:data_start]
        col_count = max(len(r) for r in grid)
        headers = []
        for col in range(col_count):
            parts = []
            for hr in header_rows:
                if col >= len(hr):
                    continue
                val = _clean_text(hr[col])
                if val and val not in parts:
                    parts.append(val)
            headers.append(" | ".join(parts))

        year_cols = []
        for col, header in enumerate(headers):
            if col == 0:
                continue
            h = header.lower()
            if str(target_year) not in h:
                continue
            full_year_signal = any(x in h for x in [
                "year ended", "twelve months", "full year", "fiscal year", "year-end",
            ])
            quarterly_signal = any(x in h for x in [
                "three months", "quarter", "six months", "nine months",
            ])
            score = 20 + (80 if full_year_signal else 0) - (50 if quarterly_signal and not full_year_signal else 0)
            year_cols.append((score, col, header))
        if not year_cols:
            for col, header in enumerate(headers):
                if col and re.search(rf"\b{target_year}\b", header):
                    year_cols.append((10, col, header))
        if not year_cols:
            continue

        max_col_score = max(s for s, _, _ in year_cols)
        candidate_cols = [c for s, c, _ in year_cols if s == max_col_score]

        # Build labels for all rows now that header handling is known.
        row_labels = [_bridge_row_label(row) for row in grid]
        gaap_rows = [i for i, label in enumerate(row_labels) if _eps_row_kind(label) == "gaap"]
        adjusted_rows = [i for i, label in enumerate(row_labels) if _eps_row_kind(label) == "adjusted"]
        if not gaap_rows or not adjusted_rows:
            continue

        best_bounds = None
        best_bounds_score = -10_000
        for col in candidate_cols:
            for gi in gaap_rows:
                gval = _accounting_value_for_target_col(grid[gi], headers, col, target_year)
                if gval is None:
                    continue
                for ai in adjusted_rows:
                    if ai <= gi:
                        continue
                    aval = _accounting_value_for_target_col(grid[ai], headers, col, target_year)
                    if aval is None:
                        continue
                    score = max_col_score
                    # Strongest protection: both EPS boundaries match the already validated bridge.
                    if expected_gaap is not None and expected_adjusted is not None:
                        if not (_bridge_value_matches(gval, expected_gaap) and _bridge_value_matches(aval, expected_adjusted)):
                            continue
                        score += 250
                    else:
                        # Without external bridge values, require a plausible non-zero bridge.
                        if abs(aval - gval) < 0.01:
                            continue
                        score += 40
                    # Prefer compact reconciliation blocks over very long mixed-purpose tables.
                    score -= max(0, ai - gi - 12) * 4
                    if score > best_bounds_score:
                        best_bounds_score = score
                        best_bounds = (gi, ai, col, gval, aval)
        if best_bounds is None:
            continue

        gaap_i, adjusted_i, selected_col, observed_gaap, observed_adjusted = best_bounds
        components = []
        for row in grid[gaap_i + 1:adjusted_i]:
            label = _bridge_row_label(row)
            rule = _match_adjustment_rule(label)
            if not rule:
                continue
            value = _accounting_value_for_target_col(row, headers, selected_col, target_year)
            if value is None or abs(value) <= 1e-9:
                continue
            components.append({
                "label": rule["label"],
                "bucket": rule["bucket"],
                "severity": rule["severity"],
                "note": rule["note"],
                "reported_eps_effect": value,
                "evidence_excerpt": label[:420],
                "evidence_type": "quantitativ bestätigte EPS-Reconciliation-Tabelle",
                "evidence_level": "Quantitativ bestätigte Bridge-Komponente",
                "structured": True,
                "bridge_component_confirmed": True,
                "bridge_bounds_validated": True,
                "bridge_gaap_observed": observed_gaap,
                "bridge_adjusted_observed": observed_adjusted,
            })

        # Deduplicate labels, preserving the first row within the validated bridge segment.
        unique = {}
        for comp in components:
            label = comp.get("label")
            if label and label not in unique:
                unique[label] = comp
        components = list(unique.values())

        # A table may have a valid bridge with zero recognized categories. Keep searching
        # for another table, but never manufacture text-only components here.
        table_score = best_bounds_score + len(components) * 10
        if table_score > best_score:
            best_score = table_score
            best_components = components

    return best_components

def _adjustment_context_is_concrete(text, match_start, match_end):
    """Reject pure non-GAAP definitions; require a concrete amount/action/period/table context."""
    t = _clean_text(text)
    context = t[max(0, match_start - 260):min(len(t), match_end + 420)]
    low = context.lower()

    definition_only = any(x in low for x in [
        "defines adjusted", "defined as", "adjusted to eliminate", "non-gaap financial measures",
        "may include", "can include", "for comparison with", "most directly comparable",
    ])
    concrete = any(x in low for x in [
        "recorded", "recognized", "incurred", "included", "excluded", "non-comparable items:",
        "noncomparable items:", "net losses per diluted share", "net gains per diluted share",
        "year ended", "twelve months ended", "three months ended",
    ])
    has_money = bool(re.search(r"(?:\$|€|£)\s*\(?-?\d", context))
    has_number_row = bool(re.search(r"\b\(?-?\d+(?:\.\d+)?\)?\s+\(?-?\d+(?:\.\d+)?\)?\b", context))
    has_period = bool(re.search(r"\b(?:20\d{2}|q[1-4]|full[-\s]?year|fiscal year|twelve months)\b", context, re.I))

    if definition_only and not (concrete and (has_money or has_number_row or has_period)):
        return False
    return bool(concrete or has_money or (has_number_row and has_period))


def _build_adjustment_recurrence_review(text, bridge_values=None, structured_components=None):
    """
    V2.20.32 conservative evidence review.

    Only quantitatively confirmed rows from the validated GAAP-to-adjusted EPS
    reconciliation are allowed into ``components``. Concrete text mentions are
    retained separately as ``context_hints`` and can never drive EPS normalization,
    recurrence classification or Fair-Value release.
    """
    t = _clean_text(text)
    bridge = bridge_values if isinstance(bridge_values, dict) else {}
    period = bridge.get("period")
    if not t or not bridge:
        return None

    components = []
    confirmed_labels = set()
    for comp in (structured_components or []):
        label = _clean_text(comp.get("label"))
        if not label or label in confirmed_labels or not comp.get("bridge_component_confirmed"):
            continue
        confirmed_labels.add(label)
        clean_comp = dict(comp)
        clean_comp["evidence_level"] = "Quantitativ bestätigte Bridge-Komponente"
        components.append(clean_comp)

    context_hints = []
    context_seen = set()
    for rule in ADJUSTMENT_REVIEW_RULES:
        if rule["label"] in confirmed_labels:
            continue
        matched_context = None
        for pattern in rule["patterns"]:
            for m in re.finditer(re.escape(pattern), t, flags=re.I):
                if _adjustment_context_is_concrete(t, m.start(), m.end()):
                    matched_context = t[max(0, m.start() - 240):min(len(t), m.end() + 520)]
                    break
            if matched_context:
                break
        if not matched_context or rule["label"] in context_seen:
            continue
        context_seen.add(rule["label"])
        context_hints.append({
            "label": rule["label"],
            "bucket": rule["bucket"],
            "severity": rule["severity"],
            "note": rule["note"],
            "evidence_excerpt": _clean_text(matched_context)[:420],
            "evidence_type": "Kontext-Hinweis",
            "evidence_level": "Kontext-Hinweis – nicht Bestandteil der EPS-Brücke bestätigt",
            "structured": False,
            "bridge_component_confirmed": False,
        })

    gaap = safe_float(bridge.get("gaap_eps"))
    adjusted = safe_float(bridge.get("adjusted_eps"))
    noncomp = safe_float(bridge.get("noncomparable_per_share"))
    gap = (adjusted - gaap) if gaap is not None and adjusted is not None else None
    total_reconciled = False
    if gap is not None and noncomp is not None:
        total_reconciled = abs(gap - noncomp) <= max(0.03, abs(noncomp) * 0.03)

    structured_values = [
        safe_float(c.get("reported_eps_effect"))
        for c in components
        if c.get("bridge_component_confirmed") and safe_float(c.get("reported_eps_effect")) is not None
    ]
    structured_component_sum = sum(structured_values) if structured_values else None
    structured_sum_reconciles = False
    if gap is not None and structured_component_sum is not None:
        structured_sum_reconciles = abs(abs(structured_component_sum) - abs(gap)) <= max(0.05, abs(gap) * 0.08)

    risk_components = [c for c in components if c["severity"] >= 3]
    unclear_components = [c for c in components if "Unklar" in c["bucket"]]
    event_components = [c for c in components if c["severity"] <= 2]

    if not components:
        status = "EPS-Brückenkomponenten noch nicht quantitativ bestätigt"
        level = "Rot"
        if context_hints:
            summary = (
                "Die Gesamt-EPS-Brücke ist vorhanden und es gibt konkrete Ereignis-/Bereinigungshinweise im Bericht. "
                "Diese Hinweise sind jedoch nicht quantitativ als Bestandteil derselben GAAP→Adjusted-EPS-Reconciliation "
                "bestätigt und dürfen deshalb die Gewinnnormalisierung nicht beeinflussen."
            )
        else:
            summary = (
                "Die Gesamt-EPS-Brücke ist vorhanden, aber einzelne Bereinigungsposten konnten nicht quantitativ "
                "innerhalb derselben EPS-Reconciliation bestätigt werden."
            )
    elif risk_components or unclear_components:
        status = "Quantitativ bestätigte Brückenkomponenten – Wiederkehrungsrisiko offen"
        level = "Gelb"
        summary = (
            "Mindestens eine Einzelkomponente ist quantitativ derselben GAAP→Adjusted-EPS-Brücke zugeordnet. "
            "Mindestens ein bestätigter Posten kann jedoch wiederkehren oder ist nicht eindeutig als einmalig belegbar."
        )
    else:
        status = "Quantitativ bestätigte Brückenkomponenten – Mehrjahresbestätigung offen"
        level = "Gelb"
        summary = (
            "Die bestätigten EPS-Brückenkomponenten wirken überwiegend ereignisbezogen. Eine automatische "
            "Normalisierung erfolgt trotzdem erst nach Mehrjahres- und Wiederholungsprüfung."
        )

    return {
        "period": period,
        "status": status,
        "status_level": level,
        "summary": summary,
        "components": components,
        "component_count": len(components),
        "confirmed_component_count": len(components),
        "context_hints": context_hints,
        "context_hint_count": len(context_hints),
        "event_related_count": len(event_components),
        "recurrence_risk_count": len(risk_components),
        "unclear_count": len(unclear_components),
        "bridge_gap": gap,
        "noncomparable_per_share": noncomp,
        "total_bridge_reconciled": total_reconciled,
        "structured_component_sum": structured_component_sum,
        "structured_sum_reconciles": structured_sum_reconciles,
        "structured_component_count": len(structured_values),
        "normalization_release": False,
        "next_step": (
            "Nur quantitativ bestätigte EPS-Brückenkomponenten werden historisch auf Wiederholung geprüft. "
            "Kontext-Hinweise bleiben separat und dürfen keinen normalisierten EPS-Wert verändern."
        ),
    }



# =========================================================
# V2.20.19 – Historische Wiederkehrbarkeits-Prüfung
# =========================================================

HISTORICAL_RECURRENCE_YEARS = 3


def _fy_year_from_period(period):
    m = re.search(r"\bFY\s*(20\d{2})\b", _clean_text(period), flags=re.I)
    return int(m.group(1)) if m else None


def _bridge_gap_value(bridge):
    bridge = bridge if isinstance(bridge, dict) else {}
    gaap = safe_float(bridge.get("gaap_eps"))
    adjusted = safe_float(bridge.get("adjusted_eps"))
    if gaap is None or adjusted is None:
        return None
    return adjusted - gaap


def _bridge_has_material_adjustment(bridge):
    bridge = bridge if isinstance(bridge, dict) else {}
    adjusted = safe_float(bridge.get("adjusted_eps"))
    gap = _bridge_gap_value(bridge)
    if gap is None:
        return False
    threshold = max(0.05, abs(adjusted or 0.0) * 0.02)
    return gap > threshold


def _parse_sitemap_locs(xml_text):
    """Return <loc> entries from a sitemap or sitemap index without assuming one XML namespace."""
    xml_text = str(xml_text or "")
    if not xml_text.strip():
        return []
    out = []
    try:
        root = ET.fromstring(xml_text)
        for node in root.iter():
            tag = str(node.tag or "").lower()
            if tag.endswith("}loc") or tag == "loc":
                value = _clean_text(node.text)
                if value.startswith(("http://", "https://")):
                    out.append(value)
    except Exception:
        # Fail-soft fallback for slightly malformed XML.
        for m in re.finditer(r"<loc[^>]*>(.*?)</loc>", xml_text, flags=re.I | re.S):
            value = _clean_text(re.sub(r"<!\[CDATA\[(.*?)\]\]>", r"\1", m.group(1), flags=re.S))
            if value.startswith(("http://", "https://")):
                out.append(value)
    return list(dict.fromkeys(out))


def _historical_title_hint_from_url(url):
    """Turn a press-release slug into a title-like hint for period validation."""
    try:
        path = unquote(urlparse(url).path or "")
        slug = path.rstrip("/").split("/")[-1]
    except Exception:
        slug = _clean_text(url)
    slug = re.sub(r"[-_]+", " ", slug)
    return _clean_text(slug)


def _historical_candidate_score(url, year):
    """Score same-company URLs for a requested FY; exact full-year result slugs dominate."""
    raw = unquote(_clean_text(url)).lower()
    words = re.sub(r"[-_/]+", " ", raw)
    y = str(int(year))
    score = 0

    # The target fiscal year must actually appear in the URL/slug. Publication
    # year alone is not enough because annual results are often released in Y+1.
    if y not in words:
        return -1000
    score += 18

    if re.search(rf"\bfull\s+year\s+{re.escape(y)}\b", words):
        score += 120
    if re.search(rf"\breports?\s+(?:full\s+year\s+)?{re.escape(y)}\s+results\b", words):
        score += 120
    if re.search(rf"\b{re.escape(y)}\s+(?:full\s+year|annual)\s+results\b", words):
        score += 100
    if any(k in words for k in ["annual results", "year end results", "full year", "earnings"]):
        score += 35
    if "results" in words:
        score += 20
    if any(k in words for k in ["press release", "press releases", "newsroom", "investor"]):
        score += 10

    # A pure quarterly release is not the desired historical cycle anchor.
    if re.search(r"\b(?:first|second|third)\s+quarter\b|\bq[123]\b", words) and "full year" not in words:
        score -= 80
    if any(k in words for k in ["career", "privacy", "sustainability", "product", "supplier"]):
        score -= 30
    return score


def _discover_company_sitemap_inventory(company_domain, deadline=None, max_child_sitemaps=4):
    """
    V2.20.20 primary-source recovery.

    Read the company's own sitemap before using a general search engine. A
    sitemap is especially useful for older press releases that are no longer on
    the first newsroom page. Only same-domain URLs are returned.
    """
    if not company_domain or not _research_budget_ok(deadline, reserve=1.2):
        return [], []

    root = _router_root(company_domain) or f"https://{company_domain}"
    sitemap_seeds = [
        urljoin(root + "/", "sitemap.xml"),
        urljoin(root + "/", "sitemap_index.xml"),
        urljoin(root + "/", "sitemap-index.xml"),
    ]
    tried = []
    direct_urls = []
    child_sitemaps = []

    for seed in sitemap_seeds:
        if not _research_budget_ok(deadline, reserve=1.0):
            break
        tried.append(seed)
        xml_text, final_url = _fetch_html(seed, timeout=2.2, deadline=deadline)
        if not xml_text:
            continue
        locs = _parse_sitemap_locs(xml_text)
        if not locs:
            continue
        for loc in locs:
            host = _normalize_host(loc)
            if not _host_belongs_to_company_family(host, company_domain):
                continue
            if re.search(r"(?:\.xml|\.xml\.gz)(?:$|\?)", loc, flags=re.I):
                child_sitemaps.append(loc)
            else:
                direct_urls.append(loc)
        # A valid root sitemap is enough; do not burn budget on alternate names.
        if direct_urls or child_sitemaps:
            break

    if child_sitemaps and _research_budget_ok(deadline, reserve=1.0):
        def child_score(url):
            hay = url.lower()
            score = 0
            for kw in ["press", "news", "investor", "page", "content", "post"]:
                if kw in hay:
                    score += 10
            return score

        for child in sorted(dict.fromkeys(child_sitemaps), key=child_score, reverse=True)[:max_child_sitemaps]:
            if not _research_budget_ok(deadline, reserve=0.8):
                break
            tried.append(child)
            xml_text, _ = _fetch_html(child, timeout=2.2, deadline=deadline)
            if not xml_text:
                continue
            for loc in _parse_sitemap_locs(xml_text):
                if _host_belongs_to_company_family(loc, company_domain) and not re.search(r"\.xml(?:$|\?)", loc, flags=re.I):
                    direct_urls.append(loc)

    return list(dict.fromkeys(direct_urls))[:30000], tried


def _historical_sitemap_candidates(company_domain, target_years, deadline=None, per_year=5):
    urls, sitemap_sources = _discover_company_sitemap_inventory(
        company_domain,
        deadline=deadline,
        max_child_sitemaps=4,
    )
    by_year = {int(y): [] for y in target_years}
    for url in urls:
        for year in target_years:
            score = _historical_candidate_score(url, year)
            if score <= 0:
                continue
            by_year[int(year)].append({
                "title": _historical_title_hint_from_url(url),
                "url": url,
                "snippet": "Unternehmens-Sitemap / historisches IR-Archiv",
                "search_source": "Unternehmens-Sitemap",
                "historical_recovery_method": "Unternehmens-Sitemap/IR-Archiv",
                "historical_candidate_score": score,
            })
    for year in by_year:
        by_year[year].sort(key=lambda x: x.get("historical_candidate_score", 0), reverse=True)
        by_year[year] = by_year[year][:int(per_year)]
    return by_year, sitemap_sources


def _historical_row_from_candidate(item, company_domain, company_name, year, deadline=None):
    url = _clean_text(item.get("url"))
    if not url or not _host_belongs_to_company_family(url, company_domain):
        return None
    if not _research_budget_ok(deadline, reserve=0.7):
        return None

    page_html = item.get("preloaded_html") or ""
    page_text = item.get("preloaded_text") or ""
    if not page_text:
        page_html, _ = _fetch_html(
            url,
            timeout=2.5,
            sec="sec.gov" in _normalize_host(url),
            deadline=deadline,
        )
        page_text = _html_to_text(page_html)
    if not page_text:
        return None

    title = item.get("title") or _historical_title_hint_from_url(url)
    combined = " ".join([
        title,
        item.get("snippet") or "",
        page_text[:140_000],
    ])
    if not _source_matches_company(
        item,
        page_text,
        company_name,
        "",
        company_domain,
        True,
    ):
        return None
    bridge = _extract_eps_bridge_values(combined, title=title)
    if not bridge or _fy_year_from_period(bridge.get("period")) != int(year):
        return None

    return {
        "year": int(year),
        "title": title or url,
        "url": url,
        "primary_source": True,
        "eps_bridge_values": bridge,
        "adjustment_recurrence_review": _build_adjustment_recurrence_review(
            combined,
            bridge,
            structured_components=_extract_adjustment_components_from_html(page_html, int(year), bridge_values=bridge),
        ),
        "historical_recovery_method": item.get("historical_recovery_method") or item.get("search_source") or "Unternehmensquelle",
    }




