def build_eps_result(
    normalized_eps,
    method,
    confidence,
    cycle_basis,
    trailing_eps,
    forward_eps,
    metadata=None
):
    adjusted_confidence, confidence_note, deviation = (
        apply_eps_confidence_brake(
            confidence,
            trailing_eps,
            forward_eps
        )
    )

    result = {
        "normalized_eps": normalized_eps,
        "method": method,
        "confidence": adjusted_confidence,
        "cycle_basis": cycle_basis,
        "confidence_note": confidence_note,
        "ttm_forward_deviation": deviation
    }

    if isinstance(metadata, dict):
        result.update(metadata)

    return result


def has_usable_positive_earnings_basis(
    eps_normalization
):
    if not isinstance(
        eps_normalization,
        dict
    ):
        return False

    if bool(eps_normalization.get("valuation_blocked", False)):
        return False

    normalized_eps = safe_float(
        eps_normalization.get(
            "normalized_eps"
        )
    )

    return (
        normalized_eps is not None
        and normalized_eps > 0
    )


# =========================================================
# Modul 5 – Multiple Score: Wachstum
# =========================================================

def growth_points(value):
    value = safe_float(value)

    if value is None:
        return None

    if value >= 0.20:
        return 15

    if value >= 0.15:
        return 13

    if value >= 0.10:
        return 11

    if value >= 0.05:
        return 8

    if value >= 0.00:
        return 5

    if value >= -0.05:
        return 2

    return 0


def calculate_growth_score(
    revenue_growth,
    earnings_growth,
    profit_margin=None,
    eps_normalization=None,
):
    """V2.20.74 – Yahoo growth score with a downside-only quality gate."""
    rev = safe_float(revenue_growth)
    earn = safe_float(earnings_growth)
    margin = safe_float(profit_margin)

    raw_revenue_points = growth_points(rev)
    raw_earnings_points = growth_points(earn)
    revenue_points = raw_revenue_points
    earnings_points = raw_earnings_points
    quality_notes = []

    # Isolated huge earnings growth is often a base/one-off effect. It may not
    # receive 15/15 automatically when sales do not corroborate it.
    if earn is not None and earn >= 0.50 and earnings_points is not None:
        if rev is not None and rev < 0.0:
            earnings_points = min(earnings_points, 5)
            quality_notes.append(
                "extremes Gewinnwachstum bei rückläufigem Umsatz: Gewinnwachstum auf 5/15 begrenzt"
            )
        elif rev is None or rev < 0.10:
            earnings_points = min(earnings_points, 8)
            quality_notes.append(
                "extremes Gewinnwachstum ohne zweistelliges Umsatzwachstum: Gewinnwachstum auf 8/15 begrenzt"
            )

    # Very high reported sales growth with a near-zero margin can reflect
    # pass-through/commodity/transaction volume rather than value growth.
    if (
        rev is not None and rev >= 0.50
        and margin is not None and margin < 0.03
        and revenue_points is not None
    ):
        revenue_points = min(revenue_points, 5)
        quality_notes.append(
            "extremes Umsatzwachstum bei Nettomarge unter 3 %: Umsatzwachstum auf 5/15 begrenzt"
        )

    available = [p for p in [revenue_points, earnings_points] if p is not None]
    if not available:
        return {
            "score": None, "revenue_points": None, "earnings_points": None,
            "raw_revenue_points": raw_revenue_points, "raw_earnings_points": raw_earnings_points,
            "confidence": "Niedrig", "quality_gate_active": False,
            "note": "Keine ausreichenden Wachstumsdaten verfügbar."
        }

    score = sum(available)
    confidence = "Hoch" if len(available) == 2 else "Mittel"
    if quality_notes:
        confidence = "Mittel"
        note = "Growth Quality Gate aktiv: " + "; ".join(quality_notes) + "."
    elif len(available) == 2:
        note = "Umsatz- und Gewinnwachstum vollständig berücksichtigt."
    else:
        note = (
            "Nur eine Wachstumskennzahl verfügbar. Es werden nur die tatsächlich "
            "belegten Punkte vergeben; fehlende Daten werden nicht hochgerechnet."
        )

    if isinstance(eps_normalization, dict) and eps_normalization.get("valuation_blocked"):
        confidence = "Niedrig"
        note += " Die Earnings-Basis ist parallel durch das Comparability Gate für die Bewertung gesperrt."

    return {
        "score": score,
        "revenue_points": revenue_points,
        "earnings_points": earnings_points,
        "raw_revenue_points": raw_revenue_points,
        "raw_earnings_points": raw_earnings_points,
        "confidence": confidence,
        "quality_gate_active": bool(quality_notes),
        "quality_gate_notes": quality_notes,
        "note": note
    }


# =========================================================
# Modul 5 – Multiple Score: Profitabilität
# =========================================================

def profitability_margin_points(
    company_type,
    profit_margin
):
    margin = safe_float(profit_margin)

    if margin is None:
        return None

    type_name = str(
        company_type.get("type", "")
    ).lower()

    if (
        "bank" in type_name
        or "versicherung" in type_name
        or "reit" in type_name
        or "immobilien" in type_name
        or "biotechnologie" in type_name
        or "closed-loop payments & consumer credit" in type_name
    ):
        return None

    if "software" in type_name:
        thresholds = [
            (0.30, 15),
            (0.20, 13),
            (0.12, 10),
            (0.07, 7),
            (0.00, 4)
        ]

    elif "halbleiter" in type_name:
        thresholds = [
            (0.30, 15),
            (0.22, 13),
            (0.15, 10),
            (0.08, 7),
            (0.00, 4)
        ]

    elif (
        "defensiver konsum" in type_name
        or "pharma" in type_name
    ):
        thresholds = [
            (0.20, 15),
            (0.15, 13),
            (0.10, 10),
            (0.06, 7),
            (0.00, 4)
        ]

    elif "zyklisch" in type_name:
        thresholds = [
            (0.12, 15),
            (0.08, 13),
            (0.05, 10),
            (0.03, 7),
            (0.00, 4)
        ]

    else:
        thresholds = [
            (0.15, 15),
            (0.10, 13),
            (0.07, 10),
            (0.04, 7),
            (0.00, 4)
        ]

    for threshold, points in thresholds:
        if margin >= threshold:
            return points

    return 0


def profitability_roe_points(
    company_type,
    roe
):
    roe_value = safe_float(roe)

    if roe_value is None:
        return None

    type_name = str(
        company_type.get("type", "")
    ).lower()

    if (
        "bank" in type_name
        or "versicherung" in type_name
        or "reit" in type_name
        or "immobilien" in type_name
        or "biotechnologie" in type_name
        or "closed-loop payments & consumer credit" in type_name
    ):
        return None

    if "zyklisch" in type_name:
        thresholds = [
            (0.25, 15),
            (0.18, 13),
            (0.12, 10),
            (0.08, 7),
            (0.00, 4)
        ]
    else:
        thresholds = [
            (0.30, 15),
            (0.22, 13),
            (0.15, 10),
            (0.10, 7),
            (0.00, 4)
        ]

    for threshold, points in thresholds:
        if roe_value >= threshold:
            return points

    return 0


def calculate_profitability_score(
    company_type,
    profit_margin,
    roe,
    earnings_growth
):
    margin_points = profitability_margin_points(
        company_type,
        profit_margin
    )

    roe_points = profitability_roe_points(
        company_type,
        roe
    )

    type_name = str(
        company_type.get("type", "")
    ).lower()

    special_model = (
        is_universal_family_fail_closed(company_type)
        or "bank" in type_name
        or "versicherung" in type_name
        or "reit" in type_name
        or "immobilien" in type_name
        or "biotechnologie" in type_name
        or "closed-loop payments & consumer credit" in type_name
    )

    if special_model:
        special_text = (
            (
                f"Universal Family Router {APP_BUILD_VERSION}: Für die freigegebene Bewertungsfamilie {company_type.get('valuation_family') or company_type.get('type')} wird die generische Margen-/ROE-Profitabilitätslogik bewusst nicht verwendet; das Holding-NAV-Spezialmodell ist maßgeblich."
                if is_released_listed_holding_family(company_type)
                else f"Universal Family Router {APP_BUILD_VERSION}: Für die Bewertungsfamilie {company_type.get('valuation_family') or company_type.get('type')} wird die generische Margen-/ROE-Profitabilitätslogik nicht verwendet. Das Familienmodell ist noch nicht freigegeben."
            )
            if is_universal_family_fail_closed(company_type)
            else (
                "Bei Banken wird die generische Margen-/ROE-Profitabilitätslogik nicht verwendet. "
                "Die Ertragskraft wird im Bank-Score über normalisierten ROTCE und Ertragsqualität bewertet."
                if "bank" in type_name
                else (
                "Bei American Express wird die generische Margen-/ROE-Profitabilitätslogik nicht verwendet. "
                "ROE/ROCE, CET1 und Kreditqualität werden im Closed-Loop-Spezialscore bewertet."
                if "closed-loop payments & consumer credit" in type_name
                else (
                    "Für diesen Unternehmenstyp wird später "
                    "eine eigene Profitabilitätslogik verwendet."
                )
            )
        )
        )
        return {
            "score": None,
            "raw_score": None,
            "margin_points": None,
            "roe_points": None,
            "confidence": "Sondermodell",
            "brake_active": False,
            "brake_text": special_text
        }

    available = [
        points
        for points in [
            margin_points,
            roe_points
        ]
        if points is not None
    ]

    if not available:
        return {
            "score": None,
            "raw_score": None,
            "margin_points": None,
            "roe_points": None,
            "confidence": "Niedrig",
            "brake_active": False,
            "brake_text": (
                "Keine ausreichenden Profitabilitätsdaten verfügbar."
            )
        }

    if len(available) == 2:
        raw_score = (
            margin_points +
            roe_points
        )
        confidence = "Hoch"
    else:
        raw_score = available[0]
        confidence = "Mittel"

    score = raw_score
    brake_active = False
    brake_text = (
        "Keine Verschlechterungsbremse aktiv."
    )

    growth = safe_float(
        earnings_growth
    )

    if growth is None:
        if confidence == "Hoch":
            confidence = "Mittel"

        brake_text = (
            "Gewinnentwicklung nicht verfügbar; "
            "Verschlechterungsbremse konnte nicht geprüft werden."
        )

    elif growth <= -0.30:
        limit = 18
        score = min(
            score,
            limit
        )
        brake_active = (
            score < raw_score
        )

        if brake_active:
            brake_text = (
                f"Starker Gewinnrückgang von "
                f"{growth * 100:.1f} % erkannt. "
                f"Die Verschlechterungsbremse begrenzt "
                f"den Profitabilitäts-Score auf "
                f"maximal {limit}/30 Punkte."
            )
        else:
            brake_text = (
                f"Starker Gewinnrückgang von "
                f"{growth * 100:.1f} % erkannt. "
                f"Der aktuelle Profitabilitäts-Score "
                f"von {raw_score}/30 liegt bereits "
                f"unter der Obergrenze von "
                f"{limit}/30 – keine weitere Kürzung."
            )

    elif growth <= -0.15:
        limit = 22
        score = min(
            score,
            limit
        )
        brake_active = (
            score < raw_score
        )

        if brake_active:
            brake_text = (
                f"Deutlicher Gewinnrückgang von "
                f"{growth * 100:.1f} % erkannt. "
                f"Die Verschlechterungsbremse begrenzt "
                f"den Profitabilitäts-Score auf "
                f"maximal {limit}/30 Punkte."
            )
        else:
            brake_text = (
                f"Deutlicher Gewinnrückgang von "
                f"{growth * 100:.1f} % erkannt. "
                f"Der aktuelle Profitabilitäts-Score "
                f"von {raw_score}/30 liegt bereits "
                f"unter der Obergrenze von "
                f"{limit}/30 – keine weitere Kürzung."
            )

    elif growth <= -0.05:
        limit = 26
        score = min(
            score,
            limit
        )
        brake_active = (
            score < raw_score
        )

        if brake_active:
            brake_text = (
                f"Gewinnrückgang von "
                f"{growth * 100:.1f} % erkannt. "
                f"Die Verschlechterungsbremse begrenzt "
                f"den Profitabilitäts-Score auf "
                f"maximal {limit}/30 Punkte."
            )
        else:
            brake_text = (
                f"Gewinnrückgang von "
                f"{growth * 100:.1f} % erkannt. "
                f"Der aktuelle Profitabilitäts-Score "
                f"von {raw_score}/30 liegt bereits "
                f"unter der Obergrenze von "
                f"{limit}/30 – keine weitere Kürzung."
            )

    return {
        "score": score,
        "raw_score": raw_score,
        "margin_points": margin_points,
        "roe_points": roe_points,
        "confidence": confidence,
        "brake_active": brake_active,
        "brake_text": brake_text
    }


