def is_baker_hughes_energy_tech_company_type(company_type):
    type_name = str((company_type or {}).get("type", "")).lower()
    return "energy technology / oilfield services" in type_name


def is_oilfield_services_energy_tech_specialist_type(company_type, symbol=None):
    sym = str(symbol or "").upper().strip()
    type_name = normalized_company_type_name(company_type)
    return sym in {"SLB", "HAL", "FTI"} or "oilfield services / energy technology" in type_name


# =========================================================
# Modul 5 – Multiple Score: Free Cashflow
# =========================================================

def is_special_fcf_model(company_type):
    if is_universal_family_fail_closed(company_type):
        return True

    type_name = str(
        company_type.get("type", "")
    ).lower()

    special_terms = [
        "bank",
        "versicherung",
        "reit",
        "immobilien",
        "autohersteller",
        "midstream",
        "halbleiterausrüstung / lithografie",
        "halbleiter / fabless / ai-wachstum",
        "energy technology / oilfield services",
        "oilfield services / energy technology",
        "edelmetall-handel / distribution & lending",
        "luxury goods / premium franchise",
        "asset manager / investment management",
        "credit bureau / data & analytics",
        "healthcare / diagnostics & research / cro + data",
        "agriculture / seeds & crop protection",
        "advertising / marketing services",
        "consumer / specialty retail",
        "consumer / toys & entertainment",
        "consumer / athletic apparel & footwear / turnaround",
        "solar manufacturing / high-growth / policy-sensitive",
        "specialty materials / specialty chemicals",
        "payment network / capital-light payments",
        "closed-loop payments & consumer credit",
        "versorger"
    ]

    return any(
        term in type_name
        for term in special_terms
    )


def fcf_margin_points(fcf_margin):
    margin = safe_float(fcf_margin)

    if margin is None:
        return None

    if margin >= 0.20:
        return 25
    if margin >= 0.15:
        return 22
    if margin >= 0.10:
        return 19
    if margin >= 0.07:
        return 16
    if margin >= 0.04:
        return 13
    if margin >= 0.00:
        return 9
    if margin >= -0.05:
        return 4

    return 0


def calculate_fcf_score(
    company_type,
    revenue,
    current_fcf,
    historical_fcf,
    net_income=None,
    fcf_source_context=None,
):
    if is_special_fcf_model(company_type):
        return {
            "score": None,
            "raw_score": None,
            "fcf_margin": None,
            "confidence": "Sondermodell",
            "status": "special",
            "note": (
                "Für diesen Unternehmenstyp wird der normale "
                "Yahoo-Free-Cashflow bewusst nicht bewertet. "
                "Hier ist später eine eigene Cashflow-Logik nötig."
            )
        }

    revenue_value = safe_float(revenue)
    fcf_value = safe_float(current_fcf)

    if revenue_value is None or revenue_value <= 0 or fcf_value is None:
        return {
            "score": None,
            "raw_score": None,
            "fcf_margin": None,
            "confidence": "Niedrig",
            "status": "missing",
            "note": "Keine ausreichenden aktuellen Daten für den FCF-Score verfügbar."
        }

    fcf_margin = fcf_value / revenue_value
    raw_score = fcf_margin_points(fcf_margin)
    score = raw_score

    history = []
    if historical_fcf:
        source_values = (
            list(historical_fcf.values())
            if isinstance(historical_fcf, dict)
            else list(historical_fcf)
        )

        for item in source_values:
            if isinstance(item, dict):
                value = item.get("value")
            else:
                value = item

            number = safe_float(value)

            if number is not None:
                history.append(number)

    if len(history) >= 3:
        confidence = "Hoch"
    elif len(history) >= 1:
        confidence = "Mittel"
    else:
        confidence = "Niedrig"

    if fcf_margin < 0:
        status = "negative"
        note = (
            "⚠️ Aktueller Free Cashflow ist negativ. "
            "Die FCF-Punkte bleiben ausschließlich von der aktuellen "
            "FCF-Marge abhängig; historische Werte erhöhen den Score nicht."
        )
    else:
        status = "normal"
        note = (
            "Aktuelle FCF-Marge bestimmt die Ausgangspunkte. "
            "Die Mehrjahreswerte dienen als Stabilitäts- und Trendkontrolle."
        )

    type_name = str(company_type.get("type", "")).lower()
    is_cyclical = (
        "zyklisch" in type_name
        or "rohstoffe" in type_name
        or "lithium" in type_name
        or "öl" in type_name
        or "gas" in type_name
        or "bergbau" in type_name
    )

    if len(history) >= 2:
        positive_years = sum(1 for value in history if value > 0)
        negative_years = sum(1 for value in history if value < 0)

        if is_cyclical and positive_years >= 1 and negative_years >= 1:
            cycle_limit = 19
            score = min(score, cycle_limit)
            status = "cyclical"
            if score < raw_score:
                note = (
                    "⚠️ Zyklischer FCF: Die historischen Free-Cashflows wechseln "
                    "zwischen positiv und negativ. Die aktuelle Stärke wird daher "
                    f"auf maximal {cycle_limit}/25 Punkte begrenzt."
                )
            else:
                note = (
                    "⚠️ Zyklischer FCF: Die historischen Free-Cashflows wechseln "
                    "zwischen positiv und negativ. Der aktuelle Score liegt bereits "
                    f"unter der Obergrenze von {cycle_limit}/25."
                )
        elif fcf_value < 0 and positive_years >= 2:
            status = "deterioration"
            note = (
                "⚠️ Free Cashflow aktuell negativ, obwohl mehrere historische Jahre "
                "positiv waren. Die guten Vorjahre erhöhen den aktuellen FCF-Score nicht."
            )
        elif fcf_value > 0 and negative_years >= 2:
            status = "recovery"
            note = (
                "↗️ FCF-Erholung erkennbar: Der aktuelle Free Cashflow ist positiv, "
                "nachdem mehrere historische Jahre negativ waren. "
                "Dafür werden keine Zusatzpunkte vergeben."
            )

    # V2.20.74 – Cashflow Quality & Horizon-Proxy Gate. This does not invent
    # forward FCF guidance. It only stops unusually conversion-heavy TTM cash
    # flow from beautifying both FCF quality and leverage.
    net_income_value = safe_float(net_income)
    fcf_to_net_income = None
    quality_reasons = []
    balance_denominator_usable = True

    if fcf_value > 0 and net_income_value is not None:
        if net_income_value > 0:
            fcf_to_net_income = fcf_value / net_income_value
            if fcf_to_net_income >= 4.0:
                score = min(score, 13)
                balance_denominator_usable = False
                quality_reasons.append(
                    f"TTM-FCF liegt bei {fcf_to_net_income:.1f}× Nettogewinn; Working-Capital-/Timing-Qualität muss geklärt werden"
                )
        else:
            score = min(score, 13)
            balance_denominator_usable = False
            quality_reasons.append(
                "positiver TTM-FCF bei nicht positivem Nettogewinn; Turnaround-/Working-Capital-Qualität muss geklärt werden"
            )

    positive_history = [value for value in history if value > 0]
    if fcf_value > 0 and len(positive_history) >= 2:
        median_history = float(pd.Series(positive_history).median())
        if median_history > 0 and fcf_value / median_history >= 3.0:
            score = min(score, 16)
            balance_denominator_usable = False
            quality_reasons.append(
                f"TTM-FCF liegt bei {fcf_value / median_history:.1f}× positivem historischem FCF-Median"
            )

    source_gap = safe_float((fcf_source_context or {}).get("gap_pct"))
    if source_gap is not None and source_gap >= 50.0 and confidence == "Hoch":
        confidence = "Mittel"
        quality_reasons.append(
            f"FCF-Quellenabweichung {source_gap:.1f} %; Cashflow-Qualität bleibt trotz Statement-Priorität unter Beobachtung"
        )

    if quality_reasons:
        status = "quality_gate" if status == "normal" else status
        note = "FCF Quality & Horizon-Proxy Gate: " + "; ".join(quality_reasons) + "."

    return {
        "score": score,
        "raw_score": raw_score,
        "fcf_margin": fcf_margin,
        "confidence": confidence,
        "status": status,
        "note": note,
        "quality_gate_active": bool(quality_reasons),
        "quality_gate_reasons": quality_reasons,
        "fcf_to_net_income": fcf_to_net_income,
        "balance_denominator_usable": balance_denominator_usable,
    }


# =========================================================
# Modul 5 – Multiple Score: Bilanz / Verschuldung
# =========================================================

def is_special_balance_model(company_type):
    if is_universal_family_fail_closed(company_type):
        return True

    type_name = str(
        company_type.get("type", "")
    ).lower()

    special_terms = [
        "bank",
        "versicherung",
        "reit",
        "immobilien",
        "autohersteller",
        "midstream",
        "halbleiterausrüstung / lithografie",
        "halbleiter / fabless / ai-wachstum",
        "energy technology / oilfield services",
        "oilfield services / energy technology",
        "edelmetall-handel / distribution & lending",
        "luxury goods / premium franchise",
        "asset manager / investment management",
        "credit bureau / data & analytics",
        "healthcare / diagnostics & research / cro + data",
        "agriculture / seeds & crop protection",
        "advertising / marketing services",
        "consumer / specialty retail",
        "consumer / toys & entertainment",
        "consumer / athletic apparel & footwear / turnaround",
        "solar manufacturing / high-growth / policy-sensitive",
        "specialty materials / specialty chemicals",
        "payment network / capital-light payments",
        "closed-loop payments & consumer credit",
        "versorger"
    ]

    return any(
        term in type_name
        for term in special_terms
    )


def balance_debt_points(net_debt_to_fcf):
    ratio = safe_float(net_debt_to_fcf)

    if ratio is None:
        return None

    if ratio < 1.0:
        return 14
    if ratio < 1.5:
        return 12
    if ratio < 2.5:
        return 9
    if ratio < 3.5:
        return 6
    if ratio < 4.5:
        return 3

    return 0


def calculate_balance_score(
    company_type,
    cash,
    debt,
    current_fcf,
    historical_fcf
):
    if is_special_balance_model(company_type):
        return {
            "score": None,
            "net_debt": None,
            "net_debt_to_fcf": None,
            "confidence": "Sondermodell",
            "status": "special",
            "note": (
                "Für diesen Unternehmenstyp wird die normale "
                "Netto-Schulden/FCF-Logik bewusst nicht verwendet. "
                "Hier ist später ein eigenes Bilanzmodell nötig."
            )
        }

    cash_value = safe_float(cash)
    debt_value = safe_float(debt)
    fcf_value = safe_float(current_fcf)

    if cash_value is None or debt_value is None:
        return {
            "score": None,
            "net_debt": None,
            "net_debt_to_fcf": None,
            "confidence": "Niedrig",
            "status": "missing",
            "note": (
                "Liquide Mittel oder Gesamtschulden fehlen. "
                "Es werden keine Bilanzpunkte geschätzt."
            )
        }

    net_debt = debt_value - cash_value

    if net_debt <= 0:
        return {
            "score": 15,
            "net_debt": net_debt,
            "net_debt_to_fcf": 0.0,
            "confidence": "Hoch",
            "status": "net_cash",
            "note": (
                "Netto-Cash: Die liquiden Mittel decken die "
                "Gesamtschulden vollständig."
            )
        }

    if fcf_value is None or fcf_value <= 0:
        return {
            "score": None,
            "net_debt": net_debt,
            "net_debt_to_fcf": None,
            "confidence": "Niedrig",
            "status": "fcf_unusable",
            "note": (
                "Nettoschulden sind vorhanden, aber der aktuelle "
                "Free Cashflow ist nicht positiv bzw. nicht verfügbar. "
                "Eine Netto-Schulden/FCF-Kennzahl wäre nicht belastbar."
            )
        }

    ratio = net_debt / fcf_value
    score = balance_debt_points(ratio)

    history = []
    if historical_fcf:
        source_values = (
            list(historical_fcf.values())
            if isinstance(historical_fcf, dict)
            else list(historical_fcf)
        )

        for item in source_values:
            if isinstance(item, dict):
                value = item.get("value")
            else:
                value = item

            number = safe_float(value)
            if number is not None:
                history.append(number)

    if len(history) >= 3:
        confidence = "Hoch"
    elif len(history) >= 1:
        confidence = "Mittel"
    else:
        confidence = "Niedrig"

    type_name = str(
        company_type.get("type", "")
    ).lower()

    is_cyclical = (
        "zyklisch" in type_name
        or "rohstoffe" in type_name
        or "lithium" in type_name
        or "öl" in type_name
        or "gas" in type_name
        or "bergbau" in type_name
    )

    positive_years = sum(
        1 for value in history if value > 0
    )
    negative_years = sum(
        1 for value in history if value < 0
    )

    status = "normal"
    note = (
        "Bilanzpunkte basieren auf Nettoschulden im Verhältnis "
        "zum aktuellen positiven Free Cashflow."
    )

    if (
        is_cyclical
        and positive_years >= 1
        and negative_years >= 1
    ):
        confidence = "Mittel"
        status = "cyclical"
        note = (
            "⚠️ Zyklische Cashflows: Die aktuelle "
            "Netto-Schulden/FCF-Kennzahl ist günstig, "
            "aber historisch nicht durchgehend stabil. "
            "Die Bilanzpunkte werden nicht erhöht; "
            "die Datensicherheit wird auf Mittel begrenzt."
        )

    return {
        "score": score,
        "net_debt": net_debt,
        "net_debt_to_fcf": ratio,
        "confidence": confidence,
        "status": status,
        "note": note
    }


