def _looks_like_listed_investment_holding(industry, business_summary):
    """High-confidence principal-capital holding-company profile.

    Yahoo can label listed investment holdings as Asset Management.  Distinguish
    companies investing their own balance-sheet capital / owning portfolio
    companies from fee-based managers that manage client AUM.  This is a
    reusable business-model rule, not an issuer/ticker exception.
    """
    industry_text = str(industry or "").lower()
    summary_text = str(business_summary or "").lower()
    combined = " ".join([industry_text, summary_text])

    # Strong evidence of a fee/advisory business: keep Asset Management.
    client_manager_terms = [
        "assets under management", " aum ", "investment advisory", "advisory services",
        "investment management services", "management fees", "advisory fees",
        "provides its services to", "client focused", "client-focused", "for its clients",
        "manages separate", "separate accounts", "mutual funds", "institutional clients",
        "retail clients", "fund management", "third-party capital", "third party capital",
    ]
    padded = f" {combined} "
    if any(term in padded for term in client_manager_terms):
        return False

    direct_holding_terms = [
        "listed holding company", "investment holding company", "listed investment company",
        "active ownership", "active owner", "ownership stakes", "portfolio companies",
        "equity portfolio", "own portfolio", "principal investments",
    ]
    if any(term in combined for term in direct_holding_terms):
        return True

    # Common provider wording for Nordic listed holdings (e.g. principal
    # portfolio investors) can misleadingly say "investment manager" even
    # though there is no client-AUM fee business.
    if (
        "publicly owned investment manager" in combined
        and "invests in the public equity markets" in combined
    ):
        return True

    # Listed private-equity / venture holding structures without client-capital
    # management also belong to the principal-capital NAV family.
    if any(term in combined for term in ["private equity firm", "venture capital firm"]):
        if any(term in combined for term in [
            "invests in listed companies", "invests in both listed and unlisted companies",
            "portfolio companies", "ownership stake", "majority or minority investments",
        ]):
            return True

    return False


def _infer_universal_family_from_metadata(symbol, sector, industry, business_summary):
    sym = str(symbol or "").upper().strip()
    sector_text = str(sector or "").lower()
    industry_text = str(industry or "").lower()
    summary_text = str(business_summary or "").lower()
    combined = " ".join([sector_text, industry_text, summary_text])

    if _looks_like_listed_investment_holding(industry_text, summary_text):
        return "listed_investment_holding", "business_summary_rule"

    if sym in UNIVERSAL_SECURITY_FAMILY_MASTER:
        return UNIVERSAL_SECURITY_FAMILY_MASTER[sym], "security_family_master"

    # Financial Services is intentionally conservative: an unidentified lender,
    # broker or payments company must never inherit industrial FCF/net-debt math.
    if "financial" in sector_text:
        if any(x in industry_text for x in ["bank", "banks", "banking"]):
            return "bank", "sector_industry_rule"
        if "asset management" in industry_text or "investment management" in industry_text:
            return "asset_manager", "sector_industry_rule"
        if "insurance" in industry_text:
            return "insurance", "sector_industry_rule"
        if "credit services" in industry_text or "consumer finance" in industry_text:
            lending_terms = [
                "consumer finance", "credit card", "private label", "installment loan", "loan receivable",
                "consumer lending", "consumer banking", "financing products", "deposit products",
            ]
            processor_terms = [
                "merchant acquiring", "payment processing", "payment processor", "payment solutions",
                "checkout", "digital payments", "merchant services",
            ]
            has_lending = any(term in combined for term in lending_terms)
            has_processor = any(term in combined for term in processor_terms)
            if has_lending and not has_processor:
                return "consumer_finance_card", "business_summary_rule"
            if has_processor and not has_lending:
                return "payments_processor", "business_summary_rule"
            return "financial_unresolved", "sector_industry_rule"
        if any(x in industry_text for x in ["financial data", "stock exchanges"]):
            exchange_terms = [
                "exchange operator", "securities exchange", "stock exchange", "options exchange",
                "futures exchange", "derivatives marketplace", "trading venue", "clearinghouse",
                "clearing house", "central counterparty", "market infrastructure", "electronic exchange",
            ]
            data_terms = [
                "credit ratings", "ratings agency", "benchmarks", "indices", "index provider",
                "financial intelligence", "data and analytics", "market intelligence", "risk solutions",
            ]
            has_exchange_economics = any(term in combined for term in exchange_terms)
            has_data_economics = any(term in combined for term in data_terms)
            if has_exchange_economics and not has_data_economics:
                return "exchange_market_infrastructure", "business_summary_rule"
            if has_data_economics and not has_exchange_economics:
                return "credit_data_analytics", "business_summary_rule"
            return "financial_unresolved", "sector_industry_rule"
        if any(x in industry_text for x in ["capital markets", "brokerage"]):
            exchange_terms = [
                "exchange operator", "securities exchange", "stock exchange", "options exchange",
                "futures exchange", "derivatives marketplace", "trading venue", "clearinghouse",
                "clearing house", "market infrastructure",
            ]
            asset_manager_terms = [
                "asset management", "investment management", "assets under management", "aum",
            ]
            if any(term in combined for term in exchange_terms):
                return "exchange_market_infrastructure", "business_summary_rule"
            if any(term in combined for term in asset_manager_terms):
                return "asset_manager", "business_summary_rule"
            return "investment_bank_broker_dealer", "sector_industry_rule"
        if any(x in industry_text for x in ["mortgage finance", "financial conglomerates"]):
            return "financial_unresolved", "sector_industry_rule"
        return "financial_unresolved", "sector_rule"

    if "real estate" in sector_text:
        if "reit" in industry_text:
            return "reit", "sector_industry_rule"
        return "real_estate_services", "sector_rule"

    if "medical devices" in industry_text:
        return "medical_devices", "industry_rule"
    if any(x in industry_text for x in ["medical care facilities", "health information services", "healthcare plans"]):
        return "healthcare_services", "industry_rule"
    if "biotechnology" in industry_text:
        return "biotech", "industry_rule"
    if "drug manufacturers" in industry_text or "pharmaceutical" in industry_text:
        return "pharma", "industry_rule"

    if "semiconductor equipment" in industry_text:
        return "semicap", "industry_rule"
    if "semiconductor" in industry_text:
        return "semiconductors", "industry_rule"
    if "software" in industry_text:
        return "software", "industry_rule"
    if any(x in industry_text for x in ["computer hardware", "information technology services", "communication equipment"]):
        return "it_hardware_services", "industry_rule"

    if "utilities" in sector_text or "utility" in sector_text:
        return "regulated_utility", "sector_rule"
    if "telecom" in combined or "telecommunication" in combined:
        return "telecom", "metadata_rule"
    if "aerospace & defense" in industry_text or "aerospace and defense" in industry_text:
        return "aerospace_defense", "industry_rule"
    if "industrials" in sector_text:
        if any(x in industry_text for x in ["integrated freight", "trucking", "railroads", "air freight", "marine shipping"]):
            return "transport_logistics", "industry_rule"
        return "industrials", "sector_rule"

    if "consumer defensive" in sector_text:
        return "branded_staples", "sector_rule"
    if "consumer cyclical" in sector_text:
        if "specialty retail" in industry_text:
            return "retail", "industry_rule"
        if "luxury" in combined or "apparel" in industry_text or "footwear" in industry_text:
            return "luxury_apparel", "metadata_rule"
        return "general_corporate", "sector_rule"

    if "communication services" in sector_text:
        return "media_internet", "sector_rule"

    return "general_corporate", "fallback"


def _legacy_classification_is_family_overrideable(current_type):
    """Return True when the legacy classifier is generic or explicitly unresolved.

    V2.21.1 family-priority rule: a high-confidence universal family must outrank
    a placeholder such as ``Software / Untertyp noch nicht eindeutig``. Explicit
    released specialist routes remain authoritative and are only enriched.
    """
    text = str(current_type or "").strip().lower()
    if not text:
        return True
    if "standard-unternehmen" in text:
        return True
    unresolved_markers = (
        "untertyp noch nicht eindeutig",
        "untertyp nicht eindeutig",
        "noch nicht eindeutig",
        "nicht eindeutig",
        "unresolved",
    )
    return any(marker in text for marker in unresolved_markers)


def apply_universal_valuation_family_router(base_classification, name, symbol, sector, industry, business_summary=None):
    """Attach a reusable valuation family without disturbing released specialist math.

    Generic Standard-Unternehmen classifications and explicitly unresolved
    legacy placeholders may be re-routed by this architecture layer. Existing
    released specialist types are enriched with family metadata but otherwise
    keep their established valuation path.
    """
    out = dict(base_classification or {})
    name_text = str(name or "").lower()
    current_type = normalized_company_type_name(out)

    existing_family = _infer_universal_family_from_existing_type(out, name_text=name_text)
    listed_holding_profile = _looks_like_listed_investment_holding(industry, business_summary)
    if listed_holding_profile and existing_family == "asset_manager":
        existing_family = None
    if _legacy_classification_is_family_overrideable(current_type):
        # Generic/unresolved legacy labels are not evidence that a released
        # specialist family exists. Let the universal metadata/master route win.
        existing_family = None
    if existing_family:
        family_id, meta = _universal_family_meta(existing_family)
        out.setdefault("valuation_family_id", family_id)
        out.setdefault("valuation_family", meta["label"])
        out.setdefault("family_router_source", "existing_specialist_route")
        out.setdefault("family_policy", meta["policy"])
        out.setdefault("family_model_status", "existing_route")
        out.setdefault("family_model_ready", True)
        out.setdefault("universal_family_fail_closed", False)
        return out

    family_id, source = _infer_universal_family_from_metadata(
        symbol, sector, industry, business_summary
    )
    family_id, meta = _universal_family_meta(family_id)
    out["valuation_family_id"] = family_id
    out["valuation_family"] = meta["label"]
    out["family_router_source"] = source
    out["family_policy"] = meta["policy"]

    # V2.21.1: Family priority is authoritative over generic/unresolved legacy
    # placeholders. Only an explicit released specialist route is allowed to
    # remain ahead of the universal family. This prevents an issuer such as
    # Block (XYZ) from being tagged Payments Processor while still executing
    # the old ambiguous Software route.
    legacy_overrideable = _legacy_classification_is_family_overrideable(current_type)
    if family_id == "listed_investment_holding" and listed_holding_profile:
        # High-confidence business-model contradiction: Yahoo industry can call
        # principal-capital listed holdings "Asset Management".  Allow the
        # universal family layer to override that generic legacy classification.
        legacy_overrideable = True
    if not legacy_overrideable:
        out["family_model_status"] = "existing_route"
        out["family_model_ready"] = True
        out["universal_family_fail_closed"] = False
        return out

    if meta["policy"] == "specialist":
        out["type"] = meta["label"]
        out["method"] = (
            f"Universal Family Router: {meta['label']} erkannt; familiengerechte Kennzahlen/Anker erforderlich. "
            "Generischer Standard-Score, Yahoo-FCF/Net-Debt-to-FCF und Standard-KGV sind bis zur Freigabe des Familienmodells gesperrt."
        )
        if family_id == "listed_investment_holding":
            out["method"] = (
                "Primary-source NAV je Aktie + aktueller Kurs/NAV-Premium-Discount + Holding-Leverage + "
                "Portfolio-Konzentrationsdiagnose; NAV-Primärdatenmodell aktiv, Ziel-Premium/Discount und Fair Value werden ausschließlich über das Holding-Spezialmodell freigegeben"
            )
            out["business_model"] = (
                "Börsennotierte Investment-/Holdinggesellschaft, die eigenes Kapital in Beteiligungen investiert; "
                "kein fee-basiertes Client-AUM-Geschäft"
            )
            out["core_segments"] = (
                "Börsennotierte Beteiligungen · Active Ownership · Holding-Level Net Debt/Liquidity · Kapitalallokation"
            )
            out["focus_areas"] = (
                "NAV je Aktie · Kurs/NAV Premium/Discount · Portfolioqualität/-konzentration · "
                "Holdingkosten · Netto-Verschuldung/Geared Capital · Kapitalallokation · Dividenden"
            )
        out["confidence_cap"] = "Niedrig bis Mittel"
        if family_id == "listed_investment_holding":
            # V92: the reusable holding family is released, but the industrial
            # standard path remains intentionally isolated. The legacy-named
            # fail_closed flag is retained as an internal standard-path lock;
            # issuer-level NAV/evidence gates still decide whether valuation is usable.
            out["family_model_status"] = "released_specialist"
            out["family_model_ready"] = True
            out["family_model_released"] = True
            out["universal_family_fail_closed"] = True
        else:
            out["family_model_status"] = "defined_unreleased"
            out["family_model_ready"] = False
            out["family_model_released"] = False
            out["universal_family_fail_closed"] = True
        out["business_model"] = out.get("business_model") or (
            "Geschäftsmodell wurde einer wiederverwendbaren Bewertungsfamilie zugeordnet; "
            "issuer-spezifische Overrides sind nur noch für echte Sonderfälle vorgesehen."
        )
        out["focus_areas"] = out.get("focus_areas") or (
            "Familienkennzahlen statt industrieller Standard-FCF-/Net-Debt-Logik; "
            "Primärdaten-/Comparability-Gate vor Fair Value"
        )
    else:
        # Generic compatibility is permitted for an actual Standard-Unternehmen.
        # An unresolved legacy type plus only a broad fallback is not enough
        # evidence to unlock industrial valuation math.
        unresolved_legacy = (
            "standard-unternehmen" not in current_type
            and _legacy_classification_is_family_overrideable(current_type)
        )
        if unresolved_legacy and source == "fallback":
            out["family_model_status"] = "classification_unresolved"
            out["family_model_ready"] = False
            out["universal_family_fail_closed"] = True
            out["method"] = (
                "Universal Family Router: Bewertungsfamilie noch nicht ausreichend sicher bestimmt; "
                "generischer Standard-Score und Fair Value bleiben bis zur belastbaren Familienzuordnung gesperrt."
            )
            out["confidence_cap"] = "Niedrig"
        else:
            out["family_model_status"] = "generic_compatible"
            out["family_model_ready"] = True
            out["universal_family_fail_closed"] = False

    return out


def is_universal_family_fail_closed(company_type):
    return bool((company_type or {}).get("universal_family_fail_closed"))


def is_released_listed_holding_family(company_type):
    return bool(
        is_listed_investment_holding_type(company_type)
        and (company_type or {}).get("family_model_status") == "released_specialist"
        and (company_type or {}).get("family_model_ready")
    )


def is_listed_investment_holding_type(company_type):
    family_id = str((company_type or {}).get("valuation_family_id") or "").strip().lower()
    type_name = str((company_type or {}).get("type") or "").strip().lower()
    return family_id == "listed_investment_holding" or "listed investment / holding company" in type_name


_HOLDING_MONTHS = {
    "january": 1, "jan": 1, "januari": 1,
    "february": 2, "feb": 2, "februari": 2,
    "march": 3, "mar": 3, "mars": 3,
    "april": 4, "apr": 4,
    "may": 5, "maj": 5,
    "june": 6, "jun": 6, "juni": 6,
    "july": 7, "jul": 7, "juli": 7,
    "august": 8, "aug": 8, "augusti": 8,
    "september": 9, "sep": 9, "sept": 9,
    "october": 10, "oct": 10, "oktober": 10, "okt": 10,
    "november": 11, "nov": 11,
    "december": 12, "dec": 12,
}


def _holding_parse_date_text(value):
    text = _clean_text(value)
    if not text:
        return None
    text = text.replace("\u00a0", " ")
    iso = re.search(r"\b(20\d{2})[-/.](\d{1,2})[-/.](\d{1,2})(?=$|[T\s])", text)
    if iso:
        try:
            return datetime(int(iso.group(1)), int(iso.group(2)), int(iso.group(3))).date()
        except Exception:
            pass
    m = re.search(r"\b([A-Za-zÅÄÖåäö]+\.?)\s+(\d{1,2}),?\s+(20\d{2})\b", text)
    if m:
        month = _HOLDING_MONTHS.get(m.group(1).lower().rstrip("."))
        if month:
            try:
                return datetime(int(m.group(3)), month, int(m.group(2))).date()
            except Exception:
                pass
    m = re.search(r"\b(\d{1,2})\s+([A-Za-zÅÄÖåäö]+\.?)\s+(20\d{2})\b", text)
    if m:
        month = _HOLDING_MONTHS.get(m.group(2).lower().rstrip("."))
        if month:
            try:
                return datetime(int(m.group(3)), month, int(m.group(1))).date()
            except Exception:
                pass
    return None



def _holding_nav_asof_hint_from_release(url=None, label=None):
    """Extract the NAV *as-of* date from release semantics, not archive publication date.

    A press-release archive row may begin with its publication date and then carry
    a title such as "Net asset value on August 31, 2026".  Generic first-date
    parsing would therefore return Sep 1, 2026.  Historical NAV pairing must bind
    to the date governed by the NAV wording itself.
    """
    raw_values = [label, url]
    patterns = [
        r"(?:net\s+asset\s+value|\bnav\b)\s+(?:as\s+of|on|at)\s+([A-Za-zÅÄÖåäö]+\s+\d{1,2},?\s+20\d{2})",
        r"(?:net\s+asset\s+value|\bnav\b)\s+(?:as\s+of|on|at)\s+(\d{1,2}\s+[A-Za-zÅÄÖåäö]+\s+20\d{2})",
        r"substansv[aä]rd(?:e|et)?\s*(?:per(?:\s+den)?|den|p[aå])?\s*(\d{1,2}\s+[A-Za-zÅÄÖåäö]+\s+20\d{2})",
        r"substansv[aä]rd(?:e|et)?\s*(?:per(?:\s+den)?|den|p[aå])?\s*([A-Za-zÅÄÖåäö]+\s+\d{1,2},?\s+20\d{2})",
    ]
    for raw in raw_values:
        if not raw:
            continue
        text = unquote(str(raw))
        text = text.replace("-", " " ).replace("_", " " ).replace("/", " " )
        text = unicodedata.normalize("NFKC", _clean_text(text) or "")
        for pat in patterns:
            m = re.search(pat, text, flags=re.I)
            if not m:
                continue
            dt = _holding_parse_date_text(m.group(1))
            if dt:
                return dt
    return None

def _holding_date_display(value):
    if hasattr(value, "strftime"):
        return value.strftime("%d.%m.%Y")
    parsed = _holding_parse_date_text(value)
    return parsed.strftime("%d.%m.%Y") if parsed else None


def _holding_same_issuer_url(url, company_domain):
    try:
        host = _normalize_host(url)
    except Exception:
        host = None
    return bool(host and company_domain and _host_belongs_to_company_family(host, company_domain))


def _holding_structured_publication_date(soup):
    if soup is None:
        return None
    candidates = []
    for attrs in [
        {"property": "article:published_time"}, {"name": "date"},
        {"name": "datePublished"}, {"itemprop": "datePublished"},
    ]:
        node = soup.find(attrs=attrs)
        if node:
            candidates.append(node.get("content") or node.get_text(" ", strip=True))
    for node in soup.find_all("time", limit=4):
        candidates.append(node.get("datetime") or node.get_text(" ", strip=True))
    for value in candidates:
        parsed = _holding_parse_date_text(value)
        if parsed:
            return parsed
    return None


def _holding_publication_date_fallback(text, as_of_date=None):
    text = _clean_text(text) or ""
    dates = []
    patterns = [
        r"([A-Za-zÅÄÖåäö]+\.?\s+\d{1,2},?\s+20\d{2})",
        r"(\d{1,2}\s+[A-Za-zÅÄÖåäö]+\.?\s+20\d{2})",
    ]
    for pat in patterns:
        for m in re.finditer(pat, text[:1800]):
            dt = _holding_parse_date_text(m.group(1))
            if dt and dt not in dates:
                dates.append(dt)
    if not dates:
        return None
    if as_of_date:
        plausible = [d for d in dates if d >= as_of_date and (d - as_of_date).days <= 60]
        later = [d for d in plausible if d > as_of_date]
        if later:
            return min(later)
        if plausible:
            return max(plausible)
    return min(dates)


def _holding_extract_nav_record(html, url, expected_as_of_date=None):
    if not html:
        return None

    expected_date_obj = None
    if expected_as_of_date is not None:
        if all(hasattr(expected_as_of_date, attr) for attr in ("year", "month", "day")):
            try:
                expected_date_obj = expected_as_of_date if not hasattr(expected_as_of_date, "date") else expected_as_of_date.date()
            except Exception:
                expected_date_obj = expected_as_of_date
        else:
            expected_date_obj = _holding_parse_date_text(expected_as_of_date)

    try:
        soup = BeautifulSoup(html, "html.parser")
        # V67: dated historical releases are parsed from the issuer article/main
        # content when such a semantic container exists.  This excludes page
        # title/navigation/current-NAV widgets before candidate ranking.
        content_scope = soup
        if expected_date_obj is not None:
            content_scope = (
                soup.find("article")
                or soup.find("main")
                or soup.find(attrs={"role": "main"})
                or soup.body
                or soup
            )
        strings = [_clean_text(x).replace("\u00a0", " ") for x in content_scope.stripped_strings]
        text = _clean_text(" ".join(strings)).replace("\u00a0", " ")
        # V58: normalize CMS/Unicode separators that are invisible in the UI but
        # can break an otherwise obvious "SEK 532 per share" regex match.
        text = unicodedata.normalize("NFKC", text)
        text = re.sub(r"[\u200b\u200c\u200d\u2060\ufeff\u00ad]", "", text)
        text = _clean_text(text)
    except Exception:
        return None
    low = text.lower()
    # V58: CMS pages often split "Net asset value", currency/value and
    # "per share" across several DOM nodes. Work on the flattened visible DOM
    # text and accept English/Swedish labels without relying on node adjacency.
    label_re = r"net(?:[\W_]+)asset(?:[\W_]+)value|substansv[aä]rd(?:e|et)|\bnav\b"
    label_positions = [m.start() for m in re.finditer(label_re, low, flags=re.I)]
    if not label_positions:
        return None

    def _value_from_window(window):
        window = unicodedata.normalize("NFKC", window or "")
        window = re.sub(r"[\u200b\u200c\u200d\u2060\ufeff\u00ad]", "", window)
        patterns = [
            # V60 uses the same punctuation-tolerant label contract as the
            # diagnostic probe. CMS markup may flatten to e.g. "Net | asset | value".
            rf"(?:{label_re}).{{0,500}}?(?:was|is|var|är|:)?[^A-Za-z0-9]{{0,50}}(?:SEK|EUR|USD|GBP|kr|kronor)[^0-9]{{0,80}}([0-9]{{1,6}}(?:[.,][0-9]{{1,2}})?).{{0,220}}?(?:per\s+(?:share|aktie))",
            r"(?:SEK|EUR|USD|GBP|kr|kronor)[^0-9]{0,80}([0-9]{1,6}(?:[.,][0-9]{1,2})?).{0,220}?(?:per\s+(?:share|aktie))",
            r"([0-9]{1,6}(?:[.,][0-9]{1,2})?)[^A-Za-z0-9]{0,50}(?:SEK|EUR|USD|GBP|kr|kronor).{0,220}?(?:per\s+(?:share|aktie))",
            rf"(?:{label_re}).{{0,500}}?([0-9]{{1,6}}(?:[.,][0-9]{{1,2}})?).{{0,220}}?(?:per\s+(?:share|aktie))",
        ]
        for pat in patterns:
            m = re.search(pat, window, flags=re.I | re.S)
            if not m:
                continue
            try:
                value = float(m.group(1).replace(" ", "").replace(",", "."))
            except Exception:
                value = None
            if value is not None and 1.0 <= value <= 100000.0:
                token = m.group(0)
                cm = re.search(r"\b(SEK|EUR|USD|GBP)\b", token, flags=re.I)
                currency = cm.group(1).upper() if cm else ("SEK" if re.search(r"\bkr\b|kronor", token, flags=re.I) else None)
                return value, currency

        # V60 local-evidence fallback: anchor on "per share/per aktie" first,
        # then choose the nearest currency/value pair immediately before it.
        # A NAV label must occur in the same short prefix, preventing unrelated
        # stock-price or contact numbers elsewhere on the page from qualifying.
        for pm in re.finditer(r"per\s+(?:share|aktie)", window, flags=re.I):
            ctx_start = max(0, pm.start() - 420)
            prefix = window[ctx_start:pm.start()]
            if not re.search(label_re, prefix, flags=re.I):
                continue
            local_candidates = []
            for cm in re.finditer(r"\b(SEK|EUR|USD|GBP|kr|kronor)\b[^0-9]{0,35}([0-9]{1,6}(?:[.,][0-9]{1,2})?)", prefix, flags=re.I):
                local_candidates.append((cm.end(), cm.group(2), cm.group(1)))
            for vm in re.finditer(r"([0-9]{1,6}(?:[.,][0-9]{1,2})?)[^A-Za-z0-9]{0,35}\b(SEK|EUR|USD|GBP|kr|kronor)\b", prefix, flags=re.I):
                local_candidates.append((vm.end(), vm.group(1), vm.group(2)))
            if local_candidates:
                _, raw_value, raw_currency = max(local_candidates, key=lambda x: x[0])
                try:
                    value = float(raw_value.replace(",", "."))
                except Exception:
                    value = None
                if value is not None and 1.0 <= value <= 100000.0:
                    cur = raw_currency.upper()
                    if cur.lower() in {"kr", "kronor"}:
                        cur = "SEK"
                    return value, cur

        # V60 bounded token fallback. This is intentionally not a generic
        # "first number after NAV" rule: a currency token AND per-share wording
        # must surround the candidate inside the same local evidence window.
        folded = window.lower()
        per_share_spans = [(m.start(), m.end()) for m in re.finditer(r"per\s+(?:share|aktie)", folded, flags=re.I)]
        if per_share_spans:
            currency_re = re.compile(r"\b(SEK|EUR|USD|GBP|kr|kronor)\b", flags=re.I)
            number_re = re.compile(r"(?<![0-9])([0-9]{1,6}(?:[.,][0-9]{1,2})?)(?![0-9])")
            label_spans = [(m.start(), m.end()) for m in re.finditer(label_re, folded, flags=re.I)]
            candidates = []
            for cm in currency_re.finditer(window):
                # Currency before value (SEK ... 532).
                tail = window[cm.end(): min(len(window), cm.end() + 180)]
                nm = number_re.search(tail)
                if nm:
                    nstart = cm.end() + nm.start(1)
                    nend = cm.end() + nm.end(1)
                    if any(-40 <= ps - nend <= 280 for ps, _ in per_share_spans) and any(-900 <= ls - nstart <= 0 for ls, _ in label_spans):
                        candidates.append((nstart, nm.group(1), cm.group(1)))
                # Value before currency (532 ... SEK).
                head_start = max(0, cm.start() - 180)
                head = window[head_start:cm.start()]
                nums = list(number_re.finditer(head))
                if nums:
                    nm = nums[-1]
                    nstart = head_start + nm.start(1)
                    nend = head_start + nm.end(1)
                    if any(-40 <= ps - nend <= 320 for ps, _ in per_share_spans) and any(-900 <= ls - nstart <= 0 for ls, _ in label_spans):
                        candidates.append((nstart, nm.group(1), cm.group(1)))
            for _, raw_value, raw_currency in sorted(candidates, key=lambda x: x[0]):
                try:
                    value = float(raw_value.replace(",", "."))
                except Exception:
                    continue
                if 1.0 <= value <= 100000.0:
                    cur = raw_currency.upper()
                    if cur.lower() in {"kr", "kronor"}:
                        cur = "SEK"
                    return value, cur
        return None, None

    best = None
    title_text = _clean_text(soup.title.get_text(" ", strip=True)) if soup.title else ""
    h1 = soup.find("h1")
    h1_text = _clean_text(h1.get_text(" ", strip=True)) if h1 else ""
    url_text = str(url or "").replace("-", " ").replace("_", " ").replace("/", " ")
    # V61: do not trust DOM order. CMS templates may place dozens of NAV
    # archive/navigation labels before the actual release body. Evaluate every
    # bounded label window; only windows that independently contain a valid
    # NAV value + currency + per-share relationship can become records.
    for pos in label_positions:
        # Historical issuer releases are deliberately parsed in a tighter local
        # window.  Date context may look slightly backward, but NAV VALUE
        # extraction starts at this exact label so an earlier current-NAV widget
        # cannot leak its number into an older article candidate.
        forward_span = 1200 if expected_date_obj is not None else 2400
        window = text[max(0, pos - 260): min(len(text), pos + forward_span)]
        value_window = (
            text[pos: min(len(text), pos + 1000)]
            if expected_date_obj is not None
            else window
        )
        nav, currency = _value_from_window(value_window)
        if nav is None:
            continue

        # V67: Bind the NAV fact to dates immediately surrounding THIS exact
        # NAV label, not to any later date elsewhere in the same window.  This
        # rejects a newer global NAV widget on an older historical article.
        date_patterns = [
            rf"(?:{label_re})\s+on\s+([A-Za-zÅÄÖåäö]+\s+\d{{1,2}},?\s+20\d{{2}})",
            r"per share\s+on\s+([A-Za-zÅÄÖåäö]+\s+\d{1,2},?\s+20\d{2})",
            rf"(?:{label_re}).*?on\s+(\d{{1,2}}\s+[A-Za-zÅÄÖåäö]+\s+20\d{{2}})",
            r"substansv[aä]rd(?:e|et).*?den\s+(\d{1,2}\s+[A-Za-zÅÄÖåäö]+\s+20\d{2})",
            r"per aktie(?:\s+den)?\s+(\d{1,2}\s+[A-Za-zÅÄÖåäö]+\s+20\d{2})",
            rf"on\s+([A-Za-zÅÄÖåäö]+\s+\d{{1,2}},?\s+20\d{{2}}).{{0,90}}?(?:{label_re})",
            rf"(?:den\s+)?(\d{{1,2}}\s+[A-Za-zÅÄÖåäö]+\s+20\d{{2}}).{{0,90}}?(?:{label_re})",
            rf"(?:{label_re}).{{0,80}}?([A-Za-zÅÄÖåäö]+\s+\d{{1,2}},?\s+20\d{{2}})",
        ]

        tight_start = max(0, pos - 180)
        tight_date_context = text[tight_start: min(len(text), pos + 320)]
        label_offset = pos - tight_start
        tight_date_hits = []
        for generic_pat in [
            r"([A-Za-zÅÄÖåäö]+\s+\d{1,2},?\s+20\d{2})",
            r"(\d{1,2}\s+[A-Za-zÅÄÖåäö]+\s+20\d{2})",
        ]:
            for dm in re.finditer(generic_pat, tight_date_context, flags=re.I):
                dt = _holding_parse_date_text(dm.group(1))
                if not dt:
                    continue
                if dm.end() <= label_offset:
                    distance = label_offset - dm.end()
                elif dm.start() >= label_offset:
                    distance = dm.start() - label_offset
                else:
                    distance = 0
                tight_date_hits.append((distance, dm.start(), dt))
        tight_date_hits.sort(key=lambda x: (x[0], x[1]))
        nearest_tight_date = tight_date_hits[0][2] if tight_date_hits else None

        if expected_date_obj is not None and nearest_tight_date is not None and nearest_tight_date != expected_date_obj:
            continue

        local_as_of = nearest_tight_date

        # Preserve the broader legacy date recovery only for non-historical
        # discovery. Historical article parsing is intentionally stricter.
        if local_as_of is None and expected_date_obj is None:
            for pat in date_patterns:
                m = re.search(pat, window, flags=re.I | re.S)
                if m:
                    local_as_of = _holding_parse_date_text(m.group(1))
                    if local_as_of:
                        break

        as_of = local_as_of
        if as_of is None:
            for source in [h1_text, title_text, url_text]:
                if not source:
                    continue
                for pat in date_patterns:
                    m = re.search(pat, source, flags=re.I | re.S)
                    if m:
                        as_of = _holding_parse_date_text(m.group(1))
                        if as_of:
                            break
                if as_of:
                    break

        if expected_date_obj is not None:
            # If the exact NAV label had no local date, the concrete dated
            # release URL/title can supply it; any explicit conflicting local
            # date was already rejected above.
            as_of = expected_date_obj

        published = _holding_structured_publication_date(soup)
        if published is None:
            fallback_published = _holding_publication_date_fallback(text, as_of)
            if fallback_published is not None and (as_of is None or fallback_published > as_of):
                published = fallback_published

        score = 3 + (2 if as_of else 0) + (1 if currency else 0) + (1 if published else 0)
        if expected_date_obj is not None and as_of == expected_date_obj:
            score += 8
        closing_prices = {}
        price_scan_text = (
            text[pos: min(len(text), pos + 1800)]
            if expected_date_obj is not None
            else text
        )
        # V66: Scan the full visible page and normalize language-specific
        # share-class wording into the same {"A": price, "C": price} map.
        # The archive can expose English releases ("Class C shares") or
        # Swedish releases ("C-aktien").  Values remain issuer-primary only.
        class_pattern_specs = [
            (r"(?:SEK|EUR|USD|GBP|kr|kronor)\s*([0-9]{1,5}(?:[.,][0-9]{1,2})?)\s+for\s+(?:the\s+)?Class\s+([A-Z])\s+shares?", "value_class"),
            (r"Class\s+([A-Z])\s+shares?.{0,55}?(?:SEK|EUR|USD|GBP|kr|kronor)\s*([0-9]{1,5}(?:[.,][0-9]{1,2})?)", "class_value"),
            (r"([0-9]{1,5}(?:[.,][0-9]{1,2})?)\s*(?:SEK|kr|kronor)\s+f[oö]r\s+([A-Z])\s*[-–—]?\s*aktien", "value_class"),
            (r"([0-9]{1,5}(?:[.,][0-9]{1,2})?)\s*(?:SEK|kr|kronor)\s+f[oö]r\s+(?:aktie(?:n)?\s+av\s+)?(?:klass|serie)\s+([A-Z])", "value_class"),
            (r"\b([A-Z])\s*[-–—]?\s*aktien\b.{0,55}?([0-9]{1,5}(?:[.,][0-9]{1,2})?)\s*(?:SEK|kr|kronor)", "class_value"),
        ]
        for pat, order in class_pattern_specs:
            for match in re.findall(pat, price_scan_text, flags=re.I | re.S):
                try:
                    if order == "value_class":
                        value, cls = match
                    else:
                        cls, value = match
                    cls_key = str(cls).upper().strip()
                    parsed_value = float(str(value).replace(" ", "").replace(",", "."))
                    if cls_key and parsed_value > 0 and cls_key not in closing_prices:
                        closing_prices[cls_key] = parsed_value
                except Exception:
                    pass

        paired_price_date = None
        for ppat in [
            r"closing\s+price\s+on\s+([A-Za-zÅÄÖåäö]+\s+\d{1,2},?\s+20\d{2})",
            r"st[aä]ngningskurs(?:en)?(?:\s+den)?\s+(\d{1,2}\s+[A-Za-zÅÄÖåäö]+\s+20\d{2})",
        ]:
            pm = re.search(ppat, price_scan_text, flags=re.I | re.S)
            if pm:
                paired_price_date = _holding_parse_date_text(pm.group(1))
                if paired_price_date:
                    break

        rec = {
            "nav_per_share": nav,
            "currency": currency,
            "as_of_date_obj": as_of,
            "as_of_date": _holding_date_display(as_of),
            "published_date_obj": published,
            "published_date": _holding_date_display(published),
            "source_url": url,
            "source_title": title_text or h1_text or None,
            "same_date_class_prices": closing_prices,
            "paired_price_date_obj": paired_price_date,
            "paired_price_date": _holding_date_display(paired_price_date),
            "quality": score,
        }
        if best is None or (rec["quality"], rec["as_of_date_obj"] or datetime(1900,1,1).date()) > (best["quality"], best["as_of_date_obj"] or datetime(1900,1,1).date()):
            best = rec
    return best



def _holding_extract_peer_nav_record(html, url):
    """Strict NAV/share extractor for peer and live current holding evidence.

    V84 hardens semantic adjacency. A generic ``per share`` occurrence is not
    enough: the nearest NAV label must belong to the same local metric phrase.
    This prevents an unrelated ``earnings per share`` row from binding a nearby
    consolidated profit figure to an earlier NAV label. Linearized report rows
    with footnote markers remain supported.
    """
    if not html:
        return None
    try:
        soup = BeautifulSoup(html, "html.parser")
        strings = [_clean_text(x).replace("\u00a0", " ") for x in soup.stripped_strings]
        text = unicodedata.normalize("NFKC", _clean_text(" ".join(strings)))
        text = re.sub(r"[\u200b\u200c\u200d\u2060\ufeff\u00ad]", "", text)
    except Exception:
        return None

    label_re = r"(?:adjusted\s+)?net(?:[\W_]+)asset(?:[\W_]+)value|substansv[aä]rd(?:e|et)|\bnav\b"
    per_share_label_re = rf"(?:{label_re}).{{0,90}}?(?:per\s+(?:share|aktie)|/\s*(?:share|aktie))"
    unrelated_metric_re = r"\b(?:earnings?|eps|profit|loss|dividend|share\s+price|market\s+capitali[sz]ation)\b"
    # Never allow a regex to reinterpret a thousands-formatted token such as
    # 117,290 as 117.29 merely because the final zero falls outside the match.
    num_token = r"([0-9]{1,5}(?:[.,][0-9]{1,2})?)(?![0-9.,])"

    def _num(raw):
        raw = _clean_text(raw).replace(" ", "")
        if re.search(r"[.,]\d{3,}$", raw):
            return None
        try:
            return float(raw.replace(",", "."))
        except Exception:
            return None

    def _currency(raw):
        cur = str(raw or "").upper()
        return "SEK" if cur.lower() in {"kr", "kronor"} else cur

    def _exact_dates(fragment):
        hits = []
        for pat in [
            r"\b(20\d{2}[-/.]\d{1,2}[-/.]\d{1,2})\b",
            r"([A-Za-zÅÄÖåäö]+\.?\s+\d{1,2},?\s+20\d{2})",
            r"(\d{1,2}\s+[A-Za-zÅÄÖåäö]+\.?\s+20\d{2})",
        ]:
            for m in re.finditer(pat, fragment or "", flags=re.I):
                dt = _holding_parse_date_text(m.group(1))
                if dt:
                    hits.append((m.start(), dt))
        # Common PDF table header form: 6/30 2026, 3/31 2026, ...
        for m in re.finditer(r"\b(\d{1,2})/(\d{1,2})\s+(20\d{2})\b", fragment or ""):
            try:
                dt = datetime(int(m.group(3)), int(m.group(1)), int(m.group(2))).date()
            except Exception:
                continue
            hits.append((m.start(), dt))
        return hits

    def _quarter_end(raw):
        m = re.search(r"\bQ([1-4])\s*[/\- ]\s*(20\d{2})\b", str(raw or ""), flags=re.I)
        if not m:
            return None
        q, y = int(m.group(1)), int(m.group(2))
        month_day = {1:(3,31), 2:(6,30), 3:(9,30), 4:(12,31)}[q]
        try:
            return datetime(y, month_day[0], month_day[1]).date()
        except Exception:
            return None

    def _adjusted_bonus(fragment):
        return 2 if re.search(r"\badjusted\s+(?:net\s+asset\s+value|nav)\b", fragment or "", flags=re.I) else 0

    candidates = []

    # 1) Narrative/card form, e.g. “Adjusted net asset value ... (SEK 397 per share)”.
    # The NAV label must be in the same compact phrase as the per-share anchor.
    for pm in re.finditer(r"(?:per\s+(?:share|aktie)|/\s*(?:share|aktie))", text, flags=re.I):
        start = max(0, pm.start() - 190)
        prefix = text[start:pm.start()]
        labels = list(re.finditer(label_re, prefix, flags=re.I))
        if not labels:
            continue
        last_label = labels[-1]
        local_phrase = prefix[last_label.start():]
        if len(local_phrase) > 155:
            continue
        after_label = local_phrase[last_label.end() - last_label.start():]
        if re.search(unrelated_metric_re, after_label, flags=re.I):
            continue

        local = []
        for m in re.finditer(rf"\b(SEK|EUR|USD|GBP|kr|kronor)\b\s*{num_token}", local_phrase, flags=re.I):
            local.append((m.end(), _num(m.group(2)), _currency(m.group(1))))
        for m in re.finditer(rf"{num_token}\s*\b(SEK|EUR|USD|GBP|kr|kronor)\b", local_phrase, flags=re.I):
            local.append((m.end(), _num(m.group(1)), _currency(m.group(2))))
        local = [x for x in local if x[1] is not None and 1.0 <= x[1] <= 10000.0]
        if not local:
            continue
        _, nav, cur = max(local, key=lambda x: x[0])
        ctx_start = max(0, start - 120)
        ctx_end = min(len(text), pm.end() + 220)
        ctx = text[ctx_start:ctx_end]
        dates = _exact_dates(ctx)
        as_of = None
        if dates:
            fact_pos = pm.start() - ctx_start
            as_of = min(dates, key=lambda x: abs(x[0] - fact_pos))[1]
        candidates.append({
            "nav_per_share": nav, "currency": cur, "as_of_date_obj": as_of,
            "semantic_guard": "nav_label_adjacent_explicit_per_share_v84",
            "quality": 11 + _adjusted_bonus(local_phrase) + (2 if as_of else 0),
        })

    # 2) Linearized report/text row, e.g. “Adjusted NAV, SEK per share* 397 367 355”.
    # Footnote markers between the row label and first value are allowed.
    for lm in re.finditer(per_share_label_re, text, flags=re.I | re.S):
        label_text = lm.group(0)
        if re.search(unrelated_metric_re, label_text, flags=re.I):
            continue
        suffix = text[lm.end():min(len(text), lm.end() + 180)]
        foot = r"\s*[,;:()\-–—]*\s*(?:[*†‡]+\s*(?:\d+\))?\s*)?"
        local = []
        for m in re.finditer(rf"^{foot}\b(SEK|EUR|USD|GBP|kr|kronor)\b[\s:(),;\-–—]{{0,8}}{num_token}", suffix, flags=re.I):
            local.append((m.end(), _num(m.group(2)), _currency(m.group(1))))
        for m in re.finditer(rf"^{foot}{num_token}[\s:(),;\-–—]{{0,8}}\b(SEK|EUR|USD|GBP|kr|kronor)\b", suffix, flags=re.I):
            local.append((m.end(), _num(m.group(1)), _currency(m.group(2))))
        if not local:
            cm = re.search(r"\b(SEK|EUR|USD|GBP|kr|kronor)\b", label_text, flags=re.I)
            inferred_cur = _currency(cm.group(1)) if cm else ("SEK" if re.search(r"substansv[aä]rd", label_text, flags=re.I) else None)
            m = re.match(rf"^{foot}{num_token}", suffix, flags=re.I)
            if m and inferred_cur:
                local.append((m.end(), _num(m.group(1)), inferred_cur))
        if not local:
            # KPI cards may render value before label, e.g.
            # “SEK 397 Adjusted net asset value per share”. Keep the lookback
            # very short so another metric cannot bleed into this row.
            prefix_card = text[max(0, lm.start() - 55):lm.start()]
            card = list(re.finditer(rf"\b(SEK|EUR|USD|GBP|kr|kronor)\b\s*{num_token}\s*$", prefix_card, flags=re.I))
            if card:
                m = card[-1]
                local.append((m.end(), _num(m.group(2)), _currency(m.group(1))))
        local = [x for x in local if x[1] is not None and 1.0 <= x[1] <= 10000.0]
        if not local:
            continue
        _, nav, cur = min(local, key=lambda x: x[0])
        ctx_start = max(0, lm.start() - 420)
        ctx_end = min(len(text), lm.end() + 320)
        ctx = text[ctx_start:ctx_end]
        dates = _exact_dates(ctx)
        # Report tables often list the current-period header immediately before
        # the NAV row. Prefer the latest non-future date in this local block.
        as_of = max((d for _, d in dates if d <= datetime.now().date()), default=None)
        candidates.append({
            "nav_per_share": nav, "currency": cur, "as_of_date_obj": as_of,
            "semantic_guard": "nav_per_share_linearized_report_row_v84",
            "quality": 13 + _adjusted_bonus(label_text) + (2 if as_of else 0),
        })

    # 3) HTML table: explicit NAV/share row + period columns.
    for table in soup.find_all("table"):
        rows = []
        for tr in table.find_all("tr"):
            cells = [_clean_text(c.get_text(" ", strip=True)).replace("\u00a0", " ") for c in tr.find_all(["th", "td"])]
            if cells:
                rows.append(cells)
        if not rows:
            continue
        period_row = None
        period_score = -1
        for cells in rows[:12]:
            score = sum(1 for c in cells if re.search(r"\bQ[1-4]\s*[/\- ]\s*20\d{2}\b|\b20\d{2}\b", c, flags=re.I))
            if score > period_score:
                period_row, period_score = cells, score
        for cells in rows:
            if len(cells) < 2 or not re.search(per_share_label_re, cells[0], flags=re.I | re.S):
                continue
            vals = []
            for idx, cell in enumerate(cells[1:], start=1):
                m = re.fullmatch(r"\s*([0-9]{1,5}(?:[.,][0-9]{1,2})?)\s*", cell)
                if m:
                    value = _num(m.group(1))
                    if value is not None and 1.0 <= value <= 10000.0:
                        vals.append((idx, value))
            if not vals:
                continue
            idx, nav = vals[-1]
            period_label = period_row[idx] if period_row and idx < len(period_row) else ""
            as_of = _quarter_end(period_label)
            if as_of is None:
                ds = _exact_dates(" ".join(strings[:120]))
                as_of = max((d for _, d in ds if d <= datetime.now().date()), default=None)
            cur = None
            cm = re.search(r"\b(SEK|EUR|USD|GBP)\b|\b(kr|kronor)\b", cells[0], flags=re.I)
            if cm:
                cur = _currency(cm.group(1) or cm.group(2))
            candidates.append({
                "nav_per_share": nav, "currency": cur or "SEK", "as_of_date_obj": as_of,
                "semantic_guard": "explicit_per_share_table_latest_period_v84", "period_label": period_label,
                "quality": 14 + _adjusted_bonus(cells[0]) + (3 if as_of else 0),
            })

    if not candidates:
        return None

    runtime_today = datetime.now().date()
    page_dates = [(pos, d) for pos, d in _exact_dates(" ".join(strings[:160])) if d <= runtime_today]
    page_latest = max((d for _, d in page_dates), default=None)
    for rec in candidates:
        if rec.get("as_of_date_obj") is not None and rec.get("as_of_date_obj") > runtime_today:
            rec["future_date_rejected"] = True
            continue
        if rec.get("as_of_date_obj") is None and page_latest is not None:
            rec["as_of_date_obj"] = page_latest
            rec["quality"] = int(rec.get("quality") or 0) + 1

    candidates = [r for r in candidates if not r.get("future_date_rejected") and (r.get("as_of_date_obj") is None or r.get("as_of_date_obj") <= runtime_today)]
    if not candidates:
        return None

    candidates.sort(key=lambda r: (int(r.get("quality") or 0), r.get("as_of_date_obj") or datetime(1900,1,1).date()), reverse=True)
    best = dict(candidates[0])
    best["as_of_date"] = _holding_date_display(best.get("as_of_date_obj"))
    best["source_url"] = url
    try:
        best["source_title"] = _clean_text((soup.find("h1") or soup.title).get_text(" ", strip=True)) if (soup.find("h1") or soup.title) else None
    except Exception:
        best["source_title"] = None
    return best


def _holding_extract_quarterly_nav_price_history(html, url, target_class=None):
    """V85 parse issuer-primary quarterly NAV/share + share-class price history.

    This is intentionally a historical-only adapter.  A record is accepted only
    when one table supplies (1) quarter/year columns, (2) an explicit NAV-per-share
    row and (3) the requested share-class price row for the same columns.  It never
    supplies the live current NAV snapshot.
    """
    if not html:
        return []
    try:
        soup = BeautifulSoup(html, "html.parser")
    except Exception:
        return []

    target = str(target_class or "").upper().strip() or None

    def _quarter_end(label):
        raw = _clean_text(label).replace("’", "'")
        pats = [
            r"\bQ([1-4])\s*[/\- ]*\s*(20\d{2})\b",
            r"\b([1-4])Q\s*[/\- ]*\s*(20\d{2})\b",
            r"\bQ([1-4])\s*[/\- ]*\s*(\d{2})\b",
            r"\b([1-4])Q\s*[/\- ]*\s*(\d{2})\b",
        ]
        for idx, pat in enumerate(pats):
            m = re.search(pat, raw, flags=re.I)
            if not m:
                continue
            q = int(m.group(1)); y = int(m.group(2))
            if idx >= 2:
                y += 2000
            month, day = {1:(3,31), 2:(6,30), 3:(9,30), 4:(12,31)}[q]
            try:
                return datetime(y, month, day).date()
            except Exception:
                return None
        return None

    def _number(cell):
        raw = _clean_text(cell).replace("\u00a0", " ").strip()
        if not raw or raw in {"-", "–", "—"}:
            return None
        # This adapter handles per-share values, not total NAV.  Spaces can be
        # thousands separators elsewhere, but accepted values remain bounded.
        raw = raw.replace("%", "").strip()
        raw = re.sub(r"\s+", "", raw)
        # Nordic decimal comma; ordinary decimal point is also accepted.
        if "," in raw and "." not in raw:
            raw = raw.replace(",", ".")
        # If both separators occur, treat the last one as decimal and the other
        # as thousands punctuation.
        elif "," in raw and "." in raw:
            if raw.rfind(",") > raw.rfind("."):
                raw = raw.replace(".", "").replace(",", ".")
            else:
                raw = raw.replace(",", "")
        raw = re.sub(r"[^0-9.\-+]", "", raw)
        try:
            val = float(raw)
        except Exception:
            return None
        return val if 0 < val <= 100000 else None

    def _nav_label_score(label):
        folded = _holding_fold_text(label)
        if not any(x in folded for x in ["net asset value", "substansvarde", "nav"]):
            return -1
        if not any(x in folded for x in ["per share", "per aktie", "/ share", "/ aktie"]):
            return -1
        if any(x in folded for x in ["growth", "change", "sequential", "%"]):
            return -1
        score = 10
        if "adjusted" in folded or "justerat" in folded:
            score += 4
        if any(x in folded for x in ["sek", "eur", "usd", "gbp", "kr"]):
            score += 1
        return score

    def _price_label_class(label):
        folded = _holding_fold_text(label)
        if not any(x in folded for x in ["share price", "stock price", "aktiekurs", "closing price", "stangningskurs"]):
            return None
        # English forms: class B / B share(s). Swedish: B-aktien / aktie B.
        for pat in [
            r"\bclass\s+([a-z])\b", r"\b([a-z])\s+shares?\b", r"\b([a-z])\s*[-–—]?\s*aktien\b",
            r"\baktie(?:n)?\s+([a-z])\b", r"\bserie\s+([a-z])\b",
            r"\b([a-z])\s*,?\s*(?:sek|eur|usd|gbp|kr)\b",
        ]:
            m = re.search(pat, folded, flags=re.I)
            if m:
                return m.group(1).upper()
        return None

    out = []
    for table in soup.find_all("table"):
        rows = []
        for tr in table.find_all("tr"):
            cells = [_clean_text(c.get_text(" ", strip=True)).replace("\u00a0", " ") for c in tr.find_all(["th", "td"])]
            if cells:
                rows.append(cells)
        if len(rows) < 3:
            continue

        # Find the row with the densest quarter labels; map actual cell index to date.
        period_map = {}
        for cells in rows[:16]:
            local = {idx: _quarter_end(cell) for idx, cell in enumerate(cells)}
            local = {idx: dt for idx, dt in local.items() if dt is not None and dt <= datetime.now().date()}
            if len(local) > len(period_map):
                period_map = local
        if len(period_map) < 3:
            # V91: some issuer tables split the column date across two header
            # rows, e.g. [2026, 2025, 2025] followed by
            # [30 June, 30 June, 31 Dec]. Reconstruct the exact period end
            # by column instead of discarding an otherwise explicit table.
            split_map = {}
            year_row_idx = None
            year_by_col = {}
            for ridx, cells in enumerate(rows[:10]):
                local_years = {}
                for cidx, cell in enumerate(cells):
                    ym = re.fullmatch(r"\s*(20\d{2})\s*", _clean_text(cell))
                    if ym:
                        local_years[cidx] = int(ym.group(1))
                if len(local_years) > len(year_by_col):
                    year_row_idx = ridx
                    year_by_col = local_years
            if year_row_idx is not None and len(year_by_col) >= 2:
                for cells in rows[year_row_idx + 1: min(len(rows), year_row_idx + 4)]:
                    local = {}
                    for cidx, year in year_by_col.items():
                        if cidx >= len(cells):
                            continue
                        day_month = _clean_text(cells[cidx])
                        if not day_month or re.search(r"20\d{2}", day_month):
                            continue
                        dt = _holding_parse_date_text(f"{day_month} {year}")
                        if dt is not None and dt <= datetime.now().date():
                            local[cidx] = dt
                    if len(local) > len(split_map):
                        split_map = local
            if len(split_map) >= 2:
                period_map = split_map
        if len(period_map) < 2:
            continue

        nav_row = None; nav_score = -1
        price_rows = {}
        for cells in rows:
            if not cells:
                continue
            score = _nav_label_score(cells[0])
            if score > nav_score:
                nav_row, nav_score = cells, score
            cls = _price_label_class(cells[0])
            if cls:
                price_rows[cls] = cells
        if nav_row is None or nav_score < 0:
            continue
        chosen_class = target if target in price_rows else (next(iter(price_rows)) if len(price_rows) == 1 else None)
        if chosen_class is None:
            continue
        price_row = price_rows.get(chosen_class)
        if not price_row:
            continue

        # Currency comes from the NAV label; SEK is a safe semantic inference only
        # when the printed label explicitly says SEK/kr.
        nav_label = nav_row[0]
        currency = None
        cm = re.search(r"\b(SEK|EUR|USD|GBP)\b", nav_label, flags=re.I)
        if cm:
            currency = cm.group(1).upper()
        elif re.search(r"\bkr\b|kronor", nav_label, flags=re.I):
            currency = "SEK"
        if currency is None:
            continue

        for idx, dt in period_map.items():
            if idx >= len(nav_row) or idx >= len(price_row):
                continue
            nav = _number(nav_row[idx]); price = _number(price_row[idx])
            if nav is None or price is None or nav <= 0 or price <= 0:
                continue
            premium = (price / nav - 1.0) * 100.0
            if premium < -60.0 or premium > 120.0:
                continue
            out.append({
                "nav_per_share": nav,
                "currency": currency,
                "as_of_date_obj": dt,
                "as_of_date": _holding_date_display(dt),
                "published_date_obj": None,
                "published_date": None,
                "source_url": url,
                "source_title": "Quarterly NAV/share & share-price key figures",
                "same_date_class_prices": {chosen_class: price},
                "paired_price_date_obj": dt,
                "paired_price_date": _holding_date_display(dt),
                "quality": 12 + (2 if nav_score >= 14 else 0),
                "history_source_kind": "issuer_quarterly_key_figures_table_v85",
            })

    # One record per quarter-end; richest/adjusted record wins.
    by_date = {}
    for rec in out:
        dt = rec.get("as_of_date_obj")
        prev = by_date.get(dt)
        if prev is None or int(rec.get("quality") or 0) > int(prev.get("quality") or 0):
            by_date[dt] = rec
    return [by_date[k] for k in sorted(by_date.keys(), reverse=True)]


def _holding_extract_report_nav_price_history(text, url, target_class=None):
    """V87 parse multi-period NAV/share + share-price rows from issuer reports.

    Historical-only adapter. It supports both preserved table rows and the
    whitespace-flattened PDF text produced by the issuer-document bridge. A
    report contributes history only when one local table block proves period
    columns, an explicit NAV-per-share row and the requested share-class price
    row. It never supplies or replaces the live current NAV snapshot.
    """
    if not text:
        return []
    html_table_history = []
    try:
        raw = str(text)
        if "<" in raw[:1000] and ">" in raw[:1000]:
            # V91: before flattening an issuer report/article, let the strict
            # HTML table adapter recover split-header NAV/share + class-price
            # history. These records remain historical-only.
            html_table_history = _holding_extract_quarterly_nav_price_history(raw, url, target_class=target_class)
            raw = BeautifulSoup(raw, "html.parser").get_text("\n", strip=True)
    except Exception:
        raw = str(text)
    raw = unicodedata.normalize("NFKC", raw).replace("\u00a0", " ")
    raw = re.sub(r"[\u200b\u200c\u200d\u2060\ufeff\u00ad]", "", raw)
    flat = _clean_text(raw)
    lines = [_clean_text(x) for x in raw.splitlines()]
    lines = [x for x in lines if x]

    target = str(target_class or "").upper().strip() or None
    runtime_today = datetime.now().date()

    def _date_tokens(s):
        out = []
        seen = set()
        s = _clean_text(s)
        # ISO is unambiguous.
        for m in re.finditer(r"\b(20\d{2})[-/.](\d{1,2})[-/.](\d{1,2})\b", s):
            try:
                dt = datetime(int(m.group(1)), int(m.group(2)), int(m.group(3))).date()
            except Exception:
                continue
            if dt <= runtime_today and dt not in seen:
                seen.add(dt); out.append((m.start(), dt))
        # Common issuer-report form: 6/30 2026 or 6/30/2026. Ambiguous
        # day/month pairs (both <=12) are rejected rather than guessed.
        for m in re.finditer(r"\b(\d{1,2})[/.](\d{1,2})(?:[/.]|\s+)(20\d{2})\b", s):
            a, b, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
            month = day = None
            if a <= 12 and b > 12:
                month, day = a, b
            elif a > 12 and b <= 12:
                day, month = a, b
            elif a <= 12 and b <= 12:
                continue
            try:
                dt = datetime(y, month, day).date()
            except Exception:
                continue
            if dt <= runtime_today and dt not in seen:
                seen.add(dt); out.append((m.start(), dt))
        # Quarter labels are also explicit enough for historical calibration.
        for m in re.finditer(r"\bQ([1-4])\s*(20\d{2})\b", s, flags=re.I):
            q, y = int(m.group(1)), int(m.group(2))
            mo, day = {1:(3,31), 2:(6,30), 3:(9,30), 4:(12,31)}[q]
            try:
                dt = datetime(y, mo, day).date()
            except Exception:
                continue
            if dt <= runtime_today and dt not in seen:
                seen.add(dt); out.append((m.start(), dt))
        return [dt for _, dt in sorted(out, key=lambda x: x[0])]

    def _values_after_label(s):
        vals = []
        for tok in re.findall(r"(?<![0-9])[-+]?\d{1,5}(?:[.,]\d{1,2})?(?![0-9])", s):
            t = tok.strip()
            if re.fullmatch(r"20\d{2}", t):
                continue
            if "," in t and "." not in t:
                t = t.replace(",", ".")
            elif "," in t and "." in t:
                if t.rfind(",") > t.rfind("."):
                    t = t.replace(".", "").replace(",", ".")
                else:
                    t = t.replace(",", "")
            try:
                v = float(t)
            except Exception:
                continue
            if 0 < v <= 100000:
                vals.append(v)
        return vals

    def _nav_row_score(line):
        folded = _holding_fold_text(line)
        if not any(x in folded for x in ["net asset value", "substansvarde", "nav"]):
            return -1
        if not any(x in folded for x in ["per share", "per aktie", "/ share", "/ aktie"]):
            return -1
        if any(x in folded for x in ["growth", "change", "sequential", "%"]):
            return -1
        score = 10
        if "adjusted" in folded or "justerat" in folded:
            score += 5
        if any(x in folded for x in ["sek", "eur", "usd", "gbp", "kr"]):
            score += 1
        return score

    def _price_row_class(line):
        folded = _holding_fold_text(line)
        if not any(x in folded for x in ["share price", "stock price", "aktiekurs", "closing price", "stangningskurs"]):
            return None
        for pat in [
            r"\bclass\s+([a-z])\b", r"\b([a-z])\s*[-–—]?\s*share\b", r"\b([a-z])\s+shares?\b",
            r"\b([a-z])\s*[-–—]?\s*aktien\b", r"\baktie(?:n)?\s+([a-z])\b", r"\bserie\s+([a-z])\b",
            r"\b([a-z])\s*,?\s*(?:sek|eur|usd|gbp|kr)\b",
        ]:
            m = re.search(pat, folded, flags=re.I)
            if m:
                return m.group(1).upper()
        return None

    out = list(html_table_history)

    # Row-preserving path (HTML/text reports or PDF extractors that keep rows).
    if len(lines) >= 3:
        for nav_i, nav_line in enumerate(lines):
            nav_score = _nav_row_score(nav_line)
            if nav_score < 0:
                continue
            period_dates = []
            for j in range(max(0, nav_i - 4), nav_i):
                dts = _date_tokens(lines[j])
                if len(dts) > len(period_dates):
                    period_dates = dts
            if len(period_dates) < 2:
                continue

            nav_vals = _values_after_label(nav_line)
            if len(nav_vals) < len(period_dates):
                continue
            nav_vals = nav_vals[-len(period_dates):]

            currency = None
            cm = re.search(r"\b(SEK|EUR|USD|GBP)\b", nav_line, flags=re.I)
            if cm:
                currency = cm.group(1).upper()
            elif re.search(r"\bkr\b|kronor", nav_line, flags=re.I):
                currency = "SEK"
            if currency is None:
                continue

            candidates = []
            for k in range(max(0, nav_i - 8), min(len(lines), nav_i + 18)):
                cls = _price_row_class(lines[k])
                if cls:
                    vals = _values_after_label(lines[k])
                    if len(vals) >= len(period_dates):
                        candidates.append((k, cls, vals[-len(period_dates):], lines[k]))
            if target:
                candidates = [x for x in candidates if x[1] == target]
            elif len({x[1] for x in candidates}) == 1:
                pass
            else:
                continue
            if not candidates:
                continue
            _, chosen_class, price_vals, _ = min(candidates, key=lambda x: abs(x[0] - nav_i))

            for dt, nav, price in zip(period_dates, nav_vals, price_vals):
                if nav <= 0 or price <= 0:
                    continue
                premium = (price / nav - 1.0) * 100.0
                if premium < -60.0 or premium > 120.0:
                    continue
                out.append({
                    "nav_per_share": nav,
                    "currency": currency,
                    "as_of_date_obj": dt,
                    "as_of_date": _holding_date_display(dt),
                    "published_date_obj": None,
                    "published_date": None,
                    "source_url": url,
                    "source_title": "Quarterly/interim report NAV/share & share-price table",
                    "same_date_class_prices": {chosen_class: price},
                    "paired_price_date_obj": dt,
                    "paired_price_date": _holding_date_display(dt),
                    "quality": 15 + (2 if nav_score >= 15 else 0),
                    "history_source_kind": "issuer_report_multi_period_table_v86",
                })

    # V87 flat-PDF recovery. The generic issuer PDF bridge deliberately cleans
    # extracted PDF text with _clean_text(), collapsing line breaks. Recover the
    # same table semantically from one whitespace stream instead of assuming rows.
    def _flat_period_cluster_before(pos):
        start = max(0, pos - 1200)
        prefix = flat[start:pos]
        token_pat = re.compile(
            r"\b(?:20\d{2}[-/.]\d{1,2}[-/.]\d{1,2}|"
            r"\d{1,2}[/.]\d{1,2}(?:[/.]|\s+)20\d{2}|Q[1-4]\s*20\d{2})\b",
            flags=re.I,
        )
        toks = []
        for m in token_pat.finditer(prefix):
            dts = _date_tokens(m.group(0))
            if dts:
                toks.append((m.start(), m.end(), dts[0]))
        if not toks:
            return []
        clusters = []
        cur = []
        prev_end = None
        for item in toks:
            if prev_end is None or item[0] - prev_end <= 32:
                cur.append(item)
            else:
                if cur:
                    clusters.append(cur)
                cur = [item]
            prev_end = item[1]
        if cur:
            clusters.append(cur)
        eligible = [c for c in clusters if 2 <= len(c) <= 5]
        if not eligible:
            return []
        # Nearest compact date cluster to the NAV row wins.
        best = max(eligible, key=lambda c: c[-1][1])
        dates = []
        for _, _, dt in best:
            if dt not in dates:
                dates.append(dt)
        return dates

    def _flat_row_values(after_pos, stop_terms, needed):
        segment = flat[after_pos: after_pos + 900]
        cut = len(segment)
        for pat in stop_terms:
            m = re.search(pat, segment, flags=re.I)
            if m and m.start() > 0:
                cut = min(cut, m.start())
        vals = _values_after_label(segment[:cut])
        return vals[:needed] if len(vals) >= needed else []

    if flat:
        nav_pat = re.compile(
            r"\b(?P<label>(?:(?:adjusted|reported)\s+)?(?:net\s+asset\s+value|nav|substansv[aä]rde)"
            r"\s*,?\s*(?:SEK|EUR|USD|GBP|kr)?\s*(?:per\s+share|per\s+aktie|/\s*share|/\s*aktie)"
            r"(?:\s*\*+)?(?:\s*\d+\))?)",
            flags=re.I,
        )
        price_anchor_pat = re.compile(
            r"\b(?:share\s+price|stock\s+price|closing\s+price|aktiekurs|st[aä]ngningskurs)\b",
            flags=re.I,
        )
        for nm in nav_pat.finditer(flat):
            nav_label = nm.group("label") or ""
            nav_score = _nav_row_score(nav_label)
            if nav_score < 0:
                continue
            period_dates = _flat_period_cluster_before(nm.start())
            if len(period_dates) < 2:
                continue
            n = len(period_dates)
            nav_vals = _flat_row_values(
                nm.end(),
                [
                    r"\bReported\s+NAV\b", r"\bAdjusted\s+NAV\b",
                    r"\bMarket\s+capitalization\b", r"\bShare\s+price\b",
                    r"\bConsolidated\b", r"\bAdjusted\s+NAV\s*,?\s*sequential\b",
                ],
                n,
            )
            if len(nav_vals) < n:
                continue

            currency = None
            cm = re.search(r"\b(SEK|EUR|USD|GBP)\b", nav_label, flags=re.I)
            if cm:
                currency = cm.group(1).upper()
            elif re.search(r"\bkr\b|kronor", nav_label, flags=re.I):
                currency = "SEK"
            if currency is None:
                continue

            price_candidates = []
            lo = max(0, nm.start() - 500)
            hi = min(len(flat), nm.end() + 1800)
            for pm in price_anchor_pat.finditer(flat, lo, hi):
                snippet = flat[pm.start(): min(len(flat), pm.start() + 700)]
                cls = _price_row_class(snippet)
                if not cls:
                    continue
                vals = _flat_row_values(
                    pm.end(),
                    [
                        r"\bAdjusted\s+NAV\s*,?\s*sequential\b", r"\bReported\s+NAV\s*,?\s*sequential\b",
                        r"\bConsolidated\b", r"\bQ[1-4]\s+20\d{2}\b", r"\bH[12]\s+20\d{2}\b",
                    ],
                    n,
                )
                if len(vals) >= n:
                    price_candidates.append((pm.start(), cls, vals))
            if target:
                price_candidates = [x for x in price_candidates if x[1] == target]
            elif len({x[1] for x in price_candidates}) != 1:
                continue
            if not price_candidates:
                continue
            _, chosen_class, price_vals = min(price_candidates, key=lambda x: abs(x[0] - nm.start()))

            for dt, nav, price in zip(period_dates, nav_vals, price_vals):
                if nav <= 0 or price <= 0:
                    continue
                premium = (price / nav - 1.0) * 100.0
                if premium < -60.0 or premium > 120.0:
                    continue
                out.append({
                    "nav_per_share": nav,
                    "currency": currency,
                    "as_of_date_obj": dt,
                    "as_of_date": _holding_date_display(dt),
                    "published_date_obj": None,
                    "published_date": None,
                    "source_url": url,
                    "source_title": "Quarterly/interim report NAV/share & share-price table (flat PDF recovery)",
                    "same_date_class_prices": {chosen_class: price},
                    "paired_price_date_obj": dt,
                    "paired_price_date": _holding_date_display(dt),
                    "quality": 16 + (2 if nav_score >= 15 else 0),
                    "history_source_kind": "issuer_report_flat_pdf_table_v87",
                })

    by_date = {}
    for rec in out:
        dt = rec.get("as_of_date_obj")
        prev = by_date.get(dt)
        if prev is None or int(rec.get("quality") or 0) > int(prev.get("quality") or 0):
            by_date[dt] = rec
    return [by_date[k] for k in sorted(by_date.keys(), reverse=True)]
def _holding_extract_current_nav_record(html, url):
    """V84 current-snapshot NAV/share extractor.

    Prefer the strict explicit-per-share semantic used by the universal peer
    adapter. This prevents a total NAV amount (for example SEK bn) from being
    mistaken for NAV/share when both appear in the same sentence. The broad
    legacy issuer parser remains a fallback and is still used directly for
    dated historical releases where share-class close provenance is required.
    """
    if not html:
        return None
    strict = _holding_extract_peer_nav_record(html, url)
    if strict:
        rec = dict(strict)
        as_of = rec.get("as_of_date_obj")
        if as_of is not None and as_of > datetime.now().date():
            return None
        try:
            soup = BeautifulSoup(html, "html.parser")
        except Exception:
            soup = None
        published = _holding_structured_publication_date(soup) if soup is not None else None
        if published is None:
            try:
                txt = _clean_text(" ".join(_clean_text(x) for x in soup.stripped_strings)) if soup is not None else ""
            except Exception:
                txt = ""
            published = _holding_publication_date_fallback(txt, rec.get("as_of_date_obj"))
            if published is not None and rec.get("as_of_date_obj") is not None and published <= rec.get("as_of_date_obj"):
                published = None
        rec["published_date_obj"] = published
        rec["published_date"] = _holding_date_display(published)
        rec.setdefault("same_date_class_prices", {})
        rec.setdefault("paired_price_date_obj", None)
        rec.setdefault("paired_price_date", None)
        rec["quality"] = max(int(rec.get("quality") or 0), 11) + (1 if published else 0)
        rec["current_nav_guard"] = "strict_nav_semantic_adjacency_nonfuture_v84"
        return rec
    # V83: the broad legacy NAV extractor is intentionally historical-only.
    # A current valuation anchor must prove explicit per-share semantics.
    return None

def _holding_extract_debt_ratio(html, url):
    if not html:
        return None
    try:
        soup = BeautifulSoup(html, "html.parser")
        text = _clean_text(soup.get_text(" ", strip=True)).replace("\u00a0", " ")
    except Exception:
        return None
    patterns = [
        ("Debt-equities ratio", r"debt[- ]equities\s+ratio\s*[:|]?\s*([0-9]{1,2}(?:[.,][0-9])?)\s*%"),
        ("Debt/Equity ratio", r"debt\s*/\s*equity\s+ratio\s*[:|]?\s*([0-9]{1,2}(?:[.,][0-9])?)\s*%"),
        ("Gearing", r"\bgearing(?:\s+ratio)?\s*[:|]?\s*([0-9]{1,2}(?:[.,][0-9])?)\s*%"),
        ("Leverage", r"\bleverage(?:\s+(?:was|is|stood\s+at|amounted\s+to))?\s*[:|]?\s*([0-9]{1,2}(?:[.,][0-9])?)\s*(?:%|percent)"),
        ("Skuldsättningsgrad", r"skulds[aä]ttningsgrad\s*[:|]?\s*([0-9]{1,2}(?:[.,][0-9])?)\s*%"),
    ]
    metric = None
    ratio = None
    ratio_match = None
    for label, pat in patterns:
        m = re.search(pat, text, flags=re.I)
        if m:
            try:
                ratio = float(m.group(1).replace(",", "."))
            except Exception:
                ratio = None
            if ratio is not None:
                metric = label
                ratio_match = m
                break
    if ratio is None:
        return None
    as_of = None
    runtime_today = datetime.now().date()

    # V82: bind provenance to the accepted ratio occurrence itself. This keeps
    # a prior-period comparator in the same sentence from stealing the date.
    if ratio_match is not None:
        after = text[ratio_match.end(): min(len(text), ratio_match.end() + 220)]
        local_date_patterns = [
            r"(?:as\s+of|on|at)\s+([A-Za-zÅÄÖåäö]+\s+\d{1,2},?\s+20\d{2})",
            r"(?:as\s+of|on|at)\s+(\d{1,2}\s+[A-Za-zÅÄÖåäö]+\s+20\d{2})",
            r"(?:per(?:\s+den)?|den)\s+(\d{1,2}\s+[A-Za-zÅÄÖåäö]+\s+20\d{2})",
        ]
        for dpat in local_date_patterns:
            dm = re.search(dpat, after, flags=re.I)
            if dm:
                dt = _holding_parse_date_text(dm.group(1))
                if dt and dt <= runtime_today:
                    as_of = dt
                    break

    title_text = _clean_text((soup.find("h1") or soup.title).get_text(" ", strip=True)) if (soup.find("h1") or soup.title) else ""
    if as_of is None:
        # Fallback only: choose the latest non-future reporting date rather than
        # the earliest date, which can be a prior-year comparison.
        for candidate in [title_text, text[:1800]]:
            dates = []
            for pat in [r"([A-Za-zÅÄÖåäö]+\s+\d{1,2},?\s+20\d{2})", r"(\d{1,2}\s+[A-Za-zÅÄÖåäö]+\s+20\d{2})"]:
                for dm in re.finditer(pat, candidate):
                    dt = _holding_parse_date_text(dm.group(1))
                    if dt and dt <= runtime_today:
                        dates.append(dt)
            if dates:
                as_of = max(dates)
                break
    published = _holding_structured_publication_date(soup)
    if published is None:
        published = _holding_publication_date_fallback(text, as_of)
    return {
        "debt_ratio_pct": ratio,
        "metric_name": metric,
        "as_of_date_obj": as_of,
        "as_of_date": _holding_date_display(as_of),
        "published_date_obj": published,
        "published_date": _holding_date_display(published),
        "source_url": url,
    }


def _holding_extract_management_cost_ratio(html, url):
    """Parse issuer-primary recurring holding/management cost as % of portfolio/NAV.

    V72 is deliberately strict about semantic binding. Generic prose that merely
    contains the words "management cost" is not enough: the metric label itself
    must prove a portfolio/NAV percentage basis, or use an explicit ratio name.
    This prevents unrelated percentages on accounting/tax-policy pages from
    becoming holding-cost evidence.
    """
    if not html:
        return None
    try:
        soup = BeautifulSoup(html, "html.parser")
    except Exception:
        return None

    cost_terms = (
        "management cost", "management costs", "management expense", "management expenses",
        "administration cost", "administrative cost",
        "forvaltningskostnad", "forvaltningskostnader", "administrationskostnad",
    )
    basis_terms = (
        "portfolio", "portfolj", "nav", "net asset value", "substansvarde",
        "asset value", "managed assets",
    )
    explicit_ratio_terms = (
        "cost ratio", "expense ratio", "management cost ratio", "management expense ratio",
    )

    def _label_semantics(value):
        folded = _holding_fold_text(value)
        has_cost = any(term in folded for term in cost_terms)
        has_basis = any(term in folded for term in basis_terms)
        explicit_ratio = any(term in folded for term in explicit_ratio_terms)
        accepted = bool((has_cost and has_basis) or explicit_ratio)
        return accepted, folded

    def _cell_ratio_candidates(cell):
        vals = []
        cleaned = _clean_text(cell).replace("\u00a0", " ")
        for raw in re.findall(r"(?<![0-9])([0-9]{1,2}(?:[.,][0-9]{1,4})?)(?![0-9])", cleaned):
            try:
                val = float(raw.replace(",", "."))
            except Exception:
                continue
            if 0 <= val <= 5.0:
                vals.append(val)
        return vals

    candidates = []

    # Preferred path: real table row whose label proves the ratio basis.
    for table in soup.find_all("table"):
        rows = []
        for tr in table.find_all("tr"):
            cells = [_clean_text(c.get_text(" ", strip=True)).replace("\u00a0", " ") for c in tr.find_all(["th", "td"])]
            if cells:
                rows.append(cells)
        if not rows:
            continue

        years = []
        for cells in rows[:10]:
            found = [int(y) for y in re.findall(r"\b(20\d{2})\b", " ".join(cells))]
            if len(found) > len(years):
                years = found

        for cells in rows:
            if not cells:
                continue
            accepted, _ = _label_semantics(cells[0])
            if not accepted:
                continue
            metric_label = cells[0]
            vals = []
            for cell in cells[1:]:
                in_cell = _cell_ratio_candidates(cell)
                if in_cell:
                    vals.append(min(in_cell))
            obs = []
            if years and vals:
                for idx, val in enumerate(vals[:len(years)]):
                    obs.append({"year": years[idx], "cost_pct": val})
            elif vals:
                obs.append({"year": None, "cost_pct": vals[0]})
            if obs:
                candidates.append({
                    "observations": obs,
                    "metric_label": metric_label,
                    "semantic_guard": "explicit_cost_to_portfolio_nav_ratio_label",
                    "source_shape": "table",
                })

    # Conservative flattened-CMS fallback. The same strong metric label is
    # mandatory and at least three historical observations must be recoverable.
    if not candidates:
        strings = [_clean_text(x).replace("\u00a0", " ") for x in soup.stripped_strings]
        for idx, value in enumerate(strings):
            accepted, _ = _label_semantics(value)
            if not accepted:
                continue
            years = []
            for node in strings[max(0, idx - 35): idx + 3]:
                found = [int(y) for y in re.findall(r"\b(20\d{2})\b", node)]
                for yr in found:
                    if yr not in years:
                        years.append(yr)
            vals = []
            for node in strings[idx + 1: idx + 45]:
                clean_node = _clean_text(node)
                if len(clean_node) > 30:
                    continue
                node_vals = _cell_ratio_candidates(clean_node)
                if len(node_vals) == 1:
                    vals.append(node_vals[0])
                if years and len(vals) >= len(years):
                    break
            if len(years) >= 3 and len(vals) >= 3:
                obs = [{"year": years[i], "cost_pct": vals[i]} for i in range(min(len(years), len(vals)))]
                candidates.append({
                    "observations": obs,
                    "metric_label": value,
                    "semantic_guard": "explicit_cost_to_portfolio_nav_ratio_label",
                    "source_shape": "flattened_table",
                })
                break

    if not candidates:
        return None

    candidates.sort(
        key=lambda c: (
            sum(1 for x in c.get("observations", []) if x.get("year")),
            len(c.get("observations", [])),
        ),
        reverse=True,
    )
    chosen = candidates[0]
    observations = chosen.get("observations") or []

    by_year = {}
    undated = []
    for obs in observations:
        yr = obs.get("year")
        val = safe_float(obs.get("cost_pct"))
        if val is None:
            continue
        if yr:
            by_year[int(yr)] = val
        else:
            undated.append(val)
    ordered = [{"year": y, "cost_pct": by_year[y]} for y in sorted(by_year, reverse=True)]
    if not ordered and undated:
        ordered = [{"year": None, "cost_pct": undated[0]}]
    if not ordered:
        return None

    latest = ordered[0]
    recent_vals = [safe_float(x.get("cost_pct")) for x in ordered[:5] if safe_float(x.get("cost_pct")) is not None]
    if not recent_vals:
        return None
    recent_ser = pd.Series(recent_vals, dtype="float64")
    return {
        "latest_cost_pct": safe_float(latest.get("cost_pct")),
        "latest_year": latest.get("year"),
        "median_5y_pct": float(recent_ser.median()),
        "min_5y_pct": float(recent_ser.min()),
        "max_5y_pct": float(recent_ser.max()),
        "observation_count": len(ordered),
        "observations": ordered[:12],
        "metric_label": chosen.get("metric_label") or "Management/holding cost ratio",
        "semantic_guard": chosen.get("semantic_guard"),
        "source_shape": chosen.get("source_shape"),
        "source_url": url,
        "quality": 4 if len(ordered) >= 5 else (3 if len(ordered) >= 3 else 1),
    }



def _holding_extract_management_cost_ratio_from_report_text(text, url):
    """Parse explicit issuer-report management-cost ratios against NAV.

    V88 accepts only two strong report shapes:
    1) current/rolling narrative explicitly saying the management cost
       corresponds to X percent of (adjusted) NAV; and
    2) a multi-year key-ratio row explicitly labelled management cost as a
       percentage of (adjusted) NAV/net asset value.
    Generic management-cost amounts are never converted into a ratio here.
    """
    if not text:
        return None
    flat = _clean_text(str(text).replace("\u00a0", " "))
    folded = _holding_fold_text(flat)
    if "management cost" not in folded:
        return None

    observations = []
    current = None

    # Current/rolling explicit ratio, e.g. "As of June 30, 2026, rolling
    # 12-month management cost ... corresponding to 0.07 percent of the
    # adjusted net asset value".
    current_patterns = [
        r"(?:rolling\s+12[- ]month\s+)?management\s+cost.{0,260}?correspond(?:ing|ed)?\s+to\s+([0-9]{1,2}(?:[.,][0-9]{1,4})?)\s*(?:percent|%)\s+of\s+(?:the\s+)?(?:adjusted\s+)?(?:net\s+asset\s+value|nav)",
        r"management\s+cost.{0,220}?([0-9]{1,2}(?:[.,][0-9]{1,4})?)\s*(?:percent|%)\s+of\s+(?:the\s+)?(?:adjusted\s+)?(?:net\s+asset\s+value|nav)",
    ]
    for pat in current_patterns:
        m = re.search(pat, flat, flags=re.I)
        if not m:
            continue
        try:
            val = float(m.group(1).replace(",", "."))
        except Exception:
            continue
        if not (0 <= val <= 5.0):
            continue
        local = flat[max(0, m.start() - 180): min(len(flat), m.end() + 80)]
        dt = None
        for dpat in [
            r"(?:as\s+of|on|at)\s+([A-Za-zÅÄÖåäö]+\s+\d{1,2},?\s+20\d{2})",
            r"(?:as\s+of|on|at)\s+(\d{1,2}\s+[A-Za-zÅÄÖåäö]+\s+20\d{2})",
        ]:
            dm = re.search(dpat, local, flags=re.I)
            if dm:
                dt = _holding_parse_date_text(dm.group(1))
                if dt:
                    break
        yr = dt.year if dt else None
        current = {"year": yr, "cost_pct": val, "as_of_date_obj": dt, "as_of_date": _holding_date_display(dt)}
        observations.append({"year": yr, "cost_pct": val})
        break

    # Multi-year report row. The label itself must bind management cost to NAV.
    label_match = re.search(
        r"management\s+cost\s+as\s+a\s*%\s+of\s+(?:adjusted\s+)?(?:net\s+asset\s+value|nav)",
        flat,
        flags=re.I,
    )
    if label_match:
        pre = flat[max(0, label_match.start() - 1800): label_match.start()]
        post = flat[label_match.end(): min(len(flat), label_match.end() + 260)]
        years = []
        # Prefer an explicit issuer/group year header near the metric row.
        header = None
        for hm in re.finditer(r"(?:Investor\s+Group|Group|Key\s+figures?)\s+((?:20\d{2}\s+){2,8})", pre, flags=re.I):
            header = hm
        if header:
            years = [int(y) for y in re.findall(r"20\d{2}", header.group(1))]
        if len(years) < 3:
            seen = []
            for y in re.findall(r"\b20\d{2}\b", pre):
                iy = int(y)
                if iy not in seen:
                    seen.append(iy)
            years = seen[-8:]
        vals = []
        for raw in re.findall(r"(?<![0-9])([0-9]{1,2}(?:[.,][0-9]{1,4})?)(?![0-9])", post):
            try:
                v = float(raw.replace(",", "."))
            except Exception:
                continue
            if 0 <= v <= 5.0:
                vals.append(v)
            if years and len(vals) >= len(years):
                break
        if len(years) >= 3 and len(vals) >= 3:
            n = min(len(years), len(vals))
            observations.extend({"year": years[i], "cost_pct": vals[i]} for i in range(n))

    if not observations:
        return None

    by_year = {}
    undated = []
    for obs in observations:
        val = safe_float(obs.get("cost_pct"))
        if val is None:
            continue
        yr = obs.get("year")
        if yr:
            by_year[int(yr)] = val
        else:
            undated.append(val)
    ordered = [{"year": y, "cost_pct": by_year[y]} for y in sorted(by_year, reverse=True)]
    if not ordered and undated:
        ordered = [{"year": None, "cost_pct": undated[0]}]
    if not ordered:
        return None

    latest = current or ordered[0]
    recent_vals = [safe_float(x.get("cost_pct")) for x in ordered[:5] if safe_float(x.get("cost_pct")) is not None]
    if not recent_vals:
        return None
    ser = pd.Series(recent_vals, dtype="float64")
    return {
        "latest_cost_pct": safe_float(latest.get("cost_pct")),
        "latest_year": latest.get("year"),
        "latest_as_of_date_obj": latest.get("as_of_date_obj"),
        "latest_as_of_date": latest.get("as_of_date"),
        "median_5y_pct": float(ser.median()),
        "min_5y_pct": float(ser.min()),
        "max_5y_pct": float(ser.max()),
        "observation_count": len(ordered),
        "observations": ordered[:12],
        "metric_label": "Management cost as % of adjusted NAV",
        "semantic_guard": "explicit_report_management_cost_to_nav_ratio",
        "source_shape": "issuer_report_ratio",
        "source_url": url,
        "quality": 4 if len(ordered) >= 5 else (3 if len(ordered) >= 3 else 1),
    }


def _holding_merge_management_cost_records(records):
    """Merge fresh current ratio and multi-year issuer history without invention."""
    rows = [r for r in (records or []) if r and safe_float(r.get("latest_cost_pct")) is not None]
    if not rows:
        return None

    def _freshness(rec):
        dt = rec.get("latest_as_of_date_obj")
        return (
            dt or datetime(int(rec.get("latest_year") or 1900), 1, 1).date(),
            int(rec.get("quality") or 0),
            int(rec.get("observation_count") or 0),
        )

    freshest = max(rows, key=_freshness)
    by_year = {}
    for rec in rows:
        for obs in rec.get("observations") or []:
            val = safe_float(obs.get("cost_pct"))
            yr = obs.get("year")
            if val is None or not yr:
                continue
            by_year[int(yr)] = val
    ordered = [{"year": y, "cost_pct": by_year[y]} for y in sorted(by_year, reverse=True)]
    if not ordered:
        ordered = freshest.get("observations") or []

    recent_vals = [safe_float(x.get("cost_pct")) for x in ordered[:5] if safe_float(x.get("cost_pct")) is not None]
    if not recent_vals:
        return freshest
    ser = pd.Series(recent_vals, dtype="float64")
    merged = dict(freshest)
    merged.update({
        "latest_cost_pct": safe_float(freshest.get("latest_cost_pct")),
        "latest_year": freshest.get("latest_year"),
        "median_5y_pct": float(ser.median()),
        "min_5y_pct": float(ser.min()),
        "max_5y_pct": float(ser.max()),
        "observation_count": len(ordered),
        "observations": ordered[:12],
        "source_shape": "merged_issuer_management_cost_evidence" if len(rows) > 1 else freshest.get("source_shape"),
        "quality": 4 if len(ordered) >= 5 else (3 if len(ordered) >= 3 else int(freshest.get("quality") or 1)),
    })
    history_sources = []
    for rec in rows:
        u = rec.get("source_url")
        if u and u not in history_sources:
            history_sources.append(u)
    merged["supporting_source_urls"] = history_sources[:4]
    return merged

def _holding_extract_portfolio(html, url):
    if not html:
        return None
    try:
        soup = BeautifulSoup(html, "html.parser")
        strings = [_clean_text(x).replace("\u00a0", " ") for x in soup.stripped_strings]
    except Exception:
        return None

    # Find a bounded holdings section first; this prevents unrelated ownership,
    # return or margin percentages elsewhere on an issuer page from entering the
    # portfolio concentration metric.
    start = None
    for i, value in enumerate(strings):
        folded = _holding_fold_text(value)
        if folded in {"the holdings", "holdings", "portfolio", "portfolj", "vara innehav"} or folded.startswith("the holdings"):
            start = i
            break
    if start is None:
        # Some CMS templates expose only a section heading such as "Our portfolio".
        for i, value in enumerate(strings):
            folded = _holding_fold_text(value)
            if any(term in folded for term in ["our portfolio", "our holdings", "portfolio companies"]):
                start = i
                break
    if start is None:
        return None

    stop_terms = (
        "investment activities", "investments", "investeringsaktiviteter", "investeringar",
        "dividends received", "erhallna utdelningar", "contact", "kontakt",
    )
    end = min(len(strings), start + 140)
    for i in range(start + 4, end):
        folded = _holding_fold_text(strings[i])
        if any(folded.startswith(term) for term in stop_terms):
            end = i
            break
    section = strings[start:end]
    section_text = _clean_text(" ".join(section))

    holdings = []
    by_key = {}
    rejection = {
        "return", "ratio", "margin", "growth", "debt", "yield", "share", "shares",
        "nav", "value", "portfolio", "holding", "holdings", "total", "capital", "votes",
        "company", "companies", "bolag", "andel", "weight",
    }

    def _accept(name, weight):
        name = _clean_text(name)
        try:
            weight = float(str(weight).replace(",", "."))
        except Exception:
            return
        if not name or not (0 < weight <= 70):
            return
        folded = _holding_fold_text(name)
        if not folded or len(name) > 60:
            return
        if any(token in folded.split() for token in rejection):
            return
        # Never turn a portfolio-value/currency node into a company merely
        # because it sits next to the first percentage in a CMS card layout.
        if re.search(r"\b(?:SEK|EUR|USD|GBP|NOK|DKK|CHF)\b", name, flags=re.I) and re.search(r"\d", name):
            return
        if re.search(r"\b(?:bn|billion|mn|million|mio|mrd)\b", folded) and re.search(r"\d", name):
            return
        if re.search(r"\b20\d{2}\b", name):
            return
        key = re.sub(r"\W+", "", folded)
        if not key:
            return
        prev = by_key.get(key)
        row = {"name": name, "weight_pct": weight}
        if prev is None or weight > prev["weight_pct"]:
            by_key[key] = row

    # 1) Prefer real HTML table rows whenever available.
    for row in soup.find_all("tr"):
        cells = [_clean_text(c.get_text(" ", strip=True)) for c in row.find_all(["th", "td"])]
        cells = [c for c in cells if c]
        if len(cells) < 2:
            continue
        pct = None
        pct_idx = None
        for idx, cell in enumerate(cells):
            m = re.fullmatch(r"([0-9]{1,2}(?:[.,][0-9])?)\s*%", cell)
            if m:
                pct = m.group(1); pct_idx = idx; break
        if pct is None:
            continue
        names = [c for idx, c in enumerate(cells) if idx != pct_idx and re.search(r"[A-Za-zÅÄÖåäö]", c)]
        if names:
            # Tables frequently use either Weight|Company or Company|Weight.
            _accept(names[-1] if pct_idx == 0 else names[0], pct)

    # 2) CMS cards can split company and percentage into adjacent nodes.
    for i, value in enumerate(section):
        m = re.fullmatch(r"([0-9]{1,2}(?:[.,][0-9])?)\s*%", value)
        if m:
            # Card layouts are normally Company -> Weight. Use the next node
            # only when the previous node clearly is not a plausible company
            # label (table Weight -> Company is handled above).
            before_count = len(by_key)
            if i > 0:
                _accept(section[i-1], m.group(1))
            if len(by_key) == before_count and i + 1 < len(section):
                _accept(section[i+1], m.group(1))
        m = re.match(r"^(.{1,60}?)\s+([0-9]{1,2}(?:[.,][0-9])?)\s*%$", value)
        if m:
            _accept(m.group(1), m.group(2))
        m = re.match(r"^([0-9]{1,2}(?:[.,][0-9])?)\s*%\s+(.{1,60}?)$", value)
        if m:
            _accept(m.group(2), m.group(1))

    # Deliberately do not infer company names from a fully flattened text
    # stream: adjacent percentages can otherwise be assigned to the next
    # company and inflate Top-N concentration. Table rows, adjacent DOM nodes
    # and one-node "Company 33 %" cards above are the accepted evidence forms.

    holdings = sorted(by_key.values(), key=lambda x: x["weight_pct"], reverse=True)[:12]
    if len(holdings) < 2:
        return None
    weights = [x["weight_pct"] for x in holdings]

    # V63: bind the portfolio reporting date to the same DOM neighborhood that
    # supplied the accepted holding names. A CMS/navigation item named
    # "Portfolio" can appear much earlier in the page than the actual holdings
    # table; using that first heading for provenance can therefore combine fresh
    # weights with an unrelated stale date. Find the densest cluster of accepted
    # holding names and inspect only a narrow window around that cluster.
    as_of = None
    date_binding = "section_fallback"
    accepted_names = {_holding_fold_text(x.get("name")) for x in holdings if x.get("name")}
    name_hits = []
    for idx, value in enumerate(strings):
        folded_value = _holding_fold_text(value)
        if not folded_value:
            continue
        for name_key in accepted_names:
            if not name_key:
                continue
            if (folded_value == name_key or folded_value.startswith(name_key + " ") or
                    folded_value.endswith(" " + name_key) or (" " + name_key + " ") in (" " + folded_value + " ")):
                name_hits.append((idx, name_key))
                break

    cluster_indices = []
    if len(name_hits) >= 2:
        # Sliding 80-node window: broad enough for responsive card/table markup,
        # narrow enough to reject navigation and unrelated historical sections.
        best = None
        left = 0
        for right in range(len(name_hits)):
            while name_hits[right][0] - name_hits[left][0] > 80:
                left += 1
            window = name_hits[left:right + 1]
            unique_names = len({name for _, name in window})
            score = (unique_names, len(window), window[-1][0])
            if best is None or score > best[0]:
                best = (score, [idx for idx, _ in window])
        if best and best[0][0] >= 2:
            cluster_indices = best[1]

    if cluster_indices:
        # V63: the portfolio date on issuer pages is commonly printed directly
        # *after* the holdings table/cards. A newer NAV/share date can sit just
        # above the portfolio block on the same page. Therefore do not choose
        # max(date) from a symmetric window. Bind first to the nearest
        # parseable date following the final accepted holding row.
        first_idx = min(cluster_indices)
        last_idx = max(cluster_indices)

        following_dates = []
        for distance, idx in enumerate(range(last_idx + 1, min(len(strings), last_idx + 22)), start=1):
            dt = _holding_parse_date_text(strings[idx])
            if dt:
                following_dates.append((distance, dt))
        if following_dates:
            following_dates.sort(key=lambda row: row[0])
            as_of = following_dates[0][1]
            date_binding = "holding_cluster_following"
        else:
            preceding_dates = []
            for distance, idx in enumerate(range(first_idx - 1, max(-1, first_idx - 13), -1), start=1):
                if idx < 0:
                    break
                dt = _holding_parse_date_text(strings[idx])
                if dt:
                    preceding_dates.append((distance, dt))
            if preceding_dates:
                preceding_dates.sort(key=lambda row: row[0])
                as_of = preceding_dates[0][1]
                date_binding = "holding_cluster_preceding_fallback"

    if as_of is None:
        for pat in [
            r"([A-Za-zÅÄÖåäö]+\s+\d{1,2},?\s+20\d{2})",
            r"(\d{1,2}\s+[A-Za-zÅÄÖåäö]+\s+20\d{2})",
        ]:
            dates = [_holding_parse_date_text(m.group(1)) for m in re.finditer(pat, section_text)]
            dates = [d for d in dates if d]
            if dates:
                as_of = max(dates)
                break

    portfolio_value_bn = None
    portfolio_currency = None
    value_patterns = [
        r"\b(SEK|EUR|USD|GBP)\s*([0-9]{1,4}(?:[.,][0-9]+)?)\s*(?:bn|billion|mdr)",
        r"\b([0-9]{1,4}(?:[.,][0-9]+)?)\s*(?:bn|billion)\s*(SEK|EUR|USD|GBP)\b",
    ]
    for idx, pat in enumerate(value_patterns):
        m = re.search(pat, section_text, flags=re.I)
        if not m:
            continue
        try:
            if idx == 0:
                ccy, val = m.group(1), m.group(2)
            else:
                val, ccy = m.group(1), m.group(2)
            portfolio_currency = ccy.upper()
            portfolio_value_bn = float(val.replace(",", "."))
        except Exception:
            portfolio_value_bn = None
        break

    return {
        "holdings": holdings,
        "holding_count": len(holdings),
        "top1_pct": weights[0] if weights else None,
        "top2_pct": sum(weights[:2]) if len(weights) >= 2 else None,
        "top3_pct": sum(weights[:3]) if len(weights) >= 3 else None,
        "top4_pct": sum(weights[:4]) if len(weights) >= 4 else None,
        "as_of_date_obj": as_of,
        "as_of_date": _holding_date_display(as_of),
        "date_binding": date_binding,
        "portfolio_value_bn": portfolio_value_bn,
        "portfolio_currency": portfolio_currency,
        "source_url": url,
        "source_kind": "issuer_html",
    }


def _holding_extract_portfolio_from_report_text(text, url):
    """Recover portfolio weights from an issuer-primary report table.

    V88 additionally accepts flattened NAV-overview tables when the report
    explicitly exposes a ``Share of total assets (%)`` column. This is a strong
    semantic shape: company row + ownership ratio + total-asset weight. The
    parser never infers weights from market values when an explicit asset-share
    column is available.
    """
    if not text:
        return None
    raw = str(text).replace("\u00a0", " ")
    lines = [_clean_text(x) for x in raw.splitlines() if _clean_text(x)]
    joined = _clean_text(" ".join(lines) if lines else raw)

    total = None
    for pat in [r"Equities portfolio\s+([0-9]{2,3}(?:[ ,][0-9]{3})+)", r"Total\s+([0-9]{2,3}(?:[ ,][0-9]{3})+)"]:
        m = re.search(pat, joined, flags=re.I)
        if m:
            try:
                total = float(re.sub(r"[ ,]", "", m.group(1)))
            except Exception:
                total = None
            if total:
                break

    values = {}
    in_perf = False
    for line in lines:
        low = line.lower()
        if "performance of the equities portfolio" in low or ("market value" in low and "change in value" in low):
            in_perf = True
            continue
        if in_perf and (low.startswith("total ") or low.startswith("jan ") or low.startswith("investment activities")):
            if values:
                break
        if not in_perf:
            continue
        m = re.match(r"^([A-ZÅÄÖ][A-Za-zÅÄÖåäö&.\- ]{1,35}?)\s+([0-9]{1,3}(?:,[0-9]{3})+)(?:\s|$)", line)
        if not m:
            continue
        name = _clean_text(m.group(1))
        if name.lower() in {"total", "other", "market value", "equities portfolio"}:
            continue
        try:
            value = float(m.group(2).replace(",", ""))
        except Exception:
            continue
        if value > 0:
            values[name] = values.get(name, 0.0) + value

    # Existing line-oriented explicit percentage fallback.
    explicit = {}
    for line in lines:
        m = re.match(r"^([A-ZÅÄÖ][A-Za-zÅÄÖåäö&.\- ]{1,35}?)(?:\s+[ABC])?\s+(?:[0-9][0-9, .]*\s+){2,7}([0-9]{1,2}(?:[.,][0-9])?)$", line)
        if not m:
            continue
        name = re.sub(r"\s+[ABC]$", "", _clean_text(m.group(1)), flags=re.I)
        try:
            w = float(m.group(2).replace(",", "."))
        except Exception:
            continue
        if 0 < w <= 70:
            explicit[name] = max(explicit.get(name, 0.0), w)

    # V88 flat-PDF NAV-overview recovery. The issuer must explicitly label the
    # weight column as share of total assets. We then inspect only the bounded
    # Listed Companies section because those rows have a stable ownership-ratio
    # column immediately before the weight. Other business-area totals are not
    # treated as individual portfolio companies.
    flat_explicit = {}
    folded_joined = _holding_fold_text(joined)
    if "share of total assets" in folded_joined:
        msec = re.search(r"\bListed Companies\b(.{40,12000}?)\bTotal Listed Companies\b", joined, flags=re.I)
        segment = msec.group(1) if msec else ""
        if segment:
            row_pat = re.compile(
                r"(?P<name>[A-ZÅÄÖ][A-Za-zÅÄÖåäö&.\- ]{1,45}?)(?:\d+\))?\s+"
                r"(?P<shares>[0-9]{1,3}(?:[ ,][0-9]{3})+)\s+"
                r"(?P<capital>[0-9]{1,3}(?:[.,][0-9])?)/(?P<votes>[0-9]{1,3}(?:[.,][0-9])?)\s+"
                r"(?P<weight>[0-9]{1,2}(?:[.,][0-9])?)(?=\s+-?[0-9])",
                flags=re.I,
            )
            reject_names = {"listed companies", "total listed companies", "adjusted values", "reported values"}
            for m in row_pat.finditer(segment):
                name = _clean_text(m.group("name"))
                if _holding_fold_text(name) in reject_names:
                    continue
                try:
                    w = float(m.group("weight").replace(",", "."))
                except Exception:
                    continue
                if 0 < w <= 70:
                    flat_explicit[name] = max(flat_explicit.get(name, 0.0), w)

    holdings = []
    source_shape = None
    if len(flat_explicit) >= 2:
        holdings = [{"name": n, "weight_pct": w} for n, w in flat_explicit.items()]
        source_shape = "report_nav_overview_asset_share"
    elif total and len(values) >= 2:
        holdings = [{"name": n, "weight_pct": round(100.0 * v / total, 0)} for n, v in values.items() if 0.005 <= v / total <= 0.70]
        source_shape = "report_market_value_derived"
    elif len(explicit) >= 2:
        holdings = [{"name": n, "weight_pct": w} for n, w in explicit.items()]
        source_shape = "report_explicit_percentage_rows"

    holdings = sorted(holdings, key=lambda x: x["weight_pct"], reverse=True)[:12]
    if len(holdings) < 2:
        return None
    weights = [x["weight_pct"] for x in holdings]

    # Bind the portfolio date to the same report, preferring explicit natural
    # language dates and then common m/d yyyy report-table headers.
    as_of = None
    runtime_today = datetime.now().date()
    date_candidates = []
    for pat in [
        r"([A-Za-zÅÄÖåäö]+\s+\d{1,2},?\s+20\d{2})",
        r"(\d{1,2}\s+[A-Za-zÅÄÖåäö]+\s+20\d{2})",
    ]:
        for dm in re.finditer(pat, joined[:8000]):
            dt = _holding_parse_date_text(dm.group(1))
            if dt and dt <= runtime_today:
                date_candidates.append(dt)
    for mm, dd, yy in re.findall(r"\b(\d{1,2})/(\d{1,2})\s+(20\d{2})\b", joined[:8000]):
        try:
            dt = datetime(int(yy), int(mm), int(dd)).date()
        except Exception:
            dt = None
        if dt and dt <= runtime_today:
            date_candidates.append(dt)
    if date_candidates:
        as_of = max(date_candidates)

    return {
        "holdings": holdings,
        "holding_count": len(holdings),
        "top1_pct": weights[0],
        "top2_pct": sum(weights[:2]),
        "top3_pct": sum(weights[:3]) if len(weights) >= 3 else None,
        "top4_pct": sum(weights[:4]) if len(weights) >= 4 else None,
        "as_of_date_obj": as_of,
        "as_of_date": _holding_date_display(as_of),
        "date_binding": "issuer_report_metric_block",
        "source_url": url,
        "source_kind": "issuer_report",
        "source_shape": source_shape,
    }

def _holding_link_rank(text):
    dt = _holding_parse_date_text(text)
    return dt.toordinal() if dt else 0


def _holding_fold_text(value):
    text = unicodedata.normalize("NFKD", _clean_text(value).lower())
    text = "".join(ch for ch in text if not unicodedata.combining(ch))
    return re.sub(r"[^a-z0-9]+", " ", text).strip()


def _holding_identity_terms(company_name):
    folded = _holding_fold_text(company_name)
    stop = {"ab", "publ", "inc", "corp", "corporation", "company", "co", "ltd", "limited", "plc", "ag", "sa", "se", "nv", "group", "holding", "holdings", "investment"}
    return [t for t in folded.split() if len(t) >= 5 and t not in stop][:6]


def _holding_search_result_matches_company(item, company_name):
    terms = _holding_identity_terms(company_name)
    if not terms:
        return False
    hay = _holding_fold_text(" ".join([
        _clean_text((item or {}).get("title")),
        _clean_text((item or {}).get("snippet")),
        _clean_text((item or {}).get("url")),
    ]))
    return any(term in hay for term in terms)


def _holding_bootstrap_company_domain(company_name, deadline=None):
    """Resolve an issuer domain only from repeated identity-matching web results.

    Search results are discovery metadata only; they never supply NAV/debt/portfolio
    values.  The actual metrics still require a fetched issuer-owned page.
    """
    name = _clean_text(company_name)
    if not name:
        return None, []
    queries = [
        f'"{name}" "net asset value"',
        f'"{name}" official website',
    ]
    excluded = (
        "yahoo.", "reuters.", "bloomberg.", "marketscreener.", "morningstar.",
        "simplywall.st", "marketwatch.", "google.", "wikipedia.", "nasdaq.com",
        "businesswire.", "globenewswire.", "prnewswire.", "stockanalysis.",
    )
    rows = []
    counts = {}
    for query in queries:
        for item in _duckduckgo_html_search(query, max_results=6, deadline=deadline):
            if not _holding_search_result_matches_company(item, name):
                continue
            host = _normalize_host(item.get("url"))
            if not host or any(x in host for x in excluded):
                continue
            rows.append(item)
            counts[host] = counts.get(host, 0) + 1
    if not counts:
        return None, rows
    ranked = sorted(counts.items(), key=lambda x: (x[1], -len(x[0])), reverse=True)
    best_host, best_count = ranked[0]
    # Require repetition unless there is only one high-confidence exact-domain result
    # whose host itself carries a distinctive company identity term.
    host_fold = _holding_fold_text(best_host).replace(" ", "")
    identity_in_host = any(term in host_fold for term in _holding_identity_terms(name))
    if best_count < 2 and not identity_in_host:
        return None, rows
    return best_host, rows


def _holding_semantic_source_search(company_domain, company_name, deadline=None, needed_kinds=None, query_offset=0, max_queries_per_kind=1):
    """Discover issuer-owned primary URLs only for still-missing evidence classes.

    V2.21.56 keeps search as discovery metadata only and lets the caller fetch
    each returned issuer-owned page immediately before launching another query.
    """
    if not company_domain:
        return {"nav": [], "report": [], "portfolio": [], "cost": [], "all": []}
    name = _clean_text(company_name)
    query_map = {
        "nav": [
            f'site:{company_domain} "{name}" "net asset value"',
            f'site:{company_domain} "net asset value" "per share"',
        ],
        "report": [
            f'site:{company_domain} "{name}" "interim report"',
        ],
        "portfolio": [
            f'site:{company_domain} "{name}" portfolio holdings',
        ],
        "cost": [
            f'site:{company_domain} "management cost, % of portfolio value"',
            f'site:{company_domain} "key ratios" "management cost"',
            f'site:{company_domain} "management cost" "portfolio value"',
            f'site:{company_domain} "key ratios"',
            f'site:{company_domain} "cost ratio" portfolio',
            f'site:{company_domain} "forvaltningskostnad"',
        ],
    }
    wanted = [k for k in (needed_kinds or ["nav", "report", "portfolio", "cost"]) if k in query_map]
    out = {"nav": [], "report": [], "portfolio": [], "cost": [], "all": []}
    seen = set()
    for kind in wanted:
        queries = query_map[kind]
        begin = max(0, int(query_offset or 0))
        stop = min(len(queries), begin + max(1, int(max_queries_per_kind or 1)))
        for query in queries[begin:stop]:
            for item in _duckduckgo_html_search(query, max_results=6, deadline=deadline):
                url = _clean_text(item.get("url"))
                if not url or url in seen or not _holding_same_issuer_url(url, company_domain):
                    continue
                if name and not _holding_search_result_matches_company(item, name):
                    semantic = _holding_fold_text(" ".join([_clean_text(item.get("title")), _clean_text(item.get("snippet"))]))
                    if not any(term in semantic for term in ["net asset value", "interim report", "portfolio", "holdings", "management cost", "cost ratio", "expense ratio"]):
                        continue
                seen.add(url)
                row = (url, _clean_text(item.get("title")) or _clean_text(item.get("snippet")))
                out[kind].append(row)
                out["all"].append(row)
    return out


def _discover_listed_holding_primary_snapshot(website, company_name=None, symbol=None):
    result = {"available": False, "nav": None, "debt": None, "portfolio": None, "holding_cost": None, "nav_history": [], "diagnostics": []}
    started_at = time.monotonic()
    # V2.21.58 gives each evidence class its own bounded budget. The overall
    # safety cap prevents runaway research, but elapsed time in one class does
    # not shrink the next class's local window.
    overall_deadline = started_at + 38.0
    timings = {"bootstrap": 0.0, "homepage": 0.0, "report": 0.0, "nav": 0.0, "portfolio": 0.0, "cost": 0.0, "history": 0.0, "fallback": 0.0}

    def _evidence_deadline(seconds):
        now = time.monotonic()
        if now >= overall_deadline:
            return None
        return min(overall_deadline, now + max(0.50, float(seconds)))

    def _timed_bucket(bucket, started):
        timings[bucket] = timings.get(bucket, 0.0) + max(0.0, time.monotonic() - started)
    raw_website = _clean_text(website)
    company_domain = _extract_company_domain(raw_website)
    bootstrap_rows = []
    if not company_domain:
        bootstrap_started = time.monotonic()
        bootstrap_deadline = _evidence_deadline(3.0)
        company_domain, bootstrap_rows = _holding_bootstrap_company_domain(company_name, deadline=bootstrap_deadline or overall_deadline)
        _timed_bucket("bootstrap", bootstrap_started)
        if company_domain:
            raw_website = f"https://{company_domain}/"
            result["diagnostics"].append(
                f"Holding Primary Source V65: Issuer-Domain aus wiederholten Company-Identity-Suchtreffern verifiziert ({company_domain})."
            )
        else:
            result["diagnostics"].append(
                "Holding Primary Source V65: Provider-Website fehlt und kein ausreichend verifizierter Issuer-Domain-Bootstrap gelungen."
            )
            return result
    parsed = urlparse(raw_website if "://" in raw_website else "https://" + raw_website)
    scheme = parsed.scheme or "https"
    host = parsed.netloc or company_domain
    root = f"{scheme}://{host}".rstrip("/")

    # V81: Trust the provider-owned URL/root before guessing locale paths.
    # Some issuers (for example modern CMS/IR sites) expose all evidence from
    # the root and return empty/404 content for synthetic /en-gb/ or /en/ paths.
    # Explicit provider subpaths remain first when Yahoo already supplies one.
    path = (parsed.path or "/").strip()
    canonical_candidates = []
    if path and path != "/":
        canonical_candidates.append(raw_website)
    for url in [raw_website, root + "/", root + "/en-gb/", root + "/en/"]:
        if url and url not in canonical_candidates and _holding_same_issuer_url(url, company_domain):
            canonical_candidates.append(url)
    canonical_url = canonical_candidates[0] if canonical_candidates else raw_website
    locale_fallback_urls = [u for u in canonical_candidates[1:] if u != canonical_url]

    fetched = {}
    nav_links = []
    report_links = []
    archive_links = []
    portfolio_links = []
    cost_links = []
    history_table_links = []
    portfolio_best = None

    def _portfolio_candidate_rank(rec):
        if not rec:
            return (datetime(1900, 1, 1).date(), 0, 0, 0)
        as_of = rec.get("as_of_date_obj") or datetime(1900, 1, 1).date()
        holding_count = int(rec.get("holding_count") or 0)
        has_value = 1 if safe_float(rec.get("portfolio_value_bn")) is not None else 0
        is_html = 1 if rec.get("source_kind") == "issuer_html" else 0
        return (as_of, holding_count, has_value, is_html)

    def _portfolio_is_stale(rec, max_age_days=120):
        if not rec or not rec.get("as_of_date_obj"):
            return True
        try:
            age = (datetime.now().date() - rec.get("as_of_date_obj")).days
            return age > max_age_days
        except Exception:
            return True

    debt_records = []
    holding_cost_records = []
    cost_candidate_count = 0
    cost_fetch_attempts = 0
    cost_parse_success = 0
    cost_semantic_rejections = 0
    cost_report_fetch_attempts = 0
    cost_report_parse_success = 0
    cost_candidate_trace = []

    def _latest_debt_date(records):
        dates = [r.get("as_of_date_obj") for r in (records or []) if r and r.get("as_of_date_obj")]
        return max(dates) if dates else None

    def _debt_records_are_stale(records, max_age_days=120):
        latest = _latest_debt_date(records)
        if latest is None:
            return True
        try:
            return (datetime.now().date() - latest).days > max_age_days
        except Exception:
            return True

    nav_records = []
    nav_release_fetch_attempts = 0
    nav_release_fetch_success = 0
    nav_release_marker_pages = 0
    nav_release_parse_probes = []

    def _looks_like_report_link(url, label):
        folded_label = _holding_fold_text(label)
        folded_url = _holding_fold_text(url)
        if any(term in folded_label for term in [
            "interim report", "half year", "six months", "year end report", "annual report",
            "delarsrapport", "bokslutsrapport", "quarterly report", "quarter report", "arsredovisning",
        ]):
            return True
        # V81: IR hubs frequently label current reports only as “Q2 Report”.
        if re.search(r"\bq[1-4]\s+(?:report|rapport|results?|presentation)\b", folded_label, flags=re.I):
            return True
        if any(term in folded_url for term in [
            "interim", "half year", "delarsrapport", "delarsrapporter",
            "quarterly report", "financial report", "reports interim",
        ]):
            return True
        # Issuers often label the direct PDF only "2026 6M Jul 8, 2026".
        if str(url).lower().split("?", 1)[0].endswith(".pdf"):
            if re.search(r"\b20\d{2}\b", label or "") and re.search(r"\b(?:3m|6m|9m|12m|q[1-4]|h[12])\b", label or "", flags=re.I):
                return True
        return False

    def _looks_like_nav_link(url, label):
        hay = _holding_fold_text(" ".join([label or "", url or ""]))
        return any(term in hay for term in ["net asset value", "substansvarde", "nav per share"])

    def fetch(url, allow_pdf=False, referer=None, phase_deadline=None):
        active_deadline = phase_deadline if phase_deadline is not None else overall_deadline
        if not url:
            return None
        # V58: only successful fetches are sticky. A timeout/empty response from
        # an earlier short evidence window may be retried in a later fresh window.
        if url in fetched and fetched.get(url):
            return fetched.get(url)
        html = ""
        resolved = url
        if allow_pdf and str(url).lower().split("?", 1)[0].endswith(".pdf"):
            # Existing generic issuer-document bridge validates issuer ownership,
            # redirects and a real PDF signature before extracting text.
            doc_diag = []
            try:
                doc = _bank_fetch_official_document(
                    url, company_domain, deadline=active_deadline, timeout=3.6,
                    diagnostics=doc_diag, referer=referer,
                )
            except Exception:
                doc = None
            if doc and doc.get("text"):
                html = doc.get("text") or ""
                resolved = doc.get("url") or url
                result["diagnostics"].append(
                    f"Holding Primary PDF Bridge V65: issuer-eigener Reporttext geladen ({len(html)} Zeichen)."
                )
                nonlocal portfolio_best
                report_port = _holding_extract_portfolio_from_report_text(html, resolved)
                if report_port and (portfolio_best is None or _portfolio_candidate_rank(report_port) > _portfolio_candidate_rank(portfolio_best)):
                    portfolio_best = report_port
                    result["diagnostics"].append("Holding Report-Portfolio Recovery V63: Portfoliokonzentration aus issuer-eigenem Reporttext rekonstruiert.")
        else:
            html, final_url = _fetch_html(url, timeout=3.6, deadline=active_deadline)
            resolved = final_url or url
            if resolved and not _holding_same_issuer_url(resolved, company_domain):
                html = ""
            # Issuer CMS/WAF fallback, only for the already verified domain.
            if not html and _holding_same_issuer_url(url, company_domain) and _research_budget_ok(active_deadline, reserve=0.35):
                effective_timeout = _bounded_timeout(active_deadline, 3.6)
                if effective_timeout is not None:
                    try:
                        headers = dict(_request_headers())
                        headers.update({
                            "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
                            "Accept-Language": "en-US,en;q=0.9,sv;q=0.7",
                            "Cache-Control": "no-cache",
                        })
                        response = requests.get(
                            url, headers=headers,
                            timeout=(min(1.8, effective_timeout), effective_timeout),
                            allow_redirects=True,
                        )
                        response.raise_for_status()
                        ctype = (response.headers.get("Content-Type") or "").lower()
                        retry_resolved = response.url or url
                        if ("html" in ctype or "text" in ctype or "xml" in ctype) and _holding_same_issuer_url(retry_resolved, company_domain):
                            html = response.text[:1_500_000]
                            resolved = retry_resolved
                    except Exception:
                        pass
        fetched[url] = html
        if html and resolved != url:
            fetched[resolved] = html
        return html

    def collect_links(base_url, html):
        if not html:
            return
        nonlocal portfolio_best
        try:
            soup = BeautifulSoup(html, "html.parser")
        except Exception:
            return
        port = _holding_extract_portfolio(html, base_url)
        if port and (portfolio_best is None or _portfolio_candidate_rank(port) > _portfolio_candidate_rank(portfolio_best)):
            portfolio_best = port
        for a in soup.find_all("a", href=True):
            label = _clean_text(a.get_text(" ", strip=True))
            low = label.lower()
            url = urljoin(base_url, a.get("href"))
            if not _holding_same_issuer_url(url, company_domain):
                continue
            if _looks_like_nav_link(url, label):
                nav_links.append((url, label))
            if _looks_like_report_link(url, label):
                report_links.append((url, label))
            portfolio_hay = _holding_fold_text(" ".join([label or "", url or ""]))
            if any(term in portfolio_hay for term in [
                "portfolio", "holdings", "the holdings", "our holdings", "portfolj",
                "ownership and development", "ownership development", "shareholdings"
            ]):
                portfolio_links.append((url, label))
            cost_hay = _holding_fold_text(" ".join([label or "", url or ""]))
            if any(term in cost_hay for term in [
                "management cost", "cost ratio", "expense ratio", "key ratios", "key figures",
                "forvaltningskostnad", "nyckeltal", "industrivarden in figures"
            ]):
                cost_links.append((url, label))
            history_hay = _holding_fold_text(" ".join([label or "", url or ""]))
            if any(term in history_hay for term in [
                "financials", "financial data", "financial information", "key figures", "key ratios",
                "quarterly data", "quarterly figures", "historical figures", "financial history",
                "nyckeltal", "finansiell data", "finansiell information"
            ]):
                history_table_links.append((url, label))
            if any(term in low for term in ["press release", "press releases", "news", "media", "regulatory releases"]):
                archive_links.append((url, label))

    def _dated_link_rank(url, label):
        hay = _clean_text(" ".join([label or "", str(url or "").replace("-", " ").replace("/", " ")]))
        dates = []
        for pat in [
            r"([A-Za-zÅÄÖåäö]+\s+\d{1,2},?\s+20\d{2})",
            r"(\d{1,2}\s+[A-Za-zÅÄÖåäö]+\s+20\d{2})",
        ]:
            for m in re.finditer(pat, hay):
                dt = _holding_parse_date_text(m.group(1))
                if dt: dates.append(dt)
        latest = max(dates) if dates else datetime(1900, 1, 1).date()
        return (latest, _holding_link_rank(label), len(label or ""))

    def dedupe_sorted(items):
        seen_urls = set(); out = []
        for url, label in sorted(items, key=lambda x: _dated_link_rank(x[0], x[1]), reverse=True):
            if url in seen_urls:
                continue
            seen_urls.add(url); out.append((url, label))
        return out

    def _cost_source_rank(url, label):
        # V73: management-cost evidence needs a metric-specific source order.
        # Generic dated-link ranking is actively harmful here because undated
        # Accounting Policies pages can outrank the actual Key Ratios table.
        raw = " ".join([_clean_text(label), str(url or "").replace("-", " ").replace("_", " ").replace("/", " ")])
        hay = _holding_fold_text(raw)
        score = 0
        if "management cost" in hay and any(term in hay for term in ["portfolio value", "portfolio", "nav", "net asset value"]):
            score += 140
        if any(term in hay for term in ["key ratios", "key figures", "nyckeltal"]):
            score += 120
        if any(term in hay for term in ["in figures", "figures"]):
            score += 35
        if any(term in hay for term in ["cost ratio", "expense ratio", "forvaltningskostnad"]):
            score += 45
        # Policy/tax prose may mention management cost but does not define the
        # recurring portfolio-value ratio. Keep it available only as a remote
        # fallback; never let it consume the first bounded fetch slots.
        if any(term in hay for term in ["accounting polic", "tax polic", "taxation", "tax", "policy", "policies"]):
            score -= 180
        return (score, len(_clean_text(label)))

    def dedupe_cost_sorted(items):
        seen_urls = set(); out = []
        for url, label in sorted(items, key=lambda x: _cost_source_rank(x[0], x[1]), reverse=True):
            if url in seen_urls:
                continue
            seen_urls.add(url); out.append((url, label))
        return out

    def _record_cost_trace(url, label, status):
        if len(cost_candidate_trace) >= 8:
            return
        path = urlparse(str(url or "")).path or "/"
        short_label = _clean_text(label)[:70]
        cost_candidate_trace.append(f"{status}:{path}" + (f" [{short_label}]" if short_label else ""))

    def consume_priority_links(referer=None, phase_deadline=None, include_nav=True, include_report=True):
        # NAV first, then the latest report. V54 allows fallback callers to pass
        # a phase-local deadline so a slow fallback cannot consume later budget.
        active_deadline = phase_deadline if phase_deadline is not None else overall_deadline
        if include_nav:
            for url, _ in dedupe_sorted(nav_links)[:3]:
                if any((r.get("source_url") == url) for r in nav_records):
                    continue
                if not _research_budget_ok(active_deadline, reserve=0.55):
                    break
                html = fetch(url, referer=referer, phase_deadline=active_deadline)
                rec = _holding_extract_current_nav_record(html, url)
                if rec:
                    nav_records.append(rec)
                collect_links(url, html)
                if nav_records:
                    break
        if include_report:
            for url, _ in dedupe_sorted(report_links)[:2]:
                if any((r.get("source_url") == url) for r in debt_records):
                    continue
                if not _research_budget_ok(active_deadline, reserve=0.55):
                    break
                html = fetch(url, allow_pdf=True, referer=referer, phase_deadline=active_deadline)
                rec = _holding_extract_debt_ratio(html, url)
                if rec:
                    debt_records.append(rec)
                # V81: a report landing page can be the issuer's primary NAV/share
                # evidence hub as well. Parse it once with the strict current-NAV
                # guard instead of forcing a separate semantic-search round trip.
                nav_rec = _holding_extract_current_nav_record(html, url)
                if nav_rec and not any((r.get("source_url") == url) for r in nav_records):
                    nav_records.append(nav_rec)
                # HTML reports can expose further issuer links; PDF text simply has none.
                # V61 deliberately keeps evaluating the bounded priority set: the
                # first valid ratio can belong to an older year-end report while a
                # newer interim report is also linked by the issuer. Final selection
                # remains newest as-of date, never DOM order.
                collect_links(url, html)

    # Phase 1: canonical issuer page receives its own budget.
    homepage_started = time.monotonic()
    homepage_deadline = _evidence_deadline(3.8)
    html = fetch(canonical_url, phase_deadline=homepage_deadline or overall_deadline)
    if html:
        rec = _holding_extract_current_nav_record(html, canonical_url)
        if rec:
            nav_records.append(rec)
        collect_links(canonical_url, html)
    _timed_bucket("homepage", homepage_started)

    # Exact issuer-primary links exposed by the homepage get independent
    # evidence windows. A slow PDF/report no longer consumes NAV time.
    if not nav_records and nav_links:
        nav_started = time.monotonic()
        direct_nav_deadline = _evidence_deadline(3.2)
        if direct_nav_deadline is not None:
            consume_priority_links(referer=canonical_url, phase_deadline=direct_nav_deadline, include_nav=True, include_report=False)
        _timed_bucket("nav", nav_started)

    if not debt_records and report_links:
        report_started = time.monotonic()
        report_deadline = _evidence_deadline(4.8)
        if report_deadline is not None:
            consume_priority_links(referer=canonical_url, phase_deadline=report_deadline, include_nav=False, include_report=True)
        _timed_bucket("report", report_started)

    def _nav_parse_probe(html):
        """Compact diagnostics only; never supplies valuation values."""
        if not html:
            return "empty"
        try:
            psoup = BeautifulSoup(html, "html.parser")
            ptext = _clean_text(" ".join(_clean_text(x) for x in psoup.stripped_strings)).replace("\u00a0", " ")
            ptext = unicodedata.normalize("NFKC", ptext)
            ptext = re.sub(r"[\u200b\u200c\u200d\u2060\ufeff\u00ad]", "", ptext)
            pfold = _holding_fold_text(ptext)
            marker = any(term in pfold for term in ["net asset value", "substansvarde", "nav per share"])
            probe_label_re = r"net(?:[\W_]+)asset(?:[\W_]+)value|substansv[aä]rd(?:e|et)|\bnav\b"
            probe_positions = [m.start() for m in re.finditer(probe_label_re, ptext, flags=re.I)]
            flex_labels = len(probe_positions)
            currency = bool(re.search(r"\b(?:SEK|EUR|USD|GBP|kr|kronor)\b", ptext, flags=re.I))
            per_share = bool(re.search(r"per\s+(?:share|aktie)", ptext, flags=re.I))
            local_eligible = 0
            for ppos in probe_positions:
                pwindow = ptext[max(0, ppos - 260): min(len(ptext), ppos + 2400)]
                if (re.search(r"\b(?:SEK|EUR|USD|GBP|kr|kronor)\b", pwindow, flags=re.I)
                        and re.search(r"per\s+(?:share|aktie)", pwindow, flags=re.I)
                        and re.search(r"(?<![0-9])[0-9]{1,6}(?:[.,][0-9]{1,2})?(?![0-9])", pwindow)):
                    local_eligible += 1
            # Report number candidates only as a count so diagnostics do not
            # accidentally become a second unvalidated data source.
            nums = len(re.findall(r"(?<![0-9])[0-9]{1,6}(?:[.,][0-9]{1,2})?(?![0-9])", ptext))
            return f"marker={'ja' if marker else 'nein'},flexLabel={flex_labels},localEligible={local_eligible},ccy={'ja' if currency else 'nein'},perShare={'ja' if per_share else 'nein'},nums={nums}"
        except Exception:
            return "probe-error"

    # V2.21.60: issuer archive is the preferred NAV recovery bridge.  The
    # archive supplies links only; the NAV value is parsed from the linked
    # issuer-owned release itself. This avoids dependence on a search engine.
    if not nav_records and archive_links:
        nav_started = time.monotonic()
        archive_nav_deadline = _evidence_deadline(4.8)
        archive_hits = 0
        if archive_nav_deadline is not None:
            for archive_url, _ in dedupe_sorted(archive_links)[:2]:
                if not _research_budget_ok(archive_nav_deadline, reserve=1.55):
                    break
                ahtml = fetch(archive_url, referer=canonical_url, phase_deadline=archive_nav_deadline)
                collect_links(archive_url, ahtml)
                candidates = dedupe_sorted(nav_links)
                archive_hits = len(candidates)
                for nav_url, _ in candidates[:3]:
                    if not _research_budget_ok(archive_nav_deadline, reserve=0.35):
                        break
                    nav_release_fetch_attempts += 1
                    nhtml = fetch(nav_url, referer=archive_url, phase_deadline=archive_nav_deadline)
                    if nhtml:
                        nav_release_fetch_success += 1
                        marker_text = _holding_fold_text(BeautifulSoup(nhtml, "html.parser").get_text(" ", strip=True))
                        if any(term in marker_text for term in ["net asset value", "substansvarde", "nav per share"]):
                            nav_release_marker_pages += 1
                    rec = _holding_extract_current_nav_record(nhtml, nav_url)
                    if rec:
                        nav_records.append(rec)
                        break
                    elif nhtml and len(nav_release_parse_probes) < 3:
                        nav_release_parse_probes.append(_nav_parse_probe(nhtml))
                if nav_records:
                    break
        _timed_bucket("nav", nav_started)
        result["diagnostics"].append(
            f"Holding Issuer-Archive NAV Recovery V65: NAV-Links={archive_hits}, "
            f"ReleaseFetch={nav_release_fetch_success}/{nav_release_fetch_attempts}, Marker={nav_release_marker_pages}, "
            f"NAV={'ja' if nav_records else 'nein'}" +
            ((" · ParseProbe=" + "; ".join(nav_release_parse_probes)) if (not nav_records and nav_release_parse_probes) else "") + "."
        )

    # Phase 2 (V2.21.60): each still-missing critical evidence class receives
    # a fresh local budget, independent of time already spent on other classes.
    semantic_counts = {"nav": 0, "report": 0, "portfolio": 0, "cost": 0}

    def _search_deadline_with_fetch_reserve(slot_end, fetch_reserve=2.20, max_search_window=1.80):
        now = time.monotonic()
        if slot_end is None:
            return None
        latest_search_end = slot_end - max(0.55, float(fetch_reserve))
        if latest_search_end <= now + 0.35:
            return None
        return min(latest_search_end, now + max(0.45, float(max_search_window)))

    def _semantic_search_and_fetch(kind, slot_end, query_offset=0, fetch_limit=2):
        nonlocal cost_candidate_count, cost_fetch_attempts, cost_parse_success, cost_semantic_rejections
        search_deadline = _search_deadline_with_fetch_reserve(slot_end)
        if search_deadline is None:
            return False
        rows = _holding_semantic_source_search(
            company_domain, company_name, deadline=search_deadline,
            needed_kinds=[kind], query_offset=query_offset, max_queries_per_kind=1,
        )
        found = rows.get(kind) or []
        semantic_counts[kind] += len(found)
        if kind == "nav":
            nav_links.extend(found)
            candidates = dedupe_sorted(found)[:fetch_limit]
            for url, _ in candidates:
                if time.monotonic() >= slot_end:
                    break
                html = fetch(url, referer=canonical_url, phase_deadline=slot_end)
                rec = _holding_extract_current_nav_record(html, url)
                if rec:
                    nav_records.append(rec)
                    collect_links(url, html)
                    return True
                collect_links(url, html)
            return bool(nav_records)
        if kind == "report":
            report_links.extend(found)
            candidates = dedupe_sorted(found)[:fetch_limit]
            found_valid = False
            for url, _ in candidates:
                if time.monotonic() >= slot_end:
                    break
                html = fetch(url, allow_pdf=True, referer=canonical_url, phase_deadline=slot_end)
                rec = _holding_extract_debt_ratio(html, url)
                if rec:
                    debt_records.append(rec)
                    found_valid = True
                collect_links(url, html)
            return found_valid or bool(debt_records)
        if kind == "portfolio":
            portfolio_links.extend(found)
            candidates = dedupe_sorted(found)[:fetch_limit]
            starting_rank = _portfolio_candidate_rank(portfolio_best)
            for url, _ in candidates:
                if time.monotonic() >= slot_end:
                    break
                html = fetch(url, referer=canonical_url, phase_deadline=slot_end)
                collect_links(url, html)
                if portfolio_best is not None and (
                    not _portfolio_is_stale(portfolio_best)
                    or _portfolio_candidate_rank(portfolio_best) > starting_rank
                ):
                    return True
            return portfolio_best is not None and not _portfolio_is_stale(portfolio_best)
        if kind == "cost":
            cost_links.extend(found)
            cost_candidate_count += len(found)
            candidates = dedupe_cost_sorted(found)[:fetch_limit]
            for url, label in candidates:
                if time.monotonic() >= slot_end:
                    break
                cost_fetch_attempts += 1
                html = fetch(url, referer=canonical_url, phase_deadline=slot_end)
                rec = _holding_extract_management_cost_ratio(html, url)
                if not rec:
                    cost_semantic_rejections += 1
                    _record_cost_trace(url, label, "reject")
                if rec:
                    cost_parse_success += 1
                    holding_cost_records.append(rec)
                    _record_cost_trace(url, label, "accept")
                    collect_links(url, html)
                    return True
                collect_links(url, html)
            return bool(holding_cost_records)
        return False

    # NAV is the valuation anchor and gets a full independent recovery budget.
    if not nav_records:
        nav_started = time.monotonic()
        nav_slot_end = _evidence_deadline(5.0)
        if nav_slot_end is not None:
            _semantic_search_and_fetch("nav", nav_slot_end, query_offset=0, fetch_limit=2)
            if not nav_records and _research_budget_ok(nav_slot_end, reserve=2.65):
                _semantic_search_and_fetch("nav", nav_slot_end, query_offset=1, fetch_limit=2)
        _timed_bucket("nav", nav_started)

    # Portfolio receives its own fresh window when missing OR when the first
    # homepage/CMS snapshot carries a stale or absent reporting date. A usable
    # older snapshot stays as fallback, but it no longer suppresses the issuer's
    # dedicated portfolio page.
    portfolio_refresh_requested = _portfolio_is_stale(portfolio_best)
    portfolio_refresh_before = (portfolio_best or {}).get("as_of_date_obj")
    if portfolio_best is None or portfolio_refresh_requested:
        portfolio_started = time.monotonic()
        portfolio_slot_end = _evidence_deadline(4.5)
        if portfolio_slot_end is not None:
            for url, _ in dedupe_sorted(portfolio_links)[:2]:
                if not _research_budget_ok(portfolio_slot_end, reserve=1.10):
                    break
                phtml = fetch(url, referer=canonical_url, phase_deadline=portfolio_slot_end)
                collect_links(url, phtml)
                if portfolio_best is not None and not _portfolio_is_stale(portfolio_best):
                    break
            if portfolio_best is None or _portfolio_is_stale(portfolio_best):
                _semantic_search_and_fetch("portfolio", portfolio_slot_end, query_offset=0, fetch_limit=2)
        _timed_bucket("portfolio", portfolio_started)
    portfolio_refresh_after = (portfolio_best or {}).get("as_of_date_obj")

    # Debt normally arrives from the direct PDF bridge. V61 also refreshes a
    # stale-but-valid ratio once, because an older year-end report must not
    # suppress a newer interim report. The old record remains a fallback.
    debt_refresh_requested = (not debt_records) or _debt_records_are_stale(debt_records)
    debt_refresh_before = _latest_debt_date(debt_records)
    if debt_refresh_requested:
        report_started = time.monotonic()
        debt_slot_end = _evidence_deadline(4.5)
        if debt_slot_end is not None:
            _semantic_search_and_fetch("report", debt_slot_end, query_offset=0, fetch_limit=2)
        _timed_bucket("report", report_started)
    debt_refresh_after = _latest_debt_date(debt_records)

    # V70: issuer-primary recurring holding/management cost evidence. This is
    # deliberately separate from generic SG&A/FCF and gets its own bounded slot.
    cost_started = time.monotonic()
    cost_slot_end = _evidence_deadline(5.4)
    if cost_slot_end is not None:
        # V89 precedence: issuer reports are evaluated before legacy website/key-figures
        # candidates. A slow or semantically irrelevant HTML page must not consume the
        # bounded slot before the already discovered current/annual reports are parsed.
        # V88: issuer reports are a first-class cost source when the report
        # explicitly binds management cost to NAV. Current/interim reports are
        # normally already cached from leverage/portfolio work, so try those
        # before spending the remaining cost budget on web search. Annual
        # reports may need a holding-only tail-page extraction for the five-year
        # key-ratio summary.
        report_cost_candidates = dedupe_sorted(report_links)[:6]
        def _report_cost_priority(row):
            url, label = row
            hay = _holding_fold_text(" ".join([label or "", url or ""]))
            is_annual = "annual report" in hay or "arsredovisning" in hay
            is_current = bool(re.search(r"\bq[1-4]\b|interim|half year|six months", hay, flags=re.I))
            return (2 if is_current else (1 if is_annual else 0), _dated_link_rank(url, label))
        report_cost_candidates.sort(key=_report_cost_priority, reverse=True)
        report_cost_seen = set()
        current_report_cost_found = False
        annual_report_cost_found = False
        for url, label in report_cost_candidates:
            if len(report_cost_seen) >= 4 or not _research_budget_ok(cost_slot_end, reserve=0.65):
                break
            hay = _holding_fold_text(" ".join([label or "", url or ""]))
            is_annual = "annual report" in hay or "arsredovisning" in hay
            is_current = bool(re.search(r"\bq[1-4]\b|interim|half year|six months", hay, flags=re.I))
            if is_annual and annual_report_cost_found:
                continue
            if is_current and current_report_cost_found:
                continue
            if url in report_cost_seen:
                continue
            report_cost_seen.add(url)
            rtext = fetched.get(url) or ""
            if is_annual:
                # Re-fetch with tail pages even if a head-only copy exists.
                cost_report_fetch_attempts += 1
                diag = []
                try:
                    doc = _bank_fetch_official_document(
                        url, company_domain, deadline=cost_slot_end, timeout=4.2,
                        diagnostics=diag, referer=canonical_url, include_tail=True,
                    )
                except Exception:
                    doc = None
                if doc and doc.get("text"):
                    rtext = doc.get("text") or rtext
            elif not rtext:
                cost_report_fetch_attempts += 1
                rtext = fetch(url, allow_pdf=True, referer=canonical_url, phase_deadline=cost_slot_end) or ""
            if not rtext:
                continue
            crec = _holding_extract_management_cost_ratio_from_report_text(rtext, url)
            if crec:
                holding_cost_records.append(crec)
                cost_report_parse_success += 1
                _record_cost_trace(url, label, "accept-report")
                if is_annual:
                    annual_report_cost_found = True
                if is_current:
                    current_report_cost_found = True
            elif is_annual or "report" in hay:
                _record_cost_trace(url, label, "reject-report")
            if current_report_cost_found and annual_report_cost_found:
                break

        # V89: legacy issuer HTML/key-figures evidence is fallback-only after the
        # report pass. It may enrich a sparse report history but can no longer starve
        # the current/annual report parsers of their evidence budget.
        merged_probe = _holding_merge_management_cost_records(holding_cost_records)
        merged_obs = int((merged_probe or {}).get("observation_count") or 0)
        if merged_obs < 3:
            initial_cost_candidates = dedupe_cost_sorted(cost_links)[:3]
            cost_candidate_count += len(initial_cost_candidates)
            for url, label in initial_cost_candidates:
                if not _research_budget_ok(cost_slot_end, reserve=0.85):
                    break
                cost_fetch_attempts += 1
                chtml = fetch(url, referer=canonical_url, phase_deadline=cost_slot_end)
                crec = _holding_extract_management_cost_ratio(chtml, url)
                if not crec:
                    cost_semantic_rejections += 1
                    _record_cost_trace(url, label, "reject")
                else:
                    cost_parse_success += 1
                    holding_cost_records.append(crec)
                    _record_cost_trace(url, label, "accept")
                    break
                collect_links(url, chtml)

        # Search is now fallback-only after already discovered issuer reports/HTML.
        merged_probe = _holding_merge_management_cost_records(holding_cost_records)
        merged_obs = int((merged_probe or {}).get("observation_count") or 0)
        if merged_obs < 3:
            _semantic_search_and_fetch("cost", cost_slot_end, query_offset=0, fetch_limit=2)
            merged_probe = _holding_merge_management_cost_records(holding_cost_records)
            merged_obs = int((merged_probe or {}).get("observation_count") or 0)
        if merged_obs < 3 and _research_budget_ok(cost_slot_end, reserve=2.10):
            _semantic_search_and_fetch("cost", cost_slot_end, query_offset=1, fetch_limit=2)
            merged_probe = _holding_merge_management_cost_records(holding_cost_records)
            merged_obs = int((merged_probe or {}).get("observation_count") or 0)
        if merged_obs < 3 and _research_budget_ok(cost_slot_end, reserve=1.35):
            _semantic_search_and_fetch("cost", cost_slot_end, query_offset=2, fetch_limit=1)
    _timed_bucket("cost", cost_started)
    result["holding_cost_adapter_diagnostic"] = (
        f"Holding Management-Cost Adapter V89: Candidates={cost_candidate_count}, "
        f"HTMLFetch={cost_fetch_attempts}, HTMLParsed={cost_parse_success}, SemanticReject={cost_semantic_rejections}, "
        f"ReportFetch={cost_report_fetch_attempts}, ReportParsed={cost_report_parse_success}, "
        f"Evidence={'yes' if holding_cost_records else 'no'}"
        + (("; CandidateTrace=" + " | ".join(cost_candidate_trace)) if cost_candidate_trace else "")
    )

    if any(semantic_counts.values()):
        result["diagnostics"].append(
            "Holding Independent-Evidence Recovery V65: "
            f"NAV-Treffer={semantic_counts['nav']}, "
            f"Portfolio-Treffer={semantic_counts['portfolio']}, "
            f"Report-Treffer={semantic_counts['report']}, "
            f"Cost-Treffer={semantic_counts['cost']}; "
            "NAV, Report/Debt, Portfolio und Holdingkosten besitzen voneinander unabhängige Zeitfenster."
        )

    # Phase 3/4: locale/archive are last-resort fallbacks and have their own
    # small windows. They cannot take time away from the evidence budgets above.
    if not (nav_records and debt_records and portfolio_best is not None):
        fallback_started = time.monotonic()
        locale_phase_end = _evidence_deadline(1.4)
        if locale_phase_end is not None:
            for url in locale_fallback_urls[:1]:
                if not _research_budget_ok(locale_phase_end, reserve=0.55):
                    break
                html = fetch(url, phase_deadline=locale_phase_end)
                if not html:
                    continue
                rec = _holding_extract_current_nav_record(html, url)
                if rec:
                    nav_records.append(rec)
                collect_links(url, html)
                consume_priority_links(referer=url, phase_deadline=locale_phase_end)
                if nav_records and debt_records and portfolio_best is not None:
                    break
        if not (nav_records and debt_records and portfolio_best is not None):
            archive_phase_end = _evidence_deadline(1.2)
            if archive_phase_end is not None:
                for url, _ in dedupe_sorted(archive_links)[:1]:
                    if not _research_budget_ok(archive_phase_end, reserve=0.55):
                        break
                    ahtml = fetch(url, phase_deadline=archive_phase_end)
                    collect_links(url, ahtml)
                    consume_priority_links(referer=url, phase_deadline=archive_phase_end)
                    break
        _timed_bucket("fallback", fallback_started)

    # V65: issuer-primary historical NAV premium/discount evidence.  This is
    # calibration evidence only; it must never unlock Fair Value by itself.
    history_started = time.monotonic()
    history_records = []
    history_archive_fetches = 0
    history_candidate_count = 0
    history_release_attempts = 0
    history_release_parsed = 0
    history_release_with_class_prices = 0
    history_expected_date_matches = 0
    history_pair_probes = []
    history_table_fetches = 0
    history_table_records = 0
    history_table_sources = []
    history_report_table_fetches = 0
    history_report_table_records = 0
    history_report_table_sources = []

    history_target_cls = None
    history_sym_base = str(symbol or "").upper().split(".", 1)[0]
    history_target_m = re.search(r"(?:-|_)([A-Z])$", history_sym_base)
    if history_target_m:
        history_target_cls = history_target_m.group(1)

    def _history_series_ready(records):
        dates = sorted({r.get("as_of_date_obj") for r in (records or []) if r.get("as_of_date_obj")})
        return bool(len(dates) >= 6 and len(dates) >= 2 and (dates[-1] - dates[0]).days >= 150)

    def _history_table_candidate_urls():
        items = []
        seen = set()
        for u, lab in history_table_links:
            if u and u not in seen and _holding_same_issuer_url(u, company_domain):
                seen.add(u); items.append((u, lab or "financial/key figures"))
        # Generic same-domain fallbacks. They are discovery URLs only; records
        # are accepted solely if the fetched page contains the strict table.
        generic_paths = [
            "/investors-media/financials", "/investors/financials",
            "/investor-relations/financials", "/financials",
            "/investors/key-figures", "/investor-relations/key-figures",
        ]
        for gp in generic_paths:
            u = root + gp
            if u not in seen:
                seen.add(u); items.append((u, "generic issuer financials candidate"))
        return items

    def _history_pair_probe(rec, expected_date=None, source_url=None):
        """Normalize one issuer release into a target-class NAV/close pairing decision."""
        rec = rec or {}
        nav_value = safe_float(rec.get("nav_per_share"))
        as_of_obj = rec.get("as_of_date_obj")
        prices = rec.get("same_date_class_prices") or {}
        target_close = safe_float(prices.get(history_target_cls)) if history_target_cls else None
        currency = str(rec.get("currency") or "").upper() or None
        reasons = []
        if as_of_obj is None:
            reasons.append("missing_nav_date")
        if nav_value is None:
            reasons.append("missing_nav")
        elif nav_value <= 0:
            reasons.append("invalid_nav")
        if not history_target_cls:
            reasons.append("missing_target_class")
        elif target_close is None:
            reasons.append("missing_target_class_close")
        elif target_close <= 0:
            reasons.append("invalid_target_class_close")
        if currency is None:
            reasons.append("missing_currency")
        if expected_date is not None and as_of_obj is not None and as_of_obj != expected_date:
            reasons.append("nav_date_conflict")

        # Publication date and paired closing-price date are provenance only.
        # The paired close may legitimately be the preceding trading day when
        # the NAV date is a weekend/month-end holiday.
        accepted = not reasons
        return {
            "accepted": accepted,
            "reason": "accepted" if accepted else ",".join(reasons),
            "expected_date": _holding_date_display(expected_date),
            "as_of_date": rec.get("as_of_date"),
            "published_date": rec.get("published_date"),
            "price_date": rec.get("paired_price_date"),
            "nav_per_share": nav_value,
            "currency": currency,
            "target_class": history_target_cls,
            "target_close": target_close,
            "available_classes": ",".join(sorted(str(k) for k in prices.keys())) if prices else "–",
            "source_url": source_url or rec.get("source_url"),
        }

    def _concrete_nav_release_link(url, label):
        """True only for a dated issuer NAV-release/article candidate, not generic NAV navigation."""
        hay = _holding_fold_text(" ".join([label or "", str(url or "").replace("-", " ").replace("_", " ")]))
        if not any(term in hay for term in ["net asset value on", "substansvarde", "substansvardet"]):
            return False
        # Article/release links should carry a date in label or URL. This rejects
        # generic NAV landing pages that polluted the V64 historical top-N list.
        if re.search(r"\b20\d{2}\b", hay):
            return True
        return bool(re.search(r"\b(?:january|february|march|april|may|june|july|august|september|october|november|december)\b", hay))

    def _derived_archive_index_urls():
        """Derive generic issuer-owned parent/year archive pages from concrete NAV release URLs."""
        candidates = []
        for u, lab in dedupe_sorted(archive_links):
            candidates.append((u, lab or "issuer archive"))
        source_urls = []
        source_urls.extend([r.get("source_url") for r in nav_records if r and r.get("source_url")])
        source_urls.extend([u for u, _ in dedupe_sorted(nav_links)[:12]])
        seen = {u for u, _ in candidates}
        for source_url in source_urls:
            try:
                parsed_u = urlparse(source_url or "")
                if not parsed_u.scheme or not parsed_u.netloc or not _holding_same_issuer_url(source_url, company_domain):
                    continue
                parts = [p for p in (parsed_u.path or "/").split("/") if p]
                if len(parts) < 2:
                    continue
                # Drop concrete article/file slug. Parent is commonly a year archive.
                parent_parts = parts[:-1]
                parent_path = "/" + "/".join(parent_parts) + "/"
                parent_url = f"{parsed_u.scheme}://{parsed_u.netloc}{parent_path}"
                if parent_url not in seen:
                    seen.add(parent_url); candidates.append((parent_url, "derived parent archive"))
                # If parent ends in a four-digit year, also visit its collection root.
                if parent_parts and re.fullmatch(r"20\d{2}", parent_parts[-1]):
                    root_parts = parent_parts[:-1]
                    if root_parts:
                        root_path = "/" + "/".join(root_parts) + "/"
                        root_url = f"{parsed_u.scheme}://{parsed_u.netloc}{root_path}"
                        if root_url not in seen:
                            seen.add(root_url); candidates.append((root_url, "derived archive root"))
            except Exception:
                continue
        return candidates

    if nav_records:
        # Reuse already parsed NAV releases first.
        for rec in nav_records:
            if rec and rec.get("as_of_date_obj") and (rec.get("same_date_class_prices") or {}):
                history_records.append(rec)

        history_slot_end = _evidence_deadline(10.5)
        if history_slot_end is not None:
            # V85: quarterly key-figure tables are a first-class historical route.
            # They are often both faster and more complete than crawling individual
            # NAV releases, especially for holdings that report NAV quarterly.
            for table_url, _table_label in _history_table_candidate_urls()[:4]:
                if history_table_fetches >= 2 or not _research_budget_ok(history_slot_end, reserve=5.0):
                    break
                thtml = fetch(table_url, referer=canonical_url, phase_deadline=history_slot_end)
                if not thtml:
                    continue
                history_table_fetches += 1
                trecs = _holding_extract_quarterly_nav_price_history(thtml, table_url, target_class=history_target_cls)
                if trecs:
                    history_table_sources.append(table_url)
                    history_table_records += len(trecs)
                    history_records.extend(trecs)
                    if _history_series_ready(history_records):
                        break

            # V86: if the website Key Figures table lags behind, reuse the latest
            # issuer quarterly/interim report. A single multi-period report can
            # contribute the current and prior quarter-end NAV/share + price pairs.
            # This route is historical-only and never feeds nav_records.
            if not _history_series_ready(history_records):
                for report_url, _report_label in dedupe_sorted(report_links)[:4]:
                    if _history_series_ready(history_records):
                        break
                    rtext = fetched.get(report_url) or ""
                    if not rtext:
                        if history_report_table_fetches >= 2 or not _research_budget_ok(history_slot_end, reserve=4.0):
                            continue
                        rtext = fetch(report_url, allow_pdf=True, referer=canonical_url, phase_deadline=history_slot_end) or ""
                        if rtext:
                            history_report_table_fetches += 1
                    else:
                        # Cached PDF/report text was already fetched for NAV/debt;
                        # count it as one report-table attempt without network cost.
                        history_report_table_fetches += 1
                    if not rtext:
                        continue
                    rrecs = _holding_extract_report_nav_price_history(rtext, report_url, target_class=history_target_cls)
                    if rrecs:
                        history_report_table_sources.append(report_url)
                        history_report_table_records += len(rrecs)
                        history_records.extend(rrecs)
                        if _history_series_ready(history_records):
                            break

            # Existing archive-first dated NAV release route remains fallback and
            # can enrich a partial quarterly table series.
            # V65 is archive-first: a pre-existing CMS NAV-link count is not proof
            # that the historical release index has been visited. Fetch up to two
            # verified issuer-owned index candidates before ranking release links.
            for archive_url, _ in _derived_archive_index_urls()[:4]:
                if history_archive_fetches >= 2 or not _research_budget_ok(history_slot_end, reserve=5.0):
                    break
                ahtml = fetch(archive_url, referer=canonical_url, phase_deadline=history_slot_end)
                if not ahtml:
                    continue
                history_archive_fetches += 1
                collect_links(archive_url, ahtml)
                strict_now = [(u, l) for u, l in dedupe_sorted(nav_links) if _concrete_nav_release_link(u, l)]
                # Six dated release candidates are enough for the first robust series.
                if len(strict_now) >= 6:
                    break

            strict_candidates_all = [(u, l) for u, l in dedupe_sorted(nav_links) if _concrete_nav_release_link(u, l)]
            history_candidate_count = len(strict_candidates_all)

            # V66: one network candidate per NAV as-of date before fetching.
            # English/Swedish twins for the same issuer release otherwise consume
            # the bounded history slot without extending the observation span.
            strict_candidates = []
            seen_candidate_dates = set()
            undated_candidates = []
            for u, l in strict_candidates_all:
                # V68: de-duplicate by the NAV as-of date encoded in the release
                # title/slug, never by the archive row's publication date.
                dt = _holding_nav_asof_hint_from_release(u, l)
                if dt:
                    if dt in seen_candidate_dates:
                        continue
                    seen_candidate_dates.add(dt)
                    strict_candidates.append((u, l))
                else:
                    undated_candidates.append((u, l))
            strict_candidates.extend(undated_candidates)

            seen_hist_urls = {r.get("source_url") for r in history_records if r.get("source_url")}
            for hist_url, hist_label in strict_candidates[:14]:
                if hist_url in seen_hist_urls:
                    continue
                if not _research_budget_ok(history_slot_end, reserve=0.35):
                    break
                history_release_attempts += 1
                # V68: strict historical parsing is anchored to the semantic NAV
                # date in the concrete release title/URL. Publication date is
                # provenance only and must never become expected_hist_date.
                expected_hist_date = _holding_nav_asof_hint_from_release(hist_url, hist_label)
                hhtml = fetch(hist_url, referer=canonical_url, phase_deadline=history_slot_end)
                if not hhtml:
                    history_pair_probes.append({
                        "accepted": False,
                        "reason": "fetch_failed",
                        "expected_date": _holding_date_display(expected_hist_date),
                        "as_of_date": None,
                        "published_date": None,
                        "price_date": None,
                        "nav_per_share": None,
                        "currency": None,
                        "target_class": history_target_cls,
                        "target_close": None,
                        "available_classes": "–",
                        "source_url": hist_url,
                    })
                    continue
                hrec = _holding_extract_nav_record(hhtml, hist_url, expected_as_of_date=expected_hist_date)
                if not hrec:
                    history_pair_probes.append({
                        "accepted": False,
                        "reason": "nav_release_parse_failed",
                        "expected_date": _holding_date_display(expected_hist_date),
                        "as_of_date": None,
                        "published_date": None,
                        "price_date": None,
                        "nav_per_share": None,
                        "currency": None,
                        "target_class": history_target_cls,
                        "target_close": None,
                        "available_classes": "–",
                        "source_url": hist_url,
                    })
                    continue
                history_release_parsed += 1
                if expected_hist_date is not None and hrec.get("as_of_date_obj") == expected_hist_date:
                    history_expected_date_matches += 1
                if hrec.get("same_date_class_prices"):
                    history_release_with_class_prices += 1

                pair_probe = _history_pair_probe(hrec, expected_date=expected_hist_date, source_url=hist_url)
                history_pair_probes.append(pair_probe)
                seen_hist_urls.add(hist_url)

                # V83: Historical calibration and the live current-NAV snapshot
                # are physically isolated. The broad historical release parser
                # may recover same-date class closes and legacy release layouts,
                # but its record must NEVER be inserted directly into nav_records.
                # If this same release is also useful as current evidence, it has
                # to independently pass the strict explicit NAV/share extractor.
                strict_release_rec = _holding_extract_current_nav_record(hhtml, hist_url)
                if strict_release_rec:
                    # Same-document historical close metadata can enrich a strict
                    # current record only when NAV value/date agree. It cannot
                    # change the strict NAV value or date.
                    same_date = (
                        strict_release_rec.get("as_of_date_obj") is not None
                        and hrec.get("as_of_date_obj") is not None
                        and strict_release_rec.get("as_of_date_obj") == hrec.get("as_of_date_obj")
                    )
                    same_nav = (
                        safe_float(strict_release_rec.get("nav_per_share")) is not None
                        and safe_float(hrec.get("nav_per_share")) is not None
                        and abs(safe_float(strict_release_rec.get("nav_per_share")) - safe_float(hrec.get("nav_per_share"))) <= 1e-6
                    )
                    if same_date and same_nav:
                        strict_release_rec["same_date_class_prices"] = dict(hrec.get("same_date_class_prices") or {})
                        strict_release_rec["paired_price_date_obj"] = hrec.get("paired_price_date_obj")
                        strict_release_rec["paired_price_date"] = hrec.get("paired_price_date")
                    nav_records.append(strict_release_rec)
                if hrec.get("as_of_date_obj") and (hrec.get("same_date_class_prices") or {}):
                    history_records.append(hrec)
                unique_dates = {r.get("as_of_date_obj") for r in history_records if r.get("as_of_date_obj")}
                # Stop once the readiness requirement is satisfied; this keeps
                # startup bounded while still producing a statistically useful span.
                if len(unique_dates) >= 6:
                    dts = [d for d in unique_dates if d]
                    if len(dts) >= 2 and (max(dts) - min(dts)).days >= 150:
                        break

    # Deduplicate by NAV date, keeping the richer record if the same release was
    # reachable through more than one issuer URL.
    by_hist_date = {}
    for rec in history_records:
        dt = rec.get("as_of_date_obj")
        if not dt:
            continue
        prev = by_hist_date.get(dt)
        rank = (len(rec.get("same_date_class_prices") or {}), int(rec.get("quality") or 0))
        prev_rank = (len((prev or {}).get("same_date_class_prices") or {}), int((prev or {}).get("quality") or 0)) if prev else (-1, -1)
        if prev is None or rank > prev_rank:
            by_hist_date[dt] = rec
    result["nav_history"] = [by_hist_date[k] for k in sorted(by_hist_date.keys(), reverse=True)]
    result["historical_pair_probes"] = history_pair_probes[:12]
    _timed_bucket("history", history_started)

    # V86: count valid target-class pairs across every historical route, not
    # only standalone release probes. Quarterly/report-table records are already
    # validated pairs and must be reflected in diagnostics as well.
    target_class_records = sum(
        1 for rec in (result.get("nav_history") or [])
        if history_target_cls and safe_float((rec.get("same_date_class_prices") or {}).get(history_target_cls)) is not None
    )
    if result.get("nav_history") or history_pair_probes:
        rejection_counts = {}
        for probe in history_pair_probes:
            if probe.get("accepted"):
                continue
            for reason in str(probe.get("reason") or "unknown").split(","):
                rejection_counts[reason] = rejection_counts.get(reason, 0) + 1
        reject_summary = ",".join(f"{k}:{v}" for k, v in sorted(rejection_counts.items())) or "none"
        result["diagnostics"].append(
            f"Holding Historical NAV Calibration V87: QuarterlyTableFetch={history_table_fetches}, QuarterlyTableRecords={history_table_records}, "
            f"ReportTableFetch={history_report_table_fetches}, ReportTableRecords={history_report_table_records}, ArchiveFetch={history_archive_fetches}, "
            f"Candidates={history_candidate_count}, UniqueDateCandidates={len(strict_candidates) if 'strict_candidates' in locals() else 0}, "
            f"ReleaseFetch={history_release_attempts}, Parsed={history_release_parsed}, DateAnchored={history_expected_date_matches}, "
            f"ClassPricePages={history_release_with_class_prices}, NavHistoryRecords={len(result.get('nav_history') or [])}, "
            f"TargetClass={history_target_cls or '–'}, ValidTargetPairs={target_class_records}, Rejections={reject_summary}, "
            f"AsOfDates={','.join([str(r.get('as_of_date') or '–') for r in (result.get('nav_history') or [])[:8]])}; "
            "publication date and paired trading-date close are provenance only and are not required to equal the NAV as-of date."
        )

    # V83 final live-NAV gate: historical/broad records can never win current
    # snapshot selection. Only candidates produced by the strict current NAV
    # extractor carry current_nav_guard and are eligible here.
    strict_nav_records = [r for r in nav_records if r.get("current_nav_guard")]
    if strict_nav_records:
        strict_nav_records.sort(
            key=lambda r: (
                r.get("as_of_date_obj") or datetime(1900,1,1).date(),
                int(r.get("quality") or 0),
                1 if r.get("published_date_obj") else 0,
            ),
            reverse=True,
        )
        result["nav"] = strict_nav_records[0]
    if debt_records:
        debt_records.sort(key=lambda r: (r.get("as_of_date_obj") or datetime(1900,1,1).date()), reverse=True)
        result["debt"] = debt_records[0]
    result["portfolio"] = portfolio_best
    _pdiag = result.get("portfolio") or {}
    if _pdiag:
        _top1 = safe_float(_pdiag.get("top1_pct")); _top2 = safe_float(_pdiag.get("top2_pct"))
        _top3 = safe_float(_pdiag.get("top3_pct")); _top4 = safe_float(_pdiag.get("top4_pct"))
        def _pd(v):
            return f"{v:.1f}%" if v is not None else "–"
        result["portfolio_adapter_diagnostic"] = (
            "Holding Concentration Evidence V89: "
            f"Evidence=yes, SourceKind={_pdiag.get('source_kind') or '–'}, Shape={_pdiag.get('source_shape') or '–'}, "
            f"Top1={_pd(_top1)}, Top2={_pd(_top2)}, Top3={_pd(_top3)}, Top4={_pd(_top4)}, "
            f"AsOf={_pdiag.get('as_of_date') or '–'}."
        )
    else:
        result["portfolio_adapter_diagnostic"] = "Holding Concentration Evidence V89: Evidence=no."
    if holding_cost_records:
        result["holding_cost"] = _holding_merge_management_cost_records(holding_cost_records)
        c = result["holding_cost"] or {}
        result["diagnostics"].append(
            f"Holding Management-Cost Evidence V88: Latest={safe_float(c.get('latest_cost_pct')):.3f}% "
            f"({c.get('latest_as_of_date') or c.get('latest_year') or '–'}), Median5Y={safe_float(c.get('median_5y_pct')):.3f}%, "
            f"Obs={int(c.get('observation_count') or 0)}, Source=issuer-primary."
        )
    result["available"] = bool(result.get("nav"))
    total_elapsed = max(0.0, time.monotonic() - started_at)
    safety_remaining = max(0.0, overall_deadline - time.monotonic())
    nav_dt = (result.get("nav") or {}).get("as_of_date") or "–"
    debt_dt = (result.get("debt") or {}).get("as_of_date") or "–"
    portfolio_dt = (result.get("portfolio") or {}).get("as_of_date") or "–"
    refresh_txt = "ja" if portfolio_refresh_requested else "nein"
    refresh_improved = bool(portfolio_refresh_after and (not portfolio_refresh_before or portfolio_refresh_after > portfolio_refresh_before))
    debt_refresh_txt = "ja" if debt_refresh_requested else "nein"
    debt_refresh_improved = bool(debt_refresh_after and (not debt_refresh_before or debt_refresh_after > debt_refresh_before))
    result["diagnostics"].append(
        "Holding Snapshot-Date Coherence V65: "
        f"NAV={nav_dt} · Debt={debt_dt} · Portfolio={portfolio_dt} · "
        f"DebtRefresh={debt_refresh_txt}/{('verbessert' if debt_refresh_improved else 'unveraendert')} · "
        f"PortfolioRefresh={refresh_txt}/{('verbessert' if refresh_improved else 'unveraendert')} · "
        f"PortfolioDateBinding={(result.get('portfolio') or {}).get('date_binding') or '–'}."
    )

    result["diagnostics"].append(
        "Holding Primary Source V65: "
        f"Domain={company_domain}, ProviderWebsite={'ja' if website else 'nein'}, Seiten={len([v for v in fetched.values() if v])}, "
        f"NAV={'ja' if result.get('nav') else 'nein'}, DebtRatio={'ja' if result.get('debt') else 'nein'}, "
        f"Portfolio={'ja' if result.get('portfolio') else 'nein'}, HistoryNAV={len(result.get('nav_history') or [])}, SafetyRest={safety_remaining:.2f}s."
    )
    strict_trace = []
    for _r in sorted(
        [r for r in nav_records if r.get("current_nav_guard")],
        key=lambda r: (r.get("as_of_date_obj") or datetime(1900,1,1).date(), int(r.get("quality") or 0)),
        reverse=True,
    )[:5]:
        _path = urlparse(str(_r.get("source_url") or "")).path or "/"
        _nv = safe_float(_r.get("nav_per_share"))
        _strict_txt = f"{_nv:.2f}" if _nv is not None else "–"
        strict_trace.append(
            f"{_strict_txt} {_r.get('currency') or '–'}@{_r.get('as_of_date') or '–'}"
            f"[{_r.get('semantic_guard') or _r.get('current_nav_guard') or 'strict'}:{_path}]"
        )
    result["diagnostics"].append(
        "Holding Current NAV Semantic Guard V84: "
        f"Canonical={canonical_url} · ReportLinks={len(dedupe_sorted(report_links))} · NAVLinks={len(dedupe_sorted(nav_links))} · "
        f"CurrentCandidates={len([r for r in nav_records if r.get('current_nav_guard')])} · "
        f"SelectedGuard={(result.get('nav') or {}).get('current_nav_guard') or 'strict-only/no-current-nav'}"
        + ((" · CurrentTrace=" + " | ".join(strict_trace)) if strict_trace else "")
        + " · Historical broad-parser records are isolated and cannot overwrite the live snapshot; future NAV dates are rejected."
    )
    result["diagnostics"].append(
        "Holding Timing V65: "
        f"Bootstrap={timings['bootstrap']:.2f}s · Homepage={timings['homepage']:.2f}s · "
        f"Report={timings['report']:.2f}s · NAV={timings['nav']:.2f}s · "
        f"Portfolio={timings['portfolio']:.2f}s · Cost={timings['cost']:.2f}s · History={timings['history']:.2f}s · "
        f"Fallback={timings['fallback']:.2f}s · Gesamt={total_elapsed:.2f}s."
    )
    return result


@st.cache_data(ttl=3600, show_spinner=False)
def _discover_listed_holding_primary_snapshot_cached(website, company_name=None, symbol=None, cache_epoch="v22196_holding_family_release_v92"):
    # V89: explicit cache epoch prevents V87/V88 snapshots from surviving a parser/evidence-layer release.
    return _discover_listed_holding_primary_snapshot(website, company_name=company_name, symbol=symbol)


def _holding_infer_share_class(symbol, class_prices=None):
    sym = str(symbol or "").upper().strip()
    base = sym.split(".", 1)[0]
    m = re.search(r"(?:-|_)([A-Z])$", base)
    if m:
        return m.group(1)
    prices = class_prices or {}
    keys = [str(k).upper() for k, v in prices.items() if safe_float(v) is not None]
    return keys[0] if len(keys) == 1 else None


def _holding_build_historical_nav_calibration(nav_history, symbol):
    observations = []
    inferred_class = _holding_infer_share_class(symbol)
    for rec in (nav_history or []):
        nav = safe_float(rec.get("nav_per_share"))
        prices = rec.get("same_date_class_prices") or {}
        share_class = inferred_class or _holding_infer_share_class(symbol, prices)
        price = safe_float(prices.get(share_class)) if share_class else None
        if nav is None or nav <= 0 or price is None or price <= 0:
            continue
        premium = (price / nav - 1.0) * 100.0
        if premium < -60.0 or premium > 120.0:
            continue
        observations.append({
            "as_of_date": rec.get("as_of_date"),
            "as_of_date_obj": rec.get("as_of_date_obj"),
            "price_date": rec.get("paired_price_date") or rec.get("as_of_date"),
            "nav_per_share": nav,
            "paired_close": price,
            "premium_discount_pct": premium,
            "share_class": share_class,
            "currency": rec.get("currency"),
            "source_url": rec.get("source_url"),
        })
    # One observation per NAV date, newest first.
    dedup = {}
    for row in observations:
        key = row.get("as_of_date_obj") or row.get("as_of_date")
        if key not in dedup:
            dedup[key] = row
    observations = sorted(dedup.values(), key=lambda r: r.get("as_of_date_obj") or datetime(1900,1,1).date(), reverse=True)
    vals = [safe_float(r.get("premium_discount_pct")) for r in observations if safe_float(r.get("premium_discount_pct")) is not None]
    if not vals:
        return {"available": False, "observations": observations, "share_class": inferred_class}
    ser = pd.Series(vals, dtype="float64")
    dates = [r.get("as_of_date_obj") for r in observations if r.get("as_of_date_obj")]
    span_days = (max(dates) - min(dates)).days if len(dates) >= 2 else 0
    ready = bool(len(vals) >= 6 and span_days >= 150 and inferred_class)
    return {
        "available": True,
        "ready": ready,
        "share_class": inferred_class or observations[0].get("share_class"),
        "observation_count": len(vals),
        "span_days": span_days,
        "start_date": _holding_date_display(min(dates)) if dates else None,
        "end_date": _holding_date_display(max(dates)) if dates else None,
        "median_pct": float(ser.median()),
        "q1_pct": float(ser.quantile(0.25)),
        "q3_pct": float(ser.quantile(0.75)),
        "min_pct": float(ser.min()),
        "max_pct": float(ser.max()),
        "mean_pct": float(ser.mean()),
        "observations": observations,
        "method": "Issuer-primary NAV/share history · issuer-paired share-class price · class-matched historical premium/discount",
    }


def _holding_family_peer_universe(symbol):
    """Reusable Stockholm listed-holding peer template with bounded fallback.

    V77 separates *preferred* peers from *fallback* peers.  The guard always
    researches the preferred cluster first and only expands when fewer than
    three valid issuer-primary NAV/share observations survive.  The metadata
    contains identities and issuer roots only; no NAV or market values are
    hard-coded.
    """
    own = str(symbol or "").strip().upper()
    if not own.endswith(".ST"):
        return []
    universe = [
        {"symbol": "INVE-B.ST", "name": "Investor AB", "website": "https://www.investorab.com/", "tier": "preferred"},
        {"symbol": "LUND-B.ST", "name": "L E Lundbergföretagen AB", "website": "https://www.lundbergforetagen.se/en/", "tier": "preferred"},
        {"symbol": "LATO-B.ST", "name": "Investment AB Latour", "website": "https://www.latour.se/en/", "tier": "preferred"},
        {"symbol": "BURE.ST", "name": "Bure Equity AB", "website": "https://www.bure.se/en/home-en", "tier": "preferred"},
        {"symbol": "SVOL-B.ST", "name": "Svolder AB", "website": "https://svolder.se/", "tier": "fallback"},
        {"symbol": "CRED-A.ST", "name": "Creades AB", "website": "https://www.creades.se/", "tier": "fallback"},
        {"symbol": "INDU-C.ST", "name": "AB Industrivärden", "website": "https://www.industrivarden.se/en-gb/", "tier": "preferred"},
    ]
    return [row for row in universe if not _same_canonical_issuer_symbol(row.get("symbol"), own)]


def _holding_peer_symbol_share_class(symbol):
    """Best-effort market share-class hint from Nordic Yahoo-style symbols."""
    sym = _clean_text(symbol).upper()
    m = re.search(r"-([A-Z])(?:\.[A-Z]+)?$", sym)
    return m.group(1) if m else None


def _holding_peer_last_price_snapshot(symbol):
    """Return latest usable market-price snapshot with trading-date provenance."""
    out = {"price": None, "price_date_obj": None, "price_date": None, "currency": None}
    try:
        t = yf.Ticker(symbol)
        # Prefer actual history so the price always carries an explicit market date.
        try:
            hist = t.history(period="7d", auto_adjust=False)
            if hist is not None and not hist.empty and "Close" in hist:
                vals = pd.to_numeric(hist["Close"], errors="coerce").dropna()
                if not vals.empty:
                    idx = vals.index[-1]
                    value = safe_float(vals.iloc[-1])
                    if value is not None and value > 0:
                        dt = None
                        try:
                            dt = idx.date()
                        except Exception:
                            try:
                                dt = pd.Timestamp(idx).date()
                            except Exception:
                                dt = None
                        out["price"] = value
                        out["price_date_obj"] = dt
                        out["price_date"] = _holding_date_display(dt) if dt else None
        except Exception:
            pass
        # Currency is provenance only; never infer it from the NAV source.
        try:
            fi = t.fast_info
            cur = getattr(fi, "currency", None)
            if cur:
                out["currency"] = str(cur).upper()
            if out["price"] is None:
                for attr in ["last_price", "previous_close"]:
                    value = safe_float(getattr(fi, attr, None))
                    if value is not None and value > 0:
                        out["price"] = value
                        break
        except Exception:
            pass
    except Exception:
        pass
    return out


def _holding_discover_peer_nav_record(peer, deadline):
    """Discover a fresh issuer-primary peer NAV/share record.

    V77 treats HTML fact pages, press releases, IR/report indexes and issuer PDFs
    as standardized routes into the same strict NAV/share parser.  Search results
    are discovery metadata only; a value is accepted only after the issuer-owned
    destination itself is fetched and parsed.  Broader IR/press navigation is
    intentionally generic so Investor/Bure-like site structures do not require
    ticker-specific parser branches.
    """
    symbol = _clean_text((peer or {}).get("symbol"))
    name = _clean_text((peer or {}).get("name"))
    website = _clean_text((peer or {}).get("website"))
    domain = _extract_company_domain(website)
    if not domain:
        return None, "domain_missing"

    candidates = []
    records = []
    discovery_seen = set()

    def _consider(payload, resolved_url, label="", route="html"):
        if not payload:
            return
        rec = _holding_extract_peer_nav_record(payload, resolved_url)
        if not rec:
            return
        as_of = rec.get("as_of_date_obj")
        if not as_of:
            # Some CMS pages place an ISO as-of date only in the release title or
            # slug.  This remains issuer-primary because resolved_url/label belong
            # to the fetched issuer page; no search snippet value is accepted.
            as_of = _holding_nav_asof_hint_from_release(resolved_url, label)
            if as_of is None:
                as_of = _holding_parse_date_text(label) or _holding_parse_date_text(resolved_url)
            if as_of is not None:
                rec["as_of_date_obj"] = as_of
                rec["as_of_date"] = _holding_date_display(as_of)
                rec["quality"] = int(rec.get("quality") or 0) + 1
        if not as_of:
            return
        try:
            age = (datetime.now().date() - as_of).days
        except Exception:
            age = 9999
        # Quarterly NAVs remain usable for family comparison for roughly five
        # months; high-frequency NAV publishers naturally surface fresher facts.
        if -7 <= age <= 155:
            row = dict(rec)
            row["nav_age_days"] = age
            row["peer_symbol"] = symbol
            row["peer_name"] = name
            row["candidate_label"] = label
            row["discovery_route"] = route
            records.append(row)

    def _queue(url, label="", parent_url=None, route="link"):
        url = _clean_text(url)
        if not url or not _holding_same_issuer_url(url, domain):
            return
        key = url.split("#", 1)[0]
        if key in discovery_seen:
            return
        discovery_seen.add(key)
        candidates.append((url, _clean_text(label), parent_url, route))

    def _rank(item):
        url, label, parent_url, route = item
        hay = _holding_fold_text(" ".join([label or "", url or ""]))
        score = 0
        if any(x in hay for x in ["net asset value per share", "nav per share", "substansvarde per aktie", "substansvärde per aktie"]): score += 240
        if any(x in hay for x in ["adjusted net asset value", "net asset value", "substansvarde", "substansvärde"]): score += 140
        if any(x in hay for x in ["2026", "q2", "second quarter", "half year", "six months", "january june", "jan jun", "januari juni"]): score += 75
        if any(x in hay for x in ["interim report", "quarterly report", "half year report", "reports presentations", "delarsrapport", "delårsrapport", "rapport"]): score += 60
        if any(x in hay for x in ["investor relations", "investors media", "investors-media", "investors", "investor"]): score += 35
        if any(x in hay for x in ["press release", "press releases", "pressreleaser", "news", "media"]): score += 20
        if str(url).lower().split("?", 1)[0].endswith(".pdf"): score += 30
        if parent_url: score += 12
        if route == "search": score += 4
        return score

    def _enqueue_second_hop(html, resolved_url):
        if not html or str(resolved_url).lower().split("?", 1)[0].endswith(".pdf"):
            return
        try:
            soup = BeautifulSoup(html, "html.parser")
            child_rows = []
            for a in soup.find_all("a", href=True):
                label = _clean_text(a.get_text(" ", strip=True))
                url = urljoin(resolved_url, a.get("href"))
                if not _holding_same_issuer_url(url, domain):
                    continue
                hay = _holding_fold_text(" ".join([label, url]))
                if not any(k in hay for k in [
                    "net asset value", "nav per share", "substansvarde", "substansvärde",
                    "interim report", "quarterly report", "half year", "six months",
                    "delarsrapport", "delårsrapport", "q1", "q2", "q3", "q4", "2026",
                    "reports", "rapport", "investor relations", "investors", "investor",
                    "press release", "pressreleaser", "press", "news", "media"
                ]):
                    continue
                child_rows.append((url, label, resolved_url, "issuer-link"))
            for row in sorted(child_rows, key=_rank, reverse=True)[:14]:
                _queue(row[0], row[1], row[2], row[3])
        except Exception:
            pass

    def _fetch_candidate(url, parent_url=None):
        try:
            if str(url).lower().split("?", 1)[0].endswith(".pdf"):
                doc_diag = []
                doc = _bank_fetch_official_document(
                    url, domain, deadline=deadline, timeout=3.4,
                    diagnostics=doc_diag, referer=parent_url,
                )
                if doc and doc.get("text"):
                    return doc.get("text") or "", doc.get("url") or url, True
                return "", url, True
            html, final_url = _fetch_html(url, timeout=3.0, deadline=deadline)
            return html or "", final_url or url, False
        except Exception:
            return "", url, str(url).lower().split("?", 1)[0].endswith(".pdf")

    # 1) Start at the issuer root.  The broader navigation vocabulary is the
    # main V77 repair for sites whose NAV lives behind Investors & Media -> 2026.
    if _research_budget_ok(deadline, reserve=1.15):
        html, resolved, _ = _fetch_candidate(website)
        if html and _holding_same_issuer_url(resolved, domain):
            _consider(html, resolved, "issuer homepage", route="homepage")
            _enqueue_second_hop(html, resolved)

    strict_home = [r for r in records if r.get("semantic_guard")]
    if strict_home:
        strict_home.sort(key=lambda r: (r.get("as_of_date_obj") or datetime(1900,1,1).date(), int(r.get("quality") or 0)), reverse=True)
        return strict_home[0], "ok"

    # 2) Exact multilingual domain-only discovery.  Search snippets can only
    # nominate URLs; values always come from the fetched issuer destination.
    search_queries = [
        f'site:{domain} "net asset value" "per share" 2026',
        f'site:{domain} "adjusted net asset value" "per share" 2026',
        f'site:{domain} "substansvärde" "per aktie" 2026',
        f'site:{domain} "substansvarde" "per aktie" 2026',
        f'site:{domain} "interim report" 2026 "net asset value"',
        f'site:{domain} "delårsrapport" 2026 "substansvärde"',
    ]
    queries_run = 0
    for query in search_queries:
        if not _research_budget_ok(deadline, reserve=1.15):
            break
        queries_run += 1
        try:
            for item in _duckduckgo_html_search(query, max_results=6, deadline=deadline):
                url = _clean_text(item.get("url"))
                if not url or not _holding_same_issuer_url(url, domain):
                    continue
                label = _clean_text(item.get("title")) or _clean_text(item.get("snippet"))
                semantic = _holding_fold_text(" ".join([label, _clean_text(item.get("snippet")), url]))
                if any(term in semantic for term in [
                    "net asset value", "nav", "substansvarde", "substansvärde",
                    "interim report", "delarsrapport", "delårsrapport", "2026"
                ]):
                    _queue(url, label, route="search")
        except Exception:
            pass
        # Run at least two complementary queries before yielding to fetches;
        # this avoids a dynamic NAV chart page crowding out a static report.
        if queries_run >= 2 and any(_rank(x) >= 220 for x in candidates):
            break

    # 3) Existing family semantic search is a final URL-discovery fallback.
    if _research_budget_ok(deadline, reserve=1.25) and not candidates:
        try:
            found = _holding_semantic_source_search(
                domain, name, deadline=deadline, needed_kinds=["nav", "report"],
                query_offset=0, max_queries_per_kind=1,
            )
            for url, label in (found.get("nav") or []) + (found.get("report") or []):
                _queue(url, label, route="semantic-search")
        except Exception:
            pass

    # 4) Best-first issuer-owned crawl.  Each fetched HTML page may nominate a
    # further issuer-owned IR/report/press child, but the per-peer deadline keeps
    # the traversal bounded.
    fetched = set()
    while candidates and _research_budget_ok(deadline, reserve=0.35):
        candidates.sort(key=_rank, reverse=True)
        url, label, parent_url, route = candidates.pop(0)
        key = url.split("#", 1)[0]
        if key in fetched:
            continue
        fetched.add(key)
        payload, resolved, is_pdf = _fetch_candidate(url, parent_url=parent_url)
        if not payload:
            continue
        _consider(payload, resolved, label, route=("issuer-pdf" if is_pdf else route))
        if records and any(r.get("semantic_guard") for r in records):
            break
        if not is_pdf:
            _enqueue_second_hop(payload, resolved)

    if not records:
        return None, "no_fresh_primary_nav"
    records.sort(key=lambda r: (bool(r.get("semantic_guard")), r.get("as_of_date_obj") or datetime(1900,1,1).date(), int(r.get("quality") or 0)), reverse=True)
    return records[0], "ok"

def _holding_build_family_peer_guard(symbol, max_seconds=36.0):
    peers = _holding_family_peer_universe(symbol)
    if not peers:
        return {"available": False, "ready": False, "observations": [], "status": "Kein freigegebener Holding-Peer-Cluster für diesen Markt.", "diagnostic": "Holding Peer NAV Guard V77: PeerUniverse=0"}

    preferred = [p for p in peers if str(p.get("tier") or "preferred") == "preferred"]
    fallback = [p for p in peers if str(p.get("tier") or "") == "fallback"]
    # Research budget is per attempted peer so a slow issuer cannot starve the
    # next one.  Fallback peers are not touched unless the preferred cluster
    # yields fewer than three valid observations.
    planned_slots = max(1, len(preferred) + min(2, len(fallback)))
    per_peer_seconds = max(5.0, min(7.0, float(max_seconds or 36.0) / planned_slots))
    observations = []
    trace = []
    attempted = 0
    fallback_used = False

    def _attempt(peer):
        nonlocal attempted
        attempted += 1
        peer_deadline = time.monotonic() + per_peer_seconds
        peer_symbol = peer.get("symbol")
        tier = str(peer.get("tier") or "preferred")
        market_class = _holding_peer_symbol_share_class(peer_symbol)
        rec, reason = _holding_discover_peer_nav_record(peer, peer_deadline)
        if not rec:
            trace.append(
                f"reject:{peer_symbol}:{reason}"
                f"(tier={tier},class={market_class or 'unspecified'},nav=–,nav_date=–,price=–,price_date=–,pnav=–)"
            )
            return False

        snap = _holding_peer_last_price_snapshot(peer_symbol)
        price = safe_float(snap.get("price"))
        nav = safe_float(rec.get("nav_per_share"))
        nav_cur = str(rec.get("currency") or "").upper() or None
        price_cur = str(snap.get("currency") or "").upper() or None
        nav_class = _clean_text(rec.get("share_class")) or None
        nav_date = rec.get("as_of_date") or _holding_date_display(rec.get("as_of_date_obj"))
        price_date = snap.get("price_date")
        route = _clean_text(rec.get("discovery_route")) or "issuer-primary"

        if nav_cur and price_cur and nav_cur != price_cur:
            trace.append(
                f"reject:{peer_symbol}:currency_mismatch"
                f"(tier={tier},route={route},class={market_class or 'unspecified'}/navclass={nav_class or 'all'},nav={format(nav, '.2f') if nav is not None else '–'} {nav_cur},nav_date={nav_date or '–'},price={format(price, '.2f') if price is not None else '–'} {price_cur},price_date={price_date or '–'},pnav=–)"
            )
            return False

        if price is None or nav is None or nav <= 0:
            trace.append(
                f"reject:{peer_symbol}:price_or_nav_missing"
                f"(tier={tier},route={route},class={market_class or 'unspecified'}/navclass={nav_class or 'all'},nav={nav if nav is not None else '–'},nav_date={nav_date or '–'},price={price if price is not None else '–'},price_date={price_date or '–'},pnav=–)"
            )
            return False

        pnav = price / nav
        premium = (pnav - 1.0) * 100.0
        if premium < -60.0 or premium > 120.0:
            trace.append(
                f"reject:{peer_symbol}:implausible_pnav"
                f"(tier={tier},route={route},class={market_class or 'unspecified'}/navclass={nav_class or 'all'},nav={nav:.2f} {nav_cur or '–'},nav_date={nav_date or '–'},price={price:.2f} {price_cur or nav_cur or '–'},price_date={price_date or '–'},pnav={pnav:.3f}x,pd={premium:+.1f}%)"
            )
            return False

        observations.append({
            "symbol": peer_symbol,
            "name": peer.get("name"),
            "peer_tier": tier,
            "share_class": market_class,
            "nav_share_class": nav_class,
            "nav_per_share": nav,
            "nav_as_of_date": nav_date,
            "nav_age_days": rec.get("nav_age_days"),
            "nav_source_url": rec.get("source_url"),
            "nav_semantic_guard": rec.get("semantic_guard"),
            "nav_discovery_route": route,
            "current_price": price,
            "price_date": price_date,
            "pnav": pnav,
            "premium_discount_pct": premium,
            "currency": nav_cur or price_cur or "SEK",
        })
        trace.append(
            f"accept:{peer_symbol}"
            f"(tier={tier},route={route},class={market_class or 'unspecified'}/navclass={nav_class or 'all'},nav={nav:.2f} {nav_cur or '–'},nav_date={nav_date or '–'},price={price:.2f} {price_cur or nav_cur or '–'},price_date={price_date or '–'},pnav={pnav:.3f}x,pd={premium:+.1f}%)"
        )
        return True

    for peer in preferred:
        _attempt(peer)

    if len(observations) < 3 and fallback:
        fallback_used = True
        for peer in fallback:
            _attempt(peer)
            if len(observations) >= 3:
                break

    vals = [safe_float(x.get("premium_discount_pct")) for x in observations if safe_float(x.get("premium_discount_pct")) is not None]
    if vals:
        ser = pd.Series(vals, dtype="float64")
        median = float(ser.median())
        q1 = float(ser.quantile(0.25))
        q3 = float(ser.quantile(0.75))
    else:
        median = q1 = q3 = None
    ready = len(vals) >= 3
    return {
        "available": bool(vals),
        "ready": ready,
        "observation_count": len(vals),
        "median_pct": median,
        "q1_pct": q1,
        "q3_pct": q3,
        "observations": observations,
        "preferred_peer_count": len(preferred),
        "fallback_peer_count": len(fallback),
        "fallback_used": fallback_used,
        "attempted_peer_count": attempted,
        "status": (f"{len(vals)} frische issuer-primary Holding-Peers · Median {median:+.1f}%" if ready and median is not None else f"Nur {len(vals)} brauchbare Holding-Peers; mindestens 3 erforderlich."),
        "diagnostic": (
            f"Holding Peer NAV Guard V77: PeerUniverse={len(peers)}, Preferred={len(preferred)}, FallbackUniverse={len(fallback)}, "
            f"AttemptedPeers={attempted}, ValidPeers={len(vals)}, FallbackUsed={'yes' if fallback_used else 'no'}, Ready={'yes' if ready else 'no'}; "
            f"PerPeerBudget={per_peer_seconds:.1f}s; Trace=" + " | ".join(trace[:14])
        ),
    }


@st.cache_data(ttl=3600, show_spinner=False)
def _holding_build_family_peer_guard_cached(symbol, cache_epoch="v22195_holding_peer_cache_refresh_v91"):
    return _holding_build_family_peer_guard(symbol)


def _holding_build_justified_nav_target_diagnostic(historical_calibration, debt_ratio_pct, top2_pct, top4_pct, holding_cost_evidence=None, peer_evidence=None):
    """Diagnostic-only target NAV premium/discount bridge with cost guard.

    V71 keeps the issuer's own historical premium/discount median as the base
    anchor. Current leverage and concentration remain bounded downside-only
    diagnostics. Recurring management/holding cost is evaluated against the
    issuer's own recent cost history instead of being capitalized into a second
    discount, which would double-count structure already embedded in the market
    history. A normal/low current cost therefore adds 0.00 pp; missing or
    materially elevated cost evidence remains fail-closed pending a separately
    justified translation rule. Peer evidence is still required for release.
    """
    hist = historical_calibration or {}
    hist_ready = bool(hist.get("ready"))
    anchor = safe_float(hist.get("median_pct")) if hist_ready else None
    q1 = safe_float(hist.get("q1_pct"))
    q3 = safe_float(hist.get("q3_pct"))
    debt = safe_float(debt_ratio_pct)
    top2 = safe_float(top2_pct)
    top4 = safe_float(top4_pct)

    leverage_adj = None
    leverage_band = "Nicht verfügbar"
    if debt is not None:
        if debt <= 5.0:
            leverage_adj = 0.0
            leverage_band = "Niedrig · kein zusätzlicher Abschlag"
        elif debt <= 10.0:
            leverage_adj = -0.25
            leverage_band = "Moderat · kleiner diagnostischer Abschlag"
        elif debt <= 20.0:
            leverage_adj = -0.75
            leverage_band = "Erhöht · diagnostischer Abschlag"
        elif debt <= 30.0:
            leverage_adj = -1.50
            leverage_band = "Hoch · deutlicher diagnostischer Abschlag"
        else:
            leverage_adj = -2.50
            leverage_band = "Sehr hoch · starker diagnostischer Abschlag"

    concentration_adj = None
    concentration_band = "Nicht verfügbar"
    if top2 is not None or top4 is not None:
        penalties = [0.0]
        if top2 is not None:
            if top2 >= 70.0:
                penalties.append(-1.00)
            elif top2 >= 55.0:
                penalties.append(-0.50)
            elif top2 >= 40.0:
                penalties.append(-0.25)
        if top4 is not None:
            if top4 >= 95.0:
                penalties.append(-1.00)
            elif top4 >= 85.0:
                penalties.append(-0.50)
            elif top4 >= 70.0:
                penalties.append(-0.25)
        concentration_adj = min(penalties)
        if concentration_adj <= -1.0:
            concentration_band = "Sehr hoch · begrenzter diagnostischer Abschlag"
        elif concentration_adj <= -0.5:
            concentration_band = "Hoch · begrenzter diagnostischer Abschlag"
        elif concentration_adj < 0:
            concentration_band = "Mittel · kleiner diagnostischer Abschlag"
        else:
            concentration_band = "Breit · kein zusätzlicher Abschlag"

    cost = holding_cost_evidence or {}
    cost_latest = safe_float(cost.get("latest_cost_pct"))
    cost_median = safe_float(cost.get("median_5y_pct"))
    cost_year = cost.get("latest_year")
    cost_obs = int(cost.get("observation_count") or 0)
    cost_adj = None
    cost_status = "Issuer-primary Holdingkosten/Strukturdrag noch nicht quantifiziert"
    cost_guard_state = "missing"
    if cost_latest is not None and cost_median is not None and cost_obs >= 3:
        # A tolerance of 0.02 percentage points (= 2 bps of portfolio value)
        # prevents noise around the issuer's own multi-year norm from becoming a
        # second valuation penalty. Elevated cases remain blocked rather than
        # receiving an invented capitalization multiple.
        if cost_latest <= cost_median + 0.02:
            cost_adj = 0.0
            cost_guard_state = "normal_or_low"
            cost_status = (
                f"Issuer-primary Managementkosten {cost_latest:.2f}% ({cost_year or 'aktuell'}) "
                f"vs. 5J-Median {cost_median:.2f}% · normal/niedrig · kein zusätzlicher Abschlag"
            )
        else:
            cost_guard_state = "elevated_translation_unreleased"
            cost_status = (
                f"Issuer-primary Managementkosten {cost_latest:.2f}% ({cost_year or 'aktuell'}) "
                f"vs. 5J-Median {cost_median:.2f}% · erhöht · Bewertungsübersetzung noch nicht freigegeben"
            )

    peer = peer_evidence or {}
    peer_adj = None
    peer_guard_state = "missing"
    peer_status = "Vergleichbare Holding-Peer-Evidenz noch nicht freigegeben"
    peer_median = safe_float(peer.get("median_pct"))
    peer_q1 = safe_float(peer.get("q1_pct"))
    peer_q3 = safe_float(peer.get("q3_pct"))
    peer_obs = int(peer.get("observation_count") or 0)
    provisional = None
    if anchor is not None:
        provisional = anchor
        for adj in [leverage_adj, concentration_adj, cost_adj]:
            if adj is not None:
                provisional += adj

    if bool(peer.get("ready")) and peer_median is not None and peer_q1 is not None and peer_q3 is not None and provisional is not None:
        lower_guard = peer_q1 - 5.0
        upper_guard = peer_q3 + 5.0
        if lower_guard <= provisional <= upper_guard:
            peer_adj = 0.0
            peer_guard_state = "comparable_reference_pass"
            peer_status = (f"{peer_obs} frische Holding-Peers · Median {peer_median:+.1f}% · IQR {peer_q1:+.1f}% bis {peer_q3:+.1f}% · issuer-spezifischer Zielwert {provisional:+.1f}% innerhalb Plausibilitätsband · 0,00 pp")
        else:
            peer_guard_state = "peer_conflict_translation_unreleased"
            peer_status = (f"{peer_obs} frische Holding-Peers · Median {peer_median:+.1f}% · IQR {peer_q1:+.1f}% bis {peer_q3:+.1f}% · issuer-spezifischer Zielwert {provisional:+.1f}% außerhalb Plausibilitätsband · keine automatische Anpassung")

    blockers = []
    if not hist_ready:
        blockers.append("historical_calibration_not_ready")
    if debt is None:
        blockers.append("leverage_evidence_missing")
    if top2 is None and top4 is None:
        blockers.append("concentration_evidence_missing")
    if cost_guard_state == "missing":
        blockers.append("holding_cost_evidence_missing")
    elif cost_guard_state == "elevated_translation_unreleased":
        blockers.append("holding_cost_translation_unreleased")
    if peer_guard_state == "missing":
        blockers.append("peer_evidence_missing")
    elif peer_guard_state == "peer_conflict_translation_unreleased":
        blockers.append("peer_conflict_translation_unreleased")

    released = bool(anchor is not None and not blockers)
    final_target = provisional if released else None
    return {
        "available": anchor is not None,
        "released": released,
        "historical_anchor_pct": anchor,
        "historical_q1_pct": q1,
        "historical_q3_pct": q3,
        "leverage_adjustment_pp": leverage_adj,
        "leverage_band": leverage_band,
        "concentration_adjustment_pp": concentration_adj,
        "concentration_band": concentration_band,
        "holding_cost_adjustment_pp": cost_adj,
        "holding_cost_status": cost_status,
        "holding_cost_guard_state": cost_guard_state,
        "holding_cost_latest_pct": cost_latest,
        "holding_cost_latest_year": cost_year,
        "holding_cost_median_5y_pct": cost_median,
        "holding_cost_observation_count": cost_obs,
        "holding_cost_source_url": cost.get("source_url"),
        "peer_adjustment_pp": peer_adj,
        "peer_status": peer_status,
        "peer_guard_state": peer_guard_state,
        "peer_median_pct": peer_median,
        "peer_q1_pct": peer_q1,
        "peer_q3_pct": peer_q3,
        "peer_observation_count": peer_obs,
        "peer_observations": peer.get("observations") or [],
        "peer_diagnostic": peer.get("diagnostic"),
        "provisional_target_pct": provisional,
        "final_target_pct": final_target,
        "release_blockers": blockers,
        "double_count_guard": (
            "Historischer Median enthält normale Holdingkosten und Struktur bereits teilweise. "
            "V77 verwendet die issuer-primary Kostenquote deshalb nur als Abweichungs-Guard gegen die eigene Mehrjahresnorm. Der Holding-Peer-Median ist ebenfalls nur ein Plausibilitäts-Guard; "
            "eine normale/niedrige Kostenquote erhält 0,00 pp und wird nicht nochmals kapitalisiert."
        ),
        "method": "Historical median + bounded current-risk overlays + issuer-primary own-history management-cost guard + family peer NAV plausibility guard",
    }


def _holding_nav_freshness_policy(nav_date_obj, historical_calibration):
    """Cadence-aware live-NAV freshness gate for listed holdings.

    V90 keeps the former 62-day threshold as a conservative fallback, but when
    issuer-primary history provides a stable reporting cadence it allows one
    normal cadence plus 35 days of publication/processing slack.  The result is
    capped so an old NAV can never stay valuation-usable indefinitely.
    """
    age_days = None
    if nav_date_obj:
        try:
            age_days = (datetime.now().date() - nav_date_obj).days
        except Exception:
            age_days = None

    hist = historical_calibration or {}
    hist_dates = []
    for row in (hist.get("observations") or []):
        dt = row.get("as_of_date_obj")
        if dt is not None:
            hist_dates.append(dt)
    hist_dates = sorted(set(hist_dates))
    intervals = []
    for left, right in zip(hist_dates, hist_dates[1:]):
        try:
            gap = (right - left).days
        except Exception:
            gap = None
        if gap is not None and 20 <= gap <= 200:
            intervals.append(float(gap))

    cadence_days = float(pd.Series(intervals, dtype="float64").median()) if len(intervals) >= 2 else None
    freshness_limit_days = 62
    basis = "fixed_fallback_62d"
    if cadence_days is not None:
        freshness_limit_days = int(round(max(62.0, min(150.0, cadence_days + 35.0))))
        basis = "issuer_history_median_cadence_plus_35d"

    fresh = bool(age_days is not None and -3 <= age_days <= freshness_limit_days)
    return {
        "fresh": fresh,
        "age_days": age_days,
        "freshness_limit_days": freshness_limit_days,
        "expected_cadence_days": cadence_days,
        "cadence_interval_count": len(intervals),
        "basis": basis,
    }


def build_listed_investment_holding_specialist_model(company_type, fundamental_info, symbol, current_price, currency_context):
    if not is_listed_investment_holding_type(company_type):
        return {"applicable": False}
    website = (fundamental_info or {}).get("website")
    company_name = (fundamental_info or {}).get("longName") or (fundamental_info or {}).get("shortName") or symbol
    discovery = _discover_listed_holding_primary_snapshot_cached(
        website, company_name=company_name, symbol=symbol,
        cache_epoch="v22196_holding_family_release_v92",
    )
    nav = discovery.get("nav") or {}
    debt = discovery.get("debt") or {}
    portfolio = discovery.get("portfolio") or {}
    holding_cost = discovery.get("holding_cost") or {}
    historical_calibration = _holding_build_historical_nav_calibration(discovery.get("nav_history") or [], symbol)
    peer_evidence = _holding_build_family_peer_guard_cached(symbol)
    nav_value = safe_float(nav.get("nav_per_share"))
    nav_currency = str(nav.get("currency") or (fundamental_info or {}).get("financialCurrency") or "").upper()
    financial_currency = str((currency_context or {}).get("financial_currency") or "").upper()
    nav_date_obj = nav.get("as_of_date_obj")
    nav_freshness = _holding_nav_freshness_policy(nav_date_obj, historical_calibration)
    age_days = nav_freshness.get("age_days")
    nav_fresh = bool(nav_freshness.get("fresh"))
    currency_ok = bool(nav_value is not None and nav_value > 0 and nav_currency and financial_currency and nav_currency == financial_currency)

    price_financial = safe_float(current_price)
    price_note = None
    share_context = (currency_context or {}).get("share_unit_context") or {}
    if share_context.get("conversion_required"):
        if not share_context.get("conversion_available"):
            price_financial = None
            price_note = "Kurs/NAV-Vergleich gesperrt: Aktien-/ADR-Umrechnung nicht verifiziert."
        else:
            ratio = safe_float(share_context.get("fundamental_shares_per_quote_unit"))
            if ratio is None or ratio <= 0:
                price_financial = None
                price_note = "Kurs/NAV-Vergleich gesperrt: Aktien-/ADR-Verhältnis nicht belastbar."
            elif price_financial is not None:
                price_financial = price_financial / ratio
    if price_financial is not None and (currency_context or {}).get("mixed_units"):
        factor = safe_float((currency_context or {}).get("financial_to_quote_factor"))
        if not (currency_context or {}).get("conversion_available") or factor is None or factor <= 0:
            price_financial = None
            price_note = "Kurs/NAV-Vergleich gesperrt: Währungsumrechnung nicht belastbar."
        else:
            price_financial = price_financial / factor
    elif price_financial is not None and str((currency_context or {}).get("quote_currency") or "").upper() != financial_currency:
        price_financial = None
        price_note = "Kurs/NAV-Vergleich gesperrt: Handels- und Finanzwährung weichen ohne verifizierte Umrechnung ab."

    price_to_nav = (price_financial / nav_value) if (price_financial is not None and nav_value and nav_value > 0 and currency_ok) else None
    premium_discount_pct = ((price_to_nav - 1.0) * 100.0) if price_to_nav is not None else None
    debt_ratio = safe_float(debt.get("debt_ratio_pct"))
    top1 = safe_float(portfolio.get("top1_pct"))
    top2 = safe_float(portfolio.get("top2_pct"))
    top3 = safe_float(portfolio.get("top3_pct"))
    top4 = safe_float(portfolio.get("top4_pct"))
    leverage_status = None
    if debt_ratio is not None:
        leverage_status = "Niedrig" if debt_ratio <= 5 else ("Moderat" if debt_ratio <= 10 else "Erhöht")
    concentration_status = None
    if top2 is not None:
        concentration_status = "Hoch" if top2 >= 60 else ("Mittel" if top2 >= 40 else "Breit")

    justified_target_diag = _holding_build_justified_nav_target_diagnostic(
        historical_calibration, debt_ratio, top2, top4, holding_cost_evidence=holding_cost, peer_evidence=peer_evidence
    )

    primary_complete = bool(nav_value and nav_value > 0 and nav_date_obj and nav_fresh and currency_ok)
    snapshot = {
        "company": (fundamental_info or {}).get("shortName") or (fundamental_info or {}).get("longName") or symbol,
        "symbol": symbol,
        "website": website,
        "reporting_currency": financial_currency or nav_currency,
        "nav_per_share": nav_value,
        "nav_currency": nav_currency,
        "nav_as_of_date": nav.get("as_of_date"),
        "nav_published_date": nav.get("published_date"),
        "nav_source_url": nav.get("source_url"),
        "nav_source_title": nav.get("source_title"),
        "nav_same_date_class_prices": nav.get("same_date_class_prices") or {},
        "nav_age_days": age_days,
        "nav_freshness_limit_days": nav_freshness.get("freshness_limit_days"),
        "nav_expected_cadence_days": nav_freshness.get("expected_cadence_days"),
        "nav_cadence_interval_count": nav_freshness.get("cadence_interval_count"),
        "nav_freshness_basis": nav_freshness.get("basis"),
        "current_price_financial": price_financial,
        "price_to_nav": price_to_nav,
        "premium_discount_pct": premium_discount_pct,
        "price_nav_note": price_note,
        "debt_ratio_pct": debt_ratio,
        "debt_ratio_metric": debt.get("metric_name"),
        "debt_as_of_date": debt.get("as_of_date"),
        "debt_published_date": debt.get("published_date"),
        "debt_source_url": debt.get("source_url"),
        "portfolio_holdings": portfolio.get("holdings") or [],
        "portfolio_top1_pct": top1,
        "portfolio_top2_pct": top2,
        "portfolio_top3_pct": top3,
        "portfolio_top4_pct": top4,
        "portfolio_as_of_date": portfolio.get("as_of_date"),
        "portfolio_value_bn": safe_float(portfolio.get("portfolio_value_bn")),
        "portfolio_currency": portfolio.get("portfolio_currency"),
        "portfolio_source_url": portfolio.get("source_url"),
        "portfolio_source_kind": portfolio.get("source_kind"),
        "portfolio_source_shape": portfolio.get("source_shape"),
        "portfolio_adapter_diagnostic": discovery.get("portfolio_adapter_diagnostic"),
        "leverage_status": leverage_status,
        "concentration_status": concentration_status,
        "holding_cost_latest_pct": safe_float(holding_cost.get("latest_cost_pct")),
        "holding_cost_latest_year": holding_cost.get("latest_year"),
        "holding_cost_median_5y_pct": safe_float(holding_cost.get("median_5y_pct")),
        "holding_cost_min_5y_pct": safe_float(holding_cost.get("min_5y_pct")),
        "holding_cost_max_5y_pct": safe_float(holding_cost.get("max_5y_pct")),
        "holding_cost_observations": holding_cost.get("observations") or [],
        "holding_cost_source_url": holding_cost.get("source_url"),
        "holding_cost_metric_label": holding_cost.get("metric_label"),
        "holding_cost_adapter_diagnostic": discovery.get("holding_cost_adapter_diagnostic"),
        "historical_nav_calibration": historical_calibration,
        "historical_nav_observations": historical_calibration.get("observations") or [],
        "historical_nav_calibration_ready": bool(historical_calibration.get("ready")),
        "historical_nav_median_premium_discount_pct": safe_float(historical_calibration.get("median_pct")),
        "historical_pair_probes": discovery.get("historical_pair_probes") or [],
        "justified_nav_target_diagnostic": justified_target_diag,
        "provisional_target_premium_discount_pct": safe_float(justified_target_diag.get("provisional_target_pct")),
        "final_target_premium_discount_pct": safe_float(justified_target_diag.get("final_target_pct")),
        "target_premium_discount_released": bool(justified_target_diag.get("released")),
        "holding_peer_evidence": peer_evidence,
        "source_name": "Issuer Primary Source · Listed Investment Holding NAV / Capital Structure · Holding Family Release & Standard-Path Isolation Guard V92",
        "diagnostics": discovery.get("diagnostics") or [],
    }
    return {
        "applicable": True,
        "primary_source_complete": primary_complete,
        "valuation_anchor_complete": bool(primary_complete and justified_target_diag.get("released")),
        "snapshot": snapshot,
        "nav_diagnostics": {
            "available": bool(nav_value and nav_value > 0),
            "fresh": nav_fresh,
            "nav_age_days": age_days,
            "nav_freshness_limit_days": nav_freshness.get("freshness_limit_days"),
            "nav_expected_cadence_days": nav_freshness.get("expected_cadence_days"),
            "nav_freshness_basis": nav_freshness.get("basis"),
            "currency_aligned": currency_ok,
            "price_nav_available": price_to_nav is not None,
            "debt_context_available": debt_ratio is not None,
            "portfolio_context_available": bool(portfolio.get("holdings")),
            "leverage_status": leverage_status,
            "concentration_status": concentration_status,
            "holding_cost_evidence_available": bool(holding_cost.get("latest_cost_pct") is not None),
            "holding_cost_guard_state": justified_target_diag.get("holding_cost_guard_state"),
            "historical_calibration_available": bool(historical_calibration.get("available")),
            "historical_calibration_ready": bool(historical_calibration.get("ready")),
            "historical_observation_count": int(historical_calibration.get("observation_count") or 0),
            "justified_target_diagnostic_available": bool(justified_target_diag.get("available")),
            "peer_evidence_ready": bool(peer_evidence.get("ready")),
            "peer_observation_count": int(peer_evidence.get("observation_count") or 0),
            "justified_target_released": bool(justified_target_diag.get("released")),
            "justified_target_blockers": justified_target_diag.get("release_blockers") or [],
        },
        "readiness": (
            "NAV-/Premium-Discount-Primärdaten vollständig · Ziel-Premium/Discount freigegeben · NAV-Fair-Value-Anker freigegeben"
            if primary_complete and justified_target_diag.get("released") else
            ("NAV-/Premium-Discount-Primärdaten vollständig · Ziel-Premium/Discount noch nicht freigegeben · Fair Value gesperrt"
             if primary_complete else "NAV-Primärdaten unvollständig · fail-closed")
        ),
        "note": (
            f"{APP_BUILD_VERSION} trennt aktuellen issuer-primary NAV, Kurs/NAV-Premium-Discount, Holding-Leverage und Portfoliokonzentration. "
            "Die historische Verteilung liefert den Basisanker; Leverage und Konzentration bleiben begrenzte diagnostische Overlays. "
            "Issuer-primary Holdingkosten/Strukturdrag werden gegen die eigene Mehrjahresnorm geprüft; ein markt-/familiengerechter Holding-Peer-Cluster dient nur als Plausibilitäts-Guard. "
            "V80 übernimmt den unveränderten V78-Holding-Fair-Value und die unveränderte V79-P/NAV-Zone. Die Handlungssignal-Übersetzung ist jetzt als eigene Holding-Schicht freigegeben und verwendet keinen generischen industriellen Fundamental-Score."
        ),
    }


