def _search_result_currency(item):
    direct = str(item.get("currency") or "").upper().strip()
    if direct:
        return direct, "yahoo"

    exchange_code = str(item.get("exchange") or "").upper().strip()
    inferred = SEARCH_EXCHANGE_CURRENCY.get(exchange_code)
    if inferred:
        return inferred, "exchange_fallback"

    display = str(item.get("exchDisp") or "").upper().strip()
    inferred = SEARCH_EXCHANGE_DISPLAY_CURRENCY.get(display)
    if inferred:
        return inferred, "exchange_fallback"

    return None, None


SEARCH_ALTERNATIVE_VENUE_PRIORITY = {
    "XETRA": 130, "PARIS": 125, "AMSTERDAM": 125, "MILAN": 123,
    "SWISS": 123, "LONDON": 123, "FRANKFURT": 115, "VIENNA": 105,
    "WSE": 100, "WARSAW": 100, "HAMBURG": 92, "BERLIN": 90,
    "MUNICH": 90, "DUSSELDORF": 90, "DÜSSELDORF": 90, "STUTTGART": 90,
    "CBOE EUROPE": 35,
    "OTC MARKETS": 10, "BUENOS AIRES": 10,
}


def _same_issuer_listing_sort_score(item):
    """Venue-first ordering inside the same issuer after the primary listing."""
    display = str(item.get("exchDisp") or "").upper().strip()
    exchange_code = str(item.get("exchange") or "").upper().strip()
    score = SEARCH_ALTERNATIVE_VENUE_PRIORITY.get(
        display, SEARCH_EXCHANGE_PRIORITY.get(exchange_code, 80)
    )
    yahoo_rank = item.get("_yahoo_rank")
    if yahoo_rank is not None:
        try:
            score += max(0, 20 - int(yahoo_rank)) / 100.0
        except Exception:
            pass
    return score


def _is_obvious_other_instrument(item, primary_item=None):
    """Conservative display-only instrument split; never changes valuation identity.

    We only separate cases that are visibly not an ordinary home/secondary
    common-share listing: OTC/depositary rows, Buenos-Aires local wrappers and
    names explicitly marked ADR/ADS/depositary receipt.  Everything else stays
    in the neutral 'Weitere Notierung' bucket rather than being over-classified.
    """
    exchange_code = str(item.get("exchange") or "").upper().strip()
    exchange_display = str(item.get("exchDisp") or "").upper().strip()
    symbol = str(item.get("symbol") or "").upper().strip()
    name = _fold_search_text(item.get("longname") or item.get("shortname") or "")

    if exchange_code in {"PNK", "OQX", "OQB", "YHD", "CCC"}:
        return True
    if "OTC" in exchange_display:
        return True
    if exchange_display == "BUENOS AIRES" or symbol.endswith(".BA"):
        return True
    if any(term in name for term in ("ADR", "ADS", "DEPOSITARY RECEIPT", "DEPOSITARY SHARES")):
        return True
    return False


@st.cache_data(ttl=900, show_spinner=False)
def search_stock_suggestions(search_text, cache_epoch):
    """
    V2.20.121 security search.

    One input accepts company name, ticker/symbol, WKN or ISIN. The resolver
    determines issuer identity first and ranks the most likely primary/home
    listing above alternative listings. Exact ticker searches are enriched
    with same-issuer alternative listings after the exact security has been
    identified. Full financial data are still loaded only after an explicit
    user selection.
    """
    query = str(search_text or "").strip()
    if len(query) < 2:
        return []

    query_type = _detect_security_query_type(query)
    identifier_rows = _resolve_identifier_openfigi(query, query_type)

    suggestions = []
    suggestions.extend(_primary_alias_rows(query))

    # Always search the literal input once.
    search_terms = [query]

    # WKN/ISIN mapping supplies issuer names. We search those names in Yahoo
    # rather than inventing Yahoo suffixes from FIGI exchange codes.
    if identifier_rows:
        for row in identifier_rows:
            name = str(row.get("name") or "").strip()
            ticker = str(row.get("ticker") or "").strip()
            if name and name not in search_terms:
                search_terms.append(name)
            if ticker and ticker not in search_terms:
                search_terms.append(ticker)
            if len(search_terms) >= 4:
                break

    global_rank = 0

    def append_yahoo_results(term, source="yahoo"):
        nonlocal global_rank
        for item in _safe_yahoo_search(term, max_results=25):
            if str(item.get("quoteType", "")).upper() != "EQUITY":
                continue
            row = dict(item)
            row.setdefault("_preferred", False)
            row["_yahoo_rank"] = global_rank
            row["_source"] = source
            suggestions.append(row)
            global_rank += 1

    for term in search_terms[:4]:
        append_yahoo_results(term)

    # V2.20.120 – ticker consistency enrichment.
    # Yahoo often returns only the exact ticker for queries such as KO or
    # RHM.DE. Once that exact security has identified the issuer, search the
    # issuer name as a second phase so alternative listings can be shown below
    # the exact ticker without weakening the exact-ticker priority.
    query_upper = query.upper()
    exact_ticker_candidates = [
        item for item in suggestions
        if str(item.get("symbol", "")).upper().strip() == query_upper
    ]
    if query_type == "ticker_or_name" and exact_ticker_candidates:
        exact_item = max(
            exact_ticker_candidates,
            key=lambda item: _listing_candidate_score(
                item, query, query_type, identifier_rows
            ),
        )
        issuer_name = str(
            exact_item.get("longname") or exact_item.get("shortname") or ""
        ).strip()
        if issuer_name and _fold_search_text(issuer_name) != _fold_search_text(query):
            append_yahoo_results(issuer_name, source="ticker_issuer_expansion")

    # Highest-quality occurrence wins for a duplicate Yahoo symbol.
    by_symbol = {}
    for item in suggestions:
        symbol = str(item.get("symbol", "")).upper().strip()
        if not symbol:
            continue
        current = by_symbol.get(symbol)
        if current is None or _listing_candidate_score(
            item, query, query_type, identifier_rows
        ) > _listing_candidate_score(current, query, query_type, identifier_rows):
            by_symbol[symbol] = item

    ranked = sorted(
        by_symbol.values(),
        key=lambda item: _listing_candidate_score(item, query, query_type, identifier_rows),
        reverse=True,
    )

    if not ranked:
        return []

    top = ranked[0]
    top_score = _listing_candidate_score(top, query, query_type, identifier_rows)
    top_symbol = str(top.get("symbol", "")).upper()
    top_exchange = str(top.get("exchDisp") or top.get("exchange") or "–")
    top_name = top.get("longname") or top.get("shortname") or top_symbol or "Unbekannt"

    # V2.20.121 – four explicit display groups:
    # preferred listing -> ordinary same-issuer listings -> obvious alternate
    # instruments/wrappers -> other issuers.  This keeps ADR/OTC/CEDEAR-style
    # rows visible without presenting them as equivalent exchange listings.
    same_issuer_alternatives = []
    same_issuer_other_instruments = []
    other_issuers = []
    for item in ranked[1:]:
        item_name = item.get("longname") or item.get("shortname") or item.get("symbol")
        if _same_issuer({"name": item_name}, {"name": top_name}):
            if _is_obvious_other_instrument(item, top):
                same_issuer_other_instruments.append(item)
            else:
                same_issuer_alternatives.append(item)
        else:
            other_issuers.append(item)

    same_issuer_alternatives.sort(
        key=_same_issuer_listing_sort_score,
        reverse=True,
    )
    same_issuer_other_instruments.sort(
        key=lambda item: _listing_candidate_score(item, query, query_type, identifier_rows),
        reverse=True,
    )
    other_issuers.sort(
        key=lambda item: _listing_candidate_score(item, query, query_type, identifier_rows),
        reverse=True,
    )

    # Keep the dropdown useful on mobile. Ordinary exchange listings get more
    # room than wrappers/OTC instruments or similarly named issuers.
    ordered_ranked = (
        [top]
        + same_issuer_alternatives[:6]
        + same_issuer_other_instruments[:3]
        + other_issuers[:3]
    )[:13]

    clean_results = []
    for idx, item in enumerate(ordered_ranked):
        symbol = str(item.get("symbol", "")).upper()
        name = item.get("longname") or item.get("shortname") or symbol or "Unbekannt"
        exchange = item.get("exchDisp") or item.get("exchange") or "–"
        score = _listing_candidate_score(item, query, query_type, identifier_rows)

        if idx == 0:
            role = "primary"
            role_label = "✓ Hauptlisting"
            if item.get("_identifier_verified"):
                match_reason = "WKN/ISIN bestätigt"
            elif symbol == query_upper:
                match_reason = "Exakter Ticker"
            elif item.get("_preferred"):
                match_reason = "Bevorzugter Emittent"
            else:
                match_reason = "Empfohlenes Listing"
            canonical_name = top_name
            primary_symbol = top_symbol
            primary_exchange = top_exchange
        elif _same_issuer({"name": name}, {"name": top_name}) and _is_obvious_other_instrument(item, top):
            role = "other_instrument"
            role_label = "◇ Anderes Instrument"
            match_reason = "Gleicher Emittent; OTC/Depositary/lokaler Wrapper"
            canonical_name = top_name
            primary_symbol = top_symbol
            primary_exchange = top_exchange
        elif _same_issuer({"name": name}, {"name": top_name}):
            role = "alternative"
            role_label = "↳ Weitere Notierung"
            match_reason = "Gleicher Emittent; alternative Börsennotierung"
            canonical_name = top_name
            primary_symbol = top_symbol
            primary_exchange = top_exchange
        else:
            role = "other_issuer"
            role_label = "• Anderes Unternehmen"
            match_reason = "Ähnlicher Suchtreffer; eigener Emittent"
            # Critical identity guard: selecting another issuer must never
            # inherit the first hit's canonical name or primary ticker.
            canonical_name = name
            primary_symbol = symbol
            primary_exchange = str(exchange)

        search_currency, currency_source = _search_result_currency(item)

        clean_results.append({
            "symbol": symbol,
            "name": name,
            "exchange": exchange,
            "exchange_code": item.get("exchange"),
            "currency": search_currency,
            "currency_source": currency_source,
            "listing_role": role,
            "listing_role_label": role_label,
            "match_reason": match_reason,
            "search_score": score,
            "query_type": query_type,
            "identifier_verified": bool(item.get("_identifier_verified")),
            "canonical_name": canonical_name,
            "primary_symbol": primary_symbol,
            "primary_exchange": primary_exchange,
            "primary_score": top_score if role != "other_issuer" else score,
        })

    return clean_results


def _compact_suggestion_label(item):
    """V2.20.121 mobile-first label with explicit result grouping."""
    role = str(item.get("listing_role") or "")
    role_prefix = {
        "primary": "✓ Hauptlisting",
        "alternative": "↳ Weitere Notierung",
        "other_instrument": "◇ Anderes Instrument",
        "other_issuer": "• Anderes Unternehmen",
    }.get(role, "• Treffer")

    core = [
        str(item.get("symbol") or "–"),
        str(item.get("exchange") or "–"),
    ]
    if item.get("currency"):
        core.append(str(item.get("currency")))

    # Repeating the same long issuer name on every alternative wastes the most
    # valuable mobile width. Keep it only for the main listing and other issuers.
    label = role_prefix + " · " + " · ".join(core)
    if role in {"primary", "other_issuer"}:
        label += " — " + str(item.get("name") or "Unbekannt")
    return label


def find_stock(search_text):
    """Backward-compatible single-result helper: returns the top ranked listing."""
    results = search_stock_suggestions(search_text, SEARCH_RESOLVER_CACHE_EPOCH)
    if not results:
        return None
    top = results[0]
    return {
        "symbol": top.get("symbol"),
        "quoteType": "EQUITY",
        "longname": top.get("name"),
        "exchange": top.get("exchange_code") or top.get("exchange"),
        "exchDisp": top.get("exchange"),
        "currency": top.get("currency"),
    }


# =========================================================
# Historische Daten
# =========================================================

def get_row_values(statement, possible_names):

    if statement is None or statement.empty:
        return []

    # Keep the historical-data path aligned with the resilient Yahoo recovery:
    # exact metric identity, but insensitive to spaces/punctuation/camel case.
    wanted = {
        "".join(char.lower() for char in str(name) if char.isalnum())
        for name in possible_names
    }

    selected = None
    for index_value in statement.index:
        key = "".join(
            char.lower()
            for char in str(index_value)
            if char.isalnum()
        )
        if key in wanted:
            selected = index_value
            break

    if selected is None:
        return []

    try:
        row = statement.loc[selected]
    except Exception:
        return []

    if isinstance(row, pd.DataFrame):
        if row.empty:
            return []
        row = row.iloc[0]

    values = []
    for date, value in row.items():
        number = safe_float(value)
        if number is not None:
            values.append({
                "date": date,
                "value": number
            })

    values.sort(
        key=lambda item: item["date"],
        reverse=True
    )
    return values


def build_historical_data(ticker):

    try:
        income = ticker.income_stmt
    except Exception:
        income = pd.DataFrame()

    try:
        cashflow = ticker.cashflow
    except Exception:
        cashflow = pd.DataFrame()

    net_income_values = get_row_values(
        income,
        [
            "Net Income",
            "Net Income Common Stockholders",
            "Net Income Continuous Operations"
        ]
    )

    diluted_eps_values = get_row_values(
        income,
        [
            "Diluted EPS",
            "Basic EPS"
        ]
    )

    free_cashflow_values = get_row_values(
        cashflow,
        [
            "Free Cash Flow"
        ]
    )

    operating_cashflow_values = get_row_values(
        cashflow,
        [
            "Operating Cash Flow",
            "Total Cash From Operating Activities"
        ]
    )

    capex_values = get_row_values(
        cashflow,
        [
            "Capital Expenditure",
            "Capital Expenditures"
        ]
    )

    if (
        not free_cashflow_values
        and operating_cashflow_values
        and capex_values
    ):

        ocf_by_year = {
            item["date"]: item["value"]
            for item in operating_cashflow_values
        }

        capex_by_year = {
            item["date"]: item["value"]
            for item in capex_values
        }

        calculated_fcf = []

        for date, ocf in ocf_by_year.items():

            if date in capex_by_year:

                calculated_fcf.append({
                    "date": date,
                    "value": (
                        ocf +
                        capex_by_year[date]
                    )
                })

        calculated_fcf.sort(
            key=lambda item: item["date"],
            reverse=True
        )

        free_cashflow_values = calculated_fcf

    net_income_values = net_income_values[:5]
    diluted_eps_values = diluted_eps_values[:5]
    free_cashflow_values = free_cashflow_values[:5]

    available_years = max(
        len(net_income_values),
        len(diluted_eps_values),
        len(free_cashflow_values)
    )

    if available_years >= 4:
        data_quality = "Hoch"

    elif available_years >= 3:
        data_quality = "Mittel"

    else:
        data_quality = "Niedrig"

    return {
        "net_income": net_income_values,
        "eps": diluted_eps_values,
        "fcf": free_cashflow_values,
        "available_years": available_years,
        "data_quality": data_quality
    }


# =========================================================
# Structural-Break-Kontrolle für zyklische EPS-Historien
# =========================================================

VERIFIED_STRUCTURAL_BREAKS = {
    # Newmont completed the Newcrest acquisition on 06.11.2023. The 2023
    # fiscal year is therefore a transition year and older years describe a
    # materially different portfolio. Only full years from 2024 onward are
    # eligible for a post-break cyclical EPS history.
    "NEM": {
        "event_name": "Newcrest-Übernahme",
        "event_date": "06.11.2023",
        "break_year": 2023,
        "first_full_comparable_year": 2024,
        "minimum_full_post_break_years": 3,
        "source_name": "Newmont – Abschluss der Newcrest-Übernahme",
        "source_note": (
            "Newmont schloss die Übernahme von Newcrest am 06.11.2023 ab. "
            "2023 gilt deshalb als Übergangsjahr; frühere Geschäftsjahre "
            "werden für die zyklische EPS-Normalisierung des heutigen "
            "Konzerns nicht gleichgewichtet weiterverwendet."
        ),
    },
}


def resolve_structural_break(symbol, company_type):
    """Return only explicitly verified material structural breaks.

    V2.12 deliberately does not infer M&A, spin-offs or portfolio changes from
    Yahoo ratios. Unknown companies receive no structural-break adjustment.
    """
    type_name = str((company_type or {}).get("type", "")).lower()
    if "zyklisch" not in type_name:
        return {"active": False}

    symbol_text = str(symbol or "").upper().strip()
    event = VERIFIED_STRUCTURAL_BREAKS.get(symbol_text)
    if not isinstance(event, dict):
        return {"active": False}

    return {"active": True, **event}


def _eps_history_rows(historical_eps):
    rows = []
    for item in historical_eps or []:
        if not isinstance(item, dict):
            continue
        value = safe_float(item.get("value"))
        date_value = item.get("date")
        year = getattr(date_value, "year", None)
        if value is None or year is None:
            continue
        rows.append({
            "year": int(year),
            "value": value,
        })
    return rows


# =========================================================
# EPS normalisieren
# =========================================================

def normalize_eps(
    company_type,
    trailing_eps,
    forward_eps,
    historical_eps,
    revenue_growth,
    earnings_growth,
    structural_break=None
):

    trailing = safe_float(trailing_eps)
    forward = safe_float(forward_eps)

    history_rows = _eps_history_rows(historical_eps)
    history = [row["value"] for row in history_rows]

    type_name = str(
        company_type.get("type", "")
    ).lower()

    generic_comparability = evaluate_generic_eps_basis_comparability(
        company_type, trailing, forward, revenue_growth
    )

    if (
        "early-stage mining" in type_name
        or "projektentwicklung" in type_name
    ):
        return build_eps_result(
            None,
            (
                "Early-Stage-/Projektunternehmen: "
                "keine belastbare EPS-Normalisierung für "
                "eine KGV-Bewertung"
            ),
            "Niedrig",
            None,
            trailing,
            forward
        )

    if "zyklisch" in type_name:

        break_control = (
            structural_break
            if isinstance(structural_break, dict)
            else {"active": False}
        )
        structural_metadata = {
            "structural_break": break_control,
            "structural_break_active": bool(break_control.get("active", False)),
            "normalization_blocked_by_structural_break": False,
            "comparable_full_years": [],
            "excluded_history_years": [],
            "comparable_full_years_count": 0,
            "minimum_full_post_break_years": None,
            "diagnostic_post_break_cycle_basis": None,
        }

        if break_control.get("active", False):
            first_year = int(break_control.get("first_full_comparable_year") or 0)
            minimum_years = int(break_control.get("minimum_full_post_break_years") or 3)

            comparable_rows = [
                row for row in history_rows
                if row["year"] >= first_year
            ]
            excluded_rows = [
                row for row in history_rows
                if row["year"] < first_year
            ]

            history = [row["value"] for row in comparable_rows]
            comparable_years = sorted({row["year"] for row in comparable_rows}, reverse=True)
            excluded_years = sorted({row["year"] for row in excluded_rows}, reverse=True)

            diagnostic_basis = None
            if len(history) >= 2:
                diagnostic_series = pd.Series(history)
                diagnostic_basis = float(
                    0.60 * diagnostic_series.median()
                    + 0.40 * diagnostic_series.mean()
                )

            structural_metadata.update({
                "comparable_full_years": comparable_years,
                "excluded_history_years": excluded_years,
                "comparable_full_years_count": len(comparable_years),
                "minimum_full_post_break_years": minimum_years,
                "diagnostic_post_break_cycle_basis": diagnostic_basis,
            })

            if len(comparable_years) < minimum_years:
                structural_metadata["normalization_blocked_by_structural_break"] = True
                method = (
                    f"Structural-Break-Kontrolle: {break_control.get('event_name', 'wesentlicher Strukturbruch')} "
                    f"am {break_control.get('event_date', '–')}; nur {len(comparable_years)} vollständig "
                    f"vergleichbare Geschäftsjahre nach dem Strukturbruch, benötigt werden mindestens "
                    f"{minimum_years}. Keine Zyklus-EPS-Bewertungsbasis freigegeben."
                )
                return build_eps_result(
                    None,
                    method,
                    "Niedrig",
                    None,
                    trailing,
                    forward,
                    structural_metadata
                )

        if len(history) >= 3:

            series = pd.Series(history)

            median_eps = float(
                series.median()
            )

            mean_eps = float(
                series.mean()
            )

            cycle_basis = (
                0.60 * median_eps +
                0.40 * mean_eps
            )

            if forward is not None:

                denominator = max(
                    abs(cycle_basis),
                    1.0
                )

                forward_difference = (
                    abs(
                        forward -
                        cycle_basis
                    )
                    / denominator
                )

                if forward_difference > 0.75:

                    normalized = (
                        0.85 * cycle_basis +
                        0.15 * forward
                    )

                    method = (
                        "Zyklus-EPS aus Median und "
                        "Durchschnitt; Forward-EPS "
                        "wegen starker Abweichung "
                        "nur mit 15 % gewichtet"
                    )

                else:

                    normalized = (
                        0.70 * cycle_basis +
                        0.30 * forward
                    )

                    method = (
                        "Zyklus-EPS aus Median und "
                        "Durchschnitt plus 30 % "
                        "Forward-EPS"
                    )

            else:

                normalized = cycle_basis

                method = (
                    "Zyklus-EPS aus 60 % Median "
                    "und 40 % Durchschnitt"
                )

            if structural_metadata.get("structural_break_active"):
                method = "Strukturbruch-bereinigt: " + method

            comparability_gate = evaluate_cycle_eps_comparability_gate(
                company_type,
                cycle_basis,
                trailing,
                forward
            )

            cycle_metadata = dict(structural_metadata)
            cycle_metadata.update({
                "cycle_eps_comparability_gate_active": bool(comparability_gate.get("active", False)),
                "cycle_eps_comparability_blocked": bool(comparability_gate.get("blocked", False)),
                "cycle_forward_deviation": comparability_gate.get("cycle_forward_deviation"),
                "cycle_comparability_ttm_forward_deviation": comparability_gate.get("ttm_forward_deviation"),
                "cycle_eps_comparability_note": comparability_gate.get("note"),
                "valuation_blocked": bool(comparability_gate.get("blocked", False)),
            })

            if comparability_gate.get("blocked"):
                method = method + "; Vergleichbarkeits-Gate: nur Diagnosewert"

            return build_eps_result(
                normalized,
                method,
                "Niedrig" if comparability_gate.get("blocked") else "Mittel",
                cycle_basis,
                trailing,
                forward,
                cycle_metadata
            )

        if trailing is not None and forward is not None:

            normalized = (
                0.60 * trailing +
                0.40 * forward
            )

            return build_eps_result(
                normalized,
                (
                    "Nur eingeschränkte Mehrjahresdaten; "
                    "60 % TTM-EPS + 40 % Forward-EPS"
                ),
                "Niedrig",
                None,
                trailing,
                forward,
                structural_metadata
            )

        normalized = (
            trailing
            if trailing is not None
            else forward
        )

        return build_eps_result(
            normalized,
            (
                "Zu wenige Daten für eine "
                "zuverlässige Zyklus-Normalisierung"
            ),
            "Niedrig",
            None,
            trailing,
            forward,
            structural_metadata
        )

    if (
        trailing is not None
        and forward is not None
        and trailing > 0
        and forward > 0
    ):

        # Missing growth data stay missing. They are not converted to 0.
        rev_growth = safe_float(
            revenue_growth
        )
        earn_growth = safe_float(
            earnings_growth
        )

        classification_strong_growth = (
            "defense / stark wachsend" in type_name
        )

        strong_growth = (
            classification_strong_growth
            or (
                rev_growth is not None
                and earn_growth is not None
                and rev_growth >= 0.15
                and earn_growth >= 0.15
            )
        )

        normal_growth = (
            (
                rev_growth is not None
                and rev_growth >= 0.08
            )
            or (
                earn_growth is not None
                and earn_growth >= 0.10
            )
        )

        if strong_growth:

            trailing_weight = 0.25
            forward_weight = 0.75

            method = (
                "25 % TTM-EPS + 75 % Forward-EPS "
                "bei starkem profitablem Wachstum"
            )

        elif normal_growth:

            trailing_weight = 0.30
            forward_weight = 0.70

            method = (
                "30 % TTM-EPS + 70 % Forward-EPS "
                "bei normalem Wachstum"
            )

        else:

            trailing_weight = 0.40
            forward_weight = 0.60

            method = (
                "40 % TTM-EPS + 60 % Forward-EPS "
                "bei stabilem Unternehmen"
            )

        base_trailing_weight = trailing_weight
        base_forward_weight = forward_weight
        base_method = method

        divergence_gate = apply_eps_divergence_gate(
            base_trailing_weight,
            base_forward_weight,
            trailing,
            forward
        )

        trailing_weight = divergence_gate[
            "trailing_weight"
        ]
        forward_weight = divergence_gate[
            "forward_weight"
        ]

        if divergence_gate.get("active"):
            method = (
                f"{trailing_weight * 100:.0f} % TTM-EPS + "
                f"{forward_weight * 100:.0f} % Current-FY-EPS "
                "durch EPS-Divergenz-Gate; "
                f"Ausgangsmethode: {base_method}"
            )

        normalized = (
            trailing_weight * trailing +
            forward_weight * forward
        )

        if len(history) >= 3:
            confidence = "Hoch"
        else:
            confidence = "Mittel"

        divergence_metadata = {
            "eps_divergence_gate_active": divergence_gate.get("active", False),
            "eps_divergence_band": divergence_gate.get("band"),
            "eps_divergence_direction": divergence_gate.get("direction"),
            "eps_divergence_note": divergence_gate.get("note"),
            "eps_base_trailing_weight": base_trailing_weight,
            "eps_base_forward_weight": base_forward_weight,
            "eps_used_trailing_weight": trailing_weight,
            "eps_used_forward_weight": forward_weight,
            "eps_basis_comparability_gate_active": generic_comparability.get("active", False),
            "eps_basis_comparability_status": generic_comparability.get("status"),
            "eps_basis_comparability_reason": generic_comparability.get("reason"),
            "structural_review_required": generic_comparability.get("structural_review_required", False),
            "valuation_blocked": generic_comparability.get("blocked", False),
        }

        if generic_comparability.get("blocked"):
            method += "; Earnings-Basis/Structural-Comparability Gate: nur Diagnosewert"

        return build_eps_result(
            normalized,
            method,
            confidence,
            None,
            trailing,
            forward,
            divergence_metadata
        )

    if forward is not None and forward > 0:
        blocked = bool(generic_comparability.get("blocked", False))
        return build_eps_result(
            forward,
            (
                "Nur Forward-EPS verwendbar; Earnings-Basis/Turnaround-Comparability Gate: nur Diagnosewert"
                if blocked else "Nur Forward-EPS verwendbar"
            ),
            "Niedrig",
            None,
            trailing,
            forward,
            {
                "eps_basis_comparability_gate_active": generic_comparability.get("active", False),
                "eps_basis_comparability_status": generic_comparability.get("status"),
                "eps_basis_comparability_reason": generic_comparability.get("reason"),
                "structural_review_required": generic_comparability.get("structural_review_required", False),
                "valuation_blocked": blocked,
            }
        )

    if trailing is not None and trailing > 0:

        return build_eps_result(
            trailing,
            "Nur TTM-EPS verwendbar",
            "Niedrig",
            None,
            trailing,
            forward
        )

    return build_eps_result(
        None,
        "Keine zuverlässige EPS-Normalisierung möglich",
        "Niedrig",
        None,
        trailing,
        forward
    )


