def _insurance_snapshot_is_fresh(snapshot):
    if not isinstance(snapshot, dict):
        return False
    try:
        valid_until = datetime.strptime(
            snapshot.get("valid_until"), "%d.%m.%Y"
        ).date()
        return datetime.now().date() <= valid_until
    except Exception:
        return False



INSURANCE_CORE_COVERAGE_INTEGRATION_VERSION = "v22044_insurance_core_ttm"

def build_insurance_core_coverage(snapshot):
    """
    Build a fail-closed Core-TTM bridge from official insurer periods.

    V2.20.44 deliberately does not annualize 6M data. For Allianz:
    Core TTM = FY2025 - 6M2025 + 6M2026.
    """
    result = {
        "available": False,
        "integration_version": INSURANCE_CORE_COVERAGE_INTEGRATION_VERSION,
        "core_eps_fy_2025": None,
        "core_eps_h1_2025": None,
        "core_eps_h2_2025": None,
        "core_eps_h1_2026": None,
        "core_ttm_eps": None,
        "core_net_income_fy_2025": None,
        "core_net_income_h1_2025": None,
        "core_net_income_h2_2025": None,
        "core_net_income_h1_2026": None,
        "core_ttm_net_income": None,
        "note": None,
    }

    if not isinstance(snapshot, dict):
        result["note"] = (
            "Core-TTM-Abdeckung nicht verfügbar: kein aktueller verifizierter "
            "Versicherungs-Primärquellen-Snapshot."
        )
        return result

    required = {
        "core_eps_fy_2025": safe_float(snapshot.get("core_eps_fy_2025")),
        "core_eps_h1_2025": safe_float(snapshot.get("core_eps_h1_2025")),
        "core_eps_h1_2026": safe_float(snapshot.get("core_eps_h1_2026")),
        "core_net_income_fy_2025": safe_float(snapshot.get("core_net_income_fy_2025")),
        "core_net_income_h1_2025": safe_float(snapshot.get("core_net_income_h1_2025")),
        "core_net_income_h1_2026": safe_float(snapshot.get("core_net_income_h1_2026")),
    }

    if any(value is None or value <= 0 for value in required.values()):
        result["note"] = (
            "Core-TTM-Abdeckung gesperrt: mindestens eine offizielle FY-/6M-"
            "Komponente fehlt oder ist nicht plausibel positiv."
        )
        return result

    core_eps_h2_2025 = required["core_eps_fy_2025"] - required["core_eps_h1_2025"]
    core_ttm_eps = core_eps_h2_2025 + required["core_eps_h1_2026"]

    core_ni_h2_2025 = (
        required["core_net_income_fy_2025"]
        - required["core_net_income_h1_2025"]
    )
    core_ttm_ni = core_ni_h2_2025 + required["core_net_income_h1_2026"]

    if (
        core_eps_h2_2025 <= 0
        or core_ttm_eps <= 0
        or core_ni_h2_2025 <= 0
        or core_ttm_ni <= 0
    ):
        result["note"] = (
            "Core-TTM-Abdeckung gesperrt: die abgeleitete H2- oder TTM-Komponente "
            "ist nicht plausibel positiv."
        )
        return result

    # Round only presentation-sensitive bridge values; keep calculations numeric.
    result.update({
        "available": True,
        **required,
        "core_eps_h2_2025": core_eps_h2_2025,
        "core_ttm_eps": core_ttm_eps,
        "core_net_income_h2_2025": core_ni_h2_2025,
        "core_ttm_net_income": core_ttm_ni,
        "note": (
            "TTM-Earnings-Coverage Gate bestanden: 12M 2025, 6M 2025 und 6M 2026 "
            f"stammen aus offiziellen {snapshot.get('company') or 'Versicherer'}-Primärquellen. "
            "TTM wird als 12M 2025 minus 6M 2025 plus 6M 2026 gebildet; die 6M-Daten "
            "werden ausdrücklich nicht annualisiert."
        ),
    })
    return result


def build_insurance_book_value_bridge(snapshot, yahoo_book_value=None):
    """Official book-value-per-share bridge and annual growth quality check."""
    result = {
        "available": False,
        "bvps_2026_h1": None,
        "bvps_2025_fy": None,
        "bvps_2024_fy": None,
        "bvps_growth_2025_pct": None,
        "yahoo_book_value_deviation_pct": None,
        "note": None,
    }
    if not isinstance(snapshot, dict):
        result["note"] = "Offizieller Buchwert-Abgleich nicht verfügbar."
        return result

    # Prefer issuer-reported carrying/book value per share when the insurer
    # publishes it directly. This avoids small but real distortions from mixing
    # total equity (including non-controlling interests) with ordinary-share counts.
    direct_bvps_26 = safe_float(snapshot.get("book_value_per_share_2026_h1"))
    direct_bvps_25 = safe_float(snapshot.get("book_value_per_share_2025_fy"))
    direct_bvps_24 = safe_float(snapshot.get("book_value_per_share_2024_fy"))
    direct_values = [direct_bvps_26, direct_bvps_25, direct_bvps_24]

    if all(value is not None and value > 0 for value in direct_values):
        bvps_26 = direct_bvps_26
        bvps_25 = direct_bvps_25
        bvps_24 = direct_bvps_24
        book_value_source_mode = "issuer_reported_per_share"
    else:
        eq_26 = safe_float(snapshot.get("shareholders_equity_2026_h1"))
        sh_26 = safe_float(snapshot.get("shares_2026_h1"))
        eq_25 = safe_float(snapshot.get("shareholders_equity_2025_fy"))
        sh_25 = safe_float(snapshot.get("shares_2025_fy"))
        eq_24 = safe_float(snapshot.get("shareholders_equity_2024_fy"))
        sh_24 = safe_float(snapshot.get("shares_2024_fy"))

        values = [eq_26, sh_26, eq_25, sh_25, eq_24, sh_24]
        if any(value is None or value <= 0 for value in values):
            result["note"] = (
                "Offizieller Buchwert-Abgleich gesperrt: Weder vollständige direkt berichtete "
                "Buchwerte je Aktie noch Equity-/Aktienzahl-Daten für alle Vergleichszeitpunkte liegen vor."
            )
            return result

        bvps_26 = eq_26 / sh_26
        bvps_25 = eq_25 / sh_25
        bvps_24 = eq_24 / sh_24
        book_value_source_mode = "derived_from_official_equity_and_shares"

    growth_25 = (bvps_25 / bvps_24 - 1.0) * 100.0

    yahoo_bv = safe_float(yahoo_book_value)
    yahoo_dev = None
    if yahoo_bv is not None and yahoo_bv > 0:
        yahoo_dev = abs(yahoo_bv / bvps_26 - 1.0) * 100.0

    result.update({
        "available": True,
        "bvps_2026_h1": bvps_26,
        "bvps_2025_fy": bvps_25,
        "bvps_2024_fy": bvps_24,
        "bvps_growth_2025_pct": growth_25,
        "yahoo_book_value_deviation_pct": yahoo_dev,
        "source_mode": book_value_source_mode,
        "note": (
            (
                "Offizieller Buchwert-Abgleich: Der direkt von Munich Re berichtete Carrying Amount je Aktie "
                "wird als Buchwertanker verwendet. Für den Score wird die abgeschlossene FY2025-Entwicklung "
                "gegenüber FY2024 verwendet; 6M 2026 wird nicht annualisiert."
            )
            if book_value_source_mode == "issuer_reported_per_share"
            else (
                "Offizieller Buchwert-Abgleich: Buchwert je Aktie wird aus dem verifizierten "
                f"Eigenkapital und der offiziellen Aktienzahl von {snapshot.get('company') or 'dem Versicherer'} "
                "je Stichtag gebildet. Für den Score wird die abgeschlossene FY2025-Entwicklung "
                "gegenüber FY2024 verwendet; 6M 2026 wird nicht annualisiert."
            )
        ),
    })
    return result


def calculate_insurance_score(snapshot, core_coverage, book_bridge):
    """
    Insurer-specific 100-point score.

    Components:
      - underlying Core RoE: 30
      - Solvency II: 25
      - underlying Core EPS growth: 20
      - official book-value-per-share growth: 15
      - distribution quality: 10
    """
    result = {
        "available": False,
        "score": None,
        "quality_level": "Nicht verfügbar",
        "core_roe_points": None,
        "solvency_points": None,
        "core_growth_points": None,
        "book_growth_points": None,
        "distribution_points": None,
        "core_roe_pct": None,
        "solvency_ii_pct": None,
        "underlying_core_eps_growth_pct": None,
        "book_value_growth_pct": None,
        "dividend_core_eps_payout_ratio": None,
        "note": None,
    }

    if not isinstance(snapshot, dict):
        result["note"] = "Versicherungs-Score gesperrt: Primärquellen-Snapshot fehlt."
        return result

    if not (core_coverage or {}).get("available"):
        result["note"] = (
            "Versicherungs-Score gesperrt: vollständige Core-TTM-Abdeckung fehlt."
        )
        return result

    if not (book_bridge or {}).get("available"):
        result["note"] = (
            "Versicherungs-Score gesperrt: offizieller Buchwert-Abgleich fehlt."
        )
        return result

    core_roe = safe_float(snapshot.get("score_roe_pct"))
    if core_roe is None:
        core_roe = safe_float(snapshot.get("underlying_core_roe_pct"))
    solvency = safe_float(snapshot.get("solvency_ii_ratio_pct"))
    core_growth = safe_float(snapshot.get("score_eps_growth_pct"))
    if core_growth is None:
        core_growth = safe_float(snapshot.get("underlying_core_eps_growth_pct"))
    book_growth = safe_float(book_bridge.get("bvps_growth_2025_pct"))
    dividend = safe_float(snapshot.get("dividend_2025_per_share"))
    fy_core_eps = safe_float(snapshot.get("core_eps_fy_2025"))

    if (
        core_roe is None
        or solvency is None
        or core_growth is None
        or book_growth is None
        or dividend is None
        or fy_core_eps is None
        or fy_core_eps <= 0
    ):
        result["note"] = (
            "Versicherungs-Score gesperrt: mindestens eine versicherungsspezifische "
            "Kernkomponente fehlt."
        )
        return result

    payout = dividend / fy_core_eps

    # Core RoE (max 30)
    if core_roe < 10:
        roe_pts = 0
    elif core_roe < 12:
        roe_pts = 10
    elif core_roe < 15:
        roe_pts = 18
    elif core_roe < 18:
        roe_pts = 24
    else:
        roe_pts = 30

    # Solvency II (max 25)
    if solvency < 150:
        solv_pts = 0
    elif solvency < 180:
        solv_pts = 10
    elif solvency < 200:
        solv_pts = 17
    elif solvency < 220:
        solv_pts = 22
    else:
        solv_pts = 25

    # Underlying Core EPS growth (max 20)
    if core_growth <= 0:
        growth_pts = 0
    elif core_growth < 3:
        growth_pts = 5
    elif core_growth < 5:
        growth_pts = 10
    elif core_growth < 7:
        growth_pts = 14
    elif core_growth < 9:
        growth_pts = 17
    else:
        growth_pts = 20

    # Official FY book-value-per-share growth (max 15)
    if book_growth <= 0:
        book_pts = 0
    elif book_growth < 2:
        book_pts = 5
    elif book_growth < 4:
        book_pts = 9
    elif book_growth < 6:
        book_pts = 12
    else:
        book_pts = 15

    # Distribution quality (max 10).
    # 40-65% of FY core EPS is treated as a balanced dividend coverage range.
    if 0.40 <= payout <= 0.65:
        dist_pts = 10
    elif 0.30 <= payout < 0.40 or 0.65 < payout <= 0.80:
        dist_pts = 7
    elif 0.20 <= payout < 0.30 or 0.80 < payout <= 1.00:
        dist_pts = 4
    else:
        dist_pts = 0

    score = roe_pts + solv_pts + growth_pts + book_pts + dist_pts
    if score >= 90:
        quality = "Sehr stark"
    elif score >= 75:
        quality = "Stark"
    elif score >= 60:
        quality = "Solide"
    elif score >= 45:
        quality = "Mittel"
    else:
        quality = "Schwach"

    result.update({
        "available": True,
        "score": float(score),
        "quality_level": quality,
        "core_roe_points": roe_pts,
        "solvency_points": solv_pts,
        "core_growth_points": growth_pts,
        "book_growth_points": book_pts,
        "distribution_points": dist_pts,
        "core_roe_pct": core_roe,
        "solvency_ii_pct": solvency,
        "underlying_core_eps_growth_pct": core_growth,
        "book_value_growth_pct": book_growth,
        "dividend_core_eps_payout_ratio": payout,
        "note": (
            "Der Versicherungs-Score verwendet ausschließlich versicherungsspezifische "
            "Qualitäts-, Kapital- und Ausschüttungsanker. Wachstum und RoE stammen aus der "
            f"freigegebenen issuer-spezifischen Primärquellenbasis von {snapshot.get('company') or 'dem Versicherer'}; "
            "es wird keine Yahoo-/Standard-Ertragsgröße in den Score gemischt."
        ),
    })
    return result



INSURANCE_VALUATION_INTEGRATION_VERSION = "v22044_insurance_dual_anchor"


def calculate_insurance_dual_anchor_valuation(snapshot, core_coverage, book_bridge, insurance_score):
    """V2.20.44 insurer valuation: official BV/P-B + Core-TTM EPS/Core-P-E.

    Fail closed when the primary-source chain is incomplete or the two
    valuation anchors diverge by more than 25%.
    """
    result = {
        "available": False,
        "integration_version": INSURANCE_VALUATION_INTEGRATION_VERSION,
        "insurance_score": None,
        "pb_corridor_lower": safe_float((snapshot or {}).get("pb_corridor_lower")) or 1.0,
        "pb_corridor_upper": safe_float((snapshot or {}).get("pb_corridor_upper")) or 2.8,
        "core_pe_corridor_lower": safe_float((snapshot or {}).get("core_pe_corridor_lower")) or 8.0,
        "core_pe_corridor_upper": safe_float((snapshot or {}).get("core_pe_corridor_upper")) or 14.0,
        "target_pb": None,
        "target_core_pe": None,
        "official_bvps": None,
        "core_ttm_eps": None,
        "fair_value_book_financial": None,
        "fair_value_core_pe_financial": None,
        "book_weight": safe_float((snapshot or {}).get("book_weight")) or 0.55,
        "core_pe_weight": safe_float((snapshot or {}).get("core_pe_weight")) or 0.45,
        "earnings_basis_label": (snapshot or {}).get("earnings_basis_label") or "Core",
        "earnings_multiple_label": (
            "Reported-TTM-KGV" if (snapshot or {}).get("profile_key") == "munich_re_reinsurance" else "Core-KGV"
        ),
        "anchor_spread_pct": None,
        "fair_value_financial": None,
        "release_reason": None,
        "note": None,
    }

    if not isinstance(snapshot, dict):
        result["note"] = "Versicherungsbewertung gesperrt: Primärquellen-Snapshot fehlt."
        return result
    if not (core_coverage or {}).get("available"):
        result["note"] = "Versicherungsbewertung gesperrt: Core-TTM-Abdeckung fehlt."
        return result
    if not (book_bridge or {}).get("available"):
        result["note"] = "Versicherungsbewertung gesperrt: offizieller Buchwert-Abgleich fehlt."
        return result
    if not (insurance_score or {}).get("available"):
        result["note"] = "Versicherungsbewertung gesperrt: Versicherungs-Score fehlt."
        return result

    score = safe_float(insurance_score.get("score"))
    bvps = safe_float(book_bridge.get("bvps_2026_h1"))
    core_ttm_eps = safe_float(core_coverage.get("core_ttm_eps"))
    yahoo_dev = safe_float(book_bridge.get("yahoo_book_value_deviation_pct"))

    if score is None or score < 0 or score > 100 or bvps is None or bvps <= 0 or core_ttm_eps is None or core_ttm_eps <= 0:
        result["note"] = "Versicherungsbewertung gesperrt: Score, Buchwert oder Core-TTM-EPS sind nicht plausibel."
        return result

    # The official BVPS is the valuation anchor. A material Yahoo-vs-official
    # book-value conflict blocks release, but Yahoo never becomes the anchor.
    if yahoo_dev is not None and yahoo_dev > 20.0:
        result["note"] = (
            "Versicherungsbewertung gesperrt: offizieller Buchwert und Yahoo-Buchwert "
            "weichen um mehr als 20 % voneinander ab."
        )
        return result

    pb_low = safe_float(snapshot.get("pb_corridor_lower")) or 1.0
    pb_high = safe_float(snapshot.get("pb_corridor_upper")) or 2.8
    pe_low = safe_float(snapshot.get("core_pe_corridor_lower")) or 8.0
    pe_high = safe_float(snapshot.get("core_pe_corridor_upper")) or 14.0
    score_fraction = score / 100.0
    target_pb = pb_low + score_fraction * (pb_high - pb_low)
    target_core_pe = pe_low + score_fraction * (pe_high - pe_low)

    fv_book = bvps * target_pb
    fv_core = core_ttm_eps * target_core_pe
    if fv_book <= 0 or fv_core <= 0:
        result["note"] = "Versicherungsbewertung gesperrt: mindestens ein Bewertungsanker ist nicht positiv."
        return result

    anchor_spread_pct = abs(fv_book / fv_core - 1.0) * 100.0
    if anchor_spread_pct > 25.0:
        result.update({
            "insurance_score": score,
            "target_pb": target_pb,
            "target_core_pe": target_core_pe,
            "official_bvps": bvps,
            "core_ttm_eps": core_ttm_eps,
            "fair_value_book_financial": fv_book,
            "fair_value_core_pe_financial": fv_core,
            "anchor_spread_pct": anchor_spread_pct,
            "release_reason": "anchor_gap",
            "note": (
                "Versicherungsbewertung gesperrt: Buchwert/P-B- und Core-KGV-Anker "
                f"liegen {anchor_spread_pct:.1f} % auseinander; maximal 25 % sind zulässig."
            ),
        })
        return result

    book_weight = safe_float(snapshot.get("book_weight")) or 0.55
    core_pe_weight = safe_float(snapshot.get("core_pe_weight")) or 0.45
    weight_sum = book_weight + core_pe_weight
    if weight_sum <= 0:
        result["note"] = "Versicherungsbewertung gesperrt: Dual-Anchor-Gewichte sind nicht plausibel."
        return result
    book_weight /= weight_sum
    core_pe_weight /= weight_sum
    fair_value = book_weight * fv_book + core_pe_weight * fv_core
    result.update({
        "available": True,
        "insurance_score": score,
        "target_pb": target_pb,
        "target_core_pe": target_core_pe,
        "official_bvps": bvps,
        "core_ttm_eps": core_ttm_eps,
        "fair_value_book_financial": fv_book,
        "fair_value_core_pe_financial": fv_core,
        "anchor_spread_pct": anchor_spread_pct,
        "fair_value_financial": fair_value,
        "book_weight": book_weight,
        "core_pe_weight": core_pe_weight,
        "earnings_basis_label": snapshot.get("earnings_basis_label") or "Core",
        "earnings_multiple_label": (
            "Reported-TTM-KGV" if snapshot.get("profile_key") == "munich_re_reinsurance" else "Core-KGV"
        ),
        "release_reason": "passed",
        "note": (
            (
                "Bewertungsfreigabe JA: Versicherungs-Score sowie offizieller P/B- und "
                "Reported-TTM-KGV-Anker sind vollständig und ausreichend konsistent. Der "
                "Munich-Re-Dual-Anchor-Fair-Value ist freigegeben."
            )
            if snapshot.get("profile_key") == "munich_re_reinsurance"
            else (
                "Bewertungsfreigabe JA: Versicherungs-Score sowie offizieller P/B- und "
                "Core-KGV-Anker sind vollständig und ausreichend konsistent. Der "
                "Dual-Anchor-Fair-Value ist freigegeben."
            )
        ),
    })
    return result

def build_insurance_special_model(
    company_type,
    info,
    price,
    currency_context,
    symbol=None
):
    """
    Conservative insurer-specific data block.

    V2.20.44 adds an official Core-TTM coverage bridge, book-value quality
    check, insurer-specific 100-point score and fail-closed dual-anchor valuation.
    Core earnings and solvency/capital ratios are never estimated from Yahoo proxies.
    """
    type_name = str(
        company_type.get("type", "")
    ).lower()

    if "versicherung" not in type_name:
        return {
            "applicable": False
        }

    snapshot = get_verified_insurance_snapshot(symbol)
    snapshot_fresh = _insurance_snapshot_is_fresh(snapshot)
    insurance_profile_key = (snapshot or {}).get("profile_key")
    is_munich_re_profile = insurance_profile_key == "munich_re_reinsurance"
    earnings_basis_label = (snapshot or {}).get("earnings_basis_label") or "Core"
    earnings_ttm_label = "Reported-TTM" if is_munich_re_profile else "Core-TTM"

    core_net_income = safe_float(
        (snapshot or {}).get("shareholders_core_net_income")
    ) if snapshot_fresh else None
    core_eps = safe_float(
        (snapshot or {}).get("core_eps_basic")
    ) if snapshot_fresh else None
    core_roe = safe_float(
        (snapshot or {}).get("core_roe_annualized_pct")
    ) if snapshot_fresh else None
    solvency_ii = safe_float(
        (snapshot or {}).get("solvency_ii_ratio_pct")
    ) if snapshot_fresh else None

    primary_source_complete = bool(
        snapshot_fresh
        and core_net_income is not None
        and core_net_income > 0
        and core_eps is not None
        and core_eps > 0
        and core_roe is not None
        and core_roe > 0
        and solvency_ii is not None
        and solvency_ii > 100
    )

    # V2.20.136 – schema-preserving fail-closed insurance gate.
    # Prior builds returned an uninitialized local ``primary_gate`` here,
    # which aborted the complete stock load for every insurance issuer before
    # the intended unsupported-issuer fallback could render. This gate is
    # informational only; valuation release continues to be controlled by the
    # existing primary_source_complete/Core-TTM/book-value/score/dual-anchor checks.
    primary_gate = {
        "available": bool(primary_source_complete),
        "passed": bool(primary_source_complete),
        "snapshot_fresh": bool(snapshot_fresh),
        "note": (
            "Versicherungs-Primärquellen-Gate bestanden."
            if primary_source_complete
            else (
                "Versicherungs-Primärquellen-Gate nicht freigegeben: Für diesen "
                "Emittenten liegt kein aktueller verifizierter issuer-spezifischer "
                "Primärquellen-Snapshot vor. Yahoo-/Standarddaten bleiben Kontext; "
                "Versicherungs-Score und Dual-Anchor-Fair-Value bleiben fail-closed."
            )
        ),
    }

    quote_price = safe_float(price)
    price_financial = convert_quote_price_to_financial_share_unit(
        quote_price,
        currency_context
    )

    book_value = safe_float(
        info.get("bookValue")
    )
    roe = safe_float(
        info.get("returnOnEquity")
    )
    trailing_eps = safe_float(
        info.get("trailingEps")
    )
    forward_eps = safe_float(
        info.get("forwardEps")
    )
    raw_dividend_yield = safe_float(
        info.get("dividendYield")
    )
    trailing_annual_dividend_yield = safe_float(
        info.get("trailingAnnualDividendYield")
    )
    dividend_rate = safe_float(
        info.get("dividendRate")
    )
    payout_ratio = safe_float(
        info.get("payoutRatio")
    )
    yahoo_price_to_book = safe_float(
        info.get("priceToBook")
    )

    # -----------------------------------------------------
    # KBV: nur anzeigen, wenn Kurs/Buchwert und Yahoo-KBV
    # als zweiter Anker ausreichend gut zusammenpassen.
    # -----------------------------------------------------
    calculated_price_to_book = None
    if (
        price_financial is not None
        and price_financial > 0
        and book_value is not None
        and book_value > 0
    ):
        calculated_price_to_book = (
            price_financial / book_value
        )

    pb_display_value = None
    pb_consistency_status = "unverified"
    pb_consistency_note = None

    if calculated_price_to_book is None:
        pb_consistency_note = (
            "KBV konnte aus Kurs und Buchwert je Aktie nicht "
            "belastbar berechnet werden. Es wird kein Wert geschätzt."
        )

    elif (
        yahoo_price_to_book is not None
        and yahoo_price_to_book > 0
    ):
        pb_deviation = abs(
            calculated_price_to_book
            / yahoo_price_to_book
            - 1.0
        )

        if pb_deviation <= 0.20:
            pb_display_value = calculated_price_to_book
            pb_consistency_status = "plausible"
            pb_consistency_note = (
                "KBV-Plausibilitätscheck bestanden: Das aus Kurs und "
                "Buchwert je Aktie berechnete KBV liegt innerhalb von "
                "20 % des separat gemeldeten Yahoo-KBV. Der Wert bleibt "
                "trotzdem nur eine Datenbasis und erzeugt noch keine Bewertung."
            )
        else:
            pb_consistency_status = "conflict"
            pb_consistency_note = (
                "⚠️ KBV-Einheiten/Plausibilität widersprüchlich: Das aus "
                "Kurs und Buchwert je Aktie berechnete KBV weicht um mehr "
                "als 20 % vom separat gemeldeten Yahoo-KBV ab. Deshalb wird "
                "das KBV nicht als belastbare Kennzahl angezeigt und nicht "
                "für eine Bewertung verwendet."
            )

    else:
        pb_consistency_note = (
            "KBV konnte zwar aus Kurs und Buchwert je Aktie berechnet werden, "
            "aber ein zweiter Yahoo-KBV-Anker fehlt. Der Wert wird deshalb "
            "nicht als belastbar angezeigt und nicht für eine Bewertung verwendet."
        )

    # -----------------------------------------------------
    # KGV-Referenzen: reine Datenbasis, keine Bewertung.
    # -----------------------------------------------------
    calculated_forward_pe = None
    if (
        price_financial is not None
        and price_financial > 0
        and forward_eps is not None
        and forward_eps > 0
    ):
        calculated_forward_pe = (
            price_financial / forward_eps
        )

    calculated_trailing_pe = None
    if (
        price_financial is not None
        and price_financial > 0
        and trailing_eps is not None
        and trailing_eps > 0
    ):
        calculated_trailing_pe = (
            price_financial / trailing_eps
        )

    # -----------------------------------------------------
    # Dividendenrendite: Yahoo liefert je nach Feld/Version
    # teils Verhältniswerte, teils bereits Prozentzahlen.
    # Wir normalisieren nur, wenn die Darstellung eindeutig
    # oder durch DividendRate/Kurs plausibilisiert ist.
    # Bei unklaren/absurden Werten bleibt die Kennzahl leer.
    # -----------------------------------------------------
    calculated_dividend_yield = None
    if (
        dividend_rate is not None
        and dividend_rate >= 0
        and price_financial is not None
        and price_financial > 0
    ):
        candidate = dividend_rate / price_financial
        if 0 <= candidate <= 0.25:
            calculated_dividend_yield = candidate

    def dividend_yield_candidates(raw_value):
        value = safe_float(raw_value)
        if value is None or value < 0:
            return []

        candidates = []

        # Eindeutiger Verhältniswert: z. B. 0.074 = 7.4 %.
        if value <= 0.25:
            candidates.append((
                "ratio",
                value
            ))

        # Mögliche bereits-prozentuale Yahoo-Darstellung:
        # z. B. 7.41 = 7.41 % -> 0.0741.
        if value <= 25.0:
            percent_candidate = value / 100.0
            if percent_candidate <= 0.25:
                candidates.append((
                    "percent",
                    percent_candidate
                ))

        return candidates

    raw_yield_candidates = dividend_yield_candidates(
        raw_dividend_yield
    )
    trailing_yield_candidates = dividend_yield_candidates(
        trailing_annual_dividend_yield
    )

    dividend_yield = None
    dividend_yield_source = None
    dividend_yield_note = None

    # Primär: DividendRate/Kurs als unabhängiger Plausibilitätsanker.
    if calculated_dividend_yield is not None:
        all_candidates = (
            raw_yield_candidates
            + trailing_yield_candidates
        )

        matching_candidates = []
        for candidate_type, candidate_value in all_candidates:
            absolute_difference = abs(
                candidate_value
                - calculated_dividend_yield
            )
            relative_difference = (
                absolute_difference
                / max(
                    calculated_dividend_yield,
                    0.01
                )
            )

            if (
                absolute_difference <= 0.005
                or relative_difference <= 0.20
            ):
                matching_candidates.append((
                    candidate_type,
                    candidate_value
                ))

        if matching_candidates:
            dividend_yield = calculated_dividend_yield
            dividend_yield_source = (
                "DividendRate/Kurs + Yahoo-Rendite plausibilisiert"
            )

            used_percent_format = any(
                candidate_type == "percent"
                for candidate_type, _ in matching_candidates
            )

            if used_percent_format:
                dividend_yield_note = (
                    "Yahoo liefert die Dividendenrendite in diesem Fall "
                    "offenbar bereits als Prozentzahl. Die Anzeige wurde "
                    "nicht blind mit 100 multipliziert, sondern über "
                    "Dividendenrate/Kurs plausibilisiert und auf einen "
                    "einheitlichen Verhältniswert normalisiert."
                )
            else:
                dividend_yield_note = (
                    "Dividendenrendite wurde über Dividendenrate/Kurs "
                    "plausibilisiert."
                )

        elif (
            raw_dividend_yield is None
            and trailing_annual_dividend_yield is None
        ):
            dividend_yield = calculated_dividend_yield
            dividend_yield_source = "DividendRate/Kurs"
            dividend_yield_note = (
                "Yahoo liefert keine separate Dividendenrendite. Die "
                "Rendite wird transparent aus Yahoo-Dividendenrate und "
                "dem für Verhältniskennzahlen angeglichenen Kurs berechnet."
            )

        else:
            dividend_yield_note = (
                "⚠️ Dividendenrendite nicht belastbar: Die Yahoo-Rendite "
                "passt weder als Verhältniswert noch als Prozentdarstellung "
                "ausreichend zur Dividendenrate/Kurs-Plausibilisierung. "
                "Der Wert wird deshalb als fehlend behandelt."
            )

    # Ohne DividendRate/Kurs nur eindeutig plausible Verhältniswerte zulassen.
    elif (
        raw_dividend_yield is not None
        and 0 <= raw_dividend_yield <= 0.25
    ):
        dividend_yield = raw_dividend_yield
        dividend_yield_source = "Yahoo dividendYield"
        dividend_yield_note = (
            "Yahoo-Dividendenrendite liegt als plausibler Verhältniswert vor."
        )

    elif (
        raw_dividend_yield is not None
        or trailing_annual_dividend_yield is not None
    ):
        dividend_yield_note = (
            "⚠️ Dividendenrendite nicht belastbar: Die Yahoo-Darstellung "
            "ist ohne einen unabhängigen Dividendenrate/Kurs-Anker nicht "
            "eindeutig als Verhältnis- oder Prozentwert interpretierbar. "
            "Es wird nicht geraten oder automatisch durch 100 geteilt."
        )

    # -----------------------------------------------------
    # Ausschüttungsquote: auffällige Werte markieren,
    # aber niemals automatisch verändern.
    # -----------------------------------------------------
    payout_ratio_note = None
    if payout_ratio is not None:
        if payout_ratio > 1.0:
            payout_ratio_note = (
                "⚠️ Ausschüttungsquote über 100 % erkannt. Der Yahoo-Wert "
                "wird unverändert angezeigt, aber nicht als normal oder "
                "nachhaltig interpretiert und nicht automatisch korrigiert."
            )
        elif payout_ratio < 0:
            payout_ratio_note = (
                "⚠️ Negative Ausschüttungsquote erkannt. Der Wert wird "
                "unverändert angezeigt und nicht automatisch interpretiert."
            )

    anchor_values = [
        roe,
        book_value,
        pb_display_value,
        calculated_forward_pe
    ]
    available_anchors = sum(
        value is not None
        for value in anchor_values
    )

    core_coverage = (
        build_insurance_core_coverage(snapshot)
        if snapshot_fresh
        else {
            "available": False,
            "integration_version": INSURANCE_CORE_COVERAGE_INTEGRATION_VERSION,
            "note": "Core-TTM-Abdeckung nicht verfügbar: Versicherungs-Snapshot ist veraltet.",
        }
    )

    book_value_bridge = (
        build_insurance_book_value_bridge(snapshot, yahoo_book_value=book_value)
        if snapshot_fresh
        else {
            "available": False,
            "note": "Offizieller Buchwert-Abgleich nicht verfügbar: Versicherungs-Snapshot ist veraltet.",
        }
    )

    insurance_score = (
        calculate_insurance_score(snapshot, core_coverage, book_value_bridge)
        if snapshot_fresh
        else {
            "available": False,
            "score": None,
            "quality_level": "Nicht verfügbar",
            "note": "Versicherungs-Score gesperrt: Versicherungs-Snapshot ist veraltet.",
        }
    )

    insurance_valuation = (
        calculate_insurance_dual_anchor_valuation(
            snapshot, core_coverage, book_value_bridge, insurance_score
        )
        if snapshot_fresh
        else {
            "available": False,
            "integration_version": INSURANCE_VALUATION_INTEGRATION_VERSION,
            "note": "Versicherungsbewertung gesperrt: Versicherungs-Snapshot ist veraltet.",
        }
    )

    readiness = (
        f"{earnings_ttm_label} + Score + Bewertung vollständig"
        if (
            primary_source_complete
            and core_coverage.get("available")
            and book_value_bridge.get("available")
            and insurance_score.get("available")
            and insurance_valuation.get("available")
        )
        else (
            f"{earnings_ttm_label} + Score vollständig"
            if (
                primary_source_complete
                and core_coverage.get("available")
                and book_value_bridge.get("available")
                and insurance_score.get("available")
            )
            else (
                "Primärdaten vollständig"
                if primary_source_complete
                else (
                    "Teilweise"
                    if available_anchors >= 3
                    else "Unvollständig"
                )
            )
        )
    )

    return {
        "applicable": True,
        "profile_key": insurance_profile_key,
        "is_munich_re_profile": is_munich_re_profile,
        "earnings_basis_label": earnings_basis_label,
        "earnings_ttm_label": earnings_ttm_label,
        "snapshot": snapshot,
        "snapshot_fresh": snapshot_fresh,
        "adapter_diagnostic": adapter_diagnostic,
        "primary_source_complete": primary_source_complete,
        "primary_gate": primary_gate,
        "price_financial": price_financial,
        "book_value_per_share": book_value,
        "roe": roe,
        "dividend_yield": dividend_yield,
        "dividend_yield_raw": raw_dividend_yield,
        "dividend_yield_source": dividend_yield_source,
        "dividend_yield_note": dividend_yield_note,
        "dividend_rate": dividend_rate,
        "payout_ratio": payout_ratio,
        "payout_ratio_note": payout_ratio_note,
        "calculated_price_to_book": calculated_price_to_book,
        "display_price_to_book": pb_display_value,
        "yahoo_price_to_book": yahoo_price_to_book,
        "pb_consistency_status": pb_consistency_status,
        "calculated_forward_pe": calculated_forward_pe,
        "calculated_trailing_pe": calculated_trailing_pe,
        "pb_consistency_note": pb_consistency_note,
        "readiness": readiness,
        "snapshot": snapshot,
        "snapshot_fresh": snapshot_fresh,
        "primary_source_complete": primary_source_complete,
        "core_earnings_available": core_net_income is not None and core_eps is not None,
        "solvency_capital_available": solvency_ii is not None,
        "shareholders_core_net_income": core_net_income,
        "core_eps_basic": core_eps,
        "core_roe_annualized_pct": core_roe,
        "solvency_ii_ratio_pct": solvency_ii,
        "shareholders_net_income": safe_float((snapshot or {}).get("shareholders_net_income")) if snapshot_fresh else None,
        "basic_eps_reported": safe_float((snapshot or {}).get("basic_eps_reported")) if snapshot_fresh else None,
        "core_eps_growth_pct": safe_float((snapshot or {}).get("core_eps_growth_pct")) if snapshot_fresh else None,
        "core_net_income_growth_pct": safe_float((snapshot or {}).get("shareholders_core_net_income_growth_pct")) if snapshot_fresh else None,
        "solvency_ii_prior_pct": safe_float((snapshot or {}).get("solvency_ii_prior_pct")) if snapshot_fresh else None,
        "solvency_ii_change_pp": safe_float((snapshot or {}).get("solvency_ii_change_pp")) if snapshot_fresh else None,
        "underlying_growth_note": (snapshot or {}).get("underlying_growth_note") if snapshot_fresh else None,
        "underlying_core_eps_growth_pct": safe_float((snapshot or {}).get("underlying_core_eps_growth_pct")) if snapshot_fresh else None,
        "underlying_core_net_income_growth_pct": safe_float((snapshot or {}).get("underlying_core_net_income_growth_pct")) if snapshot_fresh else None,
        "underlying_core_roe_pct": safe_float((snapshot or {}).get("underlying_core_roe_pct")) if snapshot_fresh else None,
        "core_coverage": core_coverage,
        "book_value_bridge": book_value_bridge,
        "insurance_score": insurance_score,
        "insurance_valuation": insurance_valuation,
        "note": (
            (
                "Munich Re Specialist V2.20.137 lädt issuer-reported IFRS Net Result/EPS, RoE, "
                "Solvency II, die nicht annualisierte Reported-TTM-Brücke, offiziellen Buchwert, "
                "Combined-Ratio-Kontext und den Versicherungs-Score. Der Dual-Anchor-Fair-Value "
                "kombiniert 55 % offiziellen Buchwert/P-B mit 45 % Reported-TTM-EPS/KGV; "
                "Yahoo-FCF/ROE/Buchwert bleiben reine Kontextwerte."
            )
            if is_munich_re_profile
            else (
                "Versicherungs-Sondermodell V2.20.44 lädt verifizierte Core Earnings/Core EPS, "
                "Core RoE und Solvency II, die vollständige Core-TTM-Brücke, den offiziellen "
                "Buchwert je Aktie und den 100-Punkte-Versicherungs-Score. Bei vollständiger "
                "und konsistenter Datenbasis wird ein Dual-Anchor-Fair-Value aus 55 % offiziellem "
                "Buchwert/P-B und 45 % Core-TTM-EPS/Core-KGV freigegeben. Die 6M-Daten werden "
                "nicht annualisiert."
            )
        )
    }


def build_insurance_special_control(base_control, insurance_model):
    """Attach the frozen V2.20.44 insurer step-3B dual-anchor gate."""
    control = dict(base_control or {})
    control.setdefault("router_status", control.get("status"))
    control.setdefault("router_note", control.get("note"))

    if control.get("control_key") != "insurance_core_capital":
        return control

    model = insurance_model if isinstance(insurance_model, dict) else {}
    snapshot = model.get("snapshot")
    is_munich_re_profile = bool(model.get("is_munich_re_profile"))
    earnings_ttm_label = model.get("earnings_ttm_label") or "Core-TTM"

    if is_munich_re_profile:
        control.update({
            "control_name": "Munich Re / Reported-Earnings-, Solvency- & Kapitalprüfung",
            "planned_checks": [
                "Issuer-reported IFRS Net Result / Reported-TTM-EPS",
                "H1 RoE / FY2025 EPS-Wachstum",
                "Offizieller Buchwert / P-B",
                "Solvency II",
                "Combined Ratios / Reinsurance-Zyklus-Kontext",
                "Dividende / Buyback / Ausschüttungsqualität",
                "Munich-Re-Versicherungs-Score",
            ],
            "status": "Router aktiv – V2.20.137 Munich Re Reinsurance Specialist V1",
            "note": (
                "V2.20.137 trennt Yahoo-Kontextdaten von Munich-Re-Primärdaten. Reported-TTM-EPS, "
                "offizieller Buchwert, RoE, Solvency II und reinsurer-spezifische Multiple-Korridore "
                "werden nur aus verifizierten Primärquellen aufgebaut."
            ),
        })

    if not model.get("primary_source_complete"):
        control.update({
            "implemented": False,
            "released": False,
            "confidence_cap": "Niedrig",
            "step3b_status": "Primärdaten unvollständig oder veraltet",
            "overall_status": "Nicht freigegeben",
            "snapshot": snapshot,
            "note": (
                "Die Versicherungs-Primärdatenprüfung benötigt aktuelle Core Earnings/Core EPS, "
                "Core RoE und Solvency II aus einer offiziellen Quelle. Fehlende Werte werden "
                "nicht durch Nettogewinn, Standard-EPS, Yahoo-ROE oder Bilanz-Proxies ersetzt."
            ),
        })
        return control

    core_coverage = model.get("core_coverage") or {}
    book_bridge = model.get("book_value_bridge") or {}
    insurance_score = model.get("insurance_score") or {}
    insurance_valuation = model.get("insurance_valuation") or {}

    score_ready = bool(
        core_coverage.get("available")
        and core_coverage.get("integration_version") == INSURANCE_CORE_COVERAGE_INTEGRATION_VERSION
        and book_bridge.get("available")
        and insurance_score.get("available")
    )
    valuation_ready = bool(
        score_ready
        and insurance_valuation.get("available")
        and insurance_valuation.get("integration_version") == INSURANCE_VALUATION_INTEGRATION_VERSION
    )

    control.update({
        "implemented": True,
        "released": valuation_ready,
        "confidence_cap": "Mittel" if valuation_ready else "Niedrig",
        "step3b_status": (
            "Dual-Anchor-Bewertung freigegeben"
            if valuation_ready
            else (
                f"{earnings_ttm_label} + Versicherungs-Score vollständig – Bewertung gesperrt"
                if score_ready
                else f"Primärdaten vollständig – {earnings_ttm_label}/Score noch unvollständig"
            )
        ),
        "overall_status": (
            f"{earnings_ttm_label} + Score + Bewertung vollständig"
            if valuation_ready
            else (
                f"{earnings_ttm_label} + Score vollständig"
                if score_ready
                else "Primärdaten vollständig"
            )
        ),
        "snapshot": snapshot,
        "checks": {
            "shareholders_core_net_income": model.get("shareholders_core_net_income"),
            "core_eps_basic": model.get("core_eps_basic"),
            "core_roe_annualized_pct": model.get("core_roe_annualized_pct"),
            "underlying_core_roe_pct": model.get("underlying_core_roe_pct"),
            "solvency_ii_ratio_pct": model.get("solvency_ii_ratio_pct"),
            "core_eps_growth_pct": model.get("core_eps_growth_pct"),
            "underlying_core_eps_growth_pct": model.get("underlying_core_eps_growth_pct"),
            "core_net_income_growth_pct": model.get("core_net_income_growth_pct"),
            "underlying_core_net_income_growth_pct": model.get("underlying_core_net_income_growth_pct"),
            "solvency_ii_prior_pct": model.get("solvency_ii_prior_pct"),
            "solvency_ii_change_pp": model.get("solvency_ii_change_pp"),
            "core_coverage": core_coverage,
            "book_value_bridge": book_bridge,
            "insurance_score": insurance_score,
            "insurance_valuation": insurance_valuation,
            "profile_key": model.get("profile_key"),
            "is_munich_re_profile": is_munich_re_profile,
            "earnings_basis_label": model.get("earnings_basis_label"),
            "earnings_ttm_label": earnings_ttm_label,
        },
        "note": (
            (
                "Munich-Re-Schritt 3B V2.20.137 validiert issuer-reported IFRS-Earnings/EPS, "
                "RoE, Solvency II, die nicht annualisierte Reported-TTM-Brücke, offiziellen "
                "Buchwert sowie reinsurer-spezifische P/B- und KGV-Anker. Die Bewertung wird "
                "nur bei vollständiger und konsistenter Dual-Anchor-Prüfung freigegeben."
            )
            if is_munich_re_profile
            else (
                "Versicherungs-Schritt 3B V2.20.44 validiert die offizielle Core-Earnings-/"
                "Kapitalbasis, die nicht annualisierte Core-TTM-Brücke, den offiziellen "
                "Buchwert-Abgleich, den 100-Punkte-Versicherungs-Score sowie getrennte "
                "P/B- und Core-KGV-Anker. Die Bewertung wird nur bei vollständiger und "
                "konsistenter Dual-Anchor-Prüfung freigegeben."
            )
        ),
    })
    return control


# =========================================================
# Banken-Sondermodell V2.20.39 – Bank TTM Special-Item Coverage Gate + Dual-Anchor Valuation
# =========================================================

BANK_TTM_COVERAGE_INTEGRATION_VERSION = "v22039_ttm_4q"

BANK_PRIMARY_SOURCE_ADAPTER_VERSION = "v22148_universal_bank_cet1_row_q4_publication_metadata_v44"
BANK_DISCOVERY_CACHE_EPOCH = BANK_PRIMARY_SOURCE_ADAPTER_VERSION
# Latest-quarter company-designated EPS adjustments at or below 2% are treated
# as immaterial for the separate ROTCE anchor when the issuer publishes no
# adjusted ROTCE. The reported issuer ROTCE is retained; no synthetic ROTCE is
# calculated. Material adjustments remain fail-closed.
BANK_ROTCE_EPS_BRIDGE_IMMATERIALITY_LIMIT = 0.02


def _bank_source_url_is_allowed(snapshot, url):
    """Accept only SEC or issuer-declared official hosts for bank TTM coverage."""
    host = _normalize_host(url)
    if not host:
        return False
    if host == "sec.gov" or host.endswith(".sec.gov"):
        return True
    allowed = [str(x or "").lower().strip() for x in (snapshot or {}).get("allowed_source_hosts", [])]
    for domain in allowed:
        if domain.startswith("www."):
            domain = domain[4:]
        if host == domain or host.endswith("." + domain):
            return True
    return False


def _bank_period_sort_key(period):
    m = re.fullmatch(r"([1-4])Q(\d{2})", str(period or "").upper().strip())
    if not m:
        return (-1, -1)
    q = int(m.group(1))
    y = 2000 + int(m.group(2))
    return (y, q)


def _bank_period_from_text(text):
    """Normalize common quarter labels found in issuer IR anchors, URLs and documents."""
    t = _clean_text(text).replace("_", " ").replace("-", " ")
    patterns = [
        r"\b([1-4])Q\s*'?([0-9]{2,4})\b",
        r"\bQ([1-4])\s*'?([0-9]{2,4})\b",
    ]
    for pat in patterns:
        m = re.search(pat, t, flags=re.I)
        if m:
            y = int(m.group(2))
            if y < 100:
                y += 2000
            return f"{int(m.group(1))}Q{str(y)[-2:]}"
    names = {"first": 1, "second": 2, "third": 3, "fourth": 4}
    m = re.search(r"\b(first|second|third|fourth)\s+quarter(?:\s+ended)?\s+(20\d{2})\b", t, flags=re.I)
    if m:
        return f"{names[m.group(1).lower()]}Q{m.group(2)[-2:]}"
    # Generic table/release wording such as “quarter ended June 30, 2026”.
    month_to_quarter = {
        "march": 1, "mar": 1, "june": 2, "jun": 2,
        "september": 3, "sep": 3, "sept": 3,
        "december": 4, "dec": 4,
    }
    m = re.search(
        r"\bquarter\s+ended\s+(march|mar|june|jun|september|sep|sept|december|dec)\s+\d{1,2},?\s+(20\d{2})\b",
        t, flags=re.I,
    )
    if m:
        return f"{month_to_quarter[m.group(1).lower()]}Q{m.group(2)[-2:]}"
    # V2.21.27: many banks title the January Q4 release as "Full Year YYYY"
    # even though the payload contains the standalone fourth-quarter results.
    # Treat that wording as Q4 only when the discovery text itself also carries
    # earnings/results semantics; ordinary annual reports do not pass this gate.
    low = t.lower()
    m = re.search(r"\b(?:full\s*year|full-year|fiscal\s+year)\s+(20\d{2})\b", t, flags=re.I)
    if m and any(term in low for term in ["earnings", "financial results", "net income", "reports", "results"]):
        return f"4Q{m.group(1)[-2:]}"
    return None


def _bank_previous_period(period, steps=1):
    key = _bank_period_sort_key(period)
    if key[0] < 0:
        return None
    y, q = key
    for _ in range(max(0, int(steps))):
        if q == 1:
            y -= 1
            q = 4
        else:
            q -= 1
    return f"{q}Q{str(y)[-2:]}"


def _bank_consecutive_periods_ending(latest_period, count=4):
    rows = []
    for offset in range(max(0, int(count)) - 1, -1, -1):
        p = _bank_previous_period(latest_period, offset)
        if p:
            rows.append(p)
    return rows


def _bank_period_end_date(period):
    key = _bank_period_sort_key(period)
    if key[0] < 0:
        return None
    y, q = key
    month_day = {1: (3, 31), 2: (6, 30), 3: (9, 30), 4: (12, 31)}[q]
    return datetime(y, month_day[0], month_day[1]).date()


def _bank_extract_first_float(text, patterns):
    t = _clean_text(text)
    for pat in patterns:
        m = re.search(pat, t, flags=re.I | re.S)
        if m:
            try:
                return float(str(m.group(1)).replace(",", ""))
            except Exception:
                pass
    return None


def _bank_numeric_values_from_tail(tail, min_value=None, max_value=None, limit=10):
    """Parse flattened PDF table cells without treating quarter-label digits as values."""
    raw_tail = str(tail or "")
    raw_tail = re.sub(r"^(?:\s*\(\d{1,2}\)\s*)+", " ", raw_tail)
    values = []
    first_pos = None
    token_re = re.compile(
        r"(?<![A-Za-z0-9])\(?-?\$?\s*\d+(?:,\d{3})*(?:\.\d+)?\)?%?(?![A-Za-z0-9])"
    )
    for m in token_re.finditer(raw_tail):
        token = m.group(0)
        raw = token.replace("$", "").replace("%", "").replace(",", "").strip()
        negative = raw.startswith("(") and raw.endswith(")")
        raw = raw.strip("() ")
        try:
            value = float(raw)
        except Exception:
            continue
        if negative:
            value = -value
        if min_value is not None and value < min_value:
            continue
        if max_value is not None and value > max_value:
            continue
        if first_pos is None:
            first_pos = m.start()
        values.append(value)
        if len(values) >= int(limit):
            break
    return values, first_pos


def _bank_is_toc_context(text, label_start):
    """Reject metric labels that sit in a local table-of-contents context."""
    raw = str(text or "")
    start = max(0, int(label_start) - 900)
    prefix = raw[start:int(label_start)].lower()
    toc_pos = max(prefix.rfind("table of contents"), prefix.rfind("contents page"))
    if toc_pos < 0:
        return False
    trailing = prefix[toc_pos:]
    section_markers = [
        "financial summary", "summary financial data", "consolidated statement",
        "regulatory capital", "capital and other metrics", "quarter ended",
    ]
    return not any(marker in trailing for marker in section_markers)


def _bank_row_numeric_values(text, label_patterns, max_chars=320, min_value=None, max_value=None):
    """Read numeric cells from the best non-TOC row-label occurrence."""
    t = _clean_text(text)
    best = None
    for pattern_index, pat in enumerate(label_patterns):
        for m in re.finditer(pat, t, flags=re.I | re.S):
            if _bank_is_toc_context(t, m.start()):
                continue
            tail = t[m.end():m.end() + int(max_chars)]
            values, first_pos = _bank_numeric_values_from_tail(
                tail, min_value=min_value, max_value=max_value, limit=10
            )
            if not values or first_pos is None:
                continue
            immediacy_bonus = 140 if first_pos <= 45 else (60 if first_pos <= 90 else 0)
            pattern_bonus = max(0, 20 - pattern_index * 5)
            score = len(values) * 25 + immediacy_bonus + pattern_bonus - min(first_pos, 240)
            candidate = (score, -first_pos, values)
            if best is None or candidate[:2] > best[:2]:
                best = candidate
    return list(best[2]) if best else []


def _bank_header_quarter_run(text, label_start, latest_period, lookback=9000):
    """Infer the closest plausible quarterly-header sequence before a metric row.

    V2.21.27 additionally accepts exact three-column latest/prior/year-ago
    headers (for example 2Q26 / 1Q26 / 2Q25). Those are common in bank
    earnings releases and are sufficient for current ROTCE/TBV/CET1 extraction.
    They are *not* sufficient for the four-quarter EPS TTM bridge, which still
    requires four explicit consecutive quarters or separate official documents.
    """
    t = _clean_text(text)
    start = max(0, int(label_start) - int(lookback))
    prefix = t[start:int(label_start)]
    latest_key = _bank_period_sort_key(latest_period)
    if latest_key[0] < 0:
        return []
    latest_y, latest_q = latest_key

    # First prefer explicit quarter+year runs. This preserves non-consecutive
    # comparison layouts such as latest / linked-quarter / year-ago.
    explicit_tokens = list(re.finditer(r"\b([1-4])Q\s*'?([0-9]{2,4})\b", prefix, flags=re.I))
    explicit_runs, cur = [], []
    for m in explicit_tokens:
        if cur and m.start() - cur[-1].end() > 90:
            if len(cur) >= 3:
                explicit_runs.append(cur)
            cur = []
        cur.append(m)
    if len(cur) >= 3:
        explicit_runs.append(cur)
    explicit_candidates = []
    latest_full = str(latest_period).upper()
    prev_full = _bank_previous_period(latest_period, 1)
    yoy_full = f"{latest_q}Q{str(latest_y - 1)[-2:]}"
    for run in explicit_runs:
        periods=[]
        for m in run[-7:]:
            y=int(m.group(2)); y = y + 2000 if y < 100 else y
            periods.append(f"{int(m.group(1))}Q{str(y)[-2:]}")
        # De-duplicate only adjacent duplicate labels introduced by flattened HTML.
        dedup=[]
        for p in periods:
            if not dedup or dedup[-1] != p:
                dedup.append(p)
        periods=dedup
        if len(periods) < 3 or latest_full not in periods:
            continue
        # A genuine 3-column comparison header should contain the linked quarter
        # and/or the year-ago quarter. Require both for a 3-cell run; wider runs
        # may be ordinary consecutive-quarter tables.
        if len(periods) == 3 and not (prev_full in periods and yoy_full in periods):
            continue
        proximity = run[-1].end()
        latest_edge_bonus = 80 if periods[0] == latest_full or periods[-1] == latest_full else 0
        semantic_bonus = 100 if prev_full in periods else 0
        semantic_bonus += 100 if yoy_full in periods else 0
        explicit_candidates.append((2000 + len(periods)*30 + latest_edge_bonus + semantic_bonus, proximity, periods))
    if explicit_candidates:
        _, _, periods = max(explicit_candidates, key=lambda x: (x[0], x[1]))
        return periods

    def directional_candidates(qs, run_end, base_bonus=0):
        out = []
        n = len(qs)
        for width in range(min(7, n), 3, -1):
            for i in range(0, n - width + 1):
                sub = qs[i:i + width]
                asc_ok = all(b == (1 if a == 4 else a + 1) for a, b in zip(sub, sub[1:]))
                desc_ok = all(b == (4 if a == 1 else a - 1) for a, b in zip(sub, sub[1:]))
                if asc_ok and sub[-1] == latest_q:
                    out.append((1000 + width * 20 + base_bonus, run_end, "asc", sub))
                if desc_ok and sub[0] == latest_q:
                    out.append((1000 + width * 20 + base_bonus, run_end, "desc", sub))
        return out

    candidates = []
    qtokens = list(re.finditer(r"\b([1-4])Q(?:\s*'?([0-9]{2,4}))?\b", prefix, flags=re.I))
    runs, cur = [], []
    for m in qtokens:
        if cur and m.start() - cur[-1].end() > 70:
            if len(cur) >= 4:
                runs.append(cur)
            cur = []
        cur.append(m)
    if len(cur) >= 4:
        runs.append(cur)
    for run in runs:
        candidates.extend(directional_candidates([int(m.group(1)) for m in run], run[-1].end(), base_bonus=5))

    month_q = {"mar": 1, "march": 1, "jun": 2, "june": 2,
               "sep": 3, "sept": 3, "september": 3, "dec": 4, "december": 4}
    mtokens = list(re.finditer(
        r"\b(march|mar\.?|june|jun\.?|september|sept\.?|sep\.?|december|dec\.?)\s+\d{1,2}\b",
        prefix, flags=re.I,
    ))
    mruns, cur = [], []
    for m in mtokens:
        if cur and m.start() - cur[-1].end() > 55:
            if len(cur) >= 4:
                mruns.append(cur)
            cur = []
        cur.append(m)
    if len(cur) >= 4:
        mruns.append(cur)
    for run in mruns:
        qs = []
        for m in run:
            key = re.sub(r"[^a-z]", "", m.group(1).lower())
            q = month_q.get(key)
            if q:
                qs.append(q)
        candidates.extend(directional_candidates(qs, run[-1].end(), base_bonus=0))

    if not candidates:
        return []
    _, _, direction, qs = max(candidates, key=lambda x: (x[0], x[1]))
    if direction == "asc":
        return _bank_consecutive_periods_ending(latest_period, len(qs))
    return [_bank_previous_period(latest_period, i) for i in range(len(qs))]


def _bank_extract_aligned_row_values(text, latest_period, label_patterns, max_chars=360,
                                     min_value=None, max_value=None, search_start=0, search_end=None):
    """Return period-aligned values from the best genuine table-row occurrence."""
    t = _clean_text(text)
    base_start = int(search_start)
    end = len(t) if search_end is None else min(len(t), int(search_end))
    best = None
    for pattern_index, pat in enumerate(label_patterns):
        for m in re.finditer(pat, t[base_start:end], flags=re.I | re.S):
            abs_start = base_start + m.start()
            abs_end = base_start + m.end()
            if _bank_is_toc_context(t, abs_start):
                continue
            periods = _bank_header_quarter_run(t, abs_start, latest_period)
            if len(periods) < 3:
                continue
            tail = t[abs_end:min(end, abs_end + int(max_chars))]
            values, first_pos = _bank_numeric_values_from_tail(
                tail, min_value=min_value, max_value=max_value, limit=max(10, len(periods) + 3)
            )
            if len(values) < len(periods) or first_pos is None:
                continue
            mapped = [{"period": p, "value": v} for p, v in zip(periods, values[:len(periods)])]
            if not any(row.get("period") == latest_period for row in mapped):
                continue
            immediacy_bonus = 190 if first_pos <= 45 else (85 if first_pos <= 90 else 0)
            pattern_bonus = max(0, 25 - pattern_index * 5)
            score = len(periods) * 30 + immediacy_bonus + pattern_bonus - min(first_pos, 260)
            candidate = (score, -first_pos, abs_start, mapped)
            if best is None or candidate[:2] > best[:2]:
                best = candidate
    return list(best[3]) if best else []


def _bank_extract_eps_from_text(text):
    values = _bank_row_numeric_values(text, [
        r"diluted\s+earnings\s+per\s+(?:common\s+)?share",
        r"earnings\s+per\s+(?:common\s+)?share\s*[-–—]?\s*diluted",
        r"diluted\s+EPS",
    ], max_chars=180, min_value=-100.0, max_value=100.0)
    if values:
        return values[0]
    return _bank_extract_first_float(text, [
        r"\bEPS\b(?:\s*\(\d+\))?[^$0-9]{0,18}\$?\s*([0-9]+(?:\.[0-9]+)?)",
    ])


def _bank_extract_quarterly_eps_series(text, latest_period, count=4):
    """Parse quarterly diluted EPS independent of left-to-right table direction."""
    patterns = [
        r"diluted\s+earnings\s+per\s+(?:common\s+)?share",
        r"earnings\s+per\s+(?:common\s+)?share\s*[-–—]?\s*diluted",
        r"diluted\s+EPS",
    ]
    aligned = _bank_extract_aligned_row_values(
        text, latest_period, patterns, max_chars=300, min_value=-100.0, max_value=100.0
    )
    expected = _bank_consecutive_periods_ending(latest_period, count)
    if aligned and expected:
        amap = {r["period"]: r["value"] for r in aligned}
        if all(p in amap for p in expected):
            return [{"period": p, "reported_eps": amap[p]} for p in reversed(expected)]

    # V2.21.26 strict alignment guard: never manufacture a four-quarter
    # sequence from the first four numeric cells of an EPS row when the
    # document does not expose an unambiguous four-quarter header. Earnings
    # releases commonly mix current/prior-year quarters with change and YTD
    # columns; treating those cells as consecutive quarters creates unit/period
    # conflicts. Returning [] deliberately activates the safer per-quarter
    # official-document path in the bank adapter.
    return []


def _bank_extract_adjusted_quarterly_eps_series(text, latest_period, count=4, reported_series=None):
    """Extract the most comprehensive company-designated adjusted EPS row.

    Some bank supplements publish more than one valid reconciliation for the
    same quarter set (for example an all-notable-items row and a narrower row
    excluding only one named item).  Selecting the first/best-positioned row can
    therefore under-adjust earlier quarters.  Evaluate every period-aligned
    official EPS row and prefer the bridge that explicitly adjusts the largest
    number of quarters versus the reported series; then prefer the larger total
    reconciled effect and finally the strongest table-context score.

    This remains quantitative-only: narrative mentions never create an
    adjustment and every accepted candidate must cover the complete expected
    period set.
    """
    patterns = [
        r"(?:total\s+[A-Za-z0-9&.'’\- ]{0,45}\s+)?diluted\s+EPS[^\n]{0,90}?(?:excluding|ex)\s+(?:significant|notable|special)\s+item",
        r"(?:diluted\s+)?earnings\s+per\s+(?:common\s+)?share[^\n]{0,90}?(?:excluding|ex)\s+(?:significant|notable|special)\s+item",
        r"(?:excluding|ex)\s+(?:significant|notable|special)\s+items?[^\n]{0,90}?(?:diluted\s+)?(?:EPS|earnings\s+per\s+share)",
    ]
    expected = _bank_consecutive_periods_ending(latest_period, count)
    if not expected:
        return []

    t = _clean_text(text)
    reported_map = {}
    for row in (reported_series or []):
        if isinstance(row, dict) and row.get("period"):
            v = safe_float(row.get("reported_eps"))
            if v is not None:
                reported_map[str(row.get("period"))] = v

    candidates = []
    for pattern_index, pat in enumerate(patterns):
        for m in re.finditer(pat, t, flags=re.I | re.S):
            if _bank_is_toc_context(t, m.start()):
                continue
            periods = _bank_header_quarter_run(t, m.start(), latest_period)
            if len(periods) < 4:
                continue
            tail = t[m.end():m.end() + 360]
            values, first_pos = _bank_numeric_values_from_tail(
                tail, min_value=-100.0, max_value=100.0, limit=max(10, len(periods) + 3)
            )
            if len(values) < len(periods) or first_pos is None:
                continue
            amap = {p: v for p, v in zip(periods, values[:len(periods)])}
            if not all(p in amap for p in expected):
                continue

            adjusted_count = 0
            total_abs_effect = 0.0
            if reported_map and all(p in reported_map for p in expected):
                for p in expected:
                    diff = safe_float(amap[p]) - safe_float(reported_map[p])
                    if diff is None:
                        continue
                    total_abs_effect += abs(diff)
                    if abs(diff) >= 0.005:
                        adjusted_count += 1

            immediacy_bonus = 190 if first_pos <= 45 else (85 if first_pos <= 90 else 0)
            pattern_bonus = max(0, 25 - pattern_index * 5)
            table_score = len(periods) * 30 + immediacy_bonus + pattern_bonus - min(first_pos, 260)
            # Primary ranking: breadth of explicit reconciliation, then economic
            # magnitude, then ordinary table-context quality.  If the reported
            # row is unavailable, table quality remains the deciding fallback.
            rank = (
                adjusted_count if reported_map else -1,
                round(total_abs_effect, 8) if reported_map else 0.0,
                table_score,
                -first_pos,
                -m.start(),
            )
            candidates.append((rank, amap))

    if not candidates:
        return []
    _, best_map = max(candidates, key=lambda x: x[0])
    return [{"period": p, "core_eps": best_map[p]} for p in reversed(expected)]


def _bank_extract_tbv_values(text, latest_period=None):
    patterns = [
        # Issuers such as Truist print the canonical metric directly as "TBVPS"
        # in quarterly key-metric tables and define the abbreviation elsewhere.
        # Period alignment keeps this shorthand as strict as the long-form labels.
        r"\bTBVPS\b",
        r"tangible\s+book\s+value\s+per\s+(?:common\s+)?share",
        r"tangible\s+common\s+book\s+value\s+per\s+share",
        # Some earnings-summary tables sit under a "Per Common Share" section
        # and abbreviate the row itself to "Tangible book value (TBV)".
        # Period alignment plus the <= $1,000/share plausibility ceiling keep
        # this distinct from total tangible common equity in dollar millions.
        r"tangible\s+book\s+value\s*(?:\(\s*TBV\s*\))?(?:\s*\(non-GAAP\))?",
    ]
    if latest_period:
        aligned = _bank_extract_aligned_row_values(text, latest_period, patterns, max_chars=380, min_value=1.0, max_value=1000.0)
        if aligned:
            # Preserve exact issuer header semantics. A latest/prior/year-ago
            # table is intentionally non-consecutive, so reconstructing only
            # consecutive quarters would discard the YoY comparison needed for
            # tangible-book growth. Sort actual mapped periods newest-first.
            ordered_rows = sorted(
                [r for r in aligned if safe_float(r.get("value")) is not None],
                key=lambda r: _bank_period_sort_key(r.get("period")),
                reverse=True,
            )
            if ordered_rows:
                return [safe_float(r.get("value")) for r in ordered_rows]
        return []
    return _bank_row_numeric_values(text, patterns, max_chars=300, min_value=1.0, max_value=1000.0)[:6]


def _bank_extract_book_value(text, latest_period=None):
    patterns = [r"(?<!tangible\s)book\s+value\s+per\s+(?:common\s+)?share"]
    if latest_period:
        aligned = _bank_extract_aligned_row_values(text, latest_period, patterns, max_chars=320, min_value=1.0, max_value=10000.0)
        for row in aligned:
            if row.get("period") == latest_period:
                return row.get("value")
        return None
    vals = _bank_row_numeric_values(text, patterns, max_chars=220, min_value=1.0, max_value=10000.0)
    return vals[0] if vals else None


def _bank_extract_rotce(text, latest_period=None):
    patterns = [
        r"return\s+on\s+average\s+tangible\s+common\s+(?:shareholders[’']?\s+)?equity(?:\s+ratio)?\s*(?:\(ROTCE\))?",
        r"return\s+on\s+tangible\s+common\s+equity\s*(?:\(ROTCE\))?",
        r"\bROTCE\b",
    ]
    if latest_period:
        aligned = _bank_extract_aligned_row_values(text, latest_period, patterns, max_chars=300, min_value=-100.0, max_value=100.0)
        for row in aligned:
            if row.get("period") == latest_period:
                return row.get("value")
        return None
    vals = _bank_row_numeric_values(text, patterns, max_chars=180, min_value=-100.0, max_value=100.0)
    return vals[0] if vals else None


def _bank_extract_cet1_values(text, latest_period=None):
    """Extract Standardized and Advanced CET1 from local capital-table context."""
    t = _clean_text(text)

    # V2.21.48: explicit quarter-aligned Standardized CET1 rows are the strongest
    # evidence. Q4 releases can repeat CET1 in bullets/footnotes; those weaker
    # occurrences must not replace the genuine regulatory-capital table row.
    exact_standardized = None
    if latest_period:
        latest_key = _bank_period_sort_key(latest_period)
        latest_y, latest_q = latest_key if latest_key[0] > 0 else (None, None)
        prev_period = _bank_previous_period(latest_period, 1)
        yoy_period = f"{latest_q}Q{str(latest_y - 1)[-2:]}" if latest_y and latest_q else None
        exact_patterns = [
            r"(?:basel\s+(?:iii|3)\s+)?standardi[sz]ed\s+CET1(?:\s+capital)?(?:\s+ratio)?\s*(?:\(%\))?",
            r"(?:basel\s+(?:iii|3)\s+)?standardi[sz]ed\s+common\s+equity\s+tier\s+1(?:\s*\(CET1\))?(?:\s+capital)?(?:\s+ratio)?",
        ]
        for pat in exact_patterns:
            if exact_standardized is not None:
                break
            for m in re.finditer(pat, t, flags=re.I | re.S):
                if _bank_is_toc_context(t, m.start()):
                    continue
                prefix = t[max(0, m.start() - 520):m.start()]
                tokens = list(re.finditer(r"\b([1-4])Q\s*'?([0-9]{2,4})\b", prefix, flags=re.I))
                periods = []
                for tok in tokens[-3:]:
                    year = int(tok.group(2)); year = year + 2000 if year < 100 else year
                    periods.append(f"{int(tok.group(1))}Q{str(year)[-2:]}")
                if len(periods) != 3 or periods[0] != latest_period:
                    continue
                if prev_period not in periods or yoy_period not in periods:
                    continue
                values, first_pos = _bank_numeric_values_from_tail(
                    t[m.end():m.end()+100], min_value=3.0, max_value=30.0, limit=3
                )
                if values and first_pos is not None and first_pos <= 30:
                    exact_standardized = safe_float(values[0])
                    break

    ratio_patterns = [
        r"common\s+equity\s+tier\s+1\s*(?:\(CET1\))?(?:\s+capital)?\s+ratio",
        r"CET1\s+(?:Capital\s+)?Ratio",
        r"common\s+equity\s+tier\s+1\s*\(CET1\)(?!\s+capital\b)",
        r"common\s+equity\s+tier\s+1\s*\([A-Z]\)\s*/\s*\([A-Z]\)",
    ]
    matches=[]
    for pat in ratio_patterns:
        for m in re.finditer(pat,t,flags=re.I|re.S):
            if not _bank_is_toc_context(t,m.start()):
                matches.append(m)
    dedup=[]
    for m in sorted(matches,key=lambda x:x.start()):
        if dedup and abs(m.start()-dedup[-1].start())<8:
            continue
        dedup.append(m)

    std_re=re.compile(r"standardi[sz]ed\s+(?:approach|approaches)|standarized\s+(?:approach|approaches)",re.I)
    adv_re=re.compile(r"advanced\s+(?:approach|approaches)",re.I)
    std_candidates=[]; adv_candidates=[]; generic_candidates=[]
    for m in dedup:
        periods=_bank_header_quarter_run(t,m.start(),latest_period) if latest_period else []
        tail=t[m.end():m.end()+360]
        values,first_pos=_bank_numeric_values_from_tail(tail,min_value=1.0,max_value=40.0,limit=max(10,len(periods)+3))
        value=None
        if latest_period:
            if periods and len(values)>=len(periods):
                amap={p:v for p,v in zip(periods,values[:len(periods)])}
                value=amap.get(latest_period)
        elif values and first_pos is not None and first_pos<=80:
            value=values[0]
        if value is None:
            continue
        prefix=t[max(0,m.start()-700):m.start()]
        sh=list(std_re.finditer(prefix)); ah=list(adv_re.finditer(prefix))
        sp=sh[-1].start() if sh else -1; ap=ah[-1].start() if ah else -1
        nearest=max(sp,ap); dist=len(prefix)-nearest if nearest>=0 else 9999
        score=1000-min(dist,1000)
        if nearest>=0 and dist<=500 and ap>sp:
            adv_candidates.append((score,value))
        elif nearest>=0 and dist<=500 and sp>ap:
            std_candidates.append((score,value))
        else:
            generic_candidates.append((1000-min(first_pos or 999,999),value))
    standardized = exact_standardized
    if standardized is None:
        standardized=max(std_candidates,default=(None,None),key=lambda x:x[0])[1]
    advanced=max(adv_candidates,default=(None,None),key=lambda x:x[0])[1]
    if standardized is None and generic_candidates:
        standardized=max(generic_candidates,key=lambda x:x[0])[1]
    return standardized,advanced


def _bank_period_long_label(period):
    key = _bank_period_sort_key(period)
    if key[0] < 0:
        return None
    year, quarter = key
    qname = {1: "First", 2: "Second", 3: "Third", 4: "Fourth"}.get(quarter)
    return f"{qname} Quarter {year}" if qname else None


def _bank_selected_items_eps_bridge(text, reported_eps, current_period):
    """Return an issuer-designated current-period Selected-Items EPS bridge.

    V2.21.34: Some banks publish a period-specific table headed "Selected Items"
    with a signed "Impact to Diluted EPS" column rather than a separate adjusted
    EPS row.  Accept only the explicitly labelled current-period subsection.  A
    literal "None" means reported EPS remains the core basis.  Otherwise sum
    only signed per-share impacts from rows that expose the table's three-column
    pre-tax / after-tax / diluted-EPS structure.  This avoids treating generic
    non-GAAP boilerplate elsewhere in the document as an EPS adjustment.
    """
    reported = safe_float(reported_eps)
    label = _bank_period_long_label(current_period)
    if reported is None or not label:
        return None
    t = _clean_text(text)
    # Require a nearby Selected Items heading so a normal quarter heading in a
    # financial table cannot be mistaken for the reconciliation subsection.
    pat = re.compile(r"Selected\s+Items(?:\s*\(\d+\))?.{0,420}?" + re.escape(label), re.I | re.S)
    matches = list(pat.finditer(t))
    if not matches:
        return None
    m = matches[-1]
    section_start = m.end()
    tail = t[section_start:section_start + 1500]
    # Stop before the next explicit quarter heading when present.
    next_q = re.search(r"\b(?:First|Second|Third|Fourth)\s+Quarter\s+20\d{2}\b", tail, flags=re.I)
    if next_q:
        tail = tail[:next_q.start()]
    if re.match(r"\s*None\b", tail, flags=re.I):
        return reported, 0.0, "Offizielle Selected-Items-Tabelle: aktuelles Quartal ausdrücklich ohne ausgewiesene EPS-Sonderposten"

    # Item rows in these issuer tables are laid out as: description, pre-tax,
    # after-tax, signed diluted-EPS impact. Footnote numbers embedded in labels
    # are harmless because the regex anchors on the three financial cells.
    triplet = re.compile(
        r"(?:\$?\s*\(?-?\d{1,3}(?:,\d{3})*\)?\s+){2}"
        r"\$?\s*(\(?-?(?:\d+\.\d+|\.\d+)\)?)"
    )
    impacts = []
    for mm in triplet.finditer(tail):
        raw = mm.group(1).replace("$", "").strip()
        neg = raw.startswith("(") and raw.endswith(")")
        raw = raw.strip("() ")
        try:
            value = float(raw)
        except Exception:
            continue
        if neg:
            value = -value
        # EPS-impact cells should be per-share values, not dollar amounts.
        if abs(value) <= 20.0:
            impacts.append(value)
    if not impacts:
        return None
    total_effect = sum(impacts)
    core = reported - total_effect
    if not math.isfinite(core) or abs(core) > 100.0:
        return None
    return core, total_effect, (
        "Offizielle periodenspezifische Selected-Items-/Diluted-EPS-Impact-Brücke; "
        "Core EPS aus gemeldetem EPS minus den explizit ausgewiesenen signierten EPS-Effekten"
    )


def _bank_has_current_period_unbridged_eps_special_item_evidence(text, current_period):
    """Detect current-period EPS special-item evidence, excluding boilerplate."""
    t = _clean_text(text)
    low = t.lower()
    sensitive = ["significant item", "significant items", "notable item", "notable items", "special item", "special items", "selected item", "selected items"]
    # Generic non-GAAP definitions often mention significant items many pages
    # after the earnings table.  They do not by themselves prove that current
    # quarter EPS contains an adjustment.  Require local EPS/per-share context.
    for term in sensitive:
        pos = 0
        while True:
            pos = low.find(term, pos)
            if pos < 0:
                break
            window = low[max(0, pos - 500):min(len(low), pos + 700)]
            has_eps_context = any(k in window for k in ["diluted eps", "earnings per share", "per diluted share", "impact to diluted eps"])
            has_current_adjustment_verb = any(k in window for k in [
                " included ", " includes ", " impact ", " impact to ", " affecting ",
                " adjusted ", " excluding ", " excludes ",
            ])
            if has_eps_context and has_current_adjustment_verb:
                return True
            pos += len(term)
    return False


def _bank_detect_special_item_bridge(text, reported_eps, current_period=None):
    """Return (core_eps, signed_effect, status) using current-period evidence only.

    Explicit issuer-adjusted EPS is preferred.  A period-specific Selected Items
    / Impact-to-Diluted-EPS table is the second accepted bridge.  Generic
    document-wide non-GAAP boilerplate never creates an adjustment by itself.
    """
    t = _clean_text(text)
    reported = safe_float(reported_eps)
    if reported is None:
        return None, None, None
    core = _bank_extract_first_float(t, [
        r"(?:EPS|earnings\s+per\s+share)[^\n]{0,80}?(?:ex|excluding)\s+(?:significant|notable|special|selected)\s+items?[^$0-9]{0,30}\$?\s*([0-9]+(?:\.[0-9]+)?)",
        r"(?:ex|excluding)\s+(?:significant|notable|special|selected)\s+items?[^\n]{0,80}?(?:EPS|earnings\s+per\s+share)[^$0-9]{0,20}\$?\s*([0-9]+(?:\.[0-9]+)?)",
    ])
    if core is not None:
        return core, reported - core, "Offizielle Ex-Significant-/Notable-/Selected-Items-EPS-Brücke"

    low = t.lower()
    adjustment_context = any(term in low for term in [
        "significant item", "significant items", "notable item", "notable items",
        "special item", "special items", "selected item", "selected items",
        "integration cost", "integration costs",
    ])
    if adjustment_context:
        adjusted_vals = _bank_row_numeric_values(t, [
            r"diluted\s+(?:earnings\s+per\s+(?:common\s+)?share|EPS)\s*[-–—]?\s*(?:as\s+)?adjusted(?:\s*\(non-GAAP\))?",
            r"adjusted\s+diluted\s+(?:earnings\s+per\s+(?:common\s+)?share|EPS)(?:\s*\(non-GAAP\))?",
        ], max_chars=140, min_value=-100.0, max_value=100.0)
        if adjusted_vals:
            core = safe_float(adjusted_vals[0])
            if core is not None:
                return core, reported - core, "Offizielle Diluted-EPS-as-adjusted-Brücke für company-designierte Sonder-/Integrationsposten"

    selected = _bank_selected_items_eps_bridge(t, reported, current_period)
    if selected is not None:
        return selected

    if _bank_has_current_period_unbridged_eps_special_item_evidence(t, current_period):
        return None, None, "Aktueller EPS-Sonderposten-Hinweis ohne quantitative company-designierte Brücke – fail-closed"
    return reported, 0.0, "Keine aktuelle company-designierte quantitative EPS-Sonderposten-Brücke erkannt; reported EPS bleibt Core-Basis"


# V2.21.16: Hub-first universal bank IR discovery.  The previous ordering
# spent the bounded request budget on guessed deep paths before ever loading the
# issuer homepage / real investor hub.  Large global issuers often mount IR
# below an additional corporate prefix (for example /global/investors), while
# other issuers use /investors or /investor-relations.  Keep these paths
# issuer-neutral: no ticker/domain special cases belong here.
BANK_IR_SEED_PATHS = [
    "",
    "/earnings",
    "/investors",
    "/investor-relations",
    "/global/investors",
    "/about/investor-relations",
    "/financials",
    "/financials/quarterly-results",
    "/financials/quarterly-results/default.aspx",
    "/financial-information",
    "/investor-relations/financial-information",
    "/investors/quarterly-earnings",
    "/investors/quarterly-results",
    "/investor-relations/quarterly-earnings",
    "/investor-relations/quarterly-results",
    "/investor-relations/financial-results",
    "/global/investors/quarterly-earnings",
    "/global/investors/financial-information",
    "/global/investors/events-and-presentations",
]

BANK_IR_HUB_TERMS = [
    "investor relations", "investors", "investor overview",
    "quarterly earnings", "quarterly results", "financial results",
    "financial information", "financials", "quarterly reports", "earnings", "earnings releases", "earnings materials",
    "events and presentations", "results and presentations",
]


def _bank_candidate_ir_roots(company_domain):
    """Issuer-owned roots to probe before guessed deep corporate paths.

    V2.21.22: Many public-company websites keep IR on ir./investor./investors.
    subdomains that are not linked from the corporate landing page.  These hosts
    still pass the strict issuer-domain-family check and therefore preserve the
    existing chain of trust without issuer-specific constants.
    """
    domain = _clean_text(company_domain).lower().split(":")[0]
    if domain.startswith("www."):
        domain = domain[4:]
    if not domain:
        return []
    roots = []
    base = _router_root(domain) or f"https://{domain}"
    for value in [
        base,
        f"https://ir.{domain}",
        f"https://investor.{domain}",
        f"https://investors.{domain}",
    ]:
        value = str(value or "").rstrip("/")
        if value and value not in roots:
            roots.append(value)
    return roots


def _bank_latest_released_calendar_periods(reference_date=None, count=4):
    """Return recent completed calendar quarters with a conservative reporting lag."""
    ref = reference_date or datetime.now().date()
    candidates = []
    for year in range(ref.year - 2, ref.year + 1):
        for q, (month, day) in {1: (3, 31), 2: (6, 30), 3: (9, 30), 4: (12, 31)}.items():
            try:
                qend = datetime(year, month, day).date()
            except Exception:
                continue
            # Avoid probing a just-ended quarter before normal earnings season.
            if qend + timedelta(days=14) <= ref:
                candidates.append((year, q, qend))
    candidates.sort(key=lambda x: x[2], reverse=True)
    return [f"{q}Q{str(year)[-2:]}" for year, q, _ in candidates[:max(1, int(count))]]


def _bank_q4_company_slug(company_name):
    text = unicodedata.normalize("NFKD", _clean_text(company_name))
    text = "".join(ch for ch in text if not unicodedata.combining(ch))
    text = text.replace("&", " and ").replace(".", "").replace("'", "")
    tokens = re.findall(r"[A-Za-z0-9]+", text)
    return "-".join(tokens[:8])


def _bank_q4_event_detail_candidates(ir_root, company_name, reference_date=None):
    """Bounded Q4 event-detail candidates for recent earnings calls.

    Q4-hosted IR sites commonly expose server-rendered event-detail pages even
    when their quarterly-results table is populated by JavaScript.  The route is
    a platform convention, not an issuer exception.  Both the URL host and any
    later document links remain subject to strict trust checks.
    """
    host = _normalize_host(ir_root)
    slug = _bank_q4_company_slug(company_name)
    if not host or not slug:
        return []
    rows = []
    for period in _bank_latest_released_calendar_periods(reference_date=reference_date, count=4):
        m = re.fullmatch(r"([1-4])Q(\d{2})", period)
        if not m:
            continue
        q = int(m.group(1)); fy = 2000 + int(m.group(2))
        event_year = fy + 1 if q == 4 else fy
        url = (
            f"https://{host}/news-events/webcasts-presentations/event-details/{event_year}/"
            f"Q{q}-{fy}-{slug}-Earnings-Conference-Call/default.aspx"
        )
        rows.append({"period": period, "url": url})
    return rows


def _bank_ir_document_class(url, title=""):
    """Classify issuer IR links before they can become bank earnings evidence.

    This is deliberately issuer-neutral.  It uses the link text/URL only and is
    meant to distinguish true quarterly earnings material from profile/marketing
    PDFs that happen to carry a quarter in the filename.
    """
    hay = _clean_text(f"{title} {unquote(url or '')}").lower()
    # Treat filename separators as word separators for classification. Issuer IR
    # archives commonly use names such as TFC_2Q26_Earnings_Release.pdf even
    # when the visible anchor says only "Press Release". This normalization is
    # issuer-neutral and does not infer an earnings class unless the actual URL
    # carries the earnings/release wording.
    hay = re.sub(r"[_\-/]+", " ", hay)

    # Strong positive classes first.  An explicit earnings presentation is still
    # valid supporting evidence, but supplements/releases rank above it.
    if any(x in hay for x in [
        "quarterly supplement", "earnings supplement", "financial supplement",
        "supplemental analyst schedules", "supplemental analyst schedule",
        "earnings tables", "financial tables",
    ]):
        return "earnings_supplement", 5
    if any(x in hay for x in [
        "earnings release", "quarterly earnings release", "financial results",
        "quarterly results release", "results and key metrics", "news release",
    ]):
        return "earnings_release", 4
    if "presentation" in hay and any(x in hay for x in [
        "earnings", "quarterly", "quarter results", "financial results",
    ]):
        return "earnings_presentation", 3

    # Explicitly non-earnings material.  These documents may contain historical
    # EPS/CET1 context, but they are not allowed to become the primary quarterly
    # bank snapshot merely because a current quarter appears in the filename.
    if any(x in hay for x in [
        "corporate profile", "company profile", "investor profile",
        "fact sheet", "factsheet", "corporate presentation",
        "investor day", "sustainability", "esg report", "esg presentation",
    ]):
        return "non_earnings_profile", -2
    if "presentation" in hay:
        return "generic_presentation", -1

    # Opaque quarter-labelled PDFs remain available only as a low-priority
    # fallback.  They do not stop deeper discovery and must still pass the
    # content-level bank parser gate.
    if _bank_period_from_text(hay) and ".pdf" in hay:
        return "period_pdf_fallback", 1
    return "other", 0


def _bank_ir_is_primary_earnings_row(row):
    if not isinstance(row, dict):
        return False
    priority = row.get("document_priority")
    if priority is None:
        _, priority = _bank_ir_document_class(row.get("url"), row.get("title"))
    try:
        return int(priority) >= 4
    except Exception:
        return False


def _bank_period_words(period):
    """Return issuer-search wording for a canonical 1Q26-style period."""
    m = re.fullmatch(r"([1-4])Q(\d{2})", _clean_text(period).upper())
    if not m:
        return None
    q = int(m.group(1))
    year = 2000 + int(m.group(2))
    ordinal = {1: "first", 2: "second", 3: "third", 4: "fourth"}[q]
    return {
        "period": f"{q}Q{str(year)[-2:]}",
        "q": q,
        "year": year,
        "ordinal": ordinal,
        "long": f"{ordinal} quarter {year}",
        "short": f"Q{q} {year}",
    }


def _bank_publication_identity_matches(text, period):
    """Require exact-quarter + earnings/results semantics in candidate identity text.

    This is intentionally stricter than generic IR relevance.  An unrelated
    dividend, capital, stress-test or conference release must never become the
    publication date merely because it falls after quarter end or appears in a
    search snippet beside a quarterly-results link.
    """
    words = _bank_period_words(period)
    if not words:
        return False
    raw = _clean_text(text)
    if not raw:
        return False
    low = re.sub(r"[\s_\-]+", " ", raw.lower())
    year = str(words["year"])
    q = str(words["q"])
    yy = year[-2:]
    ordinal = words["ordinal"]
    period_patterns = [
        rf"\b{ordinal}\s+quarter\s+{year}\b",
        rf"\bq\s*{q}\s+{year}\b",
        rf"\b{q}\s*q\s*{yy}\b",
        rf"\b{q}\s*q\s*{year}\b",
    ]
    if not any(re.search(pat, low, flags=re.I) for pat in period_patterns):
        return False
    return any(term in low for term in [
        "earnings", "financial results", "quarterly results", "quarter results",
        "reports", "reported", "net income", "diluted eps", "results",
    ])


def _bank_publication_page_identity_material(html, url=""):
    """Return only page-owned identity fields, excluding body/navigation dates.

    A generic archive/hub page can contain many period/date strings in cards or
    navigation.  Only URL + document title + the leading headings may prove that
    the page itself is the earnings/results page for the target quarter.
    """
    if not html:
        return _clean_text(url)
    try:
        soup = BeautifulSoup(html[:220000], "html.parser")
    except Exception:
        return _clean_text(url)
    bits = [_clean_text(url)]
    if soup.title:
        bits.append(_clean_text(soup.title.get_text(" ", strip=True)))
    for tag in soup.find_all(["h1", "h2"], limit=3):
        bits.append(_clean_text(tag.get_text(" ", strip=True)))
    return _clean_text(" ".join(x for x in bits if x))


def _bank_publication_page_lead_material(html, url=""):
    """Return page-owned identity/date lead, excluding archive/navigation noise."""
    if not html:
        return _clean_text(url)
    try:
        soup = BeautifulSoup(html[:220000], "html.parser")
    except Exception:
        return _clean_text(url)
    bits = [_clean_text(url)]
    if soup.title:
        bits.append(_clean_text(soup.title.get_text(" ", strip=True)))
    for tag in soup.find_all(["h1", "h2"], limit=3):
        bits.append(_clean_text(tag.get_text(" ", strip=True)))
    for meta in soup.find_all("meta"):
        key = _clean_text(meta.get("property") or meta.get("name")).lower()
        if key in {
            "article:published_time", "date", "datepublished", "publishdate",
            "publication_date", "dc.date", "dc.date.issued",
        }:
            bits.append(_clean_text(meta.get("content")))
    # Q4 detail pages often render the release dateline in a <time> element or
    # a date-labelled span/div rather than a paragraph or standard metadata.
    # Only date-bearing page-owned elements are added here.  The caller still
    # requires exact-quarter results identity and the normal post-quarter
    # 60-day plausibility window before accepting any candidate.
    date_nodes = 0
    for tag in soup.find_all(["time", "span", "div"], limit=180):
        attrs = " ".join(str(x) for x in (tag.get("class") or [])) + " " + str(tag.get("id") or "")
        attrs_low = attrs.lower()
        if tag.name != "time" and not any(key in attrs_low for key in ["date", "publish", "release"]):
            continue
        txt = _clean_text(tag.get("datetime") or tag.get_text(" ", strip=True))
        if not txt or not _bank_extract_release_dates(txt):
            continue
        bits.append(txt)
        date_nodes += 1
        if date_nodes >= 6:
            break
    for para in soup.find_all("p", limit=8):
        txt = _clean_text(para.get_text(" ", strip=True))
        if txt:
            bits.append(txt)
    return _clean_text(" ".join(x for x in bits if x))


def _bank_q4_trusted_tenant_bases(documents):
    """Return Q4 CDN tenant roots already proven by issuer-linked documents."""
    roots = []
    for row in (documents or {}).values() if isinstance(documents, dict) else (documents or []):
        if not isinstance(row, dict):
            continue
        if not (row.get("trusted_q4_direct") or row.get("trusted_q4_feed")):
            continue
        url = str(row.get("url") or "")
        m = re.match(r"^(https://s\d+\.q4cdn\.com/\d+)(?:/|$)", url, flags=re.I)
        if not m:
            continue
        root = m.group(1).rstrip("/")
        if root not in roots:
            roots.append(root)
    return roots[:3]


def _bank_extract_release_dates(text, expected_year=None):
    """Extract English/ISO date candidates in true source-text order.

    V38 records match offsets across supported date formats before parsing them,
    so an ISO date in the page URL cannot be reordered behind an earlier-looking
    body date merely because the regexes are evaluated in separate passes.
    Duplicates are removed after source-position ordering.  This helper still
    does not decide which date is a publication date; callers apply period and
    provenance semantics.
    """
    source = _clean_text(text)
    if not source:
        return []
    source = source[:20000]
    months = {
        "january": 1, "february": 2, "march": 3, "april": 4,
        "may": 5, "june": 6, "july": 7, "august": 8,
        "september": 9, "october": 10, "november": 11, "december": 12,
    }
    raw = []
    for m in re.finditer(
        r"(?i)\b(" + "|".join(months) + r")\s+(\d{1,2}),\s+(20\d{2})\b",
        source,
    ):
        raw.append((m.start(), int(m.group(3)), months[m.group(1).lower()], int(m.group(2))))
    for m in re.finditer(r"\b(20\d{2})-(\d{2})-(\d{2})\b", source):
        raw.append((m.start(), int(m.group(1)), int(m.group(2)), int(m.group(3))))

    found = []
    seen = set()
    for _, year, month, day in sorted(raw, key=lambda x: x[0]):
        if expected_year and abs(int(year) - int(expected_year)) > 1:
            continue
        try:
            value = datetime(int(year), int(month), int(day)).date()
        except Exception:
            continue
        if value in seen:
            continue
        seen.add(value)
        found.append(value)
    return found


def _bank_extract_release_date(text, expected_year=None):
    """Backward-compatible first date candidate for existing discovery callers."""
    values = _bank_extract_release_dates(text, expected_year=expected_year)
    return values[0] if values else None


def _bank_period_context_publication_date(html_or_text, period):
    """Recover a publication date from an issuer-owned event/archive page.

    Generic event and presentation archives contain many unrelated dates, so the
    page itself cannot satisfy the single-page identity gate.  This fallback only
    considers dates that are physically close to an exact target-quarter mention
    carrying earnings/results semantics.  The closest plausible post-quarter date
    wins.  It is metadata-only and cannot add valuation evidence.
    """
    words = _bank_period_words(period)
    period_end = _bank_period_end_date(period)
    raw = str(html_or_text or "")
    if not words or not period_end or not raw:
        return None
    # Preserve visible source order while stripping markup/navigation structure.
    text = _html_to_text(raw[:350000]) if "<" in raw and ">" in raw else _clean_text(raw)
    if not text:
        return None
    low = re.sub(r"[\s_\-]+", " ", text.lower())
    year = str(words["year"])
    q = str(words["q"])
    yy = year[-2:]
    ordinal = words["ordinal"]
    period_patterns = [
        rf"\b{ordinal}\s+quarter\s+{year}\b",
        rf"\bq\s*{q}\s+{year}\b",
        rf"\b{q}\s*q\s*{yy}\b",
        rf"\b{q}\s*q\s*{year}\b",
    ]
    period_hits = []
    for pat in period_patterns:
        period_hits.extend(list(re.finditer(pat, low, flags=re.I)))
    if not period_hits:
        return None

    months = {
        "january": 1, "february": 2, "march": 3, "april": 4,
        "may": 5, "june": 6, "july": 7, "august": 8,
        "september": 9, "october": 10, "november": 11, "december": 12,
    }
    date_hits = []
    for m in re.finditer(
        r"(?i)\b(" + "|".join(months) + r")\s+(\d{1,2}),\s+(20\d{2})\b",
        text,
    ):
        try:
            d = datetime(int(m.group(3)), months[m.group(1).lower()], int(m.group(2))).date()
        except Exception:
            continue
        if period_end < d <= period_end + timedelta(days=60):
            date_hits.append((m.start(), d))
    for m in re.finditer(r"\b(20\d{2})-(\d{2})-(\d{2})\b", text):
        try:
            d = datetime(int(m.group(1)), int(m.group(2)), int(m.group(3))).date()
        except Exception:
            continue
        if period_end < d <= period_end + timedelta(days=60):
            date_hits.append((m.start(), d))
    if not date_hits:
        return None

    semantic_terms = [
        "earnings", "financial results", "quarterly results", "quarter results",
        "reports", "reported", "diluted eps", "net income", "results",
    ]
    ranked = []
    for ph in period_hits:
        left = max(0, ph.start() - 360)
        right = min(len(text), ph.end() + 520)
        context_low = text[left:right].lower()
        if not any(term in context_low for term in semantic_terms):
            continue
        for pos, value in date_hits:
            # Require the date to belong to the same local event/card context.
            if pos < left or pos > right:
                continue
            distance = min(abs(pos - ph.start()), abs(pos - ph.end()))
            ranked.append((distance, pos, value))
    if not ranked:
        return None
    ranked.sort(key=lambda x: (x[0], x[1]))
    return ranked[0][2]


def _bank_q4_financials_directory_candidates(tenant_roots, period, source_url, template_rows=None):
    """Build bounded Q4 /files/doc_financials current-quarter sibling candidates."""
    words = _bank_period_words(period)
    if not words:
        return []
    year = int(words["year"])
    q = int(words["q"])
    period_code = words["period"]
    rows, seen = [], set()

    def add(tenant, filename, doc_class, priority, score, channel):
        if not tenant or not filename:
            return
        url = f"{tenant.rstrip('/')}/files/doc_financials/{year}/q{q}/{filename}"
        if url in seen:
            return
        seen.add(url)
        label = {
            "earnings_supplement": "Earnings Supplement",
            "earnings_release": "Earnings Release",
            "earnings_presentation": "Earnings Presentation",
        }.get(doc_class, "Earnings Material")
        rows.append({
            "url": url,
            "title": f"{period_code} {label}",
            "period": period_code,
            "score": score,
            "document_class": doc_class,
            "document_priority": priority,
            "trusted_q4_derived": True,
            "derived_from_url": source_url,
            "discovery_channel": channel,
        })

    for row in (template_rows or []):
        if not isinstance(row, dict):
            continue
        if not (row.get("trusted_q4_direct") or row.get("trusted_q4_feed")):
            continue
        url = str(row.get("url") or "")
        mroot = re.match(r"^(https://s\d+\.q4cdn\.com/\d+)(?:/|$)", url, flags=re.I)
        if not mroot:
            continue
        tenant = mroot.group(1).rstrip("/")
        if tenant not in tenant_roots[:2]:
            continue
        basename = unquote(url.split("?")[0].rstrip("/").rsplit("/", 1)[-1])
        if not basename.lower().endswith(".pdf") or not re.search(r"[1-4]Q\d{2}", basename, flags=re.I):
            continue
        doc_class = row.get("document_class")
        priority = row.get("document_priority")
        if priority is None or not doc_class:
            doc_class, priority = _bank_ir_document_class(url, row.get("title"))
        if doc_class not in {"earnings_supplement", "earnings_release", "earnings_presentation"}:
            continue
        filename = re.sub(r"[1-4]Q\d{2}", period_code, basename, count=1, flags=re.I)
        add(tenant, filename, doc_class, int(priority or 0), 996,
            "issuer_current_quarter_q4_financials_template_sibling")

    if not rows:
        generic = [
            (f"{period_code}EarningsSupplement.pdf", "earnings_supplement", 5),
            (f"{period_code}EarningsRelease.pdf", "earnings_release", 4),
            (f"{period_code}EarningsPresentation.pdf", "earnings_presentation", 3),
        ]
        for tenant in tenant_roots[:2]:
            for filename, doc_class, priority in generic:
                add(tenant, filename, doc_class, priority, 990,
                    "issuer_current_quarter_q4_financials_generic_sibling")
    return rows[:8]


def _bank_q4_results_detail_route_candidates(hosts, company_name, period):
    """Bounded Q4-style same-domain results-detail routes for client-rendered archives."""
    words = _bank_period_words(period)
    if not words or not company_name:
        return []
    title = f"{company_name} Reports {words['ordinal'].title()} Quarter {words['year']} Results"
    slug = ''.join(ch if ch.isalnum() else '-' for ch in title).strip('-')
    routes = [
        f"/news-events/news/news-details/{words['year']}/{slug}/default.aspx",
        f"/news/press-releases/news-details/{words['year']}/{slug}/default.aspx",
        f"/news/news-details/{words['year']}/{slug}/default.aspx",
    ]
    out = []
    for host in hosts[:3]:
        for route in routes:
            out.append(f"https://{host}{route}")
    return out[:9]


def _bank_q4_derived_supplement_candidates(tenant_roots, period, release_date, source_url, template_rows=None):
    """Build bounded current-quarter Q4 sibling materials from issuer-proven templates.

    Q4 tenants frequently keep a stable filename convention across quarters while
    the current results page itself is client-rendered.  Prefer exact filename
    templates already linked by the issuer (Supplement/Release/Presentation),
    replacing only the quarter token and release-date directory.  Only when no
    usable template survives do we fall back to a very small generic filename set.

    Every returned URL is still subject to the downstream derived-payload gate,
    which requires both expected-period and issuer-identity confirmation.
    """
    words = _bank_period_words(period)
    if not words or not release_date:
        return []
    mon = release_date.strftime("%b")
    day = str(int(release_date.day))
    day2 = f"{release_date.day:02d}"
    period_code = words["period"]

    rows = []
    seen = set()

    def add_row(tenant, filename, doc_class, priority, score, channel):
        if not tenant or not filename:
            return
        for d in [day2, day]:
            url = f"{tenant.rstrip('/')}/files/doc_events/{release_date.year}/{mon}/{d}/{filename}"
            if url in seen:
                continue
            seen.add(url)
            label = {
                "earnings_supplement": "Earnings Supplement",
                "earnings_release": "Earnings Release",
                "earnings_presentation": "Earnings Presentation",
            }.get(doc_class, "Earnings Material")
            rows.append({
                "url": url,
                "title": f"{period_code} {label}",
                "period": period_code,
                "score": score,
                "document_class": doc_class,
                "document_priority": priority,
                "trusted_q4_derived": True,
                "derived_from_url": source_url,
                "discovery_channel": channel,
            })

    # Primary route: copy the issuer's own prior-quarter filename convention.
    # This remains universal: no ticker, tenant id or issuer-specific filename is
    # encoded here.  The prior row must already be issuer-linked and Q4-trusted.
    for row in (template_rows or []):
        if not isinstance(row, dict):
            continue
        if not (row.get("trusted_q4_direct") or row.get("trusted_q4_feed")):
            continue
        url = str(row.get("url") or "")
        mroot = re.match(r"^(https://s\d+\.q4cdn\.com/\d+)(?:/|$)", url, flags=re.I)
        if not mroot:
            continue
        tenant = mroot.group(1).rstrip("/")
        if tenant not in tenant_roots[:2]:
            continue
        basename = unquote(url.split("?")[0].rstrip("/").rsplit("/", 1)[-1])
        if not basename.lower().endswith(".pdf"):
            continue
        if not re.search(r"[1-4]Q\d{2}", basename, flags=re.I):
            continue
        doc_class = row.get("document_class")
        priority = row.get("document_priority")
        if priority is None or not doc_class:
            doc_class, priority = _bank_ir_document_class(url, row.get("title"))
        if doc_class not in {"earnings_supplement", "earnings_release", "earnings_presentation"}:
            continue
        filename = re.sub(r"[1-4]Q\d{2}", period_code, basename, count=1, flags=re.I)
        add_row(
            tenant, filename, doc_class, int(priority or 0), 995,
            "issuer_current_quarter_q4_template_sibling",
        )

    if rows:
        # Deduplicate equivalent templates from several prior quarters while
        # preserving one candidate per material type/name.  Exact issuer-proven
        # filename templates intentionally outrank generic spelling guesses.
        compact = []
        names = set()
        for row in sorted(rows, key=lambda r: (int(r.get("document_priority") or 0), r.get("score", 0)), reverse=True):
            key = (row.get("document_class"), row.get("url", "").rsplit("/", 1)[-1].lower())
            if key in names:
                continue
            names.add(key)
            compact.append(row)
        return compact[:8]

    # Conservative generic fallback when no prior-quarter material template was
    # exposed.  Keep it small so failed spelling variants cannot consume the
    # research budget before a valid release is attempted.
    fallback = [
        (f"{period_code}EarningsSupplement.pdf", "earnings_supplement", 5),
        (f"{period_code}EarningsRelease.pdf", "earnings_release", 4),
        (f"{period_code}EarningsPresentation.pdf", "earnings_presentation", 3),
    ]
    for tenant in tenant_roots[:2]:
        for filename, doc_class, priority in fallback:
            add_row(
                tenant, filename, doc_class, priority, 970,
                "issuer_current_quarter_q4_generic_sibling",
            )
    return rows[:6]


def _bank_company_identity_matches(text, company_name):
    """Conservative content check for a derived Q4 document."""
    hay = unicodedata.normalize("NFKD", _clean_text(text)).lower()
    hay = " ".join(re.findall(r"[a-z0-9]+", hay))
    name = unicodedata.normalize("NFKD", _clean_text(company_name)).lower()
    tokens = [t for t in re.findall(r"[a-z0-9]+", name) if len(t) >= 3]
    legal = {
        "inc", "incorporated", "corp", "corporation", "company", "co", "ltd", "limited",
        "plc", "group", "holdings", "holding", "the", "bank", "financial", "services",
    }
    distinctive = [t for t in tokens if t not in legal]
    if not distinctive:
        distinctive = tokens
    if not distinctive:
        return False
    matches = sum(1 for token in distinctive if token in hay)
    if len(distinctive) == 1:
        return matches == 1 and len(distinctive[0]) >= 5
    return matches >= min(2, len(distinctive))


def _bank_q4_derived_payload_valid(payload, row, company_name):
    if not payload or not isinstance(row, dict) or not row.get("trusted_q4_derived"):
        return bool(payload)
    text = _clean_text(payload.get("text"))
    expected = row.get("period")
    detected = _bank_period_from_text(text[:16000])
    if expected and detected != expected:
        return False
    return _bank_company_identity_matches(text[:40000], company_name)


def _bank_ir_link_score(url, title=""):
    hay = _clean_text(f"{title} {unquote(url or '')}").lower()
    hay = re.sub(r"[_\-/]+", " ", hay)
    doc_class, doc_priority = _bank_ir_document_class(url, title)
    if doc_priority < 0:
        return -600

    score = 0
    if doc_class == "earnings_supplement":
        score += 420
    elif doc_class == "earnings_release":
        score += 300
    elif doc_class == "earnings_presentation":
        score += 180
    elif doc_class == "period_pdf_fallback":
        score += 30

    # Hub/archive discovery remains separate from document classification.
    if any(x in hay for x in [
        "quarterly earnings", "quarterly results", "quarterly reports", "earnings results",
        "/earnings", "earnings materials", "financial information", "financials/quarterly-results",
        "results and presentations", "events and presentations",
    ]):
        score += 110
    if _bank_period_from_text(hay):
        score += 100
    if ".pdf" in hay:
        score += 35
    if any(x in hay for x in ["annual report", "proxy", "dividend", "fixed income", "careers", "privacy"]):
        score -= 180
    return score


