def _bank_activate_embedded_pypdf(diagnostics=None):
    """Activate the pypdf runtime embedded in this single app file via zipimport."""
    diag = diagnostics if isinstance(diagnostics, list) else None
    try:
        from pypdf import PdfReader as _probe_reader
        if diag is not None:
            diag.append("Issuer-IR PDF Runtime: pypdf bereits im Python-Pfad verfügbar.")
        return True
    except Exception:
        pass

    try:
        payload = base64.b64decode("".join(_BANK_EMBEDDED_PYPDF_B64.split()), validate=True)
        import hashlib as _hashlib
        if _hashlib.sha256(payload).hexdigest() != _BANK_EMBEDDED_PYPDF_SHA256:
            if diag is not None:
                diag.append("Issuer-IR PDF Runtime: eingebettetes pypdf-Paket hat ungültige Prüfsumme.")
            return False

        vendor_path = os.path.join(tempfile.gettempdir(), "aktienanalyse_pypdf_5_9_0_45ab8bee4dd9.zip")
        rewrite = True
        try:
            rewrite = (not os.path.exists(vendor_path)) or os.path.getsize(vendor_path) != len(payload)
        except Exception:
            rewrite = True
        if rewrite:
            tmp_path = vendor_path + ".tmp"
            with open(tmp_path, "wb") as fh:
                fh.write(payload)
            os.replace(tmp_path, vendor_path)

        if vendor_path not in sys.path:
            sys.path.insert(0, vendor_path)
        importlib.invalidate_caches()
        from pypdf import PdfReader as _embedded_reader
        if diag is not None:
            diag.append("Issuer-IR PDF Runtime: eingebettetes pypdf 5.9.0 per Single-File-zipimport aktiviert.")
        return True
    except Exception as exc:
        if diag is not None:
            diag.append(f"Issuer-IR PDF Runtime: eingebettetes pypdf konnte nicht aktiviert werden ({type(exc).__name__}).")
        return False


def _bank_pdf_bytes_to_text(payload, diagnostics=None, include_tail=False):
    """Best-effort PDF text extraction across common pure-Python/runtime backends."""
    diag = diagnostics if isinstance(diagnostics, list) else None
    if not payload:
        if diag is not None:
            diag.append("Issuer-IR PDF: leere PDF-Antwort.")
        return ""

    def _page_indices(total_pages):
        total_pages = max(0, int(total_pages or 0))
        indices = list(range(min(45, total_pages)))
        if include_tail and total_pages > 60:
            for idx in range(max(45, total_pages - 14), total_pages):
                if idx not in indices:
                    indices.append(idx)
        return indices

    # 1) Modern pypdf; V2.21.14 can self-activate an embedded single-file runtime.
    try:
        _bank_activate_embedded_pypdf(diag)
        from io import BytesIO
        from pypdf import PdfReader
        reader = PdfReader(BytesIO(payload))
        parts = []
        for idx in _page_indices(len(reader.pages)):
            try:
                parts.append(reader.pages[idx].extract_text() or "")
            except Exception:
                continue
        text = _clean_text(" ".join(parts))
        if text:
            if diag is not None:
                diag.append(f"Issuer-IR PDF: pypdf erfolgreich ({len(text)} Zeichen; Single-File-Runtime/Laufzeitpaket).")
            return text[:240_000]
    except Exception as exc:
        if diag is not None:
            diag.append(f"Issuer-IR PDF: pypdf nicht verfügbar/fehlgeschlagen ({type(exc).__name__}).")

    # 2) Legacy PyPDF2 is still present in many Streamlit environments.
    try:
        from io import BytesIO
        from PyPDF2 import PdfReader
        reader = PdfReader(BytesIO(payload))
        parts = []
        for idx in _page_indices(len(reader.pages)):
            try:
                parts.append(reader.pages[idx].extract_text() or "")
            except Exception:
                continue
        text = _clean_text(" ".join(parts))
        if text:
            if diag is not None:
                diag.append(f"Issuer-IR PDF: PyPDF2 erfolgreich ({len(text)} Zeichen).")
            return text[:240_000]
    except Exception as exc:
        if diag is not None:
            diag.append(f"Issuer-IR PDF: PyPDF2 nicht verfügbar/fehlgeschlagen ({type(exc).__name__}).")

    # 3) PyMuPDF/fitz, often installed even when pypdf is not.
    try:
        import fitz
        doc = fitz.open(stream=payload, filetype="pdf")
        parts = []
        for idx in _page_indices(len(doc)):
            try:
                parts.append(doc[idx].get_text("text") or "")
            except Exception:
                continue
        text = _clean_text(" ".join(parts))
        if text:
            if diag is not None:
                diag.append(f"Issuer-IR PDF: PyMuPDF erfolgreich ({len(text)} Zeichen).")
            return text[:240_000]
    except Exception as exc:
        if diag is not None:
            diag.append(f"Issuer-IR PDF: PyMuPDF nicht verfügbar/fehlgeschlagen ({type(exc).__name__}).")

    # 4) pdfminer.six is another common Streamlit dependency.
    try:
        from io import BytesIO
        from pdfminer.high_level import extract_text as pdfminer_extract_text
        text = _clean_text(pdfminer_extract_text(BytesIO(payload)) or "")[:240_000]
        if text:
            if diag is not None:
                diag.append(f"Issuer-IR PDF: pdfminer erfolgreich ({len(text)} Zeichen).")
            return text
    except Exception as exc:
        if diag is not None:
            diag.append(f"Issuer-IR PDF: pdfminer nicht verfügbar/fehlgeschlagen ({type(exc).__name__}).")

    # 5) System pdftotext binary, when supplied by the hosting image.
    try:
        import subprocess, tempfile
        with tempfile.NamedTemporaryFile(suffix=".pdf") as src, tempfile.NamedTemporaryFile(suffix=".txt") as dst:
            src.write(payload)
            src.flush()
            proc = subprocess.run(
                ["pdftotext", "-layout", src.name, dst.name],
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=5.0, check=False,
            )
            if proc.returncode == 0:
                dst.seek(0)
                text = _clean_text(dst.read().decode("utf-8", errors="ignore"))[:240_000]
                if text:
                    if diag is not None:
                        diag.append(f"Issuer-IR PDF: pdftotext erfolgreich ({len(text)} Zeichen).")
                    return text
    except Exception as exc:
        if diag is not None:
            diag.append(f"Issuer-IR PDF: pdftotext nicht verfügbar/fehlgeschlagen ({type(exc).__name__}).")

    # 6) pdfplumber remains a final optional backend.
    try:
        from io import BytesIO
        import pdfplumber
        parts = []
        with pdfplumber.open(BytesIO(payload)) as pdf:
            for idx in _page_indices(len(pdf.pages)):
                try:
                    parts.append(pdf.pages[idx].extract_text() or "")
                except Exception:
                    continue
        text = _clean_text(" ".join(parts))[:240_000]
        if text and diag is not None:
            diag.append(f"Issuer-IR PDF: pdfplumber erfolgreich ({len(text)} Zeichen).")
        return text
    except Exception as exc:
        if diag is not None:
            diag.append(f"Issuer-IR PDF: pdfplumber nicht verfügbar/fehlgeschlagen ({type(exc).__name__}).")
        return ""


def _bank_fetch_official_document(url, company_domain, deadline=None, timeout=4.0, diagnostics=None, allow_q4_cdn=False, referer=None, include_tail=False):
    """Fetch issuer/SEC documents with explicit PDF-signature and redirect trust guards.

    V2.21.33 keeps issuer-family trust as the default. For a URL that itself is an
    issuer-owned direct PDF link, a HTTPS redirect to a different host may be accepted
    only when the response body carries a real PDF signature. This covers issuer IR
    download endpoints backed by external document/CDN infrastructure without opening
    generic third-party HTML as bank evidence.
    """
    diag = diagnostics if isinstance(diagnostics, list) else None
    if not url:
        return None
    remaining = _research_budget_left(deadline)
    if not _research_budget_ok(deadline, reserve=0.4):
        if diag is not None:
            diag.append(
                f"Issuer-IR Dokument: kein Zeitbudget für den Abruf · Rest={remaining:.2f}s · {url}"
                if remaining is not None else f"Issuer-IR Dokument: kein Zeitbudget für den Abruf · {url}"
            )
        return None

    host = _normalize_host(url)
    q4_trusted = bool(allow_q4_cdn and (host == "q4cdn.com" or host.endswith(".q4cdn.com")))
    issuer_owned_initial = bool(company_domain and _host_belongs_to_company_family(url, company_domain))
    allowed = bool(
        host == "sec.gov"
        or host.endswith(".sec.gov")
        or q4_trusted
        or issuer_owned_initial
    )
    if not allowed:
        if diag is not None:
            diag.append(f"Issuer-IR Dokument: Start-Host nicht freigegeben ({host or 'unbekannt'}; {url}).")
        return None

    effective_timeout = _bounded_timeout(deadline, timeout)
    if effective_timeout is None:
        if diag is not None:
            remaining = _research_budget_left(deadline)
            diag.append(
                f"Issuer-IR Dokument: kein nutzbares Request-Zeitfenster · Rest={remaining:.2f}s · {url}"
                if remaining is not None else f"Issuer-IR Dokument: kein nutzbares Request-Zeitfenster · {url}"
            )
        return None

    try:
        is_sec_host = (host == "sec.gov" or host.endswith(".sec.gov"))
        if is_sec_host:
            _sec_fair_access_pause()
        headers = dict(_request_headers(sec=is_sec_host))
        if not is_sec_host:
            headers.setdefault("Accept", "application/pdf,text/html,text/plain,*/*;q=0.8")
            headers.setdefault("Accept-Language", "en-US,en;q=0.9")
            if referer:
                headers.setdefault("Referer", referer)
        response = requests.get(
            url,
            headers=headers,
            timeout=(min(2.5, effective_timeout), effective_timeout),
            allow_redirects=True,
        )
        response.raise_for_status()
        final_url = response.url or url
        final_host = _normalize_host(final_url)
        final_q4_trusted = bool(allow_q4_cdn and (final_host == "q4cdn.com" or final_host.endswith(".q4cdn.com")))
        issuer_owned_final = bool(company_domain and _host_belongs_to_company_family(final_url, company_domain))
        ctype = (response.headers.get("Content-Type") or "").lower()
        raw = response.content or b""
        pdf_signature = raw.lstrip()[:5] == b"%PDF-"
        initial_direct_pdf = bool(issuer_owned_initial and str(url).lower().split("?", 1)[0].endswith(".pdf"))
        redirect_pdf_bridge = bool(
            initial_direct_pdf
            and final_url.startswith("https://")
            and final_host
            and pdf_signature
        )
        final_allowed = bool(
            final_host == "sec.gov"
            or final_host.endswith(".sec.gov")
            or final_q4_trusted
            or issuer_owned_final
            or redirect_pdf_bridge
        )
        if not final_allowed:
            if diag is not None:
                diag.append(
                    "Issuer-IR Dokument: Redirect-Ziel nicht freigegeben · "
                    f"Start={host or 'unbekannt'} · Ziel={final_host or 'unbekannt'} · Content-Type={ctype or '–'} · {url}"
                )
            return None
        if redirect_pdf_bridge and not issuer_owned_final and diag is not None:
            diag.append(
                "Issuer-IR Dokument: issuer-eigener PDF-Link auf externes HTTPS-PDF weitergeleitet; "
                f"PDF-Signatur bestätigt ({final_host})."
            )

        looks_pdf = bool(
            "pdf" in ctype
            or final_url.lower().split("?", 1)[0].endswith(".pdf")
            or pdf_signature
        )
        if looks_pdf:
            if not pdf_signature and raw:
                # Some servers label HTML error/challenge pages as PDF. Do not feed
                # those into PDF parsers merely because the URL ends in .pdf.
                stripped = raw.lstrip()[:32].lower()
                if stripped.startswith((b"<html", b"<!doctype", b"<head", b"<body")):
                    if diag is not None:
                        diag.append(
                            f"Issuer-IR Dokument: PDF-URL lieferte HTML statt PDF · Content-Type={ctype or '–'} · {final_url}."
                        )
                    return None
            text = _bank_pdf_bytes_to_text(raw, diagnostics=diag, include_tail=include_tail)
            doc_type = "pdf"
        elif any(x in ctype for x in ["html", "text", "xml"]) or not ctype:
            text = _html_to_text(response.text[:1_800_000])
            doc_type = "html"
        else:
            if diag is not None:
                diag.append(
                    f"Issuer-IR Dokument: nicht unterstützter Content-Type {ctype or '–'} · {final_url}."
                )
            return None

        if not text:
            if diag is not None:
                diag.append(
                    f"Issuer-IR Dokument: geladen, aber ohne extrahierbaren Text ({final_url}; Content-Type={ctype or '–'}; Bytes={len(raw)})."
                )
            return None
        if diag is not None:
            diag.append(
                f"Issuer-IR Dokument: erfolgreich geladen ({doc_type}; {final_url}; Content-Type={ctype or '–'}; Bytes={len(raw)})."
            )
        return {
            "text": text,
            "url": final_url,
            # V2.21.35: preserve the official origin URL separately from the
            # technical download endpoint. The start URL already passed the
            # strict issuer/SEC/Q4 trust gate above; for an external redirect
            # bridge it was additionally required to resolve to a real PDF.
            # Downstream TTM source validation therefore anchors to this
            # provenance URL instead of globally trusting the cache host.
            "provenance_url": url,
            "resolved_url": final_url,
            "document_type": doc_type,
            "last_modified": response.headers.get("Last-Modified"),
        }
    except Exception as exc:
        if diag is not None:
            status = getattr(getattr(exc, "response", None), "status_code", None)
            suffix = f"HTTP {status}" if status else type(exc).__name__
            diag.append(f"Issuer-IR Dokument: Abruf fehlgeschlagen ({suffix}; {url}).")
        return None


def _bank_extract_q4_api_keys(html):
    '''Extract public Q4 feed keys exposed by the issuer page itself.

    The key is discovery metadata only. No third-party key guessing or issuer-
    specific constant is used. If the issuer page does not expose a key, the
    Q4 feed bridge simply stays inactive and the normal fail-closed path applies.
    '''
    source = str(html or "")
    if not source:
        return []
    patterns = [
        r"(?i)\bapiKey\b\s*[:=]\s*[\"']([A-Za-z0-9_-]{20,96})[\"']",
        r"(?i)[\"']apiKey[\"']\s*:\s*[\"']([A-Za-z0-9_-]{20,96})[\"']",
        r"(?i)\bapiKey=([A-Za-z0-9_-]{20,96})",
    ]
    keys = []
    for pat in patterns:
        for m in re.finditer(pat, source):
            key = (m.group(1) or "").strip()
            if key and key not in keys:
                keys.append(key)
    return keys[:4]


def _bank_q4_page_signature(html):
    low = str(html or "").lower()
    return any(x in low for x in [
        "powered by q4", "q4inc.com", "q4web.com", "q4cdn.com",
        "/feed/financialreport.svc", "getfinancialreportlist",
    ])


def _bank_q4_financial_feed_documents(html, page_url, company_domain, deadline=None, diagnostics=None):
    '''Resolve issuer-published quarterly documents from a Q4 financial-report feed.

    Trust is anchored in the issuer page: the page must identify Q4 and expose
    the public API key used by its own financial-report widget. The feed itself
    is called on the issuer host. A q4cdn.com document is accepted only when it
    is returned by that issuer-host feed.
    '''
    diag = diagnostics if isinstance(diagnostics, list) else None
    if not html or not page_url or not _bank_q4_page_signature(html):
        return {"documents": [], "trusted_platform_hosts": []}
    keys = _bank_extract_q4_api_keys(html)
    if not keys:
        if diag is not None:
            diag.append("Issuer-IR Q4 Feed: Q4-Seite erkannt, aber kein öffentlich exponierter Financial-Feed-Key gefunden.")
        return {"documents": [], "trusted_platform_hosts": []}
    page_host = _normalize_host(page_url)
    if not page_host or not _host_belongs_to_company_family(page_host, company_domain):
        return {"documents": [], "trusted_platform_hosts": []}
    feed_url = f"https://{page_host}/feed/FinancialReport.svc/GetFinancialReportList"
    current_year = datetime.now().year
    rows = {}
    trusted_hosts = set()
    feed_success = False
    for key in keys:
        for year in [current_year, current_year - 1]:
            if not _research_budget_ok(deadline, reserve=1.0):
                break
            effective_timeout = _bounded_timeout(deadline, 2.6)
            if effective_timeout is None:
                break
            try:
                response = requests.get(
                    feed_url,
                    params={
                        "apiKey": key,
                        "year": year,
                        "tagList": "",
                        "languageId": 1,
                        "pageNumber": 0,
                        "pageSize": 100,
                        "includeTags": "true",
                    },
                    headers=_request_headers(),
                    timeout=(min(1.7, effective_timeout), effective_timeout),
                    allow_redirects=True,
                )
                response.raise_for_status()
                final_host = _normalize_host(response.url or feed_url)
                if not _host_belongs_to_company_family(final_host, company_domain):
                    continue
                payload = response.json() if response.content else {}
                reports = payload.get("GetFinancialReportListResult") or []
                if not isinstance(reports, list):
                    continue
                feed_success = True
                for report in reports:
                    if not isinstance(report, dict):
                        continue
                    report_title = _clean_text(report.get("ReportTitle"))
                    report_subtype = _clean_text(report.get("ReportSubType"))
                    report_year = safe_float(report.get("ReportYear"))
                    period_text = f"{report_title} {report_subtype} {int(report_year) if report_year else ''}"
                    period = _bank_period_from_text(period_text)
                    if not period:
                        continue
                    for doc in report.get("Documents") or []:
                        if not isinstance(doc, dict):
                            continue
                        doc_url = _clean_text(doc.get("DocumentPath"))
                        doc_title = _clean_text(doc.get("DocumentTitle")) or report_title
                        doc_category = _clean_text(doc.get("DocumentCategory"))
                        if not doc_url.startswith(("http://", "https://")):
                            doc_url = urljoin(f"https://{page_host}/", doc_url)
                        host = _normalize_host(doc_url)
                        issuer_hosted = _host_belongs_to_company_family(host, company_domain)
                        q4_hosted = bool(host == "q4cdn.com" or host.endswith(".q4cdn.com"))
                        if not (issuer_hosted or q4_hosted):
                            continue
                        hay = f"{doc_title} {doc_category} {doc_url}"
                        score = _bank_ir_link_score(doc_url, f"{doc_title} {doc_category}")
                        if any(x in hay.lower() for x in ["supplement", "earnings tables", "financial supplement"]):
                            score += 220
                        if score <= 0:
                            continue
                        doc_class, doc_priority = _bank_ir_document_class(doc_url, f"{doc_title} {doc_category}")
                        if doc_priority < 0:
                            continue
                        row = {
                            "url": doc_url,
                            "title": doc_title or report_title or doc_url,
                            "period": period,
                            "score": score,
                            "document_class": doc_class,
                            "document_priority": doc_priority,
                            "trusted_q4_feed": q4_hosted,
                            "discovery_channel": "issuer_q4_financial_feed",
                        }
                        old = rows.get(doc_url)
                        if old is None or row["score"] > old["score"]:
                            rows[doc_url] = row
                        if q4_hosted:
                            trusted_hosts.add("q4cdn.com")
            except Exception as exc:
                if diag is not None:
                    status = getattr(getattr(exc, "response", None), "status_code", None)
                    suffix = f"HTTP {status}" if status else type(exc).__name__
                    diag.append(f"Issuer-IR Q4 Feed: FinancialReport-Abruf fehlgeschlagen ({suffix}).")
                continue
        if rows:
            break
    if diag is not None:
        if rows:
            periods = sorted({r.get("period") for r in rows.values() if r.get("period")}, key=_bank_period_sort_key, reverse=True)
            diag.append(
                "Issuer-IR Q4 Feed: issuer-hosted FinancialReport-Feed erfolgreich · "
                f"Dokumente={len(rows)}, Perioden={','.join(periods[:6]) or 'keine'}."
            )
        elif feed_success:
            diag.append("Issuer-IR Q4 Feed: Feed erreichbar, aber keine periodisierten Bank-Earnings-Dokumente extrahiert.")
    return {
        "documents": sorted(rows.values(), key=lambda r: (_bank_period_sort_key(r.get("period")), r.get("score", 0)), reverse=True),
        "trusted_platform_hosts": sorted(trusted_hosts),
    }

def _bank_extract_ir_links(html, base_url, company_domain, allow_trusted_q4_cdn=False, inherited_period=None):
    rows = []
    if not html:
        return rows
    try:
        soup = BeautifulSoup(html, "html.parser")
        issuer_page_trusted = bool(
            base_url and _host_belongs_to_company_family(base_url, company_domain)
        )
        for a in soup.find_all("a", href=True):
            href = urljoin(base_url, a.get("href"))
            if not href.startswith(("http://", "https://")):
                continue
            host = _normalize_host(href)
            issuer_hosted = _host_belongs_to_company_family(href, company_domain)
            q4_hosted = bool(host == "q4cdn.com" or host.endswith(".q4cdn.com"))
            trusted_q4_direct = bool(
                allow_trusted_q4_cdn and issuer_page_trusted and q4_hosted
            )
            if not (issuer_hosted or trusted_q4_direct):
                continue
            title = _clean_text(a.get_text(" ", strip=True))
            score = _bank_ir_link_score(href, title)
            if score <= 0:
                continue
            doc_class, doc_priority = _bank_ir_document_class(href, title)
            rows.append({
                "url": href,
                "title": title or _historical_title_hint_from_url(href),
                "period": _bank_period_from_text(f"{title} {href}") or inherited_period,
                "score": score,
                "document_class": doc_class,
                "document_priority": doc_priority,
                "trusted_q4_direct": trusted_q4_direct,
                "discovery_channel": "issuer_q4_direct_link" if trusted_q4_direct else "issuer_ir_link",
            })
    except Exception:
        return []
    unique = {}
    for row in rows:
        old = unique.get(row["url"])
        if old is None or row["score"] > old["score"]:
            unique[row["url"]] = row
    return sorted(unique.values(), key=lambda x: x.get("score", 0), reverse=True)


def _bank_discover_issuer_ir_documents(company_domain, company_name=None, deadline=None, diagnostics=None):
    """Bounded issuer-first discovery of quarterly earnings documents.

    V2.21.22 keeps hub-first navigation and adds issuer-owned IR-subdomain probing
    plus a bounded Q4 event-detail bridge for JavaScript-rendered quarterly-results pages.
    Deeper conventional paths and issuer-domain search remain fallbacks.
    """
    diag = diagnostics if isinstance(diagnostics, list) else None
    if not company_domain or not _research_budget_ok(deadline, reserve=1.0):
        if diag is not None:
            diag.append("Issuer-IR Discovery: keine Domain oder kein Recherchebudget.")
        return {"documents": [], "entrypoints": []}
    if diag is not None:
        diag.append(f"Issuer-IR Discovery: Domain {company_domain} erkannt.")

    candidate_roots = _bank_candidate_ir_roots(company_domain)
    root = candidate_roots[0] if candidate_roots else (_router_root(company_domain) or f"https://{company_domain}")
    candidate_pages = []
    documents = {}
    entrypoints = []
    fetched = set()
    trusted_platform_hosts = set()
    q4_ir_roots = []
    publication_dates_by_period = {}
    publication_date_quality = {}

    def remember_publication_date(period, material, identity_material=None, source_priority=1):
        """Store a release date only after exact-quarter earnings identity is proven.

        ``material`` may contain date-bearing lead text, but it is never allowed to
        prove the page identity by itself when a narrower ``identity_material`` is
        available.  This prevents archive/hub body cards from contaminating an
        inherited quarter with an unrelated IR date.
        """
        period_end = _bank_period_end_date(period)
        if not period_end:
            return
        identity = _clean_text(identity_material if identity_material is not None else material)
        if not _bank_publication_identity_matches(identity, period):
            return
        candidates = _bank_extract_release_dates(material, expected_year=period_end.year)
        plausible = [d for d in candidates if period_end < d <= period_end + timedelta(days=60)]
        if not plausible:
            return
        candidate = plausible[0]
        previous = publication_dates_by_period.get(period)
        previous_priority = int(publication_date_quality.get(period) or 0)
        # Prefer stronger provenance, not an earlier calendar date. Within the
        # same provenance tier the first page-owned candidate wins, preserving
        # URL/title/meta/dateline order and preventing later body dates from
        # replacing it merely because they are chronologically earlier.
        if previous is None or int(source_priority or 0) > previous_priority:
            publication_dates_by_period[period] = candidate
            publication_date_quality[period] = int(source_priority or 0)

    def has_primary_documents():
        return any(_bank_ir_is_primary_earnings_row(r) for r in documents.values())

    def has_expected_primary_coverage():
        """True once issuer-primary documents cover the latest four released quarters.

        This is a discovery-budget guard only. It does not assert that any one
        document contains all required bank metrics; the parser still validates
        ROTCE/TBVPS/CET1 and 4Q EPS independently and remains fail-closed.
        """
        expected = set(_bank_latest_released_calendar_periods(count=4) or [])
        if len(expected) < 4:
            return False
        found = {
            r.get("period") for r in documents.values()
            if r.get("period") and _bank_ir_is_primary_earnings_row(r)
        }
        return expected.issubset(found)

    def add_links(html, final_url, inherited_period=None):
        """Index direct documents and retain plausible same-domain hub/archive pages."""
        q4_page = _bank_q4_page_signature(html)
        if inherited_period:
            page_identity = _bank_publication_page_identity_material(html, final_url)
            page_lead = _bank_publication_page_lead_material(html, final_url)
            remember_publication_date(
                inherited_period,
                page_lead,
                identity_material=page_identity,
                source_priority=3,
            )
        for row in _bank_extract_ir_links(
            html, final_url, company_domain,
            allow_trusted_q4_cdn=q4_page, inherited_period=inherited_period,
        ):
            if row.get("period"):
                row_identity = _clean_text(f"{row.get('title') or ''} {row.get('url') or ''}")
                remember_publication_date(
                    row.get("period"),
                    row_identity,
                    identity_material=row_identity,
                    source_priority=2,
                )
            url_low = row["url"].lower().split("?", 1)[0]
            title_low = (row.get("title") or "").lower()
            hay = f"{title_low} {url_low}"
            doc_priority = int(row.get("document_priority") or 0)
            if row.get("period") and doc_priority > 0 and (
                url_low.endswith(".pdf")
                or any(k in title_low for k in [
                    "supplement", "earnings release", "news release",
                    "financial results", "results and key metrics",
                ])
            ):
                old = documents.get(row["url"])
                if old is None or (doc_priority, row["score"]) > (int(old.get("document_priority") or 0), old["score"]):
                    documents[row["url"]] = row
            elif any(k in hay for k in [
                "quarterly-earnings", "quarterly earnings", "quarterly-results",
                "quarterly results", "quarterly reports", "financial-results", "financial results",
                "/earnings", "earnings materials", "financial information", "financials/quarterly-results",
                "events-and-presentations", "events and presentations", "/financials",
                "/investors", "/investor-relations",
            ]):
                candidate_pages.append(row)

    # V2.21.22 Phase 0: probe issuer-owned IR subdomains early. Corporate homepages
    # often do not expose their IR host in static HTML, so waiting for search/deep
    # paths can exhaust the bounded discovery budget before ir./investor. is tried.
    # V2.21.31 fast lane: static /earnings archives are cheaper and often more
    # complete than the generic IR landing page. Probe them first so a Q4-powered
    # root cannot spend the shared parser budget on FinancialReport feed calls when
    # the issuer already publishes four quarter-tagged primary materials directly.
    alt_probe_paths = [
        "/earnings",
        "",
        "/financials/quarterly-results/default.aspx",
        "/financials/quarterly-results",
        "/news-events/webcasts-presentations/default.aspx",
    ]
    for alt_root in candidate_roots[1:]:
        if has_expected_primary_coverage() or not _research_budget_ok(deadline, reserve=3.0):
            break
        for path in alt_probe_paths:
            if has_expected_primary_coverage() or len(fetched) >= 8 or not _research_budget_ok(deadline, reserve=2.2):
                break
            seed = urljoin(alt_root.rstrip("/") + "/", path.lstrip("/"))
            if seed in fetched:
                continue
            fetched.add(seed)
            html, final_url = _fetch_html(seed, timeout=2.2, deadline=deadline)
            if not html:
                continue
            final_url = final_url or seed
            if not _host_belongs_to_company_family(final_url, company_domain):
                continue
            entrypoints.append(final_url)
            if _bank_q4_page_signature(html):
                q4_root = f"https://{_normalize_host(final_url)}"
                if q4_root not in q4_ir_roots:
                    q4_ir_roots.append(q4_root)
            add_links(html, final_url)
            if not has_expected_primary_coverage() and _bank_q4_page_signature(html):
                q4 = _bank_q4_financial_feed_documents(
                    html, final_url, company_domain, deadline=deadline, diagnostics=diag
                )
                for qrow in q4.get("documents") or []:
                    old = documents.get(qrow.get("url"))
                    if old is None or qrow.get("score", 0) > old.get("score", 0):
                        documents[qrow["url"]] = qrow
                trusted_platform_hosts.update(q4.get("trusted_platform_hosts") or [])
            if has_expected_primary_coverage():
                break
            if q4_ir_roots and not has_primary_documents():
                break
        if has_expected_primary_coverage():
            break
        if q4_ir_roots and not has_primary_documents():
            break

    # V2.21.22 Phase 0B: Q4 event-detail bridge. Some Q4 pages render the
    # quarterly-results table client-side and expose no usable FinancialReport key
    # in the initial HTML, while the earnings event-detail pages are server-rendered
    # and link the official supplement/release directly. Probe only recent quarters,
    # only on issuer-owned Q4 roots, and trust q4cdn links only when they are direct
    # anchors on those issuer pages.
    if not has_expected_primary_coverage() and q4_ir_roots and _research_budget_ok(deadline, reserve=2.0):
        event_hits = 0
        for q4_root in q4_ir_roots[:2]:
            for candidate in _bank_q4_event_detail_candidates(q4_root, company_name):
                if len({r.get("period") for r in documents.values() if r.get("period") and _bank_ir_is_primary_earnings_row(r)}) >= 4:
                    break
                if not _research_budget_ok(deadline, reserve=1.0):
                    break
                url = candidate.get("url")
                period = candidate.get("period")
                if not url or url in fetched:
                    continue
                fetched.add(url)
                html, final_url = _fetch_html(url, timeout=2.4, deadline=deadline)
                if not html:
                    continue
                final_url = final_url or url
                if not _host_belongs_to_company_family(final_url, company_domain):
                    continue
                # Require the resolved page itself to look like the intended period/earnings event.
                page_text = _html_to_text(html[:250000])
                resolved_period = _bank_period_from_text(f"{page_text[:4000]} {final_url}") or period
                if resolved_period != period:
                    continue
                event_hits += 1
                entrypoints.append(final_url)
                add_links(html, final_url, inherited_period=period)
        if diag is not None:
            periods = sorted(
                {r.get("period") for r in documents.values() if r.get("period")},
                key=_bank_period_sort_key, reverse=True,
            )
            diag.append(
                "Issuer-IR Q4 Event Bridge: "
                f"Event-Seiten={event_hits}, Dokumente={len(documents)}, "
                f"Perioden={','.join(periods[:6]) or 'keine'}."
            )

    # V2.21.24 Phase 0C: latest-released-period completion.  Older event pages can
    # establish a trusted Q4 tenant even when the newest event-detail URL uses a
    # different naming convention.  If discovery trails the latest normally
    # released quarter, search only the issuer domain for that exact quarter,
    # follow the official results page, and derive a bounded set of Q4 sibling
    # supplement URLs from the proven tenant + official release date.
    expected_periods = _bank_latest_released_calendar_periods(count=4)
    expected_latest = expected_periods[0] if expected_periods else None
    primary_periods_before = sorted(
        {r.get("period") for r in documents.values() if r.get("period") and _bank_ir_is_primary_earnings_row(r)},
        key=_bank_period_sort_key, reverse=True,
    )
    discovered_latest = primary_periods_before[0] if primary_periods_before else None
    if (
        expected_latest
        and (not discovered_latest or _bank_period_sort_key(discovered_latest) < _bank_period_sort_key(expected_latest))
        and _research_budget_ok(deadline, reserve=1.8)
    ):
        words = _bank_period_words(expected_latest)
        tenant_roots = _bank_q4_trusted_tenant_bases(documents)
        news_hits = 0
        derived_count = 0
        if words:
            # V2.21.45: search the exact issuer IR hosts already proven during
            # discovery before falling back to the registrable corporate domain.
            # Q4-hosted IR sites are often indexed under ir.<issuer-domain> even
            # when a broad site:<corporate-domain> query does not return them.
            # Hosts are accepted only from same issuer-domain-family URLs that
            # the adapter has already resolved, so this does not broaden trust.
            proven_search_hosts = []
            for source in list(entrypoints) + list(candidate_roots) + list(q4_ir_roots):
                try:
                    host = _normalize_host(source)
                except Exception:
                    host = None
                if not host or not _host_belongs_to_company_family(host, company_domain):
                    continue
                if host not in proven_search_hosts:
                    proven_search_hosts.append(host)
            base_host = _normalize_host(company_domain) or company_domain
            if base_host and base_host not in proven_search_hosts:
                proven_search_hosts.append(base_host)
            # Prefer specific IR subdomains over the broad corporate host.
            proven_search_hosts.sort(key=lambda h: (h == base_host, len(h)))
            proven_search_hosts = proven_search_hosts[:4]

            queries = []
            for search_host in proven_search_hosts:
                queries.extend([
                    f'site:{search_host} "{company_name or ""}" "reports {words["long"]} results"',
                    f'site:{search_host} "{company_name or ""}" "{words["long"]}" earnings',
                    f'site:{search_host} "{company_name or ""}" "{words["short"]}" "earnings supplement"',
                ])
            if diag is not None:
                diag.append(
                    "Issuer-IR Trusted Q4 Detail & Financials Bridge V43: "
                    f"Periode={expected_latest}, Suchhosts={','.join(proven_search_hosts) or 'keine'}."
                )

            financials_directory_count = 0
            for drow in _bank_q4_financials_directory_candidates(
                tenant_roots, expected_latest,
                (entrypoints[-1] if entrypoints else company_domain),
                template_rows=list(documents.values()),
            ):
                old = documents.get(drow["url"])
                if old is None or drow.get("score", 0) > old.get("score", 0):
                    documents[drow["url"]] = drow
                    financials_directory_count += 1
            if financials_directory_count:
                trusted_platform_hosts.add("q4cdn.com")

            detail_route_hits = 0
            for detail_url in _bank_q4_results_detail_route_candidates(
                proven_search_hosts, company_name, expected_latest
            ):
                if detail_route_hits or not _research_budget_ok(deadline, reserve=1.05):
                    break
                if detail_url in fetched:
                    continue
                fetched.add(detail_url)
                detail_html, detail_final = _fetch_html(detail_url, timeout=2.2, deadline=deadline)
                if not detail_html:
                    continue
                detail_final = detail_final or detail_url
                if not _host_belongs_to_company_family(detail_final, company_domain):
                    continue
                detail_identity = _bank_publication_page_identity_material(detail_html, detail_final)
                if not _bank_publication_identity_matches(detail_identity, expected_latest):
                    continue
                detail_route_hits += 1
                entrypoints.append(detail_final)
                detail_lead = _bank_publication_page_lead_material(detail_html, detail_final)
                remember_publication_date(
                    expected_latest, detail_lead,
                    identity_material=detail_identity, source_priority=4,
                )
                add_links(detail_html, detail_final, inherited_period=expected_latest)

            if diag is not None:
                diag.append(
                    "Issuer-IR Trusted Q4 Detail & Financials Bridge V43: "
                    f"Detail-Treffer={detail_route_hits}, Financials-Kandidaten={financials_directory_count}."
                )

            # V2.21.46 deterministic archive bridge. Search engines can omit a newly
            # published Q4-powered results page even when the issuer's own press-release
            # archive already links it. Probe only conventional archive routes on IR
            # hosts that were already proven by the issuer discovery. A link must prove
            # the exact expected quarter and earnings/results identity in its own title
            # or URL before we follow it. The fetched page must independently pass the
            # same identity gate. No archive body date may become publication metadata.
            archive_pages = 0
            archive_period_hits = 0
            archive_paths = [
                "/news-events/news/default.aspx",
                "/news-events/news",
                "/news-events/press-releases/default.aspx",
                "/news-events/press-releases",
                "/news-events/news-releases/default.aspx",
                "/news-events/news-releases",
            ]
            for search_host in proven_search_hosts:
                if derived_count or not _research_budget_ok(deadline, reserve=1.2):
                    break
                for archive_path in archive_paths:
                    if derived_count or not _research_budget_ok(deadline, reserve=0.9):
                        break
                    archive_url = f"https://{search_host}{archive_path}"
                    if archive_url in fetched:
                        continue
                    fetched.add(archive_url)
                    archive_html, archive_final = _fetch_html(
                        archive_url, timeout=2.3, deadline=deadline
                    )
                    if not archive_html:
                        continue
                    archive_final = archive_final or archive_url
                    if not _host_belongs_to_company_family(archive_final, company_domain):
                        continue
                    archive_pages += 1
                    archive_rows = _bank_extract_ir_links(
                        archive_html, archive_final, company_domain,
                        allow_trusted_q4_cdn=_bank_q4_page_signature(archive_html),
                    )
                    for archive_row in archive_rows:
                        row_url = archive_row.get("url")
                        row_identity = _clean_text(
                            f"{archive_row.get('title') or ''} {row_url or ''}"
                        )
                        if not row_url or row_url in fetched:
                            continue
                        if _bank_period_from_text(row_identity) != expected_latest:
                            continue
                        if not _bank_publication_identity_matches(row_identity, expected_latest):
                            continue
                        fetched.add(row_url)
                        result_html, result_final = _fetch_html(
                            row_url, timeout=2.5, deadline=deadline
                        )
                        if not result_html:
                            continue
                        result_final = result_final or row_url
                        if not _host_belongs_to_company_family(result_final, company_domain):
                            continue
                        result_identity = _bank_publication_page_identity_material(
                            result_html, result_final
                        )
                        if not _bank_publication_identity_matches(result_identity, expected_latest):
                            continue
                        archive_period_hits += 1
                        entrypoints.append(result_final)
                        result_lead = _bank_publication_page_lead_material(
                            result_html, result_final
                        )
                        remember_publication_date(
                            expected_latest,
                            result_lead,
                            identity_material=result_identity,
                            source_priority=4,
                        )
                        add_links(result_html, result_final, inherited_period=expected_latest)

                        release_date = publication_dates_by_period.get(expected_latest)
                        if release_date is None:
                            period_end = _bank_period_end_date(expected_latest)
                            lead_dates = _bank_extract_release_dates(
                                result_lead, expected_year=words["year"]
                            )
                            for candidate_date in lead_dates:
                                if (
                                    period_end
                                    and period_end < candidate_date <= period_end + timedelta(days=60)
                                ):
                                    release_date = candidate_date
                                    break

                        tenant_roots = _bank_q4_trusted_tenant_bases(documents) or tenant_roots
                        for drow in _bank_q4_derived_supplement_candidates(
                            tenant_roots, expected_latest, release_date, result_final,
                            template_rows=list(documents.values()),
                        ):
                            old = documents.get(drow["url"])
                            if old is None or drow.get("score", 0) > old.get("score", 0):
                                documents[drow["url"]] = drow
                                derived_count += 1
                        if derived_count:
                            trusted_platform_hosts.add("q4cdn.com")
                            break
                    if derived_count:
                        break

            if diag is not None:
                diag.append(
                    "Issuer-IR Proven IR News-Archive Bridge V42: "
                    f"Archive-Seiten={archive_pages}, Period-Treffer={archive_period_hits}, "
                    f"abgeleitete Kandidaten={derived_count}."
                )

            for query in queries:
                if derived_count or not _research_budget_ok(deadline, reserve=1.0):
                    break
                for item in _duckduckgo_html_search(query, max_results=5, deadline=deadline):
                    url = item.get("url")
                    if not url or not _host_belongs_to_company_family(url, company_domain):
                        continue
                    item_text = f"{item.get('title')} {item.get('snippet')} {url}"
                    item_period = _bank_period_from_text(item_text)
                    if item_period and item_period != expected_latest:
                        continue
                    if url in fetched:
                        continue
                    fetched.add(url)
                    html, final_url = _fetch_html(url, timeout=2.5, deadline=deadline)
                    if not html:
                        continue
                    final_url = final_url or url
                    if not _host_belongs_to_company_family(final_url, company_domain):
                        continue
                    page_text = _html_to_text(html[:350000])
                    page_period = _bank_period_from_text(f"{item_text} {page_text[:12000]}") or expected_latest
                    if page_period != expected_latest:
                        continue
                    earnings_language = any(term in page_text.lower() for term in [
                        "reported its", "quarter results", "quarterly results", "earnings release",
                        "earnings supplement", "financial results",
                    ])
                    if not earnings_language:
                        continue
                    news_hits += 1
                    entrypoints.append(final_url)
                    add_links(html, final_url, inherited_period=expected_latest)
                    release_date = _bank_extract_release_date(page_text, expected_year=words["year"])
                    # Refresh tenant roots after following the current issuer page.
                    tenant_roots = _bank_q4_trusted_tenant_bases(documents) or tenant_roots
                    for drow in _bank_q4_derived_supplement_candidates(
                        tenant_roots, expected_latest, release_date, final_url,
                        template_rows=list(documents.values()),
                    ):
                        old = documents.get(drow["url"])
                        if old is None or drow.get("score", 0) > old.get("score", 0):
                            documents[drow["url"]] = drow
                            derived_count += 1
                    if derived_count:
                        trusted_platform_hosts.add("q4cdn.com")
                        break
        if diag is not None:
            diag.append(
                "Issuer-IR Latest-Period Completion V22: "
                f"erwartet={expected_latest or 'keine'}, zuvor={discovered_latest or 'keine'}, "
                f"Issuer-News={news_hits}, Q4-Tenants={len(tenant_roots if words else [])}, "
                f"abgeleitete Supplement-Kandidaten={derived_count + financials_directory_count if words else derived_count}."
            )

    # Phase 1: hub-first.  Do not burn the complete request budget on guessed deep
    # paths before the issuer homepage or investor hub has had a chance to reveal
    # its real information architecture.
    hub_seed_paths = BANK_IR_SEED_PATHS[:5]
    for path in hub_seed_paths:
        if has_expected_primary_coverage():
            break
        if len(fetched) >= 5 or not _research_budget_ok(deadline, reserve=2.2):
            break
        seed = urljoin(root.rstrip("/") + "/", path.lstrip("/"))
        if seed in fetched:
            continue
        fetched.add(seed)
        html, final_url = _fetch_html(seed, timeout=2.2, deadline=deadline)
        if not html:
            continue
        final_url = final_url or seed
        if not _host_belongs_to_company_family(final_url, company_domain):
            continue
        entrypoints.append(final_url)
        add_links(html, final_url)
        if not has_primary_documents() and _bank_q4_page_signature(html):
            q4_root = f"https://{_normalize_host(final_url)}"
            if q4_root not in q4_ir_roots:
                q4_ir_roots.append(q4_root)
            q4 = _bank_q4_financial_feed_documents(html, final_url, company_domain, deadline=deadline, diagnostics=diag)
            for qrow in q4.get("documents") or []:
                old = documents.get(qrow.get("url"))
                if old is None or qrow.get("score", 0) > old.get("score", 0):
                    documents[qrow["url"]] = qrow
            trusted_platform_hosts.update(q4.get("trusted_platform_hosts") or [])
        # A single current multi-quarter supplement is sufficient for the bank
        # parser, so don't require four distinct document periods here.
        if documents and any(
            any(k in ((r.get("title") or "") + " " + (r.get("url") or "")).lower()
                for k in ["supplement", "financial supplement"])
            for r in documents.values()
        ):
            break


    # V2.21.22 Phase 1B: if the corporate root did not expose the IR subdomain,
    # resolve a same-domain investor hub before spending budget on guessed deep paths.
    # This remains issuer-neutral and accepts only the company's own domain family.
    if not has_primary_documents() and not candidate_pages and _research_budget_ok(deadline, reserve=3.0):
        hub_queries = [
            f'site:{company_domain} "{company_name or ""}" "quarterly results"',
            f'site:{company_domain} "{company_name or ""}" "investor relations" financials',
        ]
        for query in hub_queries:
            if has_primary_documents() or candidate_pages or not _research_budget_ok(deadline, reserve=2.0):
                break
            for item in _duckduckgo_html_search(query, max_results=4, deadline=deadline):
                url = item.get("url")
                if not url or not _host_belongs_to_company_family(url, company_domain):
                    continue
                direct_hay = f"{item.get('title')} {url}"
                period = _bank_period_from_text(direct_hay)
                score = _bank_ir_link_score(url, f"{item.get('title')} {item.get('snippet')}")
                direct_low = direct_hay.lower()
                looks_like_period_document = bool(period and (
                    url.lower().split("?", 1)[0].endswith(".pdf")
                    or any(k in direct_low for k in [
                        "earnings supplement", "financial supplement", "earnings release",
                        "press release", "news release", "earnings presentation",
                        "reports first quarter", "reports second quarter",
                        "reports third quarter", "reports fourth quarter",
                    ])
                ))
                doc_class, doc_priority = _bank_ir_document_class(url, direct_hay)
                if looks_like_period_document and score > 0 and doc_priority > 0:
                    documents[url] = {
                        "url": url,
                        "title": item.get("title") or url,
                        "period": period,
                        "score": score,
                        "document_class": doc_class,
                        "document_priority": doc_priority,
                    }
                    continue
                if score <= 0 or not _research_budget_ok(deadline, reserve=1.5):
                    continue
                html, final_url = _fetch_html(url, timeout=2.4, deadline=deadline)
                if not html:
                    continue
                final_url = final_url or url
                if not _host_belongs_to_company_family(final_url, company_domain):
                    continue
                entrypoints.append(final_url)
                fetched.add(final_url)
                add_links(html, final_url)
                if not has_primary_documents() and _bank_q4_page_signature(html):
                    q4 = _bank_q4_financial_feed_documents(html, final_url, company_domain, deadline=deadline, diagnostics=diag)
                    for qrow in q4.get("documents") or []:
                        old = documents.get(qrow.get("url"))
                        if old is None or qrow.get("score", 0) > old.get("score", 0):
                            documents[qrow["url"]] = qrow
                    trusted_platform_hosts.update(q4.get("trusted_platform_hosts") or [])
                if has_primary_documents() or candidate_pages:
                    break

    # Phase 2: follow the best same-domain hubs discovered on the loaded pages.
    # This is the generic bridge for nested structures such as /global/investors.
    for row in sorted(candidate_pages, key=lambda x: x.get("score", 0), reverse=True)[:4]:
        if has_expected_primary_coverage():
            break
        if not _research_budget_ok(deadline, reserve=1.5):
            break
        url = row.get("url")
        if not url or url in fetched:
            continue
        fetched.add(url)
        html, final_url = _fetch_html(url, timeout=2.3, deadline=deadline)
        if not html:
            continue
        final_url = final_url or url
        if not _host_belongs_to_company_family(final_url, company_domain):
            continue
        entrypoints.append(final_url)
        add_links(html, final_url)
        if not has_primary_documents() and _bank_q4_page_signature(html):
            q4_root = f"https://{_normalize_host(final_url)}"
            if q4_root not in q4_ir_roots:
                q4_ir_roots.append(q4_root)
            q4 = _bank_q4_financial_feed_documents(html, final_url, company_domain, deadline=deadline, diagnostics=diag)
            for qrow in q4.get("documents") or []:
                old = documents.get(qrow.get("url"))
                if old is None or qrow.get("score", 0) > old.get("score", 0):
                    documents[qrow["url"]] = qrow
            trusted_platform_hosts.update(q4.get("trusted_platform_hosts") or [])
        if documents and any(
            "supplement" in (((r.get("title") or "") + " " + (r.get("url") or "")).lower())
            for r in documents.values()
        ):
            break

    # Phase 3: conventional deeper paths only when hub discovery did not produce
    # a usable periodized document.  These are generic path conventions, not issuer
    # or ticker exceptions.
    if not has_primary_documents():
        for path in BANK_IR_SEED_PATHS[5:]:
            if len(fetched) >= 9 or not _research_budget_ok(deadline, reserve=1.7):
                break
            seed = urljoin(root.rstrip("/") + "/", path.lstrip("/"))
            if seed in fetched:
                continue
            fetched.add(seed)
            html, final_url = _fetch_html(seed, timeout=2.0, deadline=deadline)
            if not html:
                continue
            final_url = final_url or seed
            if not _host_belongs_to_company_family(final_url, company_domain):
                continue
            entrypoints.append(final_url)
            add_links(html, final_url)
            if not has_primary_documents() and _bank_q4_page_signature(html):
                q4 = _bank_q4_financial_feed_documents(html, final_url, company_domain, deadline=deadline, diagnostics=diag)
                for qrow in q4.get("documents") or []:
                    old = documents.get(qrow.get("url"))
                    if old is None or qrow.get("score", 0) > old.get("score", 0):
                        documents[qrow["url"]] = qrow
                trusted_platform_hosts.update(q4.get("trusted_platform_hosts") or [])
            if has_primary_documents():
                break

    # Search is discovery-only and remains restricted to the issuer's own host.
    if not has_primary_documents() and _research_budget_ok(deadline, reserve=2.2):
        queries = [
            f'site:{company_domain} "earnings supplement" "{company_name or ""}"',
            f'site:{company_domain} "quarterly results" "{company_name or ""}"',
            f'site:{company_domain} "reports second quarter" "{company_name or ""}"',
        ]
        for query in queries:
            if has_primary_documents() or not _research_budget_ok(deadline, reserve=1.5):
                break
            for item in _duckduckgo_html_search(query, max_results=4, deadline=deadline):
                url = item.get("url")
                if not url or not _host_belongs_to_company_family(url, company_domain):
                    continue
                period = _bank_period_from_text(f"{item.get('title')} {url}")
                score = _bank_ir_link_score(url, f"{item.get('title')} {item.get('snippet')}")
                doc_class, doc_priority = _bank_ir_document_class(url, f"{item.get('title')} {item.get('snippet')}")
                if period and score > 0 and doc_priority > 0:
                    documents[url] = {
                        "url": url,
                        "title": item.get("title") or url,
                        "period": period,
                        "score": score,
                        "document_class": doc_class,
                        "document_priority": doc_priority,
                    }
                elif _research_budget_ok(deadline, reserve=1.0):
                    html, final_url = _fetch_html(url, timeout=2.0, deadline=deadline)
                    if html:
                        resolved = final_url or url
                        entrypoints.append(resolved)
                        add_links(html, resolved)
                        if not has_primary_documents() and _bank_q4_page_signature(html):
                            q4 = _bank_q4_financial_feed_documents(html, resolved, company_domain, deadline=deadline, diagnostics=diag)
                            for qrow in q4.get("documents") or []:
                                old = documents.get(qrow.get("url"))
                                if old is None or qrow.get("score", 0) > old.get("score", 0):
                                    documents[qrow["url"]] = qrow
                            trusted_platform_hosts.update(q4.get("trusted_platform_hosts") or [])

    # V2.21.39: publication-metadata completion pass.  A bank may already have
    # complete issuer-primary earnings-document coverage while those document rows
    # carry no publication date (for example a PDF feed that omits the dated
    # newsroom/event page).  In that case, do one bounded issuer-domain lookup for
    # the latest released quarter.  This pass is metadata-only: it never adds
    # valuation documents, never changes document priority and never feeds the bank
    # parser.  The accepted date must belong to the exact latest quarter and be
    # strictly after quarter end but no more than 60 days later.
    latest_metadata_periods = _bank_latest_released_calendar_periods(count=1) or []
    latest_metadata_period = latest_metadata_periods[0] if latest_metadata_periods else None
    if (
        latest_metadata_period
        and int(publication_date_quality.get(latest_metadata_period) or 0) < 4
        and _research_budget_ok(deadline, reserve=0.8)
    ):
        words = _bank_period_words(latest_metadata_period)
        period_end = _bank_period_end_date(latest_metadata_period)
        metadata_hits = 0
        if words and period_end:
            # V2.21.44: cheap issuer-owned event/archive fallback before search.
            # Static earnings hubs can expose all four primary documents while
            # omitting the dated newsroom page.  Probe only conventional paths on
            # already proven issuer hosts and accept only exact-period local context.
            if int(publication_date_quality.get(latest_metadata_period) or 0) < 4:
                archive_paths = [
                    "/events-and-presentation",
                    "/events-and-presentations",
                    "/events-and-presentations/default.aspx",
                    "/news-events",
                    "/news-events/events-presentations",
                ]
                archive_roots = []
                for ep in list(entrypoints) + list(candidate_roots):
                    try:
                        parsed = urlparse(str(ep or ""))
                        if parsed.scheme and parsed.netloc:
                            base = f"{parsed.scheme}://{parsed.netloc}"
                            if _host_belongs_to_company_family(base, company_domain) and base not in archive_roots:
                                archive_roots.append(base)
                    except Exception:
                        continue
                archive_fetches = 0
                for base in archive_roots[:3]:
                    if int(publication_date_quality.get(latest_metadata_period) or 0) >= 4:
                        break
                    for path in archive_paths:
                        if archive_fetches >= 4 or int(publication_date_quality.get(latest_metadata_period) or 0) >= 4:
                            break
                        if not _research_budget_ok(deadline, reserve=0.30):
                            break
                        probe_url = urljoin(base.rstrip("/") + "/", path.lstrip("/"))
                        if probe_url in fetched:
                            continue
                        fetched.add(probe_url)
                        archive_fetches += 1
                        html, final_url = _fetch_html(probe_url, timeout=1.6, deadline=deadline)
                        if not html:
                            continue
                        resolved = final_url or probe_url
                        if not _host_belongs_to_company_family(resolved, company_domain):
                            continue
                        context_date = _bank_period_context_publication_date(html, latest_metadata_period)
                        if context_date is None:
                            continue
                        publication_dates_by_period[latest_metadata_period] = context_date
                        publication_date_quality[latest_metadata_period] = 4
                        metadata_hits += 1
                        entrypoints.append(resolved)
                        if diag is not None:
                            diag.append(
                                "Issuer-IR Period-Context Event Archive Guard V40: "
                                f"Periode={latest_metadata_period}, Datum={context_date.strftime('%Y-%m-%d')}, "
                                f"Quelle={resolved}."
                            )
                        break

            metadata_queries = [
                f'site:{company_domain} "{company_name or ""}" "reports {words["long"]} results"',
                f'site:{company_domain} "{company_name or ""}" "{words["long"]}" earnings',
            ]
            for query in metadata_queries:
                if int(publication_date_quality.get(latest_metadata_period) or 0) >= 4 or not _research_budget_ok(deadline, reserve=0.45):
                    break
                for item in _duckduckgo_html_search(query, max_results=4, deadline=deadline):
                    url = _clean_text(item.get("url"))
                    if not url or not _host_belongs_to_company_family(url, company_domain):
                        continue
                    item_identity = _clean_text(
                        f"{item.get('title') or ''} {url}"
                    )
                    if not _bank_publication_identity_matches(
                        item_identity, latest_metadata_period
                    ):
                        continue
                    # Search snippets are discovery context only. They can quote
                    # unrelated dates from the body of the correct earnings page
                    # (e.g. an earlier dividend action) and therefore must never
                    # establish the publication date. Only title/URL identity may
                    # contribute a date before the official page is fetched.
                    candidates = _bank_extract_release_dates(
                        item_identity, expected_year=period_end.year
                    )
                    plausible = [
                        d for d in candidates
                        if period_end < d <= period_end + timedelta(days=60)
                    ]
                    if plausible:
                        remember_publication_date(
                            latest_metadata_period, item_identity,
                            identity_material=item_identity, source_priority=2,
                        )
                        metadata_hits += 1
                        # Keep searching/fetching until page-owned priority is reached.
                        if int(publication_date_quality.get(latest_metadata_period) or 0) >= 4:
                            break
                    if not _research_budget_ok(deadline, reserve=0.3):
                        continue
                    html, final_url = _fetch_html(url, timeout=2.0, deadline=deadline)
                    if not html:
                        continue
                    resolved = final_url or url
                    if not _host_belongs_to_company_family(resolved, company_domain):
                        continue
                    page_material = _bank_publication_page_lead_material(html, resolved)
                    if not _bank_publication_identity_matches(
                        page_material, latest_metadata_period
                    ):
                        continue
                    candidates = _bank_extract_release_dates(
                        page_material, expected_year=period_end.year
                    )
                    plausible = [
                        d for d in candidates
                        if period_end < d <= period_end + timedelta(days=60)
                    ]
                    if not plausible:
                        continue
                    remember_publication_date(
                        latest_metadata_period, page_material,
                        identity_material=_bank_publication_page_identity_material(html, resolved),
                        source_priority=4,
                    )
                    metadata_hits += 1
                    entrypoints.append(resolved)
                    if int(publication_date_quality.get(latest_metadata_period) or 0) >= 4:
                        break
        if diag is not None:
            recovered = publication_dates_by_period.get(latest_metadata_period)
            diag.append(
                "Issuer-IR Publication-Date Provenance Priority Guard V38: "
                f"Periode={latest_metadata_period}, Treffer={metadata_hits}, "
                f"Qualitaet={int(publication_date_quality.get(latest_metadata_period) or 0)}, "
                f"Datum={recovered.strftime('%Y-%m-%d') if recovered else 'keins'}."
            )

    rows_all = sorted(
        documents.values(),
        key=lambda r: (_bank_period_sort_key(r.get("period")), int(r.get("document_priority") or 0), r.get("score", 0)),
        reverse=True,
    )
    periods_all = sorted(
        {r.get("period") for r in rows_all if r.get("period")},
        key=_bank_period_sort_key,
        reverse=True,
    )
    # V2.21.33 recent-window guard: the bank parser needs the latest quarter,
    # four consecutive TTM quarters and the same-quarter prior-year comparator
    # for tangible-book growth. Six most recent periodized quarters cover that
    # requirement while avoiding large historical archive payloads.
    keep_periods = set(periods_all[:6])
    rows = [r for r in rows_all if r.get("period") in keep_periods]
    if diag is not None:
        periods = sorted(
            {r.get("period") for r in rows if r.get("period")},
            key=_bank_period_sort_key,
            reverse=True,
        )
        primary_count = sum(1 for r in rows if _bank_ir_is_primary_earnings_row(r))
        fallback_count = sum(1 for r in rows if int(r.get("document_priority") or 0) in [1, 3])
        diag.append(
            "Issuer-IR Discovery V31: Issuer-Redirect-Provenance/Current-Period-EPS-Scope/Primary-PDF-Redirect aktiv · "
            f"Entry-Points={len(set(entrypoints))}, Dokumente={len(rows)} (Archiv={len(rows_all)}), Primär={primary_count}, Fallback={fallback_count}, "
            f"Perioden={','.join(periods[:6]) or 'keine'}."
        )
    return {
        "documents": rows,
        "entrypoints": list(dict.fromkeys(entrypoints)),
        "trusted_platform_hosts": sorted(trusted_platform_hosts),
        "publication_dates_by_period": {
            period: value.strftime("%Y-%m-%d")
            for period, value in publication_dates_by_period.items()
        },
    }


def _bank_ir_snapshot_from_documents(symbol, company_name, company_domain, discovery, deadline=None, diagnostics=None):
    diag = diagnostics if isinstance(diagnostics, list) else None
    documents = list((discovery or {}).get("documents") or [])
    if not documents:
        if diag is not None:
            diag.append("Issuer-IR Parser: keine periodisierten Earnings-Dokumente entdeckt.")
        return None

    def payload_for(row, timeout):
        preloaded = _clean_text((row or {}).get("preloaded_text"))
        if preloaded:
            return {
                "text": preloaded,
                "url": (row or {}).get("url"),
                "provenance_url": (row or {}).get("url"),
                "resolved_url": (row or {}).get("url"),
                "document_type": (row or {}).get("document_type") or "html",
                "last_modified": None,
            }
        entrypoints = (discovery or {}).get("entrypoints") or []
        payload = _bank_fetch_official_document(
            (row or {}).get("url"), company_domain, deadline=deadline, timeout=timeout, diagnostics=diag,
            referer=(entrypoints[0] if entrypoints else None),
            allow_q4_cdn=bool(
                (row or {}).get("trusted_q4_feed")
                or (row or {}).get("trusted_q4_direct")
                or (row or {}).get("trusted_q4_derived")
            ),
        )
        if payload and (row or {}).get("trusted_q4_derived"):
            if not _bank_q4_derived_payload_valid(payload, row, company_name):
                if diag is not None:
                    diag.append(
                        f"Issuer-IR Q4 Derived Gate: verworfen – Perioden-/Issuer-Identität nicht bestätigt ({(row or {}).get('url')})."
                    )
                return None
            if diag is not None:
                diag.append(
                    f"Issuer-IR Q4 Derived Gate: bestätigt · Periode={(row or {}).get('period')} · issuergebundener Q4-Tenant."
                )
        return payload

    by_period = {}
    for row in documents:
        period = row.get("period")
        if not period:
            continue
        by_period.setdefault(period, []).append(row)
    for period in by_period:
        by_period[period].sort(
            key=lambda x: (int(x.get("document_priority") or 0), x.get("score", 0)),
            reverse=True,
        )
    latest_period = max(by_period, key=_bank_period_sort_key) if by_period else None
    if not latest_period:
        if diag is not None:
            diag.append("Issuer-IR Parser: keine jüngste Quartalsperiode bestimmbar.")
        return None
    if diag is not None:
        diag.append(f"Issuer-IR Parser: jüngste Periode {latest_period}; {len(by_period.get(latest_period) or [])} Dokumentkandidat(en).")

    latest_docs = by_period.get(latest_period) or []
    latest_payload = None
    latest_row = None
    # Supplements first, then releases, then earnings presentations and opaque
    # quarter PDFs.  Explicit profile/marketing material can never be the primary
    # current-quarter bank snapshot.
    for row in latest_docs[:5]:
        if not _research_budget_ok(deadline, reserve=1.0):
            break
        doc_class = row.get("document_class")
        doc_priority = row.get("document_priority")
        if doc_priority is None:
            doc_class, doc_priority = _bank_ir_document_class(row.get("url"), row.get("title"))
        if int(doc_priority or 0) < 0:
            continue
        if diag is not None:
            _left = _research_budget_left(deadline)
            diag.append(
                f"Issuer-IR Parser V31: Kandidat · Periode={row.get('period') or '–'} · Klasse={doc_class or 'unbekannt'} · "
                f"Priorität={int(doc_priority or 0)} · Rest={_left:.2f}s · URL={row.get('url')}"
                if _left is not None else
                f"Issuer-IR Parser V31: Kandidat · Periode={row.get('period') or '–'} · Klasse={doc_class or 'unbekannt'} · Priorität={int(doc_priority or 0)} · URL={row.get('url')}"
            )
        payload = payload_for(row, 5.5)
        if not payload:
            continue
        text_low = payload["text"].lower()
        signal_count = sum(
            1 for term in ["earnings per", "tangible book value", "tbvps", "rotce", "return on average tangible", "cet1", "common equity tier 1"]
            if term in text_low
        )
        earnings_context = any(term in text_low for term in [
            "earnings supplement", "supplemental analyst", "quarterly results",
            "financial results", "earnings release", "quarter ended",
        ])
        minimum_signals = 2 if int(doc_priority or 0) >= 3 else 4
        if signal_count >= minimum_signals and (int(doc_priority or 0) >= 3 or earnings_context):
            latest_payload = payload
            latest_row = row
            if diag is not None:
                diag.append(
                    f"Issuer-IR Dokumentklasse: {doc_class or 'unbekannt'} · Priorität={int(doc_priority or 0)} · Bank-Kernsignale={signal_count}."
                )
            break
    if not latest_payload:
        if diag is not None:
            diag.append("Issuer-IR Parser: kein jüngstes Dokument mit mindestens zwei Bank-Kernsignalen extrahierbar.")
        return None

    latest_text = latest_payload["text"]
    coverage = []
    multi = _bank_extract_quarterly_eps_series(latest_text, latest_period, count=4)
    adjusted_multi = _bank_extract_adjusted_quarterly_eps_series(latest_text, latest_period, count=4, reported_series=multi)
    sensitive_terms = ["significant item", "significant items", "notable item", "notable items", "special item", "special items"]
    latest_has_special_item_language = any(term in latest_text.lower() for term in sensitive_terms)

    # A current supplement may provide all four quarters in one table.  If it
    # also discusses special/notable items, only a quantitative company-labelled
    # adjusted EPS row may bridge them; otherwise we fall back to separate
    # period documents and remain fail-closed.
    multi_bridge_ok = (
        len(multi) == 4 and (not latest_has_special_item_language or len(adjusted_multi) == 4)
    )
    if multi_bridge_ok:
        source_url = latest_payload.get("provenance_url") or latest_payload.get("url") or latest_row.get("url")
        core_map = {r["period"]: r["core_eps"] for r in adjusted_multi} if adjusted_multi else {}
        for row in reversed(multi):
            reported = safe_float(row.get("reported_eps"))
            core = safe_float(core_map.get(row.get("period"), reported))
            if reported is None or core is None:
                coverage = []
                break
            effect = reported - core
            if adjusted_multi:
                status = "Offizielle Multi-Quarter-EPS-Reconciliation ex company-designated notable/significant/special items"
            else:
                status = "Offizielle Multi-Quarter-Tabelle; keine company-designierte quantitative EPS-Sonderposten-Brücke erkannt"
            coverage.append({
                "period": row["period"],
                "published_date": None,
                "source_url": source_url,
                "reported_eps": reported,
                "core_eps": core,
                "special_items_eps_effect": effect,
                "special_item_status": status,
            })
        coverage.sort(key=lambda r: _bank_period_sort_key(r.get("period")))
    else:
        expected = _bank_consecutive_periods_ending(latest_period, 4)
        for period in expected:
            candidates = by_period.get(period) or []
            found = None
            for candidate in candidates[:3]:
                if period == latest_period and latest_payload and candidate.get("url") == latest_row.get("url"):
                    payload = latest_payload
                else:
                    if not _research_budget_ok(deadline, reserve=0.8):
                        break
                    payload = payload_for(candidate, 3.8)
                if not payload:
                    continue
                eps = _bank_extract_eps_from_text(payload.get("text"))
                core, effect, status = _bank_detect_special_item_bridge(payload.get("text"), eps, current_period=period)
                if eps is None or core is None or effect is None or not status:
                    continue
                found = {
                    "period": period,
                    "published_date": None,
                    "source_url": payload.get("provenance_url") or payload.get("url") or candidate.get("url"),
                    "resolved_source_url": payload.get("resolved_url") or payload.get("url"),
                    "reported_eps": eps,
                    "core_eps": core,
                    "special_items_eps_effect": effect,
                    "special_item_status": status,
                }
                break
            if not found:
                return None
            coverage.append(found)

    periods = [r.get("period") for r in coverage]
    if len(periods) != 4:
        return None
    keys = [_bank_period_sort_key(x) for x in periods]
    for a, b in zip(keys, keys[1:]):
        ay, aq = a; by, bq = b
        next_key = (ay + 1, 1) if aq == 4 else (ay, aq + 1)
        if b != next_key:
            return None

    rotce = _bank_extract_rotce(latest_text, latest_period)
    cet1_std, cet1_adv = _bank_extract_cet1_values(latest_text, latest_period)
    tbv_vals = _bank_extract_tbv_values(latest_text, latest_period)
    tbv = tbv_vals[0] if tbv_vals else None
    # Most bank supplements show latest quarter, prior quarter, year-end/prior
    # quarters and the year-ago quarter in the fifth comparable column.
    tbv_prior_yoy = None
    if tbv is not None and tbv > 0:
        for idx in [4, 2, 1]:
            if len(tbv_vals) <= idx:
                continue
            candidate = safe_float(tbv_vals[idx])
            if candidate is not None and candidate > 0 and 0.50 <= candidate / tbv <= 1.50:
                tbv_prior_yoy = candidate
                break
    tbv_growth = ((tbv / tbv_prior_yoy - 1.0) * 100.0) if tbv and tbv_prior_yoy and tbv_prior_yoy > 0 else None
    book_value = _bank_extract_book_value(latest_text, latest_period)
    latest_cov = coverage[-1]
    latest_eps = safe_float(latest_cov.get("reported_eps"))
    latest_core = safe_float(latest_cov.get("core_eps"))
    latest_effect = safe_float(latest_cov.get("special_items_eps_effect"))

    # V2.21.28: do not require a separately adjusted ROTCE for a de-minimis
    # company-designated EPS bridge.  We never derive an adjusted ROTCE.  The
    # issuer-reported ROTCE is simply retained when the current-quarter EPS
    # adjustment is <=2% of reported EPS; larger adjustments still block the
    # normalized ROTCE anchor unless an explicit issuer-adjusted ROTCE exists.
    rotce_eps_bridge_ratio = None
    rotce_basis = None
    rotce_basis_mode = None
    rotce_basis_note = None
    if rotce is not None:
        if latest_effect is None or abs(latest_effect) <= 1e-12:
            rotce_basis = rotce
            rotce_basis_mode = "reported_no_current_eps_adjustment"
            rotce_basis_note = "Gemeldeter ROTCE als Bewertungsbasis; im aktuellen Quartal keine quantitative EPS-Sonderposten-Brücke."
        elif latest_eps is not None and abs(latest_eps) > 1e-12:
            rotce_eps_bridge_ratio = abs(latest_effect / latest_eps)
            if rotce_eps_bridge_ratio <= BANK_ROTCE_EPS_BRIDGE_IMMATERIALITY_LIMIT:
                rotce_basis = rotce
                rotce_basis_mode = "reported_rotce_immaterial_eps_bridge"
                rotce_basis_note = (
                    "Gemeldeter ROTCE bleibt Bewertungsbasis: Die company-designierte aktuelle EPS-Bereinigung "
                    f"beträgt nur {rotce_eps_bridge_ratio * 100.0:.1f} % des gemeldeten Quartals-EPS und liegt damit "
                    f"innerhalb des konservativen {BANK_ROTCE_EPS_BRIDGE_IMMATERIALITY_LIMIT * 100.0:.0f}-%-Materialitätslimits. "
                    "Es wird kein adjusted ROTCE geschätzt oder abgeleitet."
                )
            else:
                rotce_basis_mode = "blocked_material_eps_bridge_without_adjusted_rotce"
                rotce_basis_note = (
                    "ROTCE-Bewertungsbasis gesperrt: Die company-designierte aktuelle EPS-Bereinigung ist materiell "
                    f"({rotce_eps_bridge_ratio * 100.0:.1f} % des gemeldeten Quartals-EPS), aber die Primärquelle weist "
                    "keinen separaten adjusted ROTCE aus."
                )

    if diag is not None:
        diag.append(
            "Issuer-IR Parser-Gate: "
            f"4Q-EPS={len(coverage)}/4, 4Q-Core-Bridge={'ja' if adjusted_multi else ('nicht nötig' if not latest_has_special_item_language else 'nein')}, ROTCE={'ja' if rotce is not None else 'nein'}, "
            f"TBVPS={'ja' if tbv is not None else 'nein'}, TBV-YoY={'ja' if tbv_growth is not None else 'nein'}, "
            f"BookValue={'ja' if book_value is not None else 'nein (optional)'}, CET1-Std={'ja' if cet1_std is not None else 'nein'}, "
            f"CET1-Adv={'ja' if cet1_adv is not None else 'nein'}."
        )
    # V2.21.24: ordinary Book Value is optional context.  The released bank
    # valuation is anchored to Tangible Book Value, so a missing ordinary BVPS
    # must not block an otherwise complete issuer-primary bank snapshot.
    if None in [rotce_basis, cet1_std, tbv, tbv_growth, latest_eps, latest_core, latest_effect]:
        if diag is not None and rotce is not None and rotce_basis is None and rotce_basis_note:
            diag.append(f"Issuer-IR ROTCE Materiality Guard: {rotce_basis_note}")
        return None
    if diag is not None and rotce_basis_note:
        diag.append(f"Issuer-IR ROTCE Materiality Guard: {rotce_basis_note}")

    latest_end = _bank_period_end_date(latest_period)
    # V2.21.43 final-snapshot publication authority guard.  Discovery has already
    # applied exact-quarter earnings identity and provenance rules.  Once it
    # supplies a plausible publication date, the final snapshot must not mix that
    # authoritative date back together with arbitrary dates from the full earnings
    # document body and then choose the earliest calendar date.  That old final
    # sort reintroduced unrelated corporate-action dates (PNC: July 6 dividend
    # reference) after discovery had correctly found the July 15 earnings release.
    #
    # Therefore the qualified discovery date is the primary publication anchor.
    # Only when discovery has no usable date do we fall back to current-period
    # document provenance/title/URL and finally a bounded leading slice of the
    # validated document text.  Fallback candidates preserve source order rather
    # than chronological order.  This remains display metadata only.
    detected_release_date = None
    release_date_source = None
    discovery_release_raw = ((discovery or {}).get("publication_dates_by_period") or {}).get(latest_period)
    if discovery_release_raw:
        discovery_candidates = _bank_extract_release_dates(
            discovery_release_raw, expected_year=latest_end.year if latest_end else None
        )
        for candidate in discovery_candidates:
            if latest_end and latest_end < candidate <= latest_end + timedelta(days=60):
                detected_release_date = candidate
                release_date_source = "qualified_discovery"
                break

    if detected_release_date is None:
        fallback_material = " ".join([
            _clean_text(latest_row.get("title")),
            _clean_text(latest_row.get("url")),
            _clean_text(latest_payload.get("provenance_url")),
            _clean_text(latest_payload.get("resolved_url")),
            _clean_text(latest_payload.get("url")),
            _clean_text(latest_text)[:5000],
        ])
        fallback_candidates = _bank_extract_release_dates(
            fallback_material, expected_year=latest_end.year if latest_end else None
        )
        for candidate in fallback_candidates:
            if latest_end and latest_end < candidate <= latest_end + timedelta(days=60):
                detected_release_date = candidate
                release_date_source = "current_period_document_fallback"
                break

    # V2.21.48: trusted-Q4 publication metadata retry. /doc_financials/ PDFs
    # can prove valuation data while carrying no publication date. If discovery
    # exhausted its shared crawl budget, retry only the deterministic issuer-owned
    # Q4 results-detail route; exact quarter + results identity remains mandatory.
    if detected_release_date is None and latest_row.get("trusted_q4_derived"):
        proven_hosts = []
        for source in ((discovery or {}).get("entrypoints") or []):
            host = _normalize_host(source)
            if not host or not _host_belongs_to_company_family(host, company_domain):
                continue
            if host not in proven_hosts:
                proven_hosts.append(host)
        proven_hosts.sort(key=lambda h: (
            not (h.startswith("ir.") or h.startswith("investor.") or h.startswith("investors.")), len(h)
        ))
        for detail_url in _bank_q4_results_detail_route_candidates(
            proven_hosts[:1], company_name, latest_period
        )[:3]:
            detail_html, detail_final = _fetch_html(detail_url, timeout=1.8, deadline=None)
            if not detail_html:
                continue
            detail_final = detail_final or detail_url
            if not _host_belongs_to_company_family(detail_final, company_domain):
                continue
            identity = _bank_publication_page_identity_material(detail_html, detail_final)
            if not _bank_publication_identity_matches(identity, latest_period):
                continue
            lead = _bank_publication_page_lead_material(detail_html, detail_final)
            for candidate in _bank_extract_release_dates(
                lead, expected_year=latest_end.year if latest_end else None
            ):
                if latest_end and latest_end < candidate <= latest_end + timedelta(days=60):
                    detected_release_date = candidate
                    release_date_source = "trusted_q4_results_detail_metadata_retry"
                    break
            if detected_release_date is not None:
                break

    if diag is not None:
        diag.append(
            "CET1 Row & Q4 Publication Metadata Guard V44: "
            f"Periode={latest_period}, Quelle={release_date_source or 'keine'}, "
            f"Datum={detected_release_date.strftime('%Y-%m-%d') if detected_release_date else 'keins'}."
        )
    published_date = detected_release_date.strftime("%d.%m.%Y") if detected_release_date else None
    # Freshness remains anchored to the reported quarter end.  Publication-date
    # recovery is display metadata only and must not alter validity mathematics.
    valid_until = latest_end + timedelta(days=110) if latest_end else None
    entrypoints = (discovery or {}).get("entrypoints") or []
    source_url = latest_payload.get("provenance_url") or latest_payload.get("url") or latest_row.get("url")
    return {
        "symbol": str(symbol or "").upper(),
        "company": company_name or str(symbol or "").upper(),
        "as_of_date": latest_end.strftime("%d.%m.%Y") if latest_end else None,
        "published_date": published_date,
        "valid_until": valid_until.strftime("%d.%m.%Y") if valid_until else None,
        "source_name": "Issuer IR Quarterly Earnings · Universal Bank CET1 Row & Q4 Publication Metadata Guard · Table Parser V18",
        "source_url": source_url,
        "supplement_url": source_url,
        "source_discovery_url": entrypoints[0] if entrypoints else None,
        "allowed_source_hosts": list(dict.fromkeys([company_domain] + list((discovery or {}).get("trusted_platform_hosts") or []))),
        "adapter_version": BANK_PRIMARY_SOURCE_ADAPTER_VERSION,
        "adapter_mode": "issuer_ir_auto_discovery",
        "book_value_per_share": book_value,
        "tangible_book_value_per_share": tbv,
        "book_value_growth_yoy_pct": None,
        "tangible_book_value_growth_yoy_pct": tbv_growth,
        "roe_reported_pct": None,
        "rotce_reported_pct": rotce,
        "rotce_ex_significant_items_pct": rotce_basis,
        "rotce_normalized_label": "ROTCE Bewertungsbasis",
        "rotce_basis_mode": rotce_basis_mode,
        "rotce_basis_note": rotce_basis_note,
        "rotce_eps_bridge_ratio": rotce_eps_bridge_ratio,
        "cet1_standardized_pct": cet1_std,
        "cet1_advanced_pct": cet1_adv,
        "quarter_eps_reported": latest_eps,
        "quarter_eps_ex_significant_items": latest_core,
        "significant_items_eps_effect": latest_effect,
        "ttm_eps_coverage": coverage,
        "ttm_coverage_expected_periods": periods,
        "source_note": (
            f"{APP_BUILD_VERSION} hat die offizielle Investor-Relations-Quartalsstruktur über die generische Earnings-Document-Classifier/Q4-Material-Discovery automatisch entdeckt, "
            "TOC-sicher nur quartalsausgerichtete ROTCE-, TBVPS- und CET1-Tabellenfelder akzeptiert (normaler Buchwert bleibt optionaler Kontext) und vier aufeinanderfolgende "
            "offizielle Quartals-EPS einschließlich vorhandener quantitativer company-designierter EPS-Reconciliations in das gemeinsame Bank-Snapshot-Schema überführt. SEC bleibt Fallback; "
            "fehlende oder nicht eindeutig zuordenbare Primärdaten sperren die Bewertung weiterhin fail-closed."
        ),
    }


def _discover_universal_bank_snapshot_uncached(symbol, company_name=None, website=None):
    """Live issuer-IR first / SEC second discovery with phase-isolated budgets."""
    company_domain = _extract_company_domain(website)
    ir_diagnostics = []
    if company_domain:
        discovery_deadline = time.monotonic() + 18.0
        discovery = _bank_discover_issuer_ir_documents(
            company_domain,
            company_name=company_name,
            deadline=discovery_deadline,
            diagnostics=ir_diagnostics,
        )
        # V2.21.33: keep the fresh parser/document budget after discovery. A slow
        # issuer archive may validly consume most of the crawl budget; that must
        # not prevent the already-discovered primary PDF from being fetched.
        parser_deadline = time.monotonic() + 16.0
        ir_diagnostics.append(
            "Issuer-IR Phase Budget V31: Discovery abgeschlossen; separates 16-s-Dokument-/Parser-Budget gestartet."
        )
        snapshot = _bank_ir_snapshot_from_documents(
            symbol,
            company_name,
            company_domain,
            discovery,
            deadline=parser_deadline,
            diagnostics=ir_diagnostics,
        )
        if snapshot is not None:
            snapshot["adapter_diagnostic"] = " | ".join(ir_diagnostics)
            return snapshot
    else:
        ir_diagnostics.append("Issuer-IR Discovery: keine verifizierbare Unternehmenswebsite im Datenobjekt verfügbar.")

    sec_result = _discover_universal_bank_snapshot_v1_uncached(symbol, company_name=company_name)
    if isinstance(sec_result, dict) and sec_result.get("_diagnostic_only"):
        sec_diag = str(sec_result.get("adapter_diagnostic") or "").strip()
        combined = " | ".join([x for x in [" | ".join(ir_diagnostics), sec_diag] if x])
        sec_result["adapter_diagnostic"] = combined
    return sec_result


@st.cache_data(ttl=21600, show_spinner=False)
def _discover_universal_bank_snapshot_success_cache(symbol, company_name=None, website=None, cache_epoch=None):
    """Cache successful bank snapshots under an explicit build epoch.

    Diagnostic-only failures are returned to the wrapper, which immediately retries
    the live path so a transient network/SEC failure cannot be frozen for six hours.
    """
    return _discover_universal_bank_snapshot_uncached(
        symbol, company_name=company_name, website=website
    )


def _discover_universal_bank_snapshot_v2(symbol, company_name=None, website=None):
    cached = _discover_universal_bank_snapshot_success_cache(
        symbol, company_name=company_name, website=website,
        cache_epoch=BANK_DISCOVERY_CACHE_EPOCH,
    )
    if isinstance(cached, dict) and not cached.get("_diagnostic_only"):
        return cached
    # Failures/diagnostics must be live-retryable; do not let a transient result
    # from this or a prior runtime become the authoritative six-hour answer.
    return _discover_universal_bank_snapshot_uncached(
        symbol, company_name=company_name, website=website
    )


def _bank_period_from_filing_date(filing_date):
    """Infer the earnings quarter from a normal U.S. bank earnings filing date."""
    try:
        dt = datetime.strptime(str(filing_date or ""), "%Y-%m-%d").date()
    except Exception:
        return None
    if dt.month in (1, 2):
        return f"4Q{str(dt.year - 1)[-2:]}"
    if dt.month in (4, 5):
        return f"1Q{str(dt.year)[-2:]}"
    if dt.month in (7, 8):
        return f"2Q{str(dt.year)[-2:]}"
    if dt.month in (10, 11):
        return f"3Q{str(dt.year)[-2:]}"
    return None


def _bank_sec_exhibit_score(row_text, url):
    hay = _clean_text(f"{row_text} {unquote(url or '')}").lower()
    score = 0
    if any(x in hay for x in ["quarterly supplement", "earnings supplement", "financial supplement", "suppl.htm", "supplement.htm", "xsuppl"]):
        score += 500
    if any(x in hay for x in ["exhibit 99.2", "ex-99.2", "99.2"]):
        score += 120
    if any(x in hay for x in ["earnings release", "news release", "financial results", "release.htm", "xrelea"]):
        score += 260
    if any(x in hay for x in ["exhibit 99.1", "ex-99.1", "99.1"]):
        score += 70
    if any(x in hay for x in ["presentation", "pres.htm", "xpres"]):
        score += 80
    if any(x in hay for x in [".htm", ".html"]):
        score += 35
    return score


def _bank_discover_sec_earnings_exhibits(symbol, max_filings=6, deadline=None, diagnostics=None):
    """Generic SEC Item-2.02 earnings discovery with primary-document recovery.

    V2.21.9 introduced the Item-2.02 8-K primary-document recovery and follows its
    exhibit table links.  Filing-index .htm/.html pages remain secondary
    discovery surfaces.  This is intentionally issuer-neutral: the only
    ranking signals are generic earnings/supplement/exhibit semantics.

    ``diagnostics`` may be a mutable list.  When supplied, concise stage
    messages are appended so the UI can distinguish CIK/submissions/network,
    exhibit-discovery and table-parser failures without exposing stack traces.
    """
    diag = diagnostics if isinstance(diagnostics, list) else []

    cik = _sec_lookup_cik(symbol, deadline=deadline, diagnostics=diag)
    if not cik:
        diag.append("SEC-Stufe CIK: Auflösung nach allen offiziellen SEC-Fallbacks fehlgeschlagen.")
        return []
    diag.append(f"SEC-Stufe CIK: CIK {int(cik)} erkannt.")
    if not _research_budget_ok(deadline):
        diag.append("SEC-Stufe Budget: Recherchebudget nach CIK-Auflösung erschöpft.")
        return []

    cik10 = f"{cik:010d}"
    effective_timeout = _bounded_timeout(deadline, 3.6)
    if effective_timeout is None:
        diag.append("SEC-Stufe Submissions: kein Zeitbudget für den Abruf verfügbar.")
        return []

    submissions_url = f"https://data.sec.gov/submissions/CIK{cik10}.json"
    try:
        _sec_fair_access_pause()
        r = requests.get(
            submissions_url,
            headers=_request_headers(sec=True),
            timeout=(min(1.8, effective_timeout), effective_timeout),
        )
        r.raise_for_status()
        recent = (r.json().get("filings") or {}).get("recent") or {}
        diag.append("SEC-Stufe Submissions: recent filings geladen.")
    except Exception as exc:
        status = getattr(getattr(exc, "response", None), "status_code", None)
        suffix = f" HTTP {status}" if status else f" {type(exc).__name__}"
        diag.append("SEC-Stufe Submissions: Abruf fehlgeschlagen." + suffix)
        return []

    forms = recent.get("form") or []
    accessions = recent.get("accessionNumber") or []
    filing_dates = recent.get("filingDate") or []
    items = recent.get("items") or []
    primary_docs = recent.get("primaryDocument") or []

    candidates = []
    for i, form in enumerate(forms):
        if str(form).upper() != "8-K" or i >= len(accessions):
            continue
        item_text = _clean_text(items[i] if i < len(items) else "")
        # Item 2.02 is the standard U.S. earnings-results 8-K item.  If SEC
        # metadata is available, exclude unrelated 8-Ks before network work.
        if item_text and "2.02" not in item_text:
            continue
        accession = _clean_text(accessions[i])
        if not accession:
            continue
        candidates.append({
            "accession": accession,
            "filing_date": filing_dates[i] if i < len(filing_dates) else None,
            "primary_document": _clean_text(primary_docs[i] if i < len(primary_docs) else ""),
        })
        if len(candidates) >= max(6, int(max_filings) * 3):
            break

    diag.append(f"SEC-Stufe Item 2.02: {len(candidates)} Earnings-8-K-Kandidat(en) gefunden.")
    if not candidates:
        return []

    def _extract_exhibit_rows(html, source_url, primary_document=None):
        if not html:
            return []
        try:
            soup = BeautifulSoup(html, "html.parser")
        except Exception:
            return []

        found = {}

        # First use table rows because EDGAR filing pages and most 8-K exhibit
        # indexes expose description/type/document together in one row.
        for tr in soup.find_all("tr"):
            row_text = _clean_text(tr.get_text(" ", strip=True))
            row_low = row_text.lower()
            if not any(k in row_low for k in [
                "99.1", "99.2", "99.3", "exhibit", "earnings", "news release",
                "financial results", "quarterly supplement", "financial supplement",
            ]):
                continue
            for a in tr.find_all("a", href=True):
                raw = a.get("href") or ""
                if not raw:
                    continue
                href_low = raw.lower().split("?")[0]
                if not href_low.endswith((".htm", ".html", ".txt")):
                    continue
                url = urljoin(source_url, raw)
                if primary_document and url.rstrip("/") == urljoin(source_url, primary_document).rstrip("/"):
                    continue
                score = _bank_sec_exhibit_score(row_text, url)
                if score <= 0:
                    continue
                current = found.get(url)
                if current is None or score > current.get("score", 0):
                    found[url] = {"url": url, "row_text": row_text, "score": score}

        # Some issuer 8-Ks use simple paragraphs/lists rather than a table.
        # Scan anchors as a second generic surface and score the surrounding
        # parent text, still without any issuer-specific filename rule.
        for a in soup.find_all("a", href=True):
            raw = a.get("href") or ""
            href_low = raw.lower().split("?")[0]
            if not href_low.endswith((".htm", ".html", ".txt")):
                continue
            parent = a.find_parent(["tr", "p", "div", "li", "td"]) or a
            context = _clean_text(parent.get_text(" ", strip=True))
            anchor_text = _clean_text(a.get_text(" ", strip=True))
            row_text = _clean_text(f"{context} {anchor_text}")
            if not any(k in row_text.lower() for k in [
                "99.1", "99.2", "99.3", "exhibit", "earnings", "news release",
                "financial results", "quarterly supplement", "financial supplement",
            ]):
                continue
            url = urljoin(source_url, raw)
            if primary_document and url.rstrip("/") == urljoin(source_url, primary_document).rstrip("/"):
                continue
            score = _bank_sec_exhibit_score(row_text, url)
            if score <= 0:
                continue
            current = found.get(url)
            if current is None or score > current.get("score", 0):
                found[url] = {"url": url, "row_text": row_text, "score": score}

        return sorted(found.values(), key=lambda x: x.get("score", 0), reverse=True)

    output = []
    seen_periods = set()
    earnings_checked = 0
    primary_docs_loaded = 0
    index_pages_loaded = 0
    exhibit_candidates_seen = 0
    exhibit_documents_loaded = 0

    for filing in candidates:
        if earnings_checked >= int(max_filings) or not _research_budget_ok(deadline, reserve=0.8):
            break

        accession = filing["accession"]
        acc_nodash = accession.replace("-", "")
        base_dir = f"https://www.sec.gov/Archives/edgar/data/{cik}/{acc_nodash}/"
        exhibit_rows = []

        # Primary recovery path: SEC submissions already tells us the 8-K
        # primary document filename.  The 8-K itself commonly links directly
        # to EX-99.1/99.2/99.3 in Item 9.01, so no filing-index dependency is
        # required when this surface is accessible.
        primary_doc = filing.get("primary_document")
        if primary_doc and _research_budget_ok(deadline, reserve=1.0):
            primary_url = urljoin(base_dir, primary_doc)
            primary_html, primary_final = _fetch_html(
                primary_url, timeout=3.0, sec=True, deadline=deadline
            )
            if primary_html:
                primary_docs_loaded += 1
                exhibit_rows = _extract_exhibit_rows(
                    primary_html, primary_final or primary_url, primary_document=primary_doc
                )

        # Secondary recovery path: normal EDGAR filing-detail page.  Support
        # both suffixes because EDGAR/mirrors expose both forms in practice.
        if not exhibit_rows and _research_budget_ok(deadline, reserve=0.9):
            index_urls = [
                f"{base_dir}{accession}-index.htm",
                f"{base_dir}{accession}-index.html",
            ]
            for candidate_index_url in index_urls:
                html, final_url = _fetch_html(
                    candidate_index_url, timeout=2.8, sec=True, deadline=deadline
                )
                if not html:
                    continue
                index_pages_loaded += 1
                exhibit_rows = _extract_exhibit_rows(
                    html, final_url or candidate_index_url, primary_document=primary_doc
                )
                if exhibit_rows:
                    break

        if not exhibit_rows:
            continue

        earnings_checked += 1
        exhibit_candidates_seen += len(exhibit_rows)
        best_for_filing = None
        for exhibit in exhibit_rows[:4]:
            if not _research_budget_ok(deadline, reserve=0.45):
                break
            text = _fetch_source_text(exhibit["url"], deadline=deadline, timeout=3.4)
            if not text:
                continue
            exhibit_documents_loaded += 1
            low = text.lower()
            signal_count = sum(
                1 for term in [
                    "earnings per", "tangible book value", "rotce",
                    "return on average tangible", "cet1", "common equity tier 1",
                ]
                if term in low
            )
            if signal_count < 2:
                continue
            period = (
                _bank_period_from_text(f"{exhibit.get('row_text')} {exhibit.get('url')}")
                or _bank_period_from_text(text[:12000])
                or _bank_period_from_filing_date(filing.get("filing_date"))
            )
            if not period:
                continue
            multi_count = len(_bank_extract_quarterly_eps_series(text, period, count=4))
            cet1_pair = _bank_extract_cet1_values(text, period)
            metric_count = sum(
                x is not None for x in [
                    _bank_extract_rotce(text, period),
                    (_bank_extract_tbv_values(text, period) or [None])[0],
                    cet1_pair[0],
                ]
            )
            quality_score = (
                safe_float(exhibit.get("score")) or 0.0
            ) + signal_count * 45.0 + multi_count * 75.0 + metric_count * 80.0
            row = {
                "period": period,
                "url": exhibit["url"],
                "filing_date": filing.get("filing_date"),
                "text": text,
                "preloaded_text": text,
                "document_type": "html",
                "score": quality_score,
                "title": exhibit.get("row_text") or f"SEC earnings exhibit {period}",
            }
            if best_for_filing is None or row["score"] > best_for_filing["score"]:
                best_for_filing = row
            if multi_count == 4 and metric_count == 3:
                break

        if best_for_filing is None:
            continue
        period = best_for_filing["period"]
        if period in seen_periods:
            continue
        seen_periods.add(period)
        output.append(best_for_filing)

        # A detailed current supplement with a 4-quarter EPS row is enough for
        # the TTM gate and latest bank metrics; older filings are only needed if
        # the current document lacks that row.
        if len(_bank_extract_quarterly_eps_series(best_for_filing["text"], period, count=4)) == 4:
            break
        if len(output) >= 4:
            break

    diag.append(
        "SEC-Stufe Discovery: "
        f"Primary-8-K geladen={primary_docs_loaded}, Filing-Index geladen={index_pages_loaded}, "
        f"Exhibit-Kandidaten={exhibit_candidates_seen}, Exhibit-Dokumente geladen={exhibit_documents_loaded}."
    )
    if output:
        diag.append(
            "SEC-Stufe Auswahl: "
            + ", ".join(f"{row.get('period')} → {urlparse(row.get('url') or '').path.rsplit('/', 1)[-1]}" for row in output)
        )
    else:
        diag.append("SEC-Stufe Auswahl: kein qualifiziertes Earnings-/Supplement-Exhibit verwertbar.")

    return sorted(output, key=lambda r: _bank_period_sort_key(r.get("period")), reverse=True)


def _discover_universal_bank_snapshot_v1_uncached(symbol, company_name=None):
    """Live SEC fallback: latest Item-2.02 supplement first; failures are not cached."""
    deadline = time.monotonic() + 13.0
    sec_diagnostics = []
    rows = _bank_discover_sec_earnings_exhibits(
        symbol, max_filings=6, deadline=deadline, diagnostics=sec_diagnostics
    )
    if not rows:
        return {
            "_diagnostic_only": True,
            "adapter_version": BANK_PRIMARY_SOURCE_ADAPTER_VERSION,
            "adapter_mode": "sec_item_202_primary_document_recovery",
            "adapter_diagnostic": " | ".join(sec_diagnostics) or (
                "SEC-Fallback: kein qualifiziertes Item-2.02-Earnings-Exhibit gefunden."
            ),
        }

    documents = []
    for row in rows:
        documents.append({
            "url": row.get("url"),
            "title": row.get("title") or f"SEC earnings exhibit {row.get('period')}",
            "period": row.get("period"),
            "score": 1000 + safe_float(row.get("score") or 0),
            "preloaded_text": row.get("preloaded_text") or row.get("text"),
            "document_type": row.get("document_type") or "html",
        })

    snapshot = _bank_ir_snapshot_from_documents(
        symbol,
        company_name,
        None,
        {"documents": documents, "entrypoints": []},
        deadline=deadline,
    )
    if snapshot is None:
        return {
            "_diagnostic_only": True,
            "adapter_version": BANK_PRIMARY_SOURCE_ADAPTER_VERSION,
            "adapter_mode": "sec_item_202_primary_document_recovery",
            "adapter_diagnostic": (
                " | ".join(sec_diagnostics) +
                f" | Parser-Gate: {len(rows)} Earnings-Exhibit(s) gefunden, aber kein vollständiger Snapshot. "
                + (
                    "Extraktion jüngstes Dokument: "
                    f"4Q-EPS={len(_bank_extract_quarterly_eps_series(rows[0].get('text') or '', rows[0].get('period'), count=4))}/4, "
                    f"ROTCE={'ja' if _bank_extract_rotce(rows[0].get('text') or '', rows[0].get('period')) is not None else 'nein'}, "
                    f"TBVPS={'ja' if (_bank_extract_tbv_values(rows[0].get('text') or '', rows[0].get('period')) or [None])[0] is not None else 'nein'}, "
                    f"CET1-Std={'ja' if _bank_extract_cet1_values(rows[0].get('text') or '', rows[0].get('period'))[0] is not None else 'nein'}, "
                    f"CET1-Adv={'ja' if _bank_extract_cet1_values(rows[0].get('text') or '', rows[0].get('period'))[1] is not None else 'nein'}, "
                    f"BookValue={'ja' if _bank_extract_book_value(rows[0].get('text') or '', rows[0].get('period')) is not None else 'nein'}."
                )
            ),
        }

    latest_row = max(rows, key=lambda r: _bank_period_sort_key(r.get("period")))
    published_raw = latest_row.get("filing_date")
    try:
        published_dt = datetime.strptime(published_raw, "%Y-%m-%d").date() if published_raw else None
    except Exception:
        published_dt = None
    if published_dt:
        snapshot["published_date"] = published_dt.strftime("%d.%m.%Y")
        snapshot["valid_until"] = (published_dt + timedelta(days=110)).strftime("%d.%m.%Y")
    snapshot["source_name"] = "SEC Item 2.02 Earnings Supplement · Universal Bank Adapter V8"
    snapshot["source_url"] = latest_row.get("url") or snapshot.get("source_url")
    snapshot["supplement_url"] = latest_row.get("url") or snapshot.get("supplement_url")
    snapshot["allowed_source_hosts"] = ["sec.gov"]
    snapshot["adapter_version"] = BANK_PRIMARY_SOURCE_ADAPTER_VERSION
    snapshot["adapter_mode"] = "sec_item_202_primary_document_recovery"
    snapshot["source_note"] = (
        "V2.21.12 hat den offiziellen SEC-Earnings-8-K-Pfad über Item 2.02 erkannt, zunächst "
        "Exhibit-Links direkt aus dem Primary-8-K gelesen und danach bei Bedarf den Filing-Index verwendet. "
        "Das höchstrangige Earnings-/Quarterly-Supplement-Exhibit wird als HTML geparst. Eine aktuelle "
        "Mehrquartalstabelle darf die vier aufeinanderfolgenden diluted-EPS-Quartale direkt "
        "abdecken; ältere Earnings-8-Ks werden nur benötigt, wenn diese Tabelle nicht ausreicht. "
        "ROTCE, TBVPS und CET1 bleiben Primärquellenpflicht; unvollständige Daten sperren weiter fail-closed."
    )
    return snapshot


