def get_verified_bank_snapshot(symbol, info=None):
    """Universal bank-family adapter: verified seed, issuer IR discovery, then SEC fallback."""
    seed = _get_verified_bank_seed_snapshot(symbol)
    if seed is not None:
        return seed
    company_name = None
    website = None
    if isinstance(info, dict):
        company_name = info.get("longName") or info.get("shortName")
        website = info.get("website")
    return _discover_universal_bank_snapshot_v2(
        str(symbol or "").upper(),
        company_name=company_name,
        website=website,
    )

def _bank_snapshot_is_fresh(snapshot):
    if not isinstance(snapshot, dict):
        return False
    try:
        valid_until = datetime.strptime(
            snapshot.get("valid_until"), "%d.%m.%Y"
        ).date()
        return datetime.now().date() <= valid_until
    except Exception:
        return False



# V2.21.20: issuer-neutral U.S. large-bank CET1 regulatory-buffer reference.
# The live Federal Reserve table is preferred.  The dated June-2026 table is
# embedded only as a network-failure fallback so a blocked external request does
# not silently revert a supported U.S. large bank to the old absolute-only CET1
# scale.  These are regulatory data, not issuer-specific valuation overrides.
_FED_LARGE_BANK_CET1_FALLBACK_2026 = {
    "Ally Financial Inc.": 7.1,
    "American Express Company": 7.0,
    "Bank of America Corporation": 10.0,
    "Barclays US LLC": 8.9,
    "BMO Financial Corp.": 8.8,
    "Capital One Financial Corporation": 9.0,
    "Citigroup Inc.": 11.6,
    "Citizens Financial Group, Inc.": 9.0,
    "DB USA Corporation": 16.0,
    "DWS USA Corporation": 9.8,
    "Fifth Third Bancorp": 7.7,
    "First Citizens Bancshares, Inc.": 7.0,
    "HSBC North America Holdings Inc.": 9.6,
    "Huntington Bancshares Incorporated": 7.0,
    "JPMorgan Chase & Co.": 11.5,
    "KeyCorp": 7.7,
    "M&T Bank Corporation": 7.2,
    "Morgan Stanley": 11.8,
    "Northern Trust Corporation": 7.0,
    "RBC US Group Holdings LLC": 9.1,
    "Regions Financial Corporation": 7.0,
    "Santander Holdings USA, Inc.": 7.9,
    "State Street Corporation": 8.0,
    "Synchrony Financial": 7.0,
    "TD Group US Holdings LLC": 7.3,
    "The Bank of New York Mellon Corporation": 8.5,
    "The Charles Schwab Corporation": 7.0,
    "The Goldman Sachs Group, Inc.": 11.4,
    "The PNC Financial Services Group, Inc.": 7.0,
    "Truist Financial Corporation": 7.0,
    "U.S. Bancorp": 7.1,
    "UBS Americas Holding LLC": 9.7,
    "Wells Fargo & Company": 8.5,
}

_FED_LARGE_BANK_CAPITAL_INDEX = "https://www.federalreserve.gov/supervisionreg/large-bank-capital-requirements.htm"
_FED_LARGE_BANK_CAPITAL_FALLBACK_PDF = "https://www.federalreserve.gov/publications/files/large-bank-capital-requirements-20260624.pdf"


def _normalize_regulatory_bank_name(value):
    value = unicodedata.normalize("NFKD", str(value or "")).encode("ascii", "ignore").decode("ascii")
    value = value.lower().replace("&", " and ")
    value = re.sub(r"[^a-z0-9]+", " ", value)
    stop = {
        "the", "inc", "incorporated", "corp", "corporation", "company", "co",
        "holdings", "holding", "group", "financial", "bancshares", "llc", "plc",
    }
    tokens = [t for t in value.split() if t and t not in stop]
    return " ".join(tokens)


def _match_fed_large_bank_official_name(company_name):
    target = _normalize_regulatory_bank_name(company_name)
    if not target:
        return None
    target_tokens = set(target.split())
    best = None
    best_score = 0.0
    for official_name in _FED_LARGE_BANK_CET1_FALLBACK_2026:
        norm = _normalize_regulatory_bank_name(official_name)
        if norm == target:
            return official_name
        tokens = set(norm.split())
        if not tokens or not target_tokens:
            continue
        overlap = len(tokens & target_tokens) / max(len(tokens | target_tokens), 1)
        containment = 1.0 if (norm in target or target in norm) else 0.0
        score = max(overlap, containment)
        if score > best_score:
            best_score = score
            best = official_name
    return best if best_score >= 0.60 else None


@st.cache_data(ttl=21600, show_spinner=False)
def _fetch_live_fed_large_bank_capital_text():
    """Return current Fed large-bank capital table text and source PDF URL."""
    pdf_url = None
    try:
        r = requests.get(
            _FED_LARGE_BANK_CAPITAL_INDEX,
            headers=_request_headers(sec=False),
            timeout=(2.0, 4.5),
            allow_redirects=True,
        )
        r.raise_for_status()
        soup = BeautifulSoup(r.text, "html.parser")
        candidates = []
        for a in soup.find_all("a", href=True):
            href = urljoin(r.url or _FED_LARGE_BANK_CAPITAL_INDEX, a.get("href"))
            label = _clean_text(a.get_text(" ", strip=True)).lower()
            href_l = href.lower()
            if "large-bank-capital-requirements" in href_l and href_l.split("?", 1)[0].endswith(".pdf"):
                score = 2 + (2 if "2026" in label or "2026" in href_l else 0)
                candidates.append((score, href))
        if candidates:
            candidates.sort(key=lambda x: x[0], reverse=True)
            pdf_url = candidates[0][1]
    except Exception:
        pdf_url = None

    if not pdf_url:
        pdf_url = _FED_LARGE_BANK_CAPITAL_FALLBACK_PDF

    try:
        r = requests.get(
            pdf_url,
            headers=_request_headers(sec=False),
            timeout=(2.0, 5.5),
            allow_redirects=True,
        )
        r.raise_for_status()
        text = _bank_pdf_bytes_to_text(r.content, diagnostics=None)
        if text and "CET1" in text and "JPMorgan" in text:
            return {"text": text, "url": r.url or pdf_url, "mode": "live_fed"}
    except Exception:
        pass
    return {"text": "", "url": pdf_url, "mode": "unavailable"}


def _extract_fed_cet1_requirement_from_text(text, official_name):
    if not text or not official_name:
        return None
    cleaned = _clean_text(text)
    # Match the official row: Bank | 4.5 | SCB | GSIB/n.a. | total CET1 requirement.
    name_pattern = re.escape(official_name).replace(r"\ ", r"\s+")
    pattern = re.compile(
        name_pattern
        + r"\s*[†\^]*\s+4\.5\s+([0-9]+(?:\.[0-9]+)?)\s+"
          r"(?:n/?a|([0-9]+(?:\.[0-9]+)?))\s+([0-9]+(?:\.[0-9]+)?)",
        re.IGNORECASE,
    )
    m = pattern.search(cleaned)
    if not m:
        return None
    try:
        value = float(m.group(3))
        return value if 4.5 <= value <= 25.0 else None
    except Exception:
        return None


def get_bank_regulatory_cet1_reference(company_name):
    """Resolve issuer-specific Fed CET1 requirement when the bank is in the U.S. large-bank table."""
    official_name = _match_fed_large_bank_official_name(company_name)
    if not official_name:
        return {
            "available": False,
            "requirement_pct": None,
            "source_mode": "not_covered",
            "source_label": "Keine passende Fed-Large-Bank-Zeile erkannt",
            "source_url": _FED_LARGE_BANK_CAPITAL_INDEX,
            "official_name": None,
        }

    live = _fetch_live_fed_large_bank_capital_text()
    live_requirement = _extract_fed_cet1_requirement_from_text(live.get("text"), official_name)
    if live_requirement is not None:
        return {
            "available": True,
            "requirement_pct": live_requirement,
            "source_mode": "live_fed",
            "source_label": "Federal Reserve · aktuelle Large Bank Capital Requirements",
            "source_url": live.get("url") or _FED_LARGE_BANK_CAPITAL_INDEX,
            "official_name": official_name,
        }

    fallback_requirement = safe_float(_FED_LARGE_BANK_CET1_FALLBACK_2026.get(official_name))
    if fallback_requirement is not None:
        return {
            "available": True,
            "requirement_pct": fallback_requirement,
            "source_mode": "fed_2026_embedded_fallback",
            "source_label": "Federal Reserve · Large Bank Capital Requirements Juni 2026 (eingebetteter Fallback)",
            "source_url": _FED_LARGE_BANK_CAPITAL_FALLBACK_PDF,
            "official_name": official_name,
        }

    return {
        "available": False,
        "requirement_pct": None,
        "source_mode": "unavailable",
        "source_label": "Fed-CET1-Anforderung nicht verfügbar",
        "source_url": _FED_LARGE_BANK_CAPITAL_INDEX,
        "official_name": official_name,
    }


def calculate_bank_score_v1(snapshot, primary_source_complete, symbol=None, company_name=None):
    """
    Conservative 100-point bank score based only on bank-specific anchors.

    Components:
    - normalized ROTCE: 40 points
    - CET1 capital quality / regulatory surplus buffer: 25 points
    - tangible book value growth: 20 points
    - earnings quality / verified special-item bridge: 15 points

    Generic revenue growth, FCF and net-debt/FCF are deliberately excluded.
    """
    result = {
        "available": False,
        "score": None,
        "quality": None,
        "rotce_points": None,
        "cet1_points": None,
        "tbv_growth_points": None,
        "earnings_quality_points": None,
        "rotce_normalized_pct": None,
        "cet1_reference_pct": None,
        "cet1_standardized_pct": None,
        "cet1_advanced_pct": None,
        "cet1_requirement_pct": None,
        "cet1_buffer_pct": None,
        "cet1_score_basis": None,
        "cet1_requirement_source": None,
        "cet1_requirement_source_mode": None,
        "cet1_requirement_source_url": None,
        "tbv_growth_yoy_pct": None,
        "significant_items_share_of_reported_eps": None,
        "note": None,
    }

    if not primary_source_complete or not isinstance(snapshot, dict):
        result["note"] = (
            "Bank-Score gesperrt: aktueller verifizierter Primärquellen-Snapshot "
            "mit ROTCE, TBVPS und CET1 fehlt oder ist abgelaufen."
        )
        return result

    rotce = safe_float(snapshot.get("rotce_ex_significant_items_pct"))
    cet1_std = safe_float(snapshot.get("cet1_standardized_pct"))
    cet1_adv = safe_float(snapshot.get("cet1_advanced_pct"))
    tbv_growth = safe_float(snapshot.get("tangible_book_value_growth_yoy_pct"))

    cet1_candidates = [x for x in [cet1_std, cet1_adv] if x is not None]
    cet1_ref = min(cet1_candidates) if cet1_candidates else None

    if rotce is None or cet1_ref is None or tbv_growth is None:
        result["note"] = (
            "Bank-Score gesperrt: mindestens eine bankspezifische Kernkomponente "
            "(normalisierter ROTCE, CET1 oder TBV-Wachstum) fehlt."
        )
        return result

    if rotce >= 22.0:
        rotce_points = 40
    elif rotce >= 18.0:
        rotce_points = 36
    elif rotce >= 15.0:
        rotce_points = 32
    elif rotce >= 12.0:
        rotce_points = 24
    elif rotce >= 10.0:
        rotce_points = 16
    elif rotce >= 8.0:
        rotce_points = 8
    else:
        rotce_points = 0

    regulatory_ref = get_bank_regulatory_cet1_reference(
        company_name or snapshot.get("company") or symbol
    )
    cet1_requirement = safe_float(regulatory_ref.get("requirement_pct"))
    cet1_buffer = None
    cet1_score_basis = "absolute_fallback"
    cet1_for_score = cet1_ref

    # The Fed total CET1 capital requirement is a standardized-approach reference.
    # When available, compare the verified Standardized CET1 ratio with that
    # issuer-specific requirement. Advanced CET1 remains visible as a separate
    # prudential cross-check but is not mixed into the standardized buffer.
    if cet1_requirement is not None and cet1_std is not None:
        cet1_for_score = cet1_std
        cet1_buffer = cet1_std - cet1_requirement
        cet1_score_basis = "regulatory_buffer"
        if cet1_buffer >= 2.0:
            cet1_points = 25
        elif cet1_buffer >= 1.5:
            cet1_points = 20
        elif cet1_buffer >= 1.0:
            cet1_points = 15
        elif cet1_buffer >= 0.5:
            cet1_points = 10
        elif cet1_buffer >= 0.0:
            cet1_points = 5
        else:
            cet1_points = 0

        # Fail conservatively if the separately reported Advanced ratio is
        # exceptionally weak, without imposing the standardized SCB requirement
        # on a different regulatory denominator.
        if cet1_adv is not None:
            if cet1_adv < 7.0:
                cet1_points = min(cet1_points, 0)
            elif cet1_adv < 8.0:
                cet1_points = min(cet1_points, 5)
            elif cet1_adv < 9.0:
                cet1_points = min(cet1_points, 10)
    else:
        # Non-U.S. banks / unavailable official requirement: retain a transparent
        # conservative absolute fallback rather than inventing a regulatory buffer.
        if cet1_ref >= 13.5:
            cet1_points = 25
        elif cet1_ref >= 12.5:
            cet1_points = 20
        elif cet1_ref >= 11.5:
            cet1_points = 15
        elif cet1_ref >= 10.5:
            cet1_points = 8
        else:
            cet1_points = 0

    if tbv_growth >= 8.0:
        tbv_growth_points = 20
    elif tbv_growth >= 5.0:
        tbv_growth_points = 15
    elif tbv_growth >= 2.0:
        tbv_growth_points = 10
    elif tbv_growth >= 0.0:
        tbv_growth_points = 5
    else:
        tbv_growth_points = 0

    significant = safe_float(snapshot.get("significant_items_eps_effect"))
    reported_q_eps = safe_float(snapshot.get("quarter_eps_reported"))
    ex_q_eps = safe_float(snapshot.get("quarter_eps_ex_significant_items"))

    special_item_ratio = None
    if significant is None or abs(significant) <= 1e-12:
        earnings_quality_points = 15
    else:
        # A verified official bridge is mandatory when material special items exist.
        if (
            reported_q_eps is None
            or abs(reported_q_eps) <= 1e-12
            or ex_q_eps is None
            or rotce is None
        ):
            result["note"] = (
                "Bank-Score gesperrt: wesentliche Sonderposten sind vorhanden, "
                "aber die offizielle Bereinigungsbrücke ist nicht vollständig."
            )
            return result

        special_item_ratio = abs(significant / reported_q_eps)
        if special_item_ratio <= 0.25:
            earnings_quality_points = 12
        elif special_item_ratio <= 0.50:
            earnings_quality_points = 8
        else:
            earnings_quality_points = 4

    total = rotce_points + cet1_points + tbv_growth_points + earnings_quality_points
    if total >= 85:
        quality = "Sehr stark"
    elif total >= 70:
        quality = "Stark"
    elif total >= 55:
        quality = "Ausreichend"
    else:
        quality = "Schwach"

    result.update({
        "available": True,
        "score": total,
        "quality": quality,
        "rotce_points": rotce_points,
        "cet1_points": cet1_points,
        "tbv_growth_points": tbv_growth_points,
        "earnings_quality_points": earnings_quality_points,
        "rotce_normalized_pct": rotce,
        "cet1_reference_pct": cet1_for_score,
        "cet1_standardized_pct": cet1_std,
        "cet1_advanced_pct": cet1_adv,
        "cet1_requirement_pct": cet1_requirement,
        "cet1_buffer_pct": cet1_buffer,
        "cet1_score_basis": cet1_score_basis,
        "cet1_requirement_source": regulatory_ref.get("source_label"),
        "cet1_requirement_source_mode": regulatory_ref.get("source_mode"),
        "cet1_requirement_source_url": regulatory_ref.get("source_url"),
        "tbv_growth_yoy_pct": tbv_growth,
        "significant_items_share_of_reported_eps": special_item_ratio,
        "note": (
            "Der Bank-Score verwendet ausschließlich bankspezifische Qualitäts- und "
            "Kapitalanker. Bei U.S.-Großbanken wird CET1 primär als Puffer über der "
            "offiziellen bankspezifischen Fed-CET1-Anforderung bewertet; ohne auflösbare "
            "offizielle Anforderung bleibt die konservative absolute CET1-Fallback-Skala aktiv. "
            "Umsatzwachstum, Standard-FCF und Netto-Schulden/FCF fließen nicht ein."
        ),
    })
    return result


def calculate_bank_core_eps_v1(
    info,
    snapshot,
    eps_normalization,
    primary_source_complete,
):
    """Build a fully covered, source-verified Core-TTM EPS basis for banks.

    V2.20.39 requires four consecutive official quarterly observations.  Each
    quarter must carry reported EPS, Core/ex-significant-items EPS, the signed
    special-item effect and an official source URL.  The official reported EPS
    sum must reconcile to Yahoo TTM EPS within a small rounding tolerance.
    Forward EPS is never adjusted by assumption.
    """
    result = {
        "available": False,
        "trailing_eps_reported": None,
        "official_ttm_reported_eps": None,
        "ttm_special_items_eps_effect": None,
        "core_trailing_eps": None,
        "forward_eps": None,
        "raw_forward_eps": None,
        "forward_source": None,
        "trailing_weight": None,
        "forward_weight": None,
        "bank_normalized_core_eps": None,
        "coverage_periods": [],
        "coverage_complete": False,
        "coverage_reconciliation_diff": None,
        "coverage_reconciliation_pct": None,
        "provider_ttm_reconciliation_status": None,
        "coverage_count": 0,
        "integration_version": BANK_TTM_COVERAGE_INTEGRATION_VERSION,
        "confidence": None,
        "note": None,
    }

    if not primary_source_complete or not isinstance(snapshot, dict):
        result["note"] = (
            "Bank-Core-EPS gesperrt: aktueller verifizierter Primärquellen-Snapshot "
            "fehlt oder ist abgelaufen."
        )
        return result

    trailing = safe_float((info or {}).get("trailingEps"))
    raw_forward = safe_float((info or {}).get("forwardEps"))
    forward = safe_float((eps_normalization or {}).get("eps_forward_valuation_basis"))
    forward_source = (eps_normalization or {}).get("eps_forward_valuation_source")
    current_fy_eps = safe_float((eps_normalization or {}).get("eps_forward_current_fy"))
    guidance_override = bool((eps_normalization or {}).get("primary_guidance_override_active"))
    if trailing is None or trailing <= 0 or forward is None or forward <= 0:
        result["note"] = (
            "Bank-Core-EPS gesperrt: positives TTM-EPS und eine durch das Earnings-Horizon-Alignment "
            "freigegebene Current-FY-EPS-Basis müssen gleichzeitig vorliegen."
        )
        return result
    if not guidance_override and (current_fy_eps is None or current_fy_eps <= 0):
        result["note"] = (
            "Bank-Core-EPS gesperrt: Der rohe Provider-Forward-EPS hat keinen verifizierten "
            "0Y/current-FY-Horizont. Für den Bank-KGV-Anker ist ein expliziter Current-FY-"
            "Konsens oder eine frische offizielle Current-FY-Guidance erforderlich."
        )
        return result

    coverage = snapshot.get("ttm_eps_coverage")
    expected = snapshot.get("ttm_coverage_expected_periods")
    if not isinstance(coverage, list) or not isinstance(expected, list) or len(expected) != 4:
        result["note"] = (
            "Bank-Core-EPS gesperrt: die erwartete Vier-Quartals-TTM-Abdeckung ist nicht definiert."
        )
        return result

    rows_by_period = {}
    validated_rows = []
    for row in coverage:
        if not isinstance(row, dict):
            continue
        period = str(row.get("period") or "").strip()
        if not period or period in rows_by_period:
            result["note"] = "Bank-Core-EPS gesperrt: TTM-Quartale fehlen oder sind doppelt."
            return result
        reported = safe_float(row.get("reported_eps"))
        core = safe_float(row.get("core_eps"))
        effect = safe_float(row.get("special_items_eps_effect"))
        source_url = str(row.get("source_url") or "")
        status = str(row.get("special_item_status") or "").strip()
        if reported is None or core is None or effect is None or not source_url or not status:
            result["note"] = (
                f"Bank-Core-EPS gesperrt: Primärquellen-Abdeckung für {period or 'ein Quartal'} ist unvollständig."
            )
            return result
        if not _bank_source_url_is_allowed(snapshot, source_url):
            result["note"] = (
                f"Bank-Core-EPS gesperrt: Quelle für {period} liegt weder auf SEC.gov noch auf einem "
                "für diesen Emittenten freigegebenen offiziellen Primärquellen-Host."
            )
            return result
        bridge_diff = reported - core
        bridge_tol = max(0.02, abs(effect) * 0.05)
        if abs(bridge_diff - effect) > bridge_tol:
            result["note"] = (
                f"Bank-Core-EPS gesperrt: Reported-/Core-EPS-Brücke für {period} stimmt nicht "
                "mit dem ausgewiesenen Sondereffekt überein."
            )
            return result
        normalized_row = dict(row)
        normalized_row.update({
            "reported_eps": reported,
            "core_eps": core,
            "special_items_eps_effect": effect,
        })
        rows_by_period[period] = normalized_row

    if set(rows_by_period) != set(expected) or len(rows_by_period) != 4:
        missing = [p for p in expected if p not in rows_by_period]
        result["note"] = (
            "Bank-Core-EPS gesperrt: Vier-Quartals-TTM-Abdeckung unvollständig"
            + (f"; fehlend: {', '.join(missing)}." if missing else ".")
        )
        return result

    validated_rows = [rows_by_period[p] for p in expected]
    official_reported_ttm = sum(r["reported_eps"] for r in validated_rows)
    official_core_ttm = sum(r["core_eps"] for r in validated_rows)
    total_effect = sum(r["special_items_eps_effect"] for r in validated_rows)

    # The four consecutive official diluted-EPS quarters are the primary TTM
    # authority once their periods and source URLs are individually verified.
    # Provider/Yahoo trailing EPS is only a plausibility cross-check because a
    # data provider may aggregate TTM diluted EPS on a different weighted-share
    # basis than the simple sum of four separately reported quarterly EPS values.
    # Fail closed only for a material mismatch that is BOTH > $0.10/share and
    # > 5% of the official four-quarter sum; this still catches likely period/
    # unit mismatches without rejecting a fully source-verified official bridge.
    reconciliation_diff = trailing - official_reported_ttm
    reconciliation_pct = abs(reconciliation_diff) / max(abs(official_reported_ttm), 1e-9)
    reconciliation_conflict = abs(reconciliation_diff) > 0.10 and reconciliation_pct > 0.05
    if reconciliation_conflict:
        result.update({
            "official_ttm_reported_eps": official_reported_ttm,
            "coverage_periods": validated_rows,
            "coverage_reconciliation_diff": reconciliation_diff,
            "coverage_reconciliation_pct": reconciliation_pct,
            "provider_ttm_reconciliation_status": "conflict",
        })
        result["note"] = (
            "Bank-Core-EPS gesperrt: Die vier offiziellen Quartals-EPS sind vollständig "
            "abgedeckt, aber der Provider-TTM-Plausibilitätscheck zeigt eine materielle "
            f"Abweichung von {reconciliation_diff:+.2f} je Aktie bzw. {reconciliation_pct * 100:.1f} %. "
            "Damit bleibt ein möglicher Perioden-/Einheitenkonflikt fail-closed."
        )
        return result

    trailing_weight = safe_float((eps_normalization or {}).get("eps_used_trailing_weight"))
    forward_weight = safe_float((eps_normalization or {}).get("eps_used_forward_weight"))
    if trailing_weight is None or forward_weight is None:
        result["note"] = (
            "Bank-Core-EPS gesperrt: die konservativen TTM-/Current-FY-Gewichte der "
            "EPS-Normalisierung sind nicht eindeutig verfügbar."
        )
        return result

    weight_sum = trailing_weight + forward_weight
    if abs(weight_sum - 1.0) > 1e-6 or trailing_weight < 0 or forward_weight < 0:
        result["note"] = "Bank-Core-EPS gesperrt: TTM-/Current-FY-Gewichte sind nicht konsistent."
        return result

    if official_core_ttm <= 0:
        result["note"] = "Bank-Core-EPS gesperrt: das vollständig bereinigte Core-TTM-EPS ist nicht positiv."
        return result

    bank_normalized = trailing_weight * official_core_ttm + forward_weight * forward
    if bank_normalized <= 0:
        result["note"] = "Bank-Core-EPS gesperrt: die bereinigte Gewinnbasis ist nicht positiv."
        return result

    result.update({
        "available": True,
        "trailing_eps_reported": trailing,
        "official_ttm_reported_eps": official_reported_ttm,
        "ttm_special_items_eps_effect": total_effect,
        "core_trailing_eps": official_core_ttm,
        "forward_eps": forward,
        "raw_forward_eps": raw_forward,
        "forward_source": forward_source,
        "trailing_weight": trailing_weight,
        "forward_weight": forward_weight,
        "bank_normalized_core_eps": bank_normalized,
        "coverage_periods": validated_rows,
        "coverage_complete": True,
        "coverage_reconciliation_diff": reconciliation_diff,
        "coverage_reconciliation_pct": reconciliation_pct,
        "provider_ttm_reconciliation_status": "plausible",
        "coverage_count": len(validated_rows),
        "integration_version": BANK_TTM_COVERAGE_INTEGRATION_VERSION,
        "confidence": "Hoch",
        "note": (
            f"TTM-Coverage Gate bestanden: {', '.join(expected)} sind einzeln aus offiziellen "
            f"Bankquellen abgedeckt. Offizielle Reported-EPS-Summe {official_reported_ttm:.2f}, "
            f"vollständig bereinigtes Core-TTM-EPS {official_core_ttm:.2f}, saldierter "
            f"Sondereffekt {total_effect:+.2f}. Provider-TTM-Plausibilitätsabweichung "
            f"{reconciliation_diff:+.2f} ({reconciliation_pct * 100:.1f} %); die offizielle 4Q-Reihe bleibt Primäranker. "
            f"Danach werden {trailing_weight * 100:.0f} % Core-TTM / "
            f"{forward_weight * 100:.0f} % Current-FY-EPS verwendet. "
            f"Horizon-Quelle: {forward_source or 'Earnings Horizon Alignment'}. "
            "Der rohe Provider-Forward-EPS bleibt ausschließlich Horizont-/Plausibilitätskontext."
        ),
    })
    return result


def format_bank_core_eps_note_for_display(bank_core_eps, source_currency):
    """Render the released Bank Core-EPS coverage note in the selected display currency.

    The underlying bank_core_eps dictionary remains in the bank's financial/source
    currency for all calculations.  This helper is presentation-only and mirrors
    the structured values already shown in the adjacent metrics.
    """
    data = bank_core_eps if isinstance(bank_core_eps, dict) else {}
    if not data.get("available"):
        return text_or_dash(data.get("note"))

    periods = [
        str(row.get("period"))
        for row in (data.get("coverage_periods") or [])
        if row.get("period")
    ]
    official_reported = data.get("official_ttm_reported_eps")
    official_core = data.get("core_trailing_eps")
    total_effect = data.get("ttm_special_items_eps_effect")
    reconciliation_diff = data.get("coverage_reconciliation_diff")
    reconciliation_pct = safe_float(data.get("coverage_reconciliation_pct"))
    trailing_weight = safe_float(data.get("trailing_weight"))
    forward_weight = safe_float(data.get("forward_weight"))
    forward_source = data.get("forward_source") or "Earnings Horizon Alignment"

    period_text = ", ".join(periods) if periods else "vier offizielle Quartale"
    reported_text = format_currency_value(official_reported, source_currency, 2)
    core_text = format_currency_value(official_core, source_currency, 2)
    effect_text = format_currency_value(total_effect, source_currency, 2, signed=True)
    reconciliation_text = format_currency_value(reconciliation_diff, source_currency, 2, signed=True)
    reconciliation_pct_text = (
        f"{reconciliation_pct * 100:.1f} %" if reconciliation_pct is not None else "–"
    )
    trailing_pct = f"{trailing_weight * 100:.0f}" if trailing_weight is not None else "–"
    forward_pct = f"{forward_weight * 100:.0f}" if forward_weight is not None else "–"

    return (
        f"TTM-Coverage Gate bestanden: {period_text} sind einzeln aus offiziellen "
        f"Bankquellen abgedeckt. Offizielle Reported-EPS-Summe {reported_text}, "
        f"vollständig bereinigtes Core-TTM-EPS {core_text}, saldierter Sondereffekt {effect_text}. "
        f"Provider-TTM-Plausibilitätsabweichung {reconciliation_text} ({reconciliation_pct_text}); "
        "die offizielle 4Q-Reihe bleibt Primäranker. "
        f"Danach werden {trailing_pct} % Core-TTM / {forward_pct} % Current-FY-EPS verwendet. "
        f"Horizon-Quelle: {forward_source}. "
        "Der rohe Provider-Forward-EPS bleibt ausschließlich Horizont-/Plausibilitätskontext."
    )


def calculate_bank_valuation_v1(
    bank_score,
    snapshot,
    bank_core_eps,
    pb_consistency_status,
    forward_pe_status,
    source_consistency_note,
):
    """Dual-anchor bank valuation: 60% P/TBV and 40% bank-normalized Core P/E."""
    result = {
        "available": False,
        "bank_score": None,
        "ptbv_corridor_lower": 0.8,
        "ptbv_corridor_upper": 3.2,
        "pe_corridor_lower": 8.0,
        "pe_corridor_upper": 15.0,
        "target_ptbv": None,
        "justified_ptbv": None,
        "score_quality_ptbv_cap": None,
        "ptbv_rotce_pct": None,
        "ptbv_long_term_growth_pct": 3.0,
        "ptbv_cost_of_equity_pct": 10.0,
        "target_pe": None,
        "tbv_per_share": None,
        "normalized_eps": None,
        "fair_value_tbv_financial": None,
        "fair_value_earnings_financial": None,
        "fair_value_financial": None,
        "tbv_weight": 0.60,
        "earnings_weight": 0.40,
        "anchor_spread_pct": None,
        "confidence_cap": "Mittel bis Hoch",
        "note": None,
    }

    if not isinstance(bank_score, dict) or not bank_score.get("available"):
        result["note"] = "Bankbewertung gesperrt: kein vollständiger Bank-Score verfügbar."
        return result

    if not isinstance(snapshot, dict):
        result["note"] = "Bankbewertung gesperrt: Primärquellen-Snapshot fehlt."
        return result

    if pb_consistency_status == "conflict" or forward_pe_status == "conflict":
        result["note"] = (
            "Bankbewertung gesperrt: eine Kurs-/Buchwert- oder KGV-"
            "Plausibilitätsprüfung zeigt einen Einheiten-/Quellenkonflikt."
        )
        return result

    if str(source_consistency_note or "").startswith("⚠️"):
        result["note"] = (
            "Bankbewertung gesperrt: offizieller Buchwert und Yahoo-Buchwert "
            "weichen materiell voneinander ab."
        )
        return result

    normalized_eps = safe_float((bank_core_eps or {}).get("bank_normalized_core_eps"))
    tbv = safe_float(snapshot.get("tangible_book_value_per_share"))
    score = safe_float(bank_score.get("score"))

    coverage_rows = (bank_core_eps or {}).get("coverage_periods") or []
    coverage_integrated = bool(
        isinstance(bank_core_eps, dict)
        and bank_core_eps.get("integration_version") == BANK_TTM_COVERAGE_INTEGRATION_VERSION
        and bank_core_eps.get("coverage_complete")
        and safe_float(bank_core_eps.get("coverage_count")) == 4
        and len(coverage_rows) == 4
    )
    if not coverage_integrated:
        result["note"] = (
            "Bankbewertung gesperrt: der Core-KGV-Anker stammt nicht aus der aktuell "
            "integrierten Vier-Quartals-TTM-Abdeckung. Veraltete oder teilbereinigte "
            "Core-EPS-Pfade werden nicht akzeptiert."
        )
        return result

    if (
        normalized_eps is None
        or normalized_eps <= 0
        or not isinstance(bank_core_eps, dict)
        or not bank_core_eps.get("available")
        or tbv is None
        or tbv <= 0
        or score is None
    ):
        result["note"] = (
            "Bankbewertung gesperrt: bank-normalisierte Core-EPS-Basis und "
            "verifiziertes Tangible Book Value je Aktie müssen gleichzeitig vorliegen."
        )
        return result

    score_fraction = max(0.0, min(1.0, score / 100.0))

    # V2.21.19: P/TBV must be driven by the return earned on tangible common
    # equity, not by the aggregate bank score alone.  We therefore use a
    # normalized residual-income / justified-book relationship:
    #
    #   justified P/TBV = (normalized ROTCE - sustainable growth)
    #                     / (normalized cost of equity - sustainable growth)
    #
    # The assumptions are deliberately stable rather than market-timed: 3%
    # long-run nominal growth and a 10% equity-return hurdle.  The result is
    # clamped to the already released 0.8x-3.2x corridor.  The former
    # score-implied P/TBV survives only as a downside-only quality/capital cap,
    # so weak CET1/TBV-growth/earnings-quality evidence can still reduce the
    # book-value anchor but can never inflate a low-ROTCE bank.
    rotce_for_ptbv = safe_float(bank_score.get("rotce_normalized_pct"))
    if rotce_for_ptbv is None:
        rotce_for_ptbv = safe_float(snapshot.get("rotce_ex_significant_items_pct"))
    if rotce_for_ptbv is None:
        result["note"] = (
            "Bankbewertung gesperrt: Für den P/TBV-Anker fehlt ein verifizierter "
            "normalisierter ROTCE."
        )
        return result

    ptbv_long_term_growth = 0.03
    ptbv_cost_of_equity = 0.10
    denominator = ptbv_cost_of_equity - ptbv_long_term_growth
    if denominator <= 0:
        result["note"] = "Bankbewertung gesperrt: P/TBV-Normalannahmen sind mathematisch inkonsistent."
        return result

    justified_ptbv_raw = ((rotce_for_ptbv / 100.0) - ptbv_long_term_growth) / denominator
    justified_ptbv = max(0.8, min(3.2, justified_ptbv_raw))
    score_quality_ptbv_cap = 0.8 + (3.2 - 0.8) * score_fraction
    target_ptbv = min(justified_ptbv, score_quality_ptbv_cap)

    # The earnings multiple remains independently score-driven.
    target_pe = 8.0 + (15.0 - 8.0) * score_fraction

    fair_tbv = tbv * target_ptbv
    fair_earnings = normalized_eps * target_pe

    if fair_tbv <= 0 or fair_earnings <= 0:
        result["note"] = "Bankbewertung gesperrt: mindestens ein Bewertungsanker ist nicht positiv."
        return result

    anchor_spread = abs(fair_tbv / fair_earnings - 1.0)
    if anchor_spread > 0.25:
        result.update({
            "bank_score": score,
            "target_ptbv": target_ptbv,
            "justified_ptbv": justified_ptbv,
            "score_quality_ptbv_cap": score_quality_ptbv_cap,
            "ptbv_rotce_pct": rotce_for_ptbv,
            "ptbv_long_term_growth_pct": ptbv_long_term_growth * 100.0,
            "ptbv_cost_of_equity_pct": ptbv_cost_of_equity * 100.0,
            "target_pe": target_pe,
            "tbv_per_share": tbv,
            "normalized_eps": normalized_eps,
            "fair_value_tbv_financial": fair_tbv,
            "fair_value_earnings_financial": fair_earnings,
            "anchor_spread_pct": anchor_spread * 100.0,
            "note": (
                "Bankbewertung gesperrt: P/TBV- und KGV-Anker weichen um mehr als "
                "25 % voneinander ab. Die beiden Bewertungswege sind nicht ausreichend konsistent."
            ),
        })
        return result

    fair_blended = 0.60 * fair_tbv + 0.40 * fair_earnings
    result.update({
        "available": True,
        "bank_score": score,
        "target_ptbv": target_ptbv,
        "justified_ptbv": justified_ptbv,
        "score_quality_ptbv_cap": score_quality_ptbv_cap,
        "ptbv_rotce_pct": rotce_for_ptbv,
        "ptbv_long_term_growth_pct": ptbv_long_term_growth * 100.0,
        "ptbv_cost_of_equity_pct": ptbv_cost_of_equity * 100.0,
        "target_pe": target_pe,
        "tbv_per_share": tbv,
        "normalized_eps": normalized_eps,
        "fair_value_tbv_financial": fair_tbv,
        "fair_value_earnings_financial": fair_earnings,
        "fair_value_financial": fair_blended,
        "anchor_spread_pct": anchor_spread * 100.0,
        "note": (
            "Bank-Fair-Value V1 kombiniert 60 % Tangible-Book-Value-Anker "
            "(P/TBV) und 40 % bank-normalisierte Core-Gewinnbasis (KGV). P/TBV wird "
            "aus normalisiertem ROTCE über einen justified-book Ansatz abgeleitet und "
            "durch den scorebasierten Qualitäts-/Kapitaldeckel nur downside begrenzt; "
            "das KGV bleibt scorebasiert. Bei mehr als 25 % Abstand zwischen den beiden "
            "Fair-Value-Ankern bleibt die Bewertung gesperrt."
        ),
    })
    return result


def build_bank_special_model(
    company_type,
    info,
    price,
    currency_context,
    symbol=None,
    eps_normalization=None,
):
    """
    Bank-specific primary-source, score and dual-anchor valuation block.

    V2.20.39 keeps the verified ROTCE/TBV/CET1 gate and adds a dedicated
    bank score plus a conservative P/TBV + bank-normalized Core-P/E valuation.
    """
    type_name = str(company_type.get("type", "")).lower()

    if "bank" not in type_name:
        return {
            "applicable": False
        }

    quote_price = safe_float(price)
    price_financial = convert_quote_price_to_financial_share_unit(
        quote_price,
        currency_context
    )

    book_value = safe_float(info.get("bookValue"))
    roe = safe_float(info.get("returnOnEquity"))
    trailing_eps = safe_float(info.get("trailingEps"))
    forward_eps = safe_float(info.get("forwardEps"))
    yahoo_price_to_book = safe_float(info.get("priceToBook"))
    yahoo_forward_pe = safe_float(info.get("forwardPE"))
    if yahoo_forward_pe is None:
        yahoo_forward_pe = safe_float(info.get("forwardPe"))

    calculated_price_to_book = None
    if (
        price_financial is not None
        and price_financial > 0
        and book_value is not None
        and book_value > 0
    ):
        calculated_price_to_book = price_financial / book_value

    pb_display_value = None
    pb_consistency_status = "unverified"
    pb_consistency_note = None

    if calculated_price_to_book is None:
        pb_consistency_note = (
            "KBV konnte aus Kurs und Buchwert je Aktie nicht belastbar "
            "berechnet werden. Es wird kein Wert geschätzt."
        )
    elif yahoo_price_to_book is not None and yahoo_price_to_book > 0:
        pb_deviation = abs(calculated_price_to_book / yahoo_price_to_book - 1.0)
        if pb_deviation <= 0.20:
            pb_display_value = calculated_price_to_book
            pb_consistency_status = "plausible"
            pb_consistency_note = (
                "KBV-Plausibilitätscheck bestanden: Das aus Kurs und "
                "Buchwert je Aktie berechnete KBV liegt innerhalb von "
                "20 % des separat gemeldeten Yahoo-KBV."
            )
        else:
            pb_consistency_status = "conflict"
            pb_consistency_note = (
                "⚠️ KBV-Einheiten/Plausibilität widersprüchlich: Das aus "
                "Kurs und Buchwert je Aktie berechnete KBV weicht um mehr "
                "als 20 % vom separat gemeldeten Yahoo-KBV ab."
            )
    else:
        pb_consistency_note = (
            "KBV konnte zwar aus Kurs und Buchwert je Aktie berechnet werden, "
            "aber ein zweiter Yahoo-KBV-Anker fehlt."
        )

    calculated_forward_pe = None
    if (
        price_financial is not None
        and price_financial > 0
        and forward_eps is not None
        and forward_eps > 0
    ):
        calculated_forward_pe = price_financial / forward_eps

    forward_pe_display = None
    forward_pe_status = "unverified"
    forward_pe_note = None

    if calculated_forward_pe is None:
        forward_pe_note = (
            "Forward-KGV konnte aus Kurs und Forward-EPS nicht belastbar "
            "berechnet werden. Es wird kein Wert geschätzt."
        )
    elif yahoo_forward_pe is not None and yahoo_forward_pe > 0:
        pe_deviation = abs(calculated_forward_pe / yahoo_forward_pe - 1.0)
        if pe_deviation <= 0.20:
            forward_pe_display = calculated_forward_pe
            forward_pe_status = "plausible"
            forward_pe_note = (
                "Forward-KGV-Plausibilitätscheck bestanden: Kurs/Forward-EPS "
                "und Yahoo-forwardPE liegen innerhalb von 20 % beieinander."
            )
        else:
            forward_pe_status = "conflict"
            forward_pe_note = (
                "⚠️ Forward-KGV nicht belastbar: Das aus Kurs und Forward-EPS "
                "berechnete KGV weicht um mehr als 20 % vom Yahoo-forwardPE ab."
            )
    else:
        forward_pe_note = (
            "Forward-KGV konnte berechnet werden, aber ein separater Yahoo-"
            "forwardPE-Anker fehlt."
        )

    calculated_trailing_pe = None
    if (
        price_financial is not None
        and price_financial > 0
        and trailing_eps is not None
        and trailing_eps > 0
    ):
        calculated_trailing_pe = price_financial / trailing_eps

    snapshot_raw = get_verified_bank_snapshot(symbol, info=info)
    adapter_diagnostic = None
    if isinstance(snapshot_raw, dict) and snapshot_raw.get("_diagnostic_only"):
        adapter_diagnostic = snapshot_raw.get("adapter_diagnostic")
        snapshot = None
    elif snapshot_raw is None:
        adapter_diagnostic = (
            "Adapter-Stufe Wrapper: Discovery lieferte unerwartet weder Snapshot noch "
            "Diagnoseobjekt. V2.21.12 erzwingt deshalb bei der nächsten Ausführung einen "
            "Live-Retry statt eines gecachten Fehlers."
        )
        snapshot = None
    else:
        snapshot = snapshot_raw
    snapshot_fresh = _bank_snapshot_is_fresh(snapshot)

    primary_book_value = None
    tangible_book_value = None
    rote_reported = None
    rote_normalized = None
    cet1_standardized = None
    cet1_advanced = None
    price_to_tangible_book = None
    source_consistency_note = None
    primary_source_complete = False

    if snapshot is not None:
        primary_book_value = safe_float(snapshot.get("book_value_per_share"))
        tangible_book_value = safe_float(snapshot.get("tangible_book_value_per_share"))
        rote_reported = safe_float(snapshot.get("rotce_reported_pct"))
        rote_normalized = safe_float(snapshot.get("rotce_ex_significant_items_pct"))
        cet1_standardized = safe_float(snapshot.get("cet1_standardized_pct"))
        cet1_advanced = safe_float(snapshot.get("cet1_advanced_pct"))

        if (
            price_financial is not None
            and price_financial > 0
            and tangible_book_value is not None
            and tangible_book_value > 0
        ):
            price_to_tangible_book = price_financial / tangible_book_value

        if book_value is not None and primary_book_value is not None and primary_book_value > 0:
            source_deviation = abs(book_value / primary_book_value - 1.0)
            if source_deviation <= 0.05:
                source_consistency_note = (
                    "Primärquellen-Abgleich bestanden: Yahoo-Buchwert je Aktie "
                    f"und offizieller {snapshot.get('company') or 'Bank'}-Buchwert liegen innerhalb von 5 %."
                )
            else:
                source_consistency_note = (
                    "⚠️ Primärquellen-Abweichung: Yahoo-Buchwert je Aktie und "
                    "offizieller Buchwert weichen um mehr als 5 % voneinander ab."
                )

        primary_source_complete = all(
            value is not None
            for value in [
                tangible_book_value,
                rote_normalized,
                cet1_standardized,
            ]
        ) and snapshot_fresh

    if primary_source_complete:
        readiness = "Primärdaten vollständig"
    elif snapshot is not None and not snapshot_fresh:
        readiness = "Primärdaten veraltet"
    else:
        anchor_values = [roe, pb_display_value, forward_pe_display]
        available_anchors = sum(value is not None for value in anchor_values)
        readiness = "Teilweise" if available_anchors >= 2 else "Unvollständig"

    bank_score = calculate_bank_score_v1(
        snapshot,
        primary_source_complete,
        symbol=symbol,
        company_name=(info.get("longName") or info.get("shortName")) if isinstance(info, dict) else None,
    )
    bank_core_eps = calculate_bank_core_eps_v1(
        info,
        snapshot,
        eps_normalization,
        primary_source_complete,
    )
    bank_valuation = calculate_bank_valuation_v1(
        bank_score,
        snapshot,
        bank_core_eps,
        pb_consistency_status,
        forward_pe_status,
        source_consistency_note,
    )

    return {
        "applicable": True,
        "price_financial": price_financial,
        "book_value_per_share": book_value,
        "roe": roe,
        "calculated_price_to_book": calculated_price_to_book,
        "display_price_to_book": pb_display_value,
        "yahoo_price_to_book": yahoo_price_to_book,
        "pb_consistency_status": pb_consistency_status,
        "pb_consistency_note": pb_consistency_note,
        "calculated_forward_pe": calculated_forward_pe,
        "display_forward_pe": forward_pe_display,
        "yahoo_forward_pe": yahoo_forward_pe,
        "forward_pe_status": forward_pe_status,
        "forward_pe_note": forward_pe_note,
        "calculated_trailing_pe": calculated_trailing_pe,
        "snapshot": snapshot,
        "snapshot_fresh": snapshot_fresh,
        "adapter_diagnostic": adapter_diagnostic,
        "primary_source_complete": primary_source_complete,
        "primary_book_value_per_share": primary_book_value,
        "tangible_book_value_per_share": tangible_book_value,
        "price_to_tangible_book": price_to_tangible_book,
        "rote_reported_pct": rote_reported,
        "rote_normalized_pct": rote_normalized,
        "cet1_standardized_pct": cet1_standardized,
        "cet1_advanced_pct": cet1_advanced,
        "source_consistency_note": source_consistency_note,
        "readiness": readiness,
        "rote_available": rote_normalized is not None and snapshot_fresh,
        "tangible_book_value_available": tangible_book_value is not None and snapshot_fresh,
        "cet1_available": cet1_standardized is not None and snapshot_fresh,
        "bank_score": bank_score,
        "bank_core_eps": bank_core_eps,
        "bank_valuation": bank_valuation,
        "note": (
            "Universal Bank CET1 Row & Q4 Publication Metadata Guard V2.21.48 lädt verifizierte Primärquellen-"
            "Kennzahlen in das bestehende Bank-Familienmodell und verwendet ausschließlich bankspezifische Faktoren "
            "für den Bank-Score. Bei vollständiger Datenbasis wird ein "
            "Dual-Anchor-Fair-Value aus 60 % ROTCE-justified P/TBV und 40 % bank-normalisiertem Core-KGV "
            "berechnet. Der P/TBV-Anker wird durch den Bank-Score nur downside gedeckelt; der Core-KGV-Anker wird nur bei vollständiger Vier-Quartals-TTM-"
            "Abdeckung freigegeben. Standard-FCF und Netto-Schulden/FCF bleiben ausgeschlossen."
        )
    }


def build_bank_special_control(base_control, bank_model):
    """Attach a fail-closed Bank step 3B primary-source gate."""
    control = dict(base_control or {})
    control.setdefault("router_status", control.get("status"))
    control.setdefault("router_note", control.get("note"))

    if control.get("control_key") != "bank_book_capital":
        return control

    model = bank_model if isinstance(bank_model, dict) else {}
    snapshot = model.get("snapshot")

    if not model.get("primary_source_complete"):
        control.update({
            "implemented": False,
            "released": False,
            "confidence_cap": "Niedrig",
            "step3b_status": "Primärdaten unvollständig oder veraltet",
            "overall_status": "Nicht freigegeben",
            "snapshot": snapshot,
            "note": (
                "Die Bank-Primärdatenprüfung benötigt aktuellen ROTCE, TBVPS "
                "und CET1 aus einer offiziellen Quelle. Fehlende Werte werden "
                "nicht durch ROE, normalen Buchwert oder Yahoo-Proxies ersetzt."
            ),
        })
        return control

    bank_score = model.get("bank_score") or {}
    bank_core_eps = model.get("bank_core_eps") or {}
    bank_valuation = model.get("bank_valuation") or {}

    valuation_released = bool(
        bank_score.get("available")
        and bank_core_eps.get("available")
        and bank_core_eps.get("integration_version") == BANK_TTM_COVERAGE_INTEGRATION_VERSION
        and bank_core_eps.get("coverage_complete")
        and safe_float(bank_core_eps.get("coverage_count")) == 4
        and len(bank_core_eps.get("coverage_periods") or []) == 4
        and bank_valuation.get("available")
    )

    control.update({
        "implemented": True,
        "released": valuation_released,
        "confidence_cap": (bank_valuation.get("confidence_cap") or "Mittel"),
        "step3b_status": (
            "Bankbewertung freigegeben – Dual-Anchor V1"
            if valuation_released
            else "Primärdaten vollständig – Bankbewertung noch gesperrt"
        ),
        "overall_status": (
            "Freigegeben" if valuation_released else "Primärdaten vollständig"
        ),
        "snapshot": snapshot,
        "checks": {
            "rote_reported_pct": model.get("rote_reported_pct"),
            "rote_normalized_pct": model.get("rote_normalized_pct"),
            "tangible_book_value_per_share": model.get("tangible_book_value_per_share"),
            "price_to_tangible_book": model.get("price_to_tangible_book"),
            "cet1_standardized_pct": model.get("cet1_standardized_pct"),
            "cet1_advanced_pct": model.get("cet1_advanced_pct"),
            "bank_score": bank_score,
            "bank_core_eps": bank_core_eps,
            "bank_valuation": bank_valuation,
        },
        "note": (
            "Bank-Schritt 3B mit Universal Bank CET1 Row & Q4 Publication Metadata Guard V2.21.48 hat Primärdaten, Bank-Score, Vier-Quartals-TTM-Core-EPS-Abdeckung und beide "
            "Bewertungsanker validiert. Der Fair Value wird nur freigegeben, "
            "wenn P/TBV- und Core-KGV-Anker gleichzeitig belastbar und ausreichend "
            "konsistent sind."
            if valuation_released
            else (
                "Bank-Schritt 3B mit Universal Bank CET1 Row & Q4 Publication Metadata Guard V2.21.48 hat die Primärdatenbasis validiert, "
                "aber die Bewertungsfreigabe bleibt gesperrt: "
                + str(bank_valuation.get("note") or bank_score.get("note") or "Bankbewertung unvollständig.")
            )
        ),
    })
    return control


