def _nvidia_snapshot_is_fresh(snapshot):
    if not isinstance(snapshot, dict):
        return False
    try:
        valid_until = datetime.strptime(snapshot.get("valid_until"), "%d.%m.%Y").date()
        return datetime.now().date() <= valid_until
    except Exception:
        return False


def build_nvidia_primary_source_gate(snapshot):
    result = {
        "available": False,
        "integration_version": NVIDIA_PRIMARY_SOURCE_INTEGRATION_VERSION,
        "note": None,
    }
    if not isinstance(snapshot, dict):
        result["note"] = "NVIDIA-Primärquellen-Gate nicht verfügbar: kein verifizierter aktueller Q2-FY2027-Snapshot."
        return result

    required_positive = [
        "q2_revenue_total", "q2_data_center_revenue_total", "q2_gaap_gross_margin_pct",
        "q2_gaap_eps", "q2_non_gaap_eps", "q2_free_cashflow_total",
        "cash_and_cash_equivalents_total", "marketable_debt_securities_total",
        "inventory_total", "inventory_fy_end_total", "q3_revenue_midpoint_total",
        "q3_gaap_gross_margin_mid_pct", "q2_largest_direct_customer_revenue_share_pct",
        "q3_non_gaap_opex_total", "fy27_non_gaap_tax_rate_mid_pct",
        "q2_diluted_weighted_avg_shares", "q2_days_sales_outstanding",
    ]
    vals = {k: safe_float(snapshot.get(k)) for k in required_positive}
    if any(v is None or v <= 0 for v in vals.values()):
        result["note"] = (
            "NVIDIA-Primärquellen-Gate gesperrt: mindestens eine Pflichtkomponente aus Umsatz/Data Center, "
            "Gross Margin, EPS-Qualität, FCF, Liquidität, Inventory, Q3-Guidance oder Kundenkonzentration fehlt."
        )
        return result

    q2_rev = vals["q2_revenue_total"]
    dc_rev = vals["q2_data_center_revenue_total"]
    q2_fcf = vals["q2_free_cashflow_total"]
    inv = vals["inventory_total"]
    inv_prev = vals["inventory_fy_end_total"]
    q3_rev = vals["q3_revenue_midpoint_total"]
    gaap_eps = vals["q2_gaap_eps"]
    non_gaap_eps = vals["q2_non_gaap_eps"]
    cash_debt_sec = safe_float(snapshot.get("cash_and_cash_equivalents_total")) + safe_float(snapshot.get("marketable_debt_securities_total"))
    gross_debt = safe_float(snapshot.get("short_term_debt_total")) + safe_float(snapshot.get("long_term_debt_total"))
    h1_adv = safe_float(snapshot.get("h1_customer_advances_additions_total"))
    h1_adv_prior = safe_float(snapshot.get("h1_customer_advances_prior_total"))
    supply_commitments = safe_float(snapshot.get("supply_capacity_commitments_total"))
    supply_commitments_prev = safe_float(snapshot.get("supply_capacity_commitments_prev_quarter_total"))
    q1_q2_guide = safe_float(snapshot.get("q1_outlook_q2_revenue_midpoint_total"))

    result.update({
        "available": True,
        **{k: snapshot.get(k) for k in snapshot.keys() if k not in {"source_note"}},
        "data_center_share_q2_pct": dc_rev / q2_rev * 100.0,
        "q2_fcf_margin_pct": q2_fcf / q2_rev * 100.0,
        "inventory_growth_since_fy_end_pct": (inv / inv_prev - 1.0) * 100.0,
        "q3_revenue_midpoint_qoq_growth_pct": (q3_rev / q2_rev - 1.0) * 100.0,
        "gaap_vs_non_gaap_eps_premium_pct": (gaap_eps / non_gaap_eps - 1.0) * 100.0,
        "cash_plus_marketable_debt_securities_total": cash_debt_sec,
        "gross_debt_total": gross_debt,
        "net_liquid_financial_assets_ex_equities_total": cash_debt_sec - gross_debt,
        "h1_customer_advances_growth_pct": ((h1_adv / h1_adv_prior - 1.0) * 100.0) if h1_adv and h1_adv_prior else None,
        "supply_capacity_commitments_growth_pct": ((supply_commitments / supply_commitments_prev - 1.0) * 100.0) if supply_commitments and supply_commitments_prev else None,
        "q2_revenue_vs_q1_guidance_mid_pct": ((q2_rev / q1_q2_guide - 1.0) * 100.0) if q1_q2_guide else None,
        "inventory_to_q2_revenue_pct": inv / q2_rev * 100.0,
        "customer_advances_to_q2_revenue_pct": safe_float(snapshot.get("customer_advances_balance_total")) / q2_rev * 100.0,
        "supply_commitments_to_q2_revenue_x": supply_commitments / q2_rev if supply_commitments else None,
        "note": (
            "NVIDIA-Primärquellen-Gate bestanden: Q2-FY2027-Umsatz, Data-Center-/Kundenmix, Gross Margin, "
            "offizieller FCF, Bilanz-/Inventory-Daten, Kundenvorauszahlungen, GAAP/non-GAAP-EPS-Qualität, "
            "China-Kontext und Q3-Guidance sind validiert. V2.20.67 ergänzt DSO/Payment-Terms, Commitment-Qualität "
            "und die vollständige Q3-Operating-EPS-Brücke. Yahoo Forward-EPS bleibt ohne bestätigten Zeitraum/Basis "
            "reference-only. Dieses Primärquellen-Gate allein erzeugt keinen Fair Value; die finale V2.20.67-Bewertung wird nur nach vollständig bestandenen AI-Quality-, Demand-/Horizon- und FCF-/Peer-Safety-Gates freigegeben."
        ),
    })
    return result



def build_nvidia_demand_quality_gate(primary_gate, snapshot):
    """Separate demand-quality/working-capital gate. Signals are never treated as backlog."""
    result = {
        "available": False,
        "score": None,
        "status": "Nicht verfügbar",
        "customer_advances_points": 0,
        "supply_preparation_points": 0,
        "inventory_readiness_points": 0,
        "receivables_terms_points": 0,
        "visibility_evidence_points": 0,
        "visibility_points_cap": 4,
        "working_capital_points_cap": 3,
        "note": None,
    }
    gate = primary_gate if isinstance(primary_gate, dict) else {}
    snap = snapshot if isinstance(snapshot, dict) else {}
    if not gate.get("available"):
        result["note"] = "NVIDIA Demand-Quality-Gate gesperrt: Primary-Source-Gate nicht bestanden."
        return result

    advances_growth = safe_float(gate.get("h1_customer_advances_growth_pct"))
    supply_growth = safe_float(gate.get("supply_capacity_commitments_growth_pct"))
    inventory_growth = safe_float(gate.get("inventory_growth_since_fy_end_pct"))
    dso_days = safe_float(gate.get("q2_days_sales_outstanding"))
    customer_share = safe_float(gate.get("q2_largest_direct_customer_revenue_share_pct"))
    if any(v is None for v in [advances_growth, supply_growth, inventory_growth, dso_days, customer_share]):
        result["note"] = "NVIDIA Demand-Quality-Gate gesperrt: Advances, Commitments, Inventory, DSO oder Kundenkonzentration fehlen."
        return result

    # 20: customer advances are a real cash/contracting signal, but still not backlog.
    advances_points = 20 if advances_growth >= 75 else (15 if advances_growth >= 25 else 8)

    # 20: supply/capacity preparation. Cap at 15 because NVIDIA says agreements can in some cases be canceled/rescheduled/adjusted.
    if supply_growth >= 75:
        supply_points = 15
    elif supply_growth >= 25:
        supply_points = 12
    else:
        supply_points = 8

    # 20: inventory readiness vs. inventory-risk build.
    if inventory_growth <= 20:
        inventory_points = 20
    elif inventory_growth <= 35:
        inventory_points = 16
    elif inventory_growth <= 50:
        inventory_points = 12
    elif inventory_growth <= 70:
        inventory_points = 8
    else:
        inventory_points = 4

    # 20: receivables/payment-term quality. 60 DSO reflects extended terms to certain large investment-grade customers.
    if dso_days <= 45:
        receivables_points = 20
    elif dso_days <= 50:
        receivables_points = 16
    elif dso_days <= 55:
        receivables_points = 13
    elif dso_days <= 65:
        receivables_points = 10
    else:
        receivables_points = 6

    # 20: direct demand evidence. No numeric current backlog/order book => hard cap; customer concentration also matters.
    if snap.get("current_numeric_backlog_released") is True and customer_share < 10:
        evidence_points = 18
    elif snap.get("current_numeric_backlog_released") is True:
        evidence_points = 15
    else:
        evidence_points = 8 if customer_share >= 15 else 10

    score = int(advances_points + supply_points + inventory_points + receivables_points + evidence_points)
    if score >= 80:
        status = "Hoch bestätigt"
    elif score >= 65:
        status = "Begrenzt bestätigt"
    elif score >= 50:
        status = "Gemischt"
    else:
        status = "Schwach"

    visibility_cap = 7 if score >= 65 else (5 if score >= 50 else 4)
    working_cap_cap = 4 if (dso_days >= 60 or supply_growth > 100 or inventory_growth > 40) else (7 if score >= 65 else 5)

    result.update({
        "available": True,
        "score": score,
        "status": status,
        "customer_advances_points": advances_points,
        "supply_preparation_points": supply_points,
        "inventory_readiness_points": inventory_points,
        "receivables_terms_points": receivables_points,
        "visibility_evidence_points": evidence_points,
        "visibility_points_cap": visibility_cap,
        "working_capital_points_cap": working_cap_cap,
        "dso_days": dso_days,
        "inventory_growth_pct": inventory_growth,
        "supply_commitments_growth_pct": supply_growth,
        "customer_advances_growth_pct": advances_growth,
        "current_numeric_backlog_released": bool(snap.get("current_numeric_backlog_released")),
        "commitments_adjustable": bool(snap.get("supply_commitments_can_be_adjusted")),
        "note": (
            "Customer Advances und Supply-/Capacity-Commitments stützen die Nachfragevisibilität, sind aber kein Backlog. "
            "Die Supply-Vereinbarungen können laut NVIDIA in bestimmten Fällen storniert, verschoben oder angepasst werden. "
            "Inventory-Aufbau und 60 Tage DSO wegen verlängerter Zahlungsziele werden deshalb als Working-Capital-/Execution-Risiko separat berücksichtigt."
        ),
    })
    return result


def build_nvidia_ai_quality_score(primary_gate, snapshot, demand_quality_gate=None):
    """Primary-source-only 100-point NVIDIA/Fabless-AI quality score with V2.20.64 demand-quality caps."""
    result = {
        "available": False,
        "score": None,
        "quality_level": "Nicht verfügbar",
        "demand_execution_points": 0,
        "margin_resilience_points": 0,
        "fcf_liquidity_points": 0,
        "platform_transition_points": 0,
        "demand_visibility_points": 0,
        "concentration_geopolitics_points": 0,
        "inventory_commitment_quality_points": 0,
        "earnings_quality_points": 0,
        "note": None,
    }
    gate = primary_gate if isinstance(primary_gate, dict) else {}
    snap = snapshot if isinstance(snapshot, dict) else {}
    dq = demand_quality_gate if isinstance(demand_quality_gate, dict) else build_nvidia_demand_quality_gate(gate, snap)
    if not gate.get("available") or not dq.get("available"):
        result["note"] = "NVIDIA AI-Quality-Score gesperrt: Primary-Source- oder Demand-Quality-Gate nicht bestanden."
        return result

    q2_yoy = safe_float(gate.get("q2_revenue_yoy_growth_pct"))
    q2_qoq = safe_float(gate.get("q2_revenue_qoq_growth_pct"))
    q3_qoq = safe_float(gate.get("q3_revenue_midpoint_qoq_growth_pct"))
    q2_vs_guide = safe_float(gate.get("q2_revenue_vs_q1_guidance_mid_pct"))
    q2_gm = safe_float(gate.get("q2_non_gaap_gross_margin_pct") or gate.get("q2_gaap_gross_margin_pct"))
    q3_gm = safe_float(gate.get("q3_non_gaap_gross_margin_mid_pct") or gate.get("q3_gaap_gross_margin_mid_pct"))
    fcf_margin = safe_float(gate.get("q2_fcf_margin_pct"))
    net_liquid = safe_float(gate.get("net_liquid_financial_assets_ex_equities_total"))
    dc_share = safe_float(gate.get("data_center_share_q2_pct"))
    customer_share = safe_float(gate.get("q2_largest_direct_customer_revenue_share_pct"))
    gaap_premium = safe_float(gate.get("gaap_vs_non_gaap_eps_premium_pct"))
    eq_gains = safe_float(gate.get("q2_equity_securities_gains_total"))
    gaap_net_income = safe_float(gate.get("q2_gaap_net_income_total"))
    required = [q2_yoy, q2_qoq, q3_qoq, q2_vs_guide, q2_gm, q3_gm, fcf_margin, net_liquid,
                dc_share, customer_share, gaap_premium, eq_gains, gaap_net_income]
    if any(v is None for v in required) or gaap_net_income <= 0:
        result["note"] = "NVIDIA AI-Quality-Score gesperrt: mindestens eine verifizierte Score-Komponente fehlt."
        return result

    if q2_yoy >= 80 and q2_qoq >= 10 and q3_qoq >= 5 and q2_vs_guide >= 0:
        demand_points = 20
    elif q2_yoy >= 50 and q3_qoq >= 0:
        demand_points = 16
    elif q2_yoy >= 25:
        demand_points = 11
    else:
        demand_points = 6

    gm_drop = q2_gm - q3_gm
    if q2_gm >= 70 and q3_gm >= 70 and gm_drop <= 2.0:
        margin_points = 15
    elif q2_gm >= 65 and q3_gm >= 65:
        margin_points = 12
    elif q2_gm >= 55:
        margin_points = 8
    else:
        margin_points = 4

    if fcf_margin >= 20 and net_liquid > 0:
        fcf_points = 15
    elif fcf_margin >= 15 and net_liquid > 0:
        fcf_points = 12
    elif fcf_margin >= 10:
        fcf_points = 8
    else:
        fcf_points = 4

    blackwell = str(gate.get("blackwell_architecture_revenue_status") or "").lower()
    rubin = str(gate.get("vera_rubin_status") or "").lower()
    if "vast majority" in blackwell and "full production" in rubin:
        platform_points = 15
    elif blackwell and rubin:
        platform_points = 12
    else:
        platform_points = 6

    # Demand visibility is explicitly capped by the separate Demand-Quality Gate.
    visibility_points = min(10, int(dq.get("visibility_points_cap") or 4))

    concentration_points = 10
    if dc_share >= 90:
        concentration_points -= 2
    elif dc_share >= 80:
        concentration_points -= 1
    if customer_share >= 15:
        concentration_points -= 2
    elif customer_share >= 10:
        concentration_points -= 1
    if gate.get("q3_china_data_center_compute_assumed") is False:
        concentration_points -= 1
    concentration_points = max(0, concentration_points)

    # Inventory/commitments/receivables quality is capped by the separate demand-quality gate.
    inventory_points = min(10, int(dq.get("working_capital_points_cap") or 3))

    equity_gain_share = eq_gains / gaap_net_income * 100.0
    if gaap_premium <= 5 and equity_gain_share <= 5:
        earnings_points = 5
    elif gaap_premium <= 15 and equity_gain_share <= 20:
        earnings_points = 3
    else:
        earnings_points = 1

    score = int(demand_points + margin_points + fcf_points + platform_points + visibility_points + concentration_points + inventory_points + earnings_points)
    if score >= 90:
        level = "Sehr hoch"
    elif score >= 80:
        level = "Hoch"
    elif score >= 65:
        level = "Gut"
    elif score >= 50:
        level = "Mittel"
    else:
        level = "Niedrig"

    result.update({
        "available": True,
        "score": score,
        "quality_level": level,
        "demand_execution_points": demand_points,
        "margin_resilience_points": margin_points,
        "fcf_liquidity_points": fcf_points,
        "platform_transition_points": platform_points,
        "demand_visibility_points": visibility_points,
        "concentration_geopolitics_points": concentration_points,
        "inventory_commitment_quality_points": inventory_points,
        "earnings_quality_points": earnings_points,
        "q2_revenue_vs_q1_guidance_mid_pct": q2_vs_guide,
        "equity_gains_share_of_gaap_net_income_pct": equity_gain_share,
        "demand_quality_score": safe_float(dq.get("score")),
        "note": (
            "Der NVIDIA AI-Quality-Score verwendet ausschließlich verifizierte Primärdaten. V2.20.67 deckelt Demand Visibility "
            "und Inventory/Commitment/Working-Capital-Qualität über das separate Demand-Quality-Gate. Customer Advances und "
            "Supply-/Capacity-Commitments sind Nachfrage-/Vorbereitungssignale, ausdrücklich kein Backlog; 60 Tage DSO, Inventory-Aufbau, "
            "Kunden-/Data-Center-Konzentration, China-Annahme und Equity-Securities-Gewinne begrenzen den Score."
        ),
    })
    return result


def build_nvidia_forward_earnings_credibility_gate(primary_gate, snapshot, info, demand_quality_gate=None):
    """Build an official-horizon operating EPS proxy and keep provider Forward-EPS reference-only until horizon/basis align."""
    result = {
        "available": False,
        "status": "Nicht verfügbar",
        "credibility_score": None,
        "forward_horizon_alignment_status": "Nicht geprüft",
        "forward_comparable": False,
        "forward_weight": 0.0,
        "official_proxy_weight": 1.0,
        "h1_non_gaap_eps": None,
        "q3_non_gaap_eps_proxy": None,
        "fy27_operating_eps_proxy": None,
        "diagnostic_ai_earnings_reference": None,
        "note": None,
    }
    gate = primary_gate if isinstance(primary_gate, dict) else {}
    snap = snapshot if isinstance(snapshot, dict) else {}
    info = info if isinstance(info, dict) else {}
    dq = demand_quality_gate if isinstance(demand_quality_gate, dict) else build_nvidia_demand_quality_gate(gate, snap)
    if not gate.get("available") or not dq.get("available"):
        result["note"] = "NVIDIA Earnings-Horizon-Gate gesperrt: Primary-Source- oder Demand-Quality-Gate nicht bestanden."
        return result

    q1_ng_eps = safe_float(snap.get("q1_non_gaap_eps"))
    q2_ng_eps = safe_float(gate.get("q2_non_gaap_eps"))
    q3_rev = safe_float(gate.get("q3_revenue_midpoint_total"))
    q3_ng_gm = safe_float(gate.get("q3_non_gaap_gross_margin_mid_pct") or gate.get("q3_gaap_gross_margin_mid_pct"))
    q3_ng_opex = safe_float(gate.get("q3_non_gaap_opex_total"))
    tax_mid = safe_float(gate.get("fy27_non_gaap_tax_rate_mid_pct"))
    diluted_shares = safe_float(gate.get("q2_diluted_weighted_avg_shares"))
    forward_eps = safe_float(info.get("forwardEps"))
    q2_vs_guide = safe_float(gate.get("q2_revenue_vs_q1_guidance_mid_pct"))
    q3_qoq = safe_float(gate.get("q3_revenue_midpoint_qoq_growth_pct"))
    blackwell = str(gate.get("blackwell_architecture_revenue_status") or "").lower()
    rubin = str(gate.get("vera_rubin_status") or "").lower()

    required = [q1_ng_eps, q2_ng_eps, q3_rev, q3_ng_gm, q3_ng_opex, tax_mid, diluted_shares, q2_vs_guide, q3_qoq]
    if any(v is None for v in required) or min(q1_ng_eps, q2_ng_eps, q3_rev, q3_ng_gm, q3_ng_opex, diluted_shares) <= 0:
        result["note"] = "NVIDIA Earnings-Horizon-Gate gesperrt: offizielle H1-EPS-, Q3-Umsatz/Margen/OpEx-, Steuer- oder Aktienzahlbasis fehlt."
        return result

    h1_ng_eps = q1_ng_eps + q2_ng_eps
    q3_gross_profit = q3_rev * (q3_ng_gm / 100.0)
    q3_operating_income_proxy = max(0.0, q3_gross_profit - q3_ng_opex)
    q3_after_tax_operating_income_proxy = q3_operating_income_proxy * (1.0 - tax_mid / 100.0)
    q3_eps_proxy = q3_after_tax_operating_income_proxy / diluted_shares
    # Q4 remains flat to Q3 in the mechanical bridge because no Q4 revenue/EPS guidance is available.
    fy27_proxy = h1_ng_eps + 2.0 * q3_eps_proxy

    # Yahoo forwardEps does not expose a sufficiently reliable fiscal horizon/accounting-basis tag here.
    # Therefore a direct FY27-vs-forward comparison cannot affect the earnings basis.
    horizon_confirmed = False
    forward_gap_pct = ((forward_eps / fy27_proxy - 1.0) * 100.0) if forward_eps and fy27_proxy > 0 else None

    official_h1_points = 20
    execution_points = 20 if q2_vs_guide >= 2.0 else (15 if q2_vs_guide >= 0 else 8)
    q3_bridge_points = 25 if q3_qoq >= 5.0 and q3_ng_gm >= 70.0 and q3_ng_opex > 0 and 10.0 <= tax_mid <= 25.0 else 15
    platform_points = 10 if "vast majority" in blackwell and "full production" in rubin else 6
    dq_score = safe_float(dq.get("score")) or 0.0
    demand_quality_points = 5 if dq_score >= 65 else (3 if dq_score >= 50 else 0)
    horizon_points = 10 if horizon_confirmed else 0
    credibility_score = int(official_h1_points + execution_points + q3_bridge_points + platform_points + demand_quality_points + horizon_points)
    status = "Operative Basis bestätigt; Forward-Horizont offen" if credibility_score >= 75 else "Operative Basis begrenzt; Forward-Horizont offen"

    result.update({
        "available": True,
        "status": status,
        "credibility_score": credibility_score,
        "forward_eps": forward_eps,
        "forward_horizon_alignment_status": "Nicht bestätigt",
        "forward_comparable": False,
        "forward_reference_gap_pct": forward_gap_pct,
        "forward_weight": 0.0,
        "official_proxy_weight": 1.0,
        "h1_non_gaap_eps": h1_ng_eps,
        "q3_revenue_midpoint_total": q3_rev,
        "q3_non_gaap_gross_margin_mid_pct": q3_ng_gm,
        "q3_non_gaap_opex_total": q3_ng_opex,
        "fy27_non_gaap_tax_rate_mid_pct": tax_mid,
        "q2_diluted_weighted_avg_shares": diluted_shares,
        "q3_gross_profit_proxy": q3_gross_profit,
        "q3_operating_income_proxy": q3_operating_income_proxy,
        "q3_after_tax_operating_income_proxy": q3_after_tax_operating_income_proxy,
        "q3_non_gaap_eps_proxy": q3_eps_proxy,
        "fy27_operating_eps_proxy": fy27_proxy,
        "diagnostic_ai_earnings_reference": fy27_proxy,
        "official_h1_base_points": official_h1_points,
        "q2_execution_points": execution_points,
        "q3_guidance_bridge_points": q3_bridge_points,
        "platform_support_points": platform_points,
        "demand_quality_support_points": demand_quality_points,
        "horizon_alignment_points": horizon_points,
        "note": (
            "V2.20.67 berechnet den Q3-Operating-EPS-Proxy transparent aus offizieller Q3-Umsatzguidance × non-GAAP-Gross-Margin "
            "minus non-GAAP-OpEx, danach mit dem FY27-non-GAAP-Steuer-Midpoint und der Q2-verwässerten Aktienzahl. Der FY27-Proxy ist "
            "H1 non-GAAP Ist + Q3-Proxy + flache Q4-Annahme auf Q3-Niveau und keine NVIDIA-EPS-Guidance. Yahoo Forward-EPS bleibt "
            "reference-only, solange dessen Fiskalhorizont und Rechnungslegungsbasis nicht ausreichend bestätigt sind; deshalb 0 % Forward-/100 % Proxy-Gewichtung."
        ),
    })
    return result


def build_nvidia_valuation_anchor(ai_quality_score, earnings_horizon_gate, demand_quality_gate=None):
    """V2.20.67 NVIDIA/Fabless-AI quality-adjusted operating P/E anchor.

    Roles are intentionally non-overlapping:
    - Earnings-Horizon Alignment provides the sole FY27 operating EPS basis.
    - AI Quality Score alone selects target P/E and corridor.
    - Demand/margin/concentration/working-capital inputs are already inside the score and
      therefore do not apply additional multiple caps.
    - Yahoo Forward-EPS, Yahoo FCF/EV-EBITDA and peers remain outside the fundamental anchor before V2.20.67 safety gates.
    """
    result = {
        "available": False,
        "earnings_reference": None,
        "score": None,
        "score_target_pe": None,
        "target_pe": None,
        "corridor_low": None,
        "corridor_high": None,
        "fair_value_financial": None,
        "peer_overlay_allowed": True,
        "peer_overlay_applied": False,
        "fcf_overlay_allowed": True,
        "note": None,
    }
    score_data = ai_quality_score if isinstance(ai_quality_score, dict) else {}
    cred = earnings_horizon_gate if isinstance(earnings_horizon_gate, dict) else {}
    demand = demand_quality_gate if isinstance(demand_quality_gate, dict) else {}

    if not score_data.get("available") or not cred.get("available") or not demand.get("available"):
        result["note"] = "NVIDIA-Bewertungsanker gesperrt: AI-Quality-, Demand-Quality- oder Earnings-Horizon-Gate fehlt."
        return result

    score = safe_float(score_data.get("score"))
    demand_score = safe_float(demand.get("score"))
    credibility_score = safe_float(cred.get("credibility_score"))
    earnings_ref = safe_float(cred.get("fy27_operating_eps_proxy"))
    forward_weight = safe_float(cred.get("forward_weight"))
    proxy_weight = safe_float(cred.get("official_proxy_weight"))

    if any(v is None for v in [score, demand_score, credibility_score, earnings_ref, forward_weight, proxy_weight]) or earnings_ref <= 0:
        result["note"] = "NVIDIA-Bewertungsanker gesperrt: Score, Demand Quality, Credibility oder FY27-Operating-EPS-Proxy ist nicht belastbar verfügbar."
        return result

    # Fail closed unless the operative proxy is sufficiently supported. The Yahoo forward
    # consensus remains 0%-weighted until its fiscal horizon/accounting basis is verified.
    if credibility_score < 75.0:
        result.update({"score": score, "earnings_reference": earnings_ref, "credibility_score": credibility_score})
        result["note"] = f"NVIDIA-Bewertungsanker gesperrt: Earnings-Horizon/Operating-Credibility {credibility_score:.0f}/100 liegt unter dem Mindestwert 75/100."
        return result
    if demand_score < 50.0:
        result.update({"score": score, "earnings_reference": earnings_ref, "demand_quality_score": demand_score})
        result["note"] = f"NVIDIA-Bewertungsanker gesperrt: Demand-Quality {demand_score:.0f}/100 liegt unter dem Mindestwert 50/100."
        return result
    if abs(forward_weight) > 1e-12 or abs(proxy_weight - 1.0) > 1e-12:
        result.update({"score": score, "earnings_reference": earnings_ref})
        result["note"] = "NVIDIA-Bewertungsanker gesperrt: V2.20.67 erlaubt nur die 100%-FY27-Operating-Proxy-Basis; Yahoo Forward-EPS darf nicht eingemischt werden."
        return result

    # Score-only P/E table. No additional demand, margin, China, concentration or
    # working-capital cap is applied here, because those dimensions already affect
    # the AI Quality Score. This prevents double counting.
    if score >= 90.0:
        target_pe, low, high = 30.0, 27.0, 33.0
    elif score >= 85.0:
        target_pe, low, high = 29.0, 26.0, 32.0
    elif score >= 80.0:
        target_pe, low, high = 28.0, 25.0, 31.0
    elif score >= 70.0:
        target_pe, low, high = 25.0, 22.0, 28.0
    elif score >= 60.0:
        target_pe, low, high = 22.0, 19.0, 25.0
    else:
        target_pe, low, high = 18.0, 15.0, 21.0

    fair_value = earnings_ref * target_pe
    result.update({
        "available": True,
        "earnings_reference": earnings_ref,
        "score": score,
        "quality_level": score_data.get("quality_level"),
        "demand_quality_score": demand_score,
        "demand_quality_status": demand.get("status"),
        "credibility_score": credibility_score,
        "credibility_status": cred.get("status"),
        "forward_horizon_alignment_status": cred.get("forward_horizon_alignment_status"),
        "forward_weight": forward_weight,
        "official_proxy_weight": proxy_weight,
        "score_target_pe": target_pe,
        "target_pe": target_pe,
        "corridor_low": low,
        "corridor_high": high,
        "fair_value_financial": fair_value,
        "peer_overlay_allowed": True,
        "peer_overlay_applied": False,
        "fcf_overlay_allowed": True,
        "note": (
            "NVIDIA V2.20.67 trennt die Rollen strikt: Der mechanische FY27-Operating-EPS-Proxy aus dem Earnings-Horizon-Gate "
            "ist die einzige Earnings-Basis; der primärquellenbasierte AI-Quality-Score bestimmt allein Ziel-KGV und Korridor. "
            "Demand Quality, Gross Margin, Konzentration, China, Inventory/Commitments und Working Capital werden nicht nochmals "
            "als Multiple-Caps angewendet, weil sie bereits im Quality Score enthalten sind. Yahoo Forward-EPS, Yahoo-FCF/EV-EBITDA "
            "und Yahoo-FCF/EV-EBITDA bleiben außerhalb des Fair Values. Die separaten FCF-/Normalized-Peer-Safety-Gates sind in V2.20.67 aktiv und werden nach dem Fundamentalaner angewendet."
        ),
    })
    return result


def build_nvidia_fcf_conversion_safety_gate(nvidia_valuation, primary_gate):
    """Downside-only H1 FCF sanity gate; never creates upside.

    Uses only official H1 FCF, official H1 non-GAAP net income and Q2 diluted shares.
    Conversion below 60% blocks rather than inventing an adjustment. If conversion is
    sound but implied annualized H1 FCF yield is below 2.0%, fair value is capped at
    the equity value consistent with a 2.0% yield.
    """
    result = {
        "available": False, "passed": False, "blocked": False, "cap_applied": False,
        "h1_fcf_total": None, "h1_non_gaap_net_income_total": None,
        "h1_fcf_conversion_pct": None, "minimum_conversion_pct": 60.0,
        "annualized_h1_fcf_total": None, "diluted_shares": None,
        "implied_equity_value_total": None, "implied_annualized_fcf_yield_pct": None,
        "minimum_fcf_yield_pct": 2.0, "maximum_fair_value_from_fcf": None,
        "fair_value_before_fcf": None, "fair_value_after_fcf": None, "note": None,
    }
    v = nvidia_valuation if isinstance(nvidia_valuation, dict) else {}
    g = primary_gate if isinstance(primary_gate, dict) else {}
    if not v.get("available") or not g.get("available"):
        result["note"] = "NVIDIA-FCF-Safety-Gate gesperrt: Bewertungsanker oder Primärquellen-Gate nicht vollständig."
        return result
    fcf = safe_float(g.get("h1_free_cashflow_total"))
    ni = safe_float(g.get("h1_non_gaap_net_income_total"))
    shares = safe_float(g.get("q2_diluted_weighted_avg_shares"))
    fv = safe_float(v.get("fair_value_financial"))
    if any(x is None or x <= 0 for x in [fcf, ni, shares, fv]):
        result["note"] = "NVIDIA-FCF-Safety-Gate gesperrt: offizieller H1-FCF, H1 non-GAAP Net Income, Aktienzahl oder Fair Value fehlt."
        return result
    conv = fcf / ni * 100.0
    ann = fcf * 2.0
    implied_eq = fv * shares
    yld = ann / implied_eq * 100.0 if implied_eq > 0 else None
    max_fv = ann / (0.02 * shares)
    result.update({
        "available": True, "h1_fcf_total": fcf, "h1_non_gaap_net_income_total": ni,
        "h1_fcf_conversion_pct": conv, "annualized_h1_fcf_total": ann,
        "diluted_shares": shares, "implied_equity_value_total": implied_eq,
        "implied_annualized_fcf_yield_pct": yld, "maximum_fair_value_from_fcf": max_fv,
        "fair_value_before_fcf": fv,
    })
    if conv < 60.0:
        result.update({"blocked": True, "fair_value_after_fcf": None})
        result["note"] = (
            f"FCF-Safety blockiert: H1-FCF-Conversion {conv:.1f}% liegt unter 60%. "
            "Es wird kein pauschaler Bewertungsabschlag erfunden; die Bewertung bleibt fail-closed."
        )
        return result
    final_fv = min(fv, max_fv)
    cap = final_fv < fv - 1e-9
    result.update({"passed": True, "cap_applied": cap, "fair_value_after_fcf": final_fv})
    if cap:
        result["note"] = (
            f"FCF-Safety-Cap angewendet: implizite annualisierte H1-FCF-Rendite {yld:.2f}% lag unter 2.0%; "
            "der Fair Value wurde ausschließlich abwärts auf die 2.0%-Yield-Grenze begrenzt."
        )
    else:
        result["note"] = (
            f"FCF-Safety bestanden: H1-FCF-Conversion {conv:.1f}% und implizite annualisierte H1-FCF-Rendite {yld:.2f}% "
            "erfüllen die Mindestwerte 60% bzw. 2.0%. Kein FCF-bedingter Aufschlag oder Abschlag."
        )
    return result


def apply_nvidia_fcf_safety(nvidia_valuation, fcf_gate):
    v = dict(nvidia_valuation or {})
    g = fcf_gate if isinstance(fcf_gate, dict) else {}
    v.update({
        "fcf_safety_available": bool(g.get("available")),
        "fcf_safety_passed": bool(g.get("passed")),
        "fcf_safety_blocked": bool(g.get("blocked")),
        "fcf_cap_applied": bool(g.get("cap_applied")),
        "h1_fcf_total": safe_float(g.get("h1_fcf_total")),
        "h1_non_gaap_net_income_total": safe_float(g.get("h1_non_gaap_net_income_total")),
        "h1_fcf_conversion_pct": safe_float(g.get("h1_fcf_conversion_pct")),
        "annualized_h1_fcf_total": safe_float(g.get("annualized_h1_fcf_total")),
        "implied_annualized_fcf_yield_pct": safe_float(g.get("implied_annualized_fcf_yield_pct")),
        "minimum_fcf_yield_pct": safe_float(g.get("minimum_fcf_yield_pct")),
        "minimum_fcf_conversion_pct": safe_float(g.get("minimum_conversion_pct")),
        "fcf_fair_value_cap": safe_float(g.get("maximum_fair_value_from_fcf")),
    })
    if g.get("blocked"):
        v["available"] = False
        v["fair_value_financial"] = None
        v["note"] = g.get("note")
        return v
    after = safe_float(g.get("fair_value_after_fcf"))
    if g.get("available") and g.get("passed") and after is not None and after > 0:
        v["fair_value_financial"] = after
        earnings = safe_float(v.get("earnings_reference"))
        if earnings and earnings > 0:
            v["target_pe"] = after / earnings
    return v

def build_nvidia_special_model(company_type, info, currency_context, symbol=None):
    if not is_nvidia_ai_growth_company_type(company_type):
        return {"applicable": False}
    snapshot = get_verified_nvidia_snapshot(symbol)
    snapshot_fresh = _nvidia_snapshot_is_fresh(snapshot)
    gate = build_nvidia_primary_source_gate(snapshot)
    complete = bool(snapshot_fresh and gate.get("available"))
    demand_quality = build_nvidia_demand_quality_gate(gate, snapshot) if complete else {"available": False}
    ai_score = build_nvidia_ai_quality_score(gate, snapshot, demand_quality) if complete else {"available": False}
    earnings_gate = build_nvidia_forward_earnings_credibility_gate(gate, snapshot, info, demand_quality) if complete else {"available": False}
    score_and_earnings_complete = bool(complete and demand_quality.get("available") and ai_score.get("available") and earnings_gate.get("available"))
    nvidia_valuation = build_nvidia_valuation_anchor(ai_score, earnings_gate, demand_quality) if score_and_earnings_complete else {"available": False}
    valuation_ready = bool(nvidia_valuation.get("available"))
    return {
        "applicable": True,
        "snapshot": snapshot,
        "snapshot_fresh": snapshot_fresh,
        "primary_source_complete": complete,
        "primary_gate": gate,
        "demand_quality_gate": demand_quality,
        "ai_quality_score": ai_score,
        "forward_earnings_credibility": earnings_gate,
        "earnings_horizon_alignment": earnings_gate,
        "nvidia_valuation": nvidia_valuation,
        "score_and_earnings_gate_complete": score_and_earnings_complete,
        "fcf_safety_gate": {"available": False},
        "peer_safety_complete": False,
        "fcf_safety_complete": False,
        "valuation_anchor_complete": False,
        "integration_version": NVIDIA_PRIMARY_SOURCE_INTEGRATION_VERSION,
        "yahoo_trailing_eps_context": safe_float(info.get("trailingEps")),
        "yahoo_forward_eps_context": safe_float(info.get("forwardEps")),
        "yahoo_free_cashflow_context": safe_float(info.get("freeCashflow")),
        "yahoo_ev_to_ebitda_context": safe_float(info.get("enterpriseToEbitda")),
        "readiness": (
            "Safety Gates ausstehend" if complete and score_and_earnings_complete and valuation_ready
            else ("AI Score + Demand/Horizon Gates vollständig" if score_and_earnings_complete else ("Primärdaten vollständig" if complete else "Unvollständig"))
        ),
        "note": (
            "NVIDIA/Fabless-AI-Sondermodell V2.20.67 verwendet aktuelle offizielle Q1/Q2-FY2027-Daten, Q3-Guidance und den Q2-Earnings-Call. "
            "Demand Quality trennt Advances/Supply Commitments von echtem Backlog; das Earnings-Horizon-Gate liefert ausschließlich den mechanischen FY27-Operating-EPS-Proxy. "
            "Bei bestandenem Mindestgate bestimmt der AI-Quality-Score allein das quality-adjustierte Operating-KGV. Yahoo Forward-EPS bleibt reference-only; "
            "Yahoo-FCF/EV-EBITDA bleibt außerhalb des Fair Values. Normalized-Peer-Safety und H1-FCF-Safety sind in V2.20.67 aktiv und werden nach dem Fundamentalaner angewendet."
        ),
    }


def build_nvidia_special_control(base_control, nvidia_model):
    control = dict(base_control or {})
    control.setdefault("router_status", control.get("status"))
    control.setdefault("router_note", control.get("note"))
    if control.get("control_key") != "ai_growth_margin":
        return control
    model = nvidia_model if isinstance(nvidia_model, dict) else {}
    gate = model.get("primary_gate") or {}
    snapshot = model.get("snapshot")
    demand_quality = model.get("demand_quality_gate") or {}
    ai_score = model.get("ai_quality_score") or {}
    earnings_gate = model.get("forward_earnings_credibility") or {}
    valuation = model.get("nvidia_valuation") or {}
    fcf_safety = model.get("fcf_safety_gate") or {}
    common_checks = {
        "primary_gate": gate,
        "demand_quality_gate": demand_quality,
        "ai_quality_score": ai_score,
        "forward_earnings_credibility": earnings_gate,
        "earnings_horizon_alignment": earnings_gate,
        "nvidia_valuation": valuation,
        "fcf_safety_gate": fcf_safety,
        **gate,
    }
    if not model.get("primary_source_complete"):
        control.update({
            "implemented": False,
            "released": False,
            "confidence_cap": "Niedrig",
            "step3b_status": "NVIDIA-Primärdaten unvollständig oder veraltet",
            "overall_status": "Nicht freigegeben",
            "snapshot": snapshot,
            "checks": {"primary_gate": gate, **gate},
            "note": (
                "Die NVIDIA-Spezialkontrolle benötigt einen aktuellen offiziellen Q2/Folgesnapshot für AI-Nachfrage, "
                "Gross Margin, FCF, Liquidität/Inventory, Kundenkonzentration, China-Risiko und Guidance. Fehlende Pflichtdaten werden nicht aus Yahoo oder Schätzungen ersetzt."
            ),
        })
        return control
    if not model.get("score_and_earnings_gate_complete"):
        control.update({
            "implemented": False,
            "released": False,
            "confidence_cap": "Niedrig",
            "step3b_status": "NVIDIA AI-Score/Demand-/Horizon-Gate unvollständig",
            "overall_status": "Nicht freigegeben",
            "snapshot": snapshot,
            "checks": common_checks,
            "note": "NVIDIA-Primärdaten sind vorhanden, aber AI-Quality-Score, Demand-Quality- oder Earnings-Horizon-Gate ist unvollständig. Bewertung bleibt fail-closed.",
        })
        return control
    if not model.get("valuation_anchor_complete"):
        control.update({
            "implemented": True,
            "released": False,
            "confidence_cap": "Niedrig",
            "step3b_status": "NVIDIA Bewertungs-/Safety-Gates nicht vollständig freigegeben",
            "overall_status": "Bewertungsanker nicht freigegeben",
            "snapshot": snapshot,
            "checks": common_checks,
            "note": valuation.get("note") or "NVIDIA-Operating-P/E-Bewertungsanker nicht freigegeben. Bewertung bleibt fail-closed.",
        })
        return control

    control.update({
        "implemented": True,
        "released": True,
        "confidence_cap": "Mittel",
        "step3b_status": "NVIDIA Operating-KGV + FCF-/Normalized-Peer-Safety freigegeben",
        "overall_status": "Bewertung freigegeben",
        "snapshot": snapshot,
        "checks": common_checks,
        "note": (
            "V2.20.67 gibt den NVIDIA-/Fabless-AI-Bewertungsanker nur frei, wenn Primärdaten, Demand Quality, AI Quality, Earnings-Horizon-Alignment sowie FCF-/Peer-Safety vollständig sind, "
            "die Operating-Credibility mindestens 75/100 und Demand Quality mindestens 50/100 erreichen. Der mechanische FY27-Operating-EPS-Proxy ist die einzige Earnings-Basis; "
            "der AI-Quality-Score bestimmt allein Ziel-KGV und Korridor. Yahoo Forward-EPS bleibt reference-only. FCF-Safety ist downside-only; Peer-Overlay benötigt mindestens drei voll vergleichbare normalisierte Peers und duale ±5-%-Caps."
        ),
    })
    return control


