def build_payment_network_specialist_score(snapshot):
    snap = snapshot if isinstance(snapshot, dict) else {}
    result = {"available": False, "score": None, "quality_level": None, "components": {}, "note": None}
    sym = str(snap.get("symbol") or "").upper()
    if sym not in {"V", "MA"}:
        result["note"] = "Kein kalibrierter Payment-Network-Score für diesen Emittenten."
        return result

    required = [
        "period_net_revenue_growth_pct", "period_adjusted_eps", "period_adjusted_eps_growth_pct",
        "network_volume_growth_pct", "cross_border_growth_pct", "transaction_growth_pct",
        "adjusted_operating_margin_pct", "cash_conversion_pct", "capital_returns",
    ]
    if any(safe_float(snap.get(k)) is None for k in required):
        result["note"] = "Payment-Network-Score gesperrt: mindestens eine issuer-primary Qualitätskennzahl fehlt."
        return result

    components = dict(snap.get("score_components") or {})
    if not components or any(safe_float(v) is None for v in components.values()):
        result["note"] = "Payment-Network-Score gesperrt: issuer-spezifische Score-Komponenten fehlen."
        return result
    score = round(sum(float(v) for v in components.values()), 2)
    if score < 0 or score > 100:
        result["note"] = "Payment-Network-Score gesperrt: Score außerhalb 0–100."
        return result

    result.update({
        "available": True,
        "score": score,
        "quality_level": _specialist_quality_level(score),
        "components": components,
        "note": (
            "Der Payment-Network-Score bewertet Netzwerkvolumen/Transaktionen, Cross-Border-Monetarisierung, "
            "Net-Revenue-/Adjusted-EPS-Wachstum, non-GAAP Operating Margin, issuer-primary Cash Conversion "
            "und Kapitalrückführungsqualität. Generischer ROE-, Yahoo-FCF- und Net-Debt/FCF-Score bleibt außen vor."
        ),
    })
    return result


def build_payment_network_specialist_valuation(snapshot, specialist_score):
    snap = snapshot if isinstance(snapshot, dict) else {}
    score_data = specialist_score if isinstance(specialist_score, dict) else {}
    result = {
        "available": False,
        "valuation_method_name": None,
        "earnings_basis": None,
        "earnings_basis_name": None,
        "earnings_basis_confidence": None,
        "earnings_basis_note": None,
        "base_target_pe": None,
        "target_pe": None,
        "corridor_low": None,
        "corridor_high": None,
        "risk_pe_cap": None,
        "risk_overlay_applied": False,
        "risk_overlay_effect_pct": None,
        "fair_value_financial": None,
        "note": None,
    }
    sym = str(snap.get("symbol") or "").upper()
    if sym not in {"V", "MA"} or not score_data.get("available"):
        result["note"] = "Payment-Network-Spezialbewertung gesperrt: issuer-spezifischer Score nicht vollständig."
        return result

    earnings = safe_float(snap.get("valuation_eps_basis"))
    score = safe_float(score_data.get("score"))
    low = safe_float(snap.get("pe_corridor_low"))
    high = safe_float(snap.get("pe_corridor_high"))
    if earnings is None or earnings <= 0 or score is None or low is None or high is None or high <= low:
        result["note"] = "Payment-Network-Spezialbewertung gesperrt: Earnings-Basis, Score oder P/E-Korridor fehlt."
        return result

    base_target = low + (high - low) * (score / 100.0)
    risk_cap = safe_float(snap.get("risk_pe_cap"))
    target = min(base_target, risk_cap) if risk_cap is not None and risk_cap > 0 else base_target
    risk_applied = target < base_target - 1e-9
    risk_effect = ((target / base_target) - 1.0) * 100.0 if base_target > 0 else None
    fair = earnings * target
    result.update({
        "available": True,
        "valuation_method_name": snap.get("valuation_method_name") or "Payment Network Adjusted-Earnings P/E + Regulatory/Litigation Overlay",
        "earnings_basis": earnings,
        "earnings_basis_name": snap.get("earnings_basis_name"),
        "earnings_basis_confidence": snap.get("earnings_basis_confidence") or "Mittel",
        "earnings_basis_note": snap.get("earnings_basis_note"),
        "base_target_pe": base_target,
        "target_pe": target,
        "corridor_low": low,
        "corridor_high": high,
        "risk_pe_cap": risk_cap,
        "risk_overlay_applied": risk_applied,
        "risk_overlay_effect_pct": risk_effect,
        "risk_overlay_name": snap.get("risk_overlay_name"),
        "risk_overlay_level": snap.get("risk_overlay_level"),
        "risk_note": snap.get("risk_note"),
        "fair_value_financial": fair,
        "note": (
            f"Fair Value = issuer-primary {snap.get('earnings_basis_name') or 'Adjusted-Earnings-Basis'} × Payment-Network Quality-P/E; "
            "anschließend wirkt ausschließlich ein downside-only Regulatory/Litigation P/E-Cap. Analystenziele und generischer Yahoo-FCF sind kein Bewertungsanker."
        ),
    })
    return result


def build_payment_network_specialist_model(company_type, fundamental_info, symbol):
    applicable = is_payment_network_specialist_type(company_type, symbol)
    if not applicable:
        return {"applicable": False}
    sym = str(symbol or "").upper().strip()
    snapshot = get_verified_payment_network_snapshot(sym)
    if not snapshot:
        note = (
            f"Payment-Network-Familie erkannt, aber kein freigegebener issuer-spezifischer Primärquellen-Snapshot für {sym or 'diesen Emittenten'}. "
            "Generischer Standard-Score, Yahoo-FCF/Net-Debt-to-FCF und Standard-KGV bleiben gesperrt; Fair Value bleibt fail-closed."
        )
        return {
            "applicable": True, "symbol": sym, "issuer_supported": False, "primary_source_complete": False,
            "snapshot": None,
            "specialist_score": {"available": False, "note": note},
            "specialist_valuation": {"available": False, "note": note},
            "valuation_anchor_complete": False,
            "readiness": "Payment-Network-Issuer noch nicht kalibriert",
            "note": note,
        }

    fresh = False
    try:
        valid_until = datetime.strptime(str(snapshot.get("valid_until")), "%d.%m.%Y").date()
        published = datetime.strptime(str(snapshot.get("published_date")), "%d.%m.%Y").date()
        today = datetime.now().date()
        fresh = published <= today <= valid_until
    except Exception:
        fresh = False

    stale_note = f"{snapshot.get('company') or sym} Primärquellen-Snapshot ist veraltet oder zeitlich ungültig."
    score = build_payment_network_specialist_score(snapshot) if fresh else {"available": False, "note": stale_note}
    valuation = build_payment_network_specialist_valuation(snapshot, score) if fresh else {"available": False, "note": stale_note}
    complete = bool(fresh and score.get("available") and valuation.get("available"))
    return {
        "applicable": True,
        "symbol": sym,
        "issuer_supported": True,
        "primary_source_complete": bool(fresh),
        "snapshot_fresh": bool(fresh),
        "snapshot": snapshot,
        "specialist_score": score,
        "specialist_valuation": valuation,
        "valuation_anchor_complete": complete,
        "readiness": "Payment-Network-Spezialbewertung freigegeben" if complete else "Payment-Network-Spezialbewertung gesperrt",
    }


def build_payment_network_special_control(control, payment_model):
    if not isinstance(control, dict) or control.get("control_key") != "payment_network_adjusted_eps":
        return control
    model = payment_model if isinstance(payment_model, dict) else {}
    snap = model.get("snapshot") or {}
    score = model.get("specialist_score") or {}
    valuation = model.get("specialist_valuation") or {}
    released = bool(
        model.get("issuer_supported") and model.get("primary_source_complete")
        and model.get("valuation_anchor_complete") and score.get("available") and valuation.get("available")
    )
    out = dict(control)
    out.update({
        "implemented": bool(model.get("issuer_supported")),
        "released": released,
        "issuer_supported": bool(model.get("issuer_supported")),
        "confidence_cap": (snap.get("valuation_confidence_cap") if snap else None) or "Mittel",
        "router_status": "Schritt 3B freigegeben" if released else "Schritt 3B nicht freigegeben – Issuer noch nicht kalibriert",
        "step3b_status": "Payment-Network-Fair-Value freigegeben" if released else "Payment-Network-Fair-Value gesperrt",
        "snapshot": snap,
        "checks": {"specialist_score": score, "specialist_valuation": valuation},
        "note": (
            f"{APP_BUILD_VERSION} trennt Visa/Mastercard von Banken und dem generischen Standard-Unternehmen-Pfad. "
            f"{snap.get('company') or model.get('symbol') or 'Der Emittent'} nutzt ausschließlich issuer-spezifische Netzwerk-, Adjusted-Earnings-, "
            "Cash-Conversion- und Kapitalrückführungsdaten; Litigation-/Regulatory-Risiken dürfen das Quality-P/E ausschließlich downside-only begrenzen. "
            "Analystenziele bleiben Modul 8."
            if model.get("issuer_supported") else (model.get("note") or "Payment-Network-Spezialroute noch nicht kalibriert.")
        ),
    })
    return out


def apply_regulated_utility_action_brake(new_buy_signal, holding_signal, utility_model):
    """Downside-only action overlay for risks that are not reliably priceable by a single P/E.

    It never upgrades a signal. EIX's unresolved wildfire-liability tail risk is
    explicitly treated as a condition where a numerical Fair Value may remain
    useful, but Buy/Add actions are capped at Observe/Hold until the framework
    materially improves. POR currently has no hard action cap; its transaction
    risk is already reflected through the P/E cap and Medium confidence.
    """
    model = utility_model if isinstance(utility_model, dict) else {}
    snap = model.get("snapshot") or {}
    if not model.get("applicable") or not model.get("valuation_anchor_complete"):
        return new_buy_signal, holding_signal
    if snap.get("risk_action_cap") != "observe_hold":
        return new_buy_signal, holding_signal

    nb = dict(new_buy_signal or {})
    hs = dict(holding_signal or {})
    if nb.get("signal") in {"Starker Kauf", "Kauf"}:
        nb.update({
            "signal": "Beobachten",
            "reason": (
                "Rechnerische Unterbewertung vorhanden, aber der aktuelle Utility-Risiko-Overlay begrenzt "
                "Neukäufe auf Beobachten, solange das offene Wildfire-Haftungsregime nicht ausreichend geklärt ist."
            ),
            "utility_risk_action_brake": True,
        })
    if hs.get("signal") == "Nachkaufen":
        hs.update({
            "signal": "Halten",
            "reason": (
                "Rechnerische Unterbewertung vorhanden, aber der aktuelle Utility-Risiko-Overlay sperrt "
                "einen Nachkauf, solange das offene Wildfire-Haftungsregime nicht ausreichend geklärt ist."
            ),
            "utility_risk_action_brake": True,
        })
    return nb, hs



