def calculate_peer_check(
    company_type,
    peer_group,
    fundamental_multiple,
    cache_version,
    earnings_basis_usable=True
):
    result = {
        "method_supported": False,
        "peer_rows": [],
        "usable_count": 0,
        "peer_median": None,
        "adjustment_pct": 0.0,
        "adjusted_multiple": None,
        "applied": False,
        "note": None
    }

    type_name = str(company_type.get("type", "")).lower()

    if not peer_group.get("available"):
        if "standard-unternehmen" in type_name:
            result["note"] = (
                "Kein automatischer Peer-Check für den Sammeltyp "
                "Standard-Unternehmen. Der Peer-Check ist hier optional "
                "und blockiert den Fair Value nicht; verwendet wird das "
                "unveränderte Fundamental-Multiple."
            )
        else:
            result["note"] = (
                "Keine automatische Peer-Gruppe verfügbar."
            )
        return result

    if (peer_group or {}).get("peer_model") == "listed_holding_nav_reference_v1":
        result.update({
            "method_supported": True,
            "adjusted_multiple": fundamental_multiple,
            "applied": False,
            "note": "Listed-Holding-Peers werden nicht über Yahoo-Forward-KGV bewertet. Der NAV/Premium-Discount-Peer-Guard läuft ausschließlich im Holding-Spezialmodell; Schritt 2B bleibt reference-only.",
        })
        return result

    if (peer_group or {}).get("target_symbol") == "BKR" and "energy technology / oilfield services" in type_name:
        return _calculate_baker_hughes_peer_reference(
            peer_group, fundamental_multiple, cache_version
        )

    if (peer_group or {}).get("target_symbol") == "KTOS" and "defense / stark wachsend" in type_name:
        return _calculate_kratos_peer_reference(
            peer_group, fundamental_multiple, cache_version
        )

    if (peer_group or {}).get("peer_model") == "defense_high_growth_prime_reference_v2":
        return _calculate_defense_high_growth_peer_reference(
            peer_group, fundamental_multiple, cache_version
        )

    if (peer_group or {}).get("peer_model") == "medical_devices_v2":
        return _calculate_medical_devices_peer_overlay(
            peer_group, fundamental_multiple, cache_version
        )

    if (peer_group or {}).get("peer_model") == "asset_management_reference_guard_v1":
        return _calculate_asset_management_peer_reference(
            peer_group, fundamental_multiple, cache_version
        )

    if (peer_group or {}).get("peer_model") == "luxury_premium_reference_v1":
        return _calculate_luxury_premium_peer_reference(
            peer_group, fundamental_multiple, cache_version
        )

    if (peer_group or {}).get("peer_model") == "oilfield_services_energy_tech_reference_v1":
        return _calculate_oilfield_services_energy_tech_peer_reference(
            peer_group, fundamental_multiple, cache_version
        )

    if (peer_group or {}).get("peer_model") == "integrated_oil_gas_major_reference_v1":
        return _calculate_integrated_oil_gas_peer_reference(
            peer_group, fundamental_multiple, cache_version
        )

    if (peer_group or {}).get("peer_model") == "branded_consumer_staples_reference_v2":
        return _calculate_branded_consumer_staples_peer_reference(
            peer_group, fundamental_multiple, cache_version
        )

    if "midstream" in type_name:
        return _calculate_midstream_peer_overlay(
            peer_group, fundamental_multiple, cache_version
        )

    if "autohersteller" in type_name:
        return _calculate_automotive_peer_overlay(
            peer_group, fundamental_multiple, cache_version
        )

    if "halbleiterausrüstung / lithografie" in type_name:
        return _calculate_semicap_peer_overlay(
            peer_group, fundamental_multiple, cache_version
        )

    if "halbleiter / fabless / ai-wachstum" in type_name:
        return _calculate_nvidia_peer_overlay(
            peer_group, fundamental_multiple, cache_version
        )

    if not peer_forward_pe_is_supported(company_type):
        result["note"] = (
            "Für diesen Unternehmenstyp wird kein einfaches "
            "Forward-KGV-Peerverfahren verwendet. Zyklische "
            "und Sondermodelle benötigen eine eigene "
            "normalisierte Peer-Bewertung."
        )
        return result

    if not earnings_basis_usable:
        result["note"] = (
            "KGV-Peer-Check gesperrt: Für die Aktie liegt "
            "keine positive und verwertbare normalisierte "
            "Gewinnbasis vor. Es werden deshalb keine "
            "Peer-KGVs geladen oder angewendet."
        )
        return result

    result["method_supported"] = True

    for peer in peer_group.get("peers", []):

        peer_data = load_peer_forward_pe(
            peer["symbol"],
            cache_version
        )

        row = {
            "symbol": peer["symbol"],
            "name": peer["name"],
            "usable": peer_data["usable"],
            "forward_pe": peer_data["forward_pe"],
            "source": peer_data.get("source"),
            "reason": peer_data["reason"]
        }

        result["peer_rows"].append(row)

    usable_values = [
        row["forward_pe"]
        for row in result["peer_rows"]
        if row["usable"]
    ]

    result["usable_count"] = len(
        usable_values
    )

    if result["usable_count"] < 3:
        result["note"] = (
            "Weniger als 3 brauchbare Peer-KGVs verfügbar. "
            "Nach unserer Regel erfolgt deshalb keine "
            "automatische Peer-Anpassung."
        )

        if fundamental_multiple is not None:
            result["adjusted_multiple"] = (
                fundamental_multiple
            )

        return result

    peer_median = float(
        pd.Series(usable_values).median()
    )

    result["peer_median"] = peer_median

    if (
        fundamental_multiple is None
        or fundamental_multiple <= 0
    ):
        result["note"] = (
            "Peer-Median vorhanden, aber kein belastbares "
            "Fundamental-Multiple als Ausgangsbasis."
        )
        return result

    raw_difference = (
        peer_median / fundamental_multiple
        - 1.0
    )

    adjustment_pct = max(
        -0.05,
        min(0.05, raw_difference)
    )

    adjusted_multiple = (
        fundamental_multiple
        * (1.0 + adjustment_pct)
    )

    result["adjustment_pct"] = (
        adjustment_pct
    )
    result["adjusted_multiple"] = (
        adjusted_multiple
    )
    result["applied"] = True

    if abs(raw_difference) <= 0.05:
        result["note"] = (
            "Der Peer-Median liegt nahe am eigenen "
            "Fundamental-Multiple. Die tatsächliche "
            "Abweichung wird vollständig berücksichtigt."
        )
    else:
        result["note"] = (
            "Der Abstand zum Peer-Median ist größer als "
            "5 %. Die automatische Peer-Anpassung wird "
            "deshalb strikt auf maximal ±5 % begrenzt."
        )

    if "autozulieferer / zyklisch" in str(company_type.get("type", "")).lower():
        result["note"] += (
            " Bei Autozulieferern dient das Forward-KGV nur als externer "
            "Realitätscheck. Die zyklus-normalisierte EPS-Basis bleibt "
            "unverändert; der Peer-Check kontrolliert ausschließlich das "
            "Multiple innerhalb der ±5-%-Grenze."
        )

    return result


