def is_defense_high_growth_prime_specialist(company_type, symbol=None):
    symbol_text = str(symbol or "").upper().strip()
    type_name = str((company_type or {}).get("type") or "").lower()
    return symbol_text in {"RHM.DE", "RHM.F", "RNMBY", "RNMBF"} and "defense / stark wachsend" in type_name


def _defense_high_growth_target_pe(score):
    s = safe_float(score)
    if s is None:
        return None
    s = max(0.0, min(100.0, s))
    if s < 50.0:
        return 18.0 + (s / 50.0) * 3.0
    if s < 65.0:
        return 21.0 + ((s - 50.0) / 15.0) * 2.0
    if s < 80.0:
        return 23.0 + ((s - 65.0) / 15.0) * 3.0
    if s < 90.0:
        return 26.0 + ((s - 80.0) / 10.0) * 2.5
    return 28.5 + ((s - 90.0) / 10.0) * 1.5


def _defense_quality_level(score):
    s = safe_float(score)
    if s is None:
        return None
    if s >= 90: return "Sehr stark"
    if s >= 80: return "Stark"
    if s >= 70: return "Gut"
    if s >= 50: return "Ausreichend"
    return "Schwach"


def build_defense_high_growth_specialist_model(company_type, info, symbol, current_fy_eps):
    result = {
        "applicable": False,
        "primary_source_complete": False,
        "valuation_anchor_complete": False,
        "snapshot": None,
        "specialist_score": {},
        "earnings_basis": {},
        "specialist_valuation": {},
        "note": None,
    }
    if not is_defense_high_growth_prime_specialist(company_type, symbol):
        return result
    result["applicable"] = True
    snap = get_verified_defense_snapshot(symbol)
    result["snapshot"] = snap
    if not snap or snap.get("model_variant") != "rheinmetall_high_growth_defense_prime_v2":
        result["note"] = "Rheinmetall Defense-V2-Primärdaten fehlen; generischer Fallback ist nicht zulässig."
        return result
    try:
        fresh = datetime.now().date() <= datetime.strptime(snap.get("valid_until"), "%d.%m.%Y").date()
    except Exception:
        fresh = False

    backlog = safe_float(snap.get("backlog_current")); prev_backlog = safe_float(snap.get("backlog_previous"))
    backlog_growth = ((backlog / prev_backlog - 1.0) * 100.0) if backlog is not None and prev_backlog not in [None, 0] else None
    fixed = safe_float(snap.get("fixed_order_backlog_current"))
    fixed_share = fixed / backlog * 100.0 if fixed is not None and backlog not in [None, 0] else None
    near_cov = safe_float(snap.get("near_term_fixed_coverage_pct"))
    btb = safe_float(snap.get("book_to_bill_lower_bound"))
    growth_lo = safe_float(snap.get("organic_growth_guidance_low_pct")); growth_hi = safe_float(snap.get("organic_growth_guidance_high_pct"))
    growth_mid = (growth_lo + growth_hi) / 2.0 if None not in [growth_lo, growth_hi] else None
    h1_growth = safe_float(snap.get("revenue_h1_yoy_pct"))
    op_growth = safe_float(snap.get("operating_result_h1_yoy_pct"))
    margin_h1 = safe_float(snap.get("current_margin")); margin_q2 = safe_float(snap.get("latest_quarter_margin")); margin_guide = safe_float(snap.get("guidance_margin"))
    adj_h1 = safe_float(snap.get("adjusted_h1_eps")); adj_h1_prev = safe_float(snap.get("adjusted_h1_eps_previous")); fy25_adj = safe_float(snap.get("fy2025_adjusted_eps"))
    eps_growth = ((adj_h1 / adj_h1_prev - 1.0) * 100.0) if adj_h1 is not None and adj_h1_prev not in [None, 0] else None
    h1_ofcf = safe_float(snap.get("h1_operating_free_cashflow")); cash_conv_guide = safe_float(snap.get("cash_conversion_guidance_min_pct"))
    net_debt = safe_float(snap.get("net_financial_debt")); equity = safe_float(snap.get("equity"))
    net_debt_equity = net_debt / equity * 100.0 if net_debt is not None and equity not in [None, 0] else None

    order_score = 0
    if backlog_growth is not None and backlog_growth >= 25: order_score += 6
    elif backlog_growth is not None and backlog_growth >= 10: order_score += 4
    if fixed_share is not None and fixed_share >= 65: order_score += 5
    elif fixed_share is not None and fixed_share >= 50: order_score += 3
    if near_cov is not None and near_cov >= 80: order_score += 5
    elif near_cov is not None and near_cov >= 65: order_score += 3
    if btb is not None and btb >= 2.0: order_score += 4
    elif btb is not None and btb >= 1.2: order_score += 2
    order_score = min(20, order_score)

    growth_score = 0
    if growth_mid is not None and growth_mid >= 25: growth_score += 10
    elif growth_mid is not None and growth_mid >= 15: growth_score += 7
    if h1_growth is not None and h1_growth >= 30: growth_score += 5
    elif h1_growth is not None and h1_growth >= 15: growth_score += 3
    growth_score = min(15, growth_score)

    margin_score = 0
    if op_growth is not None and op_growth >= 40: margin_score += 5
    elif op_growth is not None and op_growth >= 20: margin_score += 3
    if margin_guide is not None and margin_guide >= 18: margin_score += 6
    elif margin_guide is not None and margin_guide >= 15: margin_score += 4
    if margin_h1 is not None and margin_q2 is not None and margin_q2 >= margin_h1 and margin_h1 >= 14: margin_score += 4
    elif margin_h1 is not None and margin_h1 >= 14: margin_score += 2
    margin_score = min(15, margin_score)

    earnings_score = 0
    if eps_growth is not None and eps_growth >= 50: earnings_score += 7
    elif eps_growth is not None and eps_growth >= 20: earnings_score += 5
    if fy25_adj is not None and fy25_adj > 0: earnings_score += 3
    current_eps = safe_float(current_fy_eps)
    if current_eps is not None and current_eps > 0: earnings_score += 2
    earnings_score = min(12, earnings_score)  # Same-basis current-FY EPS is consensus, not issuer EPS guidance.

    cash_score = 0
    if h1_ofcf is not None and h1_ofcf > 0: cash_score = 8
    elif h1_ofcf is not None and h1_ofcf < 0 and cash_conv_guide is not None and cash_conv_guide >= 40: cash_score = 4
    elif cash_conv_guide is not None and cash_conv_guide >= 40: cash_score = 5

    balance_score = 0
    if net_debt_equity is not None:
        if net_debt_equity <= 25: balance_score = 9
        elif net_debt_equity <= 50: balance_score = 6
        elif net_debt_equity <= 75: balance_score = 4
        else: balance_score = 2

    # Guidance was narrowed after the F126 cancellation, while organic growth and margin guidance remained intact.
    execution_score = 8 if None not in [growth_mid, margin_guide] and growth_mid >= 25 and margin_guide >= 18 else 5
    strategic_score = int(safe_float(snap.get("strategic_position_score")) or 0)
    components = {
        "Orderqualität & Revenue Visibility": order_score,
        "Organisches Wachstum & Guidance": growth_score,
        "Operating Result / Margenqualität": margin_score,
        "Earnings-Qualität": earnings_score,
        "Cashflow / Working-Capital-Qualität": cash_score,
        "Bilanzqualität": balance_score,
        "Execution / Guidance": execution_score,
        "Strategische Position / Diversifikation": strategic_score,
    }
    score = sum(components.values())
    raw_pe = _defense_high_growth_target_pe(score)
    cash_guard_cap = 28.0 if h1_ofcf is not None and h1_ofcf < 0 else 30.0
    target_pe = min(raw_pe, cash_guard_cap) if raw_pe is not None else None
    premium_checks = {
        "order_visibility": bool(order_score >= 16),
        "organic_growth_gt_20": bool(growth_mid is not None and growth_mid > 20),
        "margin_ge_18": bool(margin_guide is not None and margin_guide >= 18),
        "adjusted_eps_growth": bool(eps_growth is not None and eps_growth > 20),
        "balance_not_excessive": bool(net_debt_equity is not None and net_debt_equity <= 60),
    }
    unlock_count = sum(bool(v) for v in premium_checks.values())
    fv = current_eps * target_pe if current_eps is not None and current_eps > 0 and target_pe is not None else None
    earnings_basis = {
        "available": bool(current_eps is not None and current_eps > 0),
        "value": current_eps,
        "method": "0Y/current-FY Analystenkonsens; Primärquellen-Growth/Margin/Adjusted-EPS-Trajectory als Credibility Gate",
        "confidence": "Mittel",
        "fy2025_adjusted_eps": fy25_adj,
        "h1_2026_adjusted_eps": adj_h1,
        "h1_2025_adjusted_eps": adj_h1_prev,
        "h1_adjusted_eps_growth_pct": eps_growth,
        "provider_ttm_is_context_only": True,
    }
    val = {
        "available": bool(fresh and fv is not None and score >= 50),
        "valuation_method_name": "Defense High-Growth Prime Current-FY P/E",
        "earnings_basis": current_eps,
        "corridor_low": 18.0,
        "corridor_high": 30.0,
        "raw_score_multiple": raw_pe,
        "target_multiple": target_pe,
        "cash_conversion_guard_cap": cash_guard_cap,
        "cash_conversion_guard_binding": bool(raw_pe is not None and target_pe is not None and target_pe < raw_pe - 1e-9),
        "premium_unlock_count": unlock_count,
        "premium_unlock_passed": unlock_count >= 4,
        "premium_unlock_checks": premium_checks,
        "fair_value_financial": fv,
        "peer_reference_median_pe": None,
        "peer_lock": True,
    }
    result.update({
        "primary_source_complete": bool(fresh),
        "valuation_anchor_complete": bool(val.get("available")),
        "specialist_score": {
            "available": True, "score": score, "quality_level": _defense_quality_level(score), "components": components,
            "backlog_growth_pct": backlog_growth, "fixed_order_share_pct": fixed_share, "near_term_fixed_coverage_pct": near_cov,
            "organic_growth_guidance_mid_pct": growth_mid, "h1_revenue_growth_pct": h1_growth, "operating_result_growth_pct": op_growth,
            "net_debt_to_equity_pct": net_debt_equity,
        },
        "earnings_basis": earnings_basis,
        "specialist_valuation": val,
        "note": (
            f"{APP_BUILD_VERSION}: Rheinmetall wird über Auftragsqualität/Visibility, organische Guidance, Margen-/Earnings-Qualität, Cash Conversion, Bilanz und Execution bewertet. "
            "Generisches Yahoo-Gewinnwachstum, TTM-FCF-Marge und Net-Debt/FCF steuern weder Score noch Ziel-KGV."
        ),
    })
    return result


def _defense_backlog_status(growth_pct):
    if growth_pct is None:
        return "Daten unzureichend"
    if growth_pct >= 15.0:
        return "Stark"
    if growth_pct >= 0.0:
        return "Positiv"
    if growth_pct > -10.0:
        return "Leicht rückläufig"
    return "Schwach"


def _defense_coverage_status(value):
    if value is None:
        return "Daten unzureichend"
    if value >= 3.0:
        return "Sehr stark"
    if value >= 2.0:
        return "Stark"
    if value >= 1.0:
        return "Ausreichend"
    return "Schwach"


def _defense_fixed_orders_status(share_pct):
    if share_pct is None:
        return "Daten unzureichend"
    if share_pct >= 70.0:
        return "Sehr stark"
    if share_pct >= 60.0:
        return "Stark"
    if share_pct >= 50.0:
        return "Ausreichend"
    return "Schwach"


def _defense_book_to_bill_status(value):
    if value is None:
        return "Daten unzureichend"
    if value >= 1.5:
        return "Sehr stark"
    if value >= 1.2:
        return "Stark"
    if value >= 1.0:
        return "Ausreichend"
    return "Schwach"


def _defense_near_term_status(value):
    if value is None:
        return "Daten unzureichend"
    if value >= 80.0:
        return "Sehr stark"
    if value >= 65.0:
        return "Stark"
    if value >= 50.0:
        return "Ausreichend"
    return "Schwach"


def evaluate_defense_margin_trend(
    current_margin=None,
    comparable_previous_margin=None,
    latest_quarter_margin=None,
    previous_full_year_margin=None,
    guidance_margin=None,
):
    result = {
        "current_margin": safe_float(current_margin),
        "previous_margin": safe_float(comparable_previous_margin),
        "margin_change_pp": None,
        "latest_quarter_margin": safe_float(latest_quarter_margin),
        "previous_full_year_margin": safe_float(previous_full_year_margin),
        "guidance_margin": safe_float(guidance_margin),
        "guidance_change_pp": None,
        "historical_trend": "Daten unzureichend",
        "guidance_trend": "Daten unzureichend",
        "overall_status": "Daten unzureichend",
    }

    current = result["current_margin"]
    previous = result["previous_margin"]

    if current is not None and previous is not None:
        change = current - previous
        result["margin_change_pp"] = change

        if change >= 2.0:
            result["historical_trend"] = "Sehr stark"
        elif change >= 0.5:
            result["historical_trend"] = "Stark"
        elif change > -0.5:
            result["historical_trend"] = "Stabil"
        elif change > -2.0:
            result["historical_trend"] = "Leicht rückläufig"
        else:
            result["historical_trend"] = "Schwach"

    guidance = result["guidance_margin"]
    previous_full_year = result["previous_full_year_margin"]

    if guidance is not None and previous_full_year is not None:
        change = guidance - previous_full_year
        result["guidance_change_pp"] = change

        if change >= 1.0:
            result["guidance_trend"] = "Steigend"
        elif change >= -0.5:
            result["guidance_trend"] = "Stabil bis steigend"
        elif change > -1.5:
            result["guidance_trend"] = "Leicht rückläufig"
        else:
            result["guidance_trend"] = "Schwach"

    hist = result["historical_trend"]
    guide = result["guidance_trend"]

    if hist == "Sehr stark" and guide in ["Steigend", "Stabil bis steigend"]:
        result["overall_status"] = "Sehr stark"
    elif hist in ["Sehr stark", "Stark"] and guide != "Schwach":
        result["overall_status"] = "Stark"
    elif hist == "Stabil" and guide in ["Steigend", "Stabil bis steigend"]:
        result["overall_status"] = "Ausreichend"
    elif hist in ["Leicht rückläufig", "Schwach"]:
        result["overall_status"] = "Schwach"

    return result


def build_defense_special_control(base_control, company_type, symbol, specialist_model=None):
    """Enrich the 3A router result with Defense step 3B when verified data exist."""

    symbol_text = str(symbol or "").upper().strip()
    control = dict(base_control or {})
    control.setdefault("router_status", control.get("status"))
    control.setdefault("router_note", control.get("note"))

    if control.get("control_key") != "defense_order_visibility":
        control.setdefault("implemented", False)
        control.setdefault("released", False)
        return control

    snapshot = get_verified_defense_snapshot(symbol)

    if snapshot is None:
        control.update({
            "implemented": False,
            "released": False,
            "confidence_cap": "Niedrig",
            "step3b_status": "Schritt 3B Daten fehlen",
            "note": (
                "Die Defense-Logik ist fachlich implementiert, aber für diese "
                "Aktie liegt noch kein verifizierter offizieller Spezialdaten-"
                "Snapshot vor. Es wird nichts geschätzt; Fair Value bleibt gesperrt."
            ),
        })
        return control

    try:
        valid_until = datetime.strptime(
            snapshot["valid_until"], "%d.%m.%Y"
        ).date()
        snapshot_fresh = datetime.now().date() <= valid_until
    except Exception:
        snapshot_fresh = False

    backlog_current = safe_float(snapshot.get("backlog_current"))
    backlog_previous = safe_float(snapshot.get("backlog_previous"))
    revenue_low = safe_float(snapshot.get("revenue_guidance_low"))
    revenue_high = safe_float(snapshot.get("revenue_guidance_high"))

    backlog_growth_pct = None
    if backlog_current is not None and backlog_previous not in [None, 0]:
        backlog_growth_pct = (backlog_current / backlog_previous - 1.0) * 100.0

    revenue_base = None
    if revenue_low is not None and revenue_high is not None:
        revenue_base = (revenue_low + revenue_high) / 2.0

    revenue_coverage = None
    if backlog_current is not None and revenue_base not in [None, 0]:
        revenue_coverage = backlog_current / revenue_base

    fixed_current = safe_float(snapshot.get("fixed_order_backlog_current"))
    fixed_previous = safe_float(snapshot.get("fixed_order_backlog_previous"))

    fixed_share_pct = None
    if fixed_current is not None and backlog_current not in [None, 0]:
        fixed_share_pct = fixed_current / backlog_current * 100.0

    fixed_previous_share_pct = None
    if fixed_previous is not None and backlog_previous not in [None, 0]:
        fixed_previous_share_pct = fixed_previous / backlog_previous * 100.0

    fixed_share_change_pp = None
    if fixed_share_pct is not None and fixed_previous_share_pct is not None:
        fixed_share_change_pp = fixed_share_pct - fixed_previous_share_pct

    book_to_bill = safe_float(snapshot.get("book_to_bill_lower_bound"))
    near_term_coverage = safe_float(snapshot.get("near_term_fixed_coverage_pct"))

    margin = evaluate_defense_margin_trend(
        snapshot.get("current_margin"),
        snapshot.get("comparable_previous_margin"),
        snapshot.get("latest_quarter_margin"),
        snapshot.get("previous_full_year_margin"),
        snapshot.get("guidance_margin"),
    )

    kratos_growth = None
    kratos_earnings = None
    kratos_owner_operating = None
    kratos_profitability_bridge = None
    kratos_2027_horizon = None
    kratos_cashflow = None
    if symbol_text == "KTOS":
        funded = safe_float(snapshot.get("funded_backlog_current"))
        unfunded = safe_float(snapshot.get("unfunded_backlog_current"))
        funded_share = funded / backlog_current * 100.0 if funded is not None and backlog_current not in [None, 0] else None
        h1_revenue = safe_float(snapshot.get("revenue_h1"))
        fy_mid = revenue_base
        h2_needed = fy_mid - h1_revenue if fy_mid is not None and h1_revenue is not None else None
        backlog_fy26_pct = safe_float(snapshot.get("backlog_expected_revenue_fy26_pct"))
        backlog_fy26_amount = backlog_current * backlog_fy26_pct / 100.0 if backlog_current is not None and backlog_fy26_pct is not None else None
        h2_backlog_coverage_pct = backlog_fy26_amount / h2_needed * 100.0 if backlog_fy26_amount is not None and h2_needed not in [None, 0] and h2_needed > 0 else None
        q2_gaap = safe_float(snapshot.get("q2_gaap_eps")); q2_adj = safe_float(snapshot.get("q2_adjusted_eps"))
        h1_gaap = safe_float(snapshot.get("h1_gaap_eps")); h1_adj = safe_float(snapshot.get("h1_adjusted_eps"))
        h1_gaap_ni = safe_float(snapshot.get("h1_gaap_net_income")); h1_adj_ni = safe_float(snapshot.get("h1_adjusted_net_income"))
        adjusted_to_gaap_ni = h1_adj_ni / h1_gaap_ni if h1_adj_ni is not None and h1_gaap_ni not in [None, 0] else None
        if h2_backlog_coverage_pct is not None:
            near_term_coverage = h2_backlog_coverage_pct
        kratos_growth = {
            "funded_backlog": funded,
            "unfunded_backlog": unfunded,
            "funded_share_pct": funded_share,
            "ltm_book_to_bill": safe_float(snapshot.get("ltm_book_to_bill")),
            "bid_proposal_pipeline": safe_float(snapshot.get("bid_proposal_pipeline_current")),
            "q2_revenue": safe_float(snapshot.get("revenue_q2")),
            "q2_revenue_yoy_pct": safe_float(snapshot.get("revenue_q2_yoy_pct")),
            "q2_organic_growth_pct": safe_float(snapshot.get("organic_revenue_q2_yoy_pct")),
            "h1_revenue": h1_revenue,
            "fy26_revenue_mid": fy_mid,
            "h2_revenue_needed": h2_needed,
            "backlog_expected_fy26_amount": backlog_fy26_amount,
            "h2_backlog_coverage_pct": h2_backlog_coverage_pct,
            "q3_revenue_low": safe_float(snapshot.get("q3_revenue_guidance_low")),
            "q3_revenue_high": safe_float(snapshot.get("q3_revenue_guidance_high")),
            "q3_organic_growth_low_pct": safe_float(snapshot.get("q3_organic_growth_low_pct")),
            "q3_organic_growth_high_pct": safe_float(snapshot.get("q3_organic_growth_high_pct")),
            "visibility_status": "Stark, aber nicht backlog-garantiert" if h2_backlog_coverage_pct is not None and h2_backlog_coverage_pct >= 65.0 else "Begrenzt",
        }
        kratos_earnings = {
            "q2_gaap_eps": q2_gaap, "q2_adjusted_eps": q2_adj,
            "h1_gaap_eps": h1_gaap, "h1_adjusted_eps": h1_adj,
            "h1_gaap_net_income": h1_gaap_ni, "h1_adjusted_net_income": h1_adj_ni,
            "adjusted_to_gaap_net_income_multiple": adjusted_to_gaap_ni,
            "h1_stock_compensation": safe_float(snapshot.get("h1_stock_compensation")),
            "fy_adjusted_eps_guidance_available": False,
            "earnings_basis_released": False,
            "status": "Nicht als Bewertungsbasis freigegeben",
            "reason": (
                "Q2/H1 Adjusted EPS liegt wesentlich über GAAP EPS. V2.20.72 prüft deshalb jede Non-GAAP-Anpassung einzeln: "
                "Depreciation, Stock-Based Compensation und Contract/Development-Amortisation bleiben wirtschaftliche Kosten; "
                "akquisitionsbedingte Intangible-Amortisation wird wegen der weiterhin hohen offiziellen Amortisationsplanung nicht automatisch herausgerechnet. "
                "Yahoo Forward-EPS bleibt reference-only, bis eine einzelne belastbare operative Earnings-Basis separat freigegeben ist."
            ),
        }

        # V2.20.72 Owner-Operating Earnings Adjustment Quality Gate.
        # Start from the company's official H1 adjusted pre-tax bridge, then put recurring
        # economic costs back. This is diagnostic only; no valuation earnings basis is released.
        adj_pre_tax = safe_float(snapshot.get("h1_adjusted_pre_tax_income"))
        ng_tax = safe_float(snapshot.get("h1_non_gaap_income_taxes"))
        dep = safe_float(snapshot.get("h1_depreciation"))
        sbc = safe_float(snapshot.get("h1_stock_compensation"))
        intang_amort = safe_float(snapshot.get("h1_intangible_amortization"))
        contract_amort = safe_float(snapshot.get("h1_contract_development_amortization"))
        acq_restruct = safe_float(snapshot.get("h1_acquisition_restructuring_items"))
        contingent_reversal = safe_float(snapshot.get("h1_contingent_acquisition_consideration_reversal"))
        diluted_shares = safe_float(snapshot.get("h1_diluted_shares"))
        owner_tax_rate = ng_tax / adj_pre_tax if ng_tax is not None and adj_pre_tax not in [None, 0] else None

        strict_pre_tax = None
        strict_net_income = None
        strict_eps = None
        conditional_pre_tax = None
        conditional_net_income = None
        conditional_eps = None
        if None not in [adj_pre_tax, dep, sbc, intang_amort, contract_amort]:
            strict_pre_tax = adj_pre_tax - dep - sbc - intang_amort - contract_amort
            conditional_pre_tax = strict_pre_tax + intang_amort
            if owner_tax_rate is not None and 0 <= owner_tax_rate < 1:
                strict_net_income = strict_pre_tax * (1.0 - owner_tax_rate)
                conditional_net_income = conditional_pre_tax * (1.0 - owner_tax_rate)
                if diluted_shares not in [None, 0]:
                    strict_eps = strict_net_income / diluted_shares
                    conditional_eps = conditional_net_income / diluted_shares

        kratos_owner_operating = {
            "status": "Teilweise bestätigt · keine Bewertungsbasis",
            "earnings_basis_released": False,
            "adjusted_pre_tax_income": adj_pre_tax,
            "non_gaap_tax": ng_tax,
            "diagnostic_tax_rate_pct": owner_tax_rate * 100.0 if owner_tax_rate is not None else None,
            "depreciation": dep,
            "stock_compensation": sbc,
            "contract_development_amortization": contract_amort,
            "intangible_amortization": intang_amort,
            "acquisition_restructuring": acq_restruct,
            "contingent_consideration_reversal": contingent_reversal,
            "future_intangible_amortization_remainder_2026": safe_float(snapshot.get("future_intangible_amortization_remainder_2026")),
            "future_intangible_amortization_2027": safe_float(snapshot.get("future_intangible_amortization_2027")),
            "strict_owner_pre_tax": strict_pre_tax,
            "strict_owner_net_income": strict_net_income,
            "strict_owner_eps": strict_eps,
            "conditional_owner_pre_tax": conditional_pre_tax,
            "conditional_owner_net_income": conditional_net_income,
            "conditional_owner_eps": conditional_eps,
            "range_low_eps": strict_eps,
            "range_high_eps": conditional_eps,
            "normalization_policy": {
                "Depreciation": "0 % Auto-Addback · wirtschaftliche Wiederbeschaffungskosten",
                "Stock-Based Compensation": "0 % Auto-Addback · reale Verwässerung/Compensation",
                "Contract/Development-Amortisation": "0 % Auto-Addback · kapitalisierte Entwicklungs-/Vertragskosten",
                "Acquired Intangible Amortisation": "0 % automatische Freigabe · nur bedingte Obergrenze",
                "Acquisition/Restructuring": "normalisierbar, sofern separat und nicht wiederkehrend",
                "Contingent Acquisition Consideration Reversal": "Gewinn wird neutralisiert, nicht als operative Earnings gezählt",
            },
            "reason": (
                "Die Company-Adjusted-EPS-Brücke addiert auch Depreciation, SBC und Contract/Development-Amortisation zurück. "
                "V2.20.72 behandelt diese Positionen nicht als kostenlose Addbacks. Acquired-Intangible-Amortisation bleibt wegen offiziell erwarteter "
                "Amortisation von 21,3 Mio. USD im Rest 2026 und 40,2 Mio. USD 2027 automatisch gesperrt und wird nur als bedingte Obergrenze gezeigt. "
                "Daher entsteht bewusst nur eine diagnostische H1-EPS-Spanne und noch keine Bewertungsbasis."
            ),
        }

        # V2.20.72 FY26 Owner-Operating Profitability Bridge & 2027 Horizon Lock.
        # The official FY26 midpoint reconciles Operating Income to Adjusted EBITDA via
        # Depreciation + Amortization + SBC. These are not treated as free economic earnings.
        fy26_rev_low = safe_float(snapshot.get("revenue_guidance_low"))
        fy26_rev_high = safe_float(snapshot.get("revenue_guidance_high"))
        fy26_rev_mid = (fy26_rev_low + fy26_rev_high) / 2.0 if None not in [fy26_rev_low, fy26_rev_high] else None
        oi_low = safe_float(snapshot.get("fy26_operating_income_guidance_low"))
        oi_high = safe_float(snapshot.get("fy26_operating_income_guidance_high"))
        dep_low = safe_float(snapshot.get("fy26_depreciation_guidance_low"))
        dep_high = safe_float(snapshot.get("fy26_depreciation_guidance_high"))
        amort_low = safe_float(snapshot.get("fy26_amortization_guidance_low"))
        amort_high = safe_float(snapshot.get("fy26_amortization_guidance_high"))
        sbc_low = safe_float(snapshot.get("fy26_stock_compensation_guidance_low"))
        sbc_high = safe_float(snapshot.get("fy26_stock_compensation_guidance_high"))
        adj_ebitda_low = safe_float(snapshot.get("fy26_adjusted_ebitda_guidance_low"))
        adj_ebitda_high = safe_float(snapshot.get("fy26_adjusted_ebitda_guidance_high"))

        def _mid(lo, hi):
            return (lo + hi) / 2.0 if None not in [lo, hi] else None

        oi_mid = _mid(oi_low, oi_high)
        dep_mid = _mid(dep_low, dep_high)
        amort_mid = _mid(amort_low, amort_high)
        sbc_mid = _mid(sbc_low, sbc_high)
        adj_ebitda_mid = _mid(adj_ebitda_low, adj_ebitda_high)
        bridge_sum_mid = None
        if None not in [oi_mid, dep_mid, amort_mid, sbc_mid]:
            bridge_sum_mid = oi_mid + dep_mid + amort_mid + sbc_mid
        bridge_gap_mid = bridge_sum_mid - adj_ebitda_mid if None not in [bridge_sum_mid, adj_ebitda_mid] else None
        total_addbacks_mid = dep_mid + amort_mid + sbc_mid if None not in [dep_mid, amort_mid, sbc_mid] else None
        addbacks_share_adj_ebitda_pct = total_addbacks_mid / adj_ebitda_mid * 100.0 if total_addbacks_mid is not None and adj_ebitda_mid not in [None, 0] else None
        sbc_share_adj_ebitda_pct = sbc_mid / adj_ebitda_mid * 100.0 if sbc_mid is not None and adj_ebitda_mid not in [None, 0] else None

        acquired_intangible_fy26 = None
        if intang_amort is not None and safe_float(snapshot.get("future_intangible_amortization_remainder_2026")) is not None:
            acquired_intangible_fy26 = intang_amort + safe_float(snapshot.get("future_intangible_amortization_remainder_2026"))

        strict_ebit_low = oi_low
        strict_ebit_high = oi_high
        conditional_ebit_low = oi_low + acquired_intangible_fy26 if oi_low is not None and acquired_intangible_fy26 is not None else None
        conditional_ebit_high = oi_high + acquired_intangible_fy26 if oi_high is not None and acquired_intangible_fy26 is not None else None
        strict_margin_low = strict_ebit_low / fy26_rev_high * 100.0 if strict_ebit_low is not None and fy26_rev_high not in [None, 0] else None
        strict_margin_high = strict_ebit_high / fy26_rev_low * 100.0 if strict_ebit_high is not None and fy26_rev_low not in [None, 0] else None
        conditional_margin_low = conditional_ebit_low / fy26_rev_high * 100.0 if conditional_ebit_low is not None and fy26_rev_high not in [None, 0] else None
        conditional_margin_high = conditional_ebit_high / fy26_rev_low * 100.0 if conditional_ebit_high is not None and fy26_rev_low not in [None, 0] else None
        adj_ebitda_margin_mid = adj_ebitda_mid / fy26_rev_mid * 100.0 if adj_ebitda_mid is not None and fy26_rev_mid not in [None, 0] else None

        kratos_profitability_bridge = {
            "available": all(v is not None for v in [fy26_rev_low, fy26_rev_high, oi_low, oi_high, dep_low, dep_high, amort_low, amort_high, sbc_low, sbc_high, adj_ebitda_low, adj_ebitda_high]),
            "fy26_revenue_low": fy26_rev_low,
            "fy26_revenue_high": fy26_rev_high,
            "fy26_revenue_mid": fy26_rev_mid,
            "operating_income_low": oi_low,
            "operating_income_high": oi_high,
            "operating_income_mid": oi_mid,
            "depreciation_low": dep_low,
            "depreciation_high": dep_high,
            "depreciation_mid": dep_mid,
            "amortization_low": amort_low,
            "amortization_high": amort_high,
            "amortization_mid": amort_mid,
            "stock_comp_low": sbc_low,
            "stock_comp_high": sbc_high,
            "stock_comp_mid": sbc_mid,
            "adjusted_ebitda_low": adj_ebitda_low,
            "adjusted_ebitda_high": adj_ebitda_high,
            "adjusted_ebitda_mid": adj_ebitda_mid,
            "bridge_sum_mid": bridge_sum_mid,
            "bridge_gap_mid": bridge_gap_mid,
            "total_addbacks_mid": total_addbacks_mid,
            "addbacks_share_adj_ebitda_pct": addbacks_share_adj_ebitda_pct,
            "sbc_share_adj_ebitda_pct": sbc_share_adj_ebitda_pct,
            "acquired_intangible_amortization_fy26_diagnostic": acquired_intangible_fy26,
            "strict_owner_operating_ebit_low": strict_ebit_low,
            "strict_owner_operating_ebit_high": strict_ebit_high,
            "strict_owner_operating_margin_low_pct": strict_margin_low,
            "strict_owner_operating_margin_high_pct": strict_margin_high,
            "conditional_owner_operating_ebit_low": conditional_ebit_low,
            "conditional_owner_operating_ebit_high": conditional_ebit_high,
            "conditional_owner_operating_margin_low_pct": conditional_margin_low,
            "conditional_owner_operating_margin_high_pct": conditional_margin_high,
            "adjusted_ebitda_margin_mid_pct": adj_ebitda_margin_mid,
            "earnings_basis_released": False,
            "status": "FY26 Profitabilitätsbrücke bestätigt · keine Bewertungsbasis",
            "reason": (
                "Die FY26-Guidance zeigt, dass Operating Income + Depreciation + Amortization + SBC am Mittelpunkt praktisch vollständig zum Adjusted EBITDA überleitet. "
                "Depreciation, SBC und Contract/Development-Amortisation bleiben daher wirtschaftliche Kosten. Der strikte Owner-Operating-EBIT-Korridor bleibt auf der offiziellen Operating-Income-Guidance; "
                "nur die separat identifizierte acquired-intangible amortization darf als bedingte obere Diagnose gezeigt werden. Diese Obergrenze ist keine freigegebene Earnings-Basis."
            ),
        }

        fy27_margin_uplift_pp = safe_float(snapshot.get("fy27_adjusted_ebitda_margin_uplift_pp"))
        fy27_indicated_adj_ebitda_margin = adj_ebitda_margin_mid + fy27_margin_uplift_pp if adj_ebitda_margin_mid is not None and fy27_margin_uplift_pp is not None else None
        kratos_2027_horizon = {
            "full_guidance_available": bool(snapshot.get("fy27_full_guidance_available")),
            "guidance_timing": snapshot.get("fy27_guidance_timing"),
            "fy26_adjusted_ebitda_margin_mid_pct": adj_ebitda_margin_mid,
            "expected_adjusted_ebitda_margin_uplift_pp": fy27_margin_uplift_pp,
            "indicated_2027_adjusted_ebitda_margin_pct": fy27_indicated_adj_ebitda_margin,
            "revenue_guidance_available": False,
            "operating_income_guidance_available": False,
            "eps_guidance_available": False,
            "earnings_basis_released": False,
            "status": "GESPERRT – keine 2027 operative Earnings-Basis",
            "reason": (
                "Kratos erwartet für 2027 eine weitere Verbesserung der Adjusted-EBITDA-Marge um rund 100 Basispunkte gegenüber 2026, hat aber noch keine ausreichend vollständige offizielle FY27-Primärdatenbasis veröffentlicht, aus der sich eine belastbare Owner-Operating-Earnings-Basis ableiten lässt. "
                "Die Margenrichtung wird deshalb nicht in Umsatz, EBIT, EPS oder Fair Value extrapoliert. Ein 2027 Bewertungsanker bleibt fail-closed bis zur angekündigten FY27-Guidance beziehungsweise einer ausreichend vollständigen offiziellen FY27-Primärdatenbasis. Eine explizite EPS-Guidance ist dafür nicht zwingend erforderlich, wenn die notwendigen Umsatz-, Profitabilitäts- und Addback-Bausteine belastbar vorliegen."
            ),
        }

        kratos_cashflow = {
            "q2_fcf_use": safe_float(snapshot.get("q2_fcf_use")),
            "fy26_fcf_use_low": safe_float(snapshot.get("fy26_fcf_use_low")),
            "fy26_fcf_use_high": safe_float(snapshot.get("fy26_fcf_use_high")),
            "fy26_ocf_low": safe_float(snapshot.get("fy26_operating_cashflow_guidance_low")),
            "fy26_ocf_high": safe_float(snapshot.get("fy26_operating_cashflow_guidance_high")),
            "fy26_capex_low": safe_float(snapshot.get("fy26_capex_guidance_low")),
            "fy26_capex_high": safe_float(snapshot.get("fy26_capex_guidance_high")),
            "status": "Investitions-/Working-Capital-belastet",
            "note": (
                "Negativer FCF wird nicht als normalisierte Earnings-Basis verwendet. Kratos führt den FY26-FCF-Abfluss selbst auf Produktionshochlauf, "
                "Working Capital, Inventory und Kapazitäts-/Entwicklungsinvestitionen zurück; der Abfluss bleibt dennoch ein reales Cashflow-Risiko."
            ),
        }

    checks = {
        "backlog": {
            "value": backlog_current,
            "previous": backlog_previous,
            "growth_pct": backlog_growth_pct,
            "status": _defense_backlog_status(backlog_growth_pct),
        },
        "revenue_coverage": {
            "value": revenue_coverage,
            "revenue_base": revenue_base,
            "status": _defense_coverage_status(revenue_coverage),
        },
        "fixed_orders": {
            "value": fixed_current,
            "share_pct": fixed_share_pct,
            "previous_share_pct": fixed_previous_share_pct,
            "share_change_pp": fixed_share_change_pp,
            "status": _defense_fixed_orders_status(fixed_share_pct),
        },
        "book_to_bill": {
            "value": book_to_bill,
            "is_lower_bound": bool(snapshot.get("book_to_bill_is_lower_bound")),
            "period": snapshot.get("book_to_bill_period"),
            "status": _defense_book_to_bill_status(book_to_bill),
        },
        "near_term_fixed_coverage": {
            "value_pct": near_term_coverage,
            "horizon": snapshot.get("near_term_horizon"),
            "status": _defense_near_term_status(near_term_coverage),
        },
        "margin_trend": margin,
        "kratos_growth_visibility": kratos_growth,
        "kratos_earnings_credibility": kratos_earnings,
        "kratos_owner_operating_earnings": kratos_owner_operating if symbol_text == "KTOS" else None,
        "kratos_fy26_profitability_bridge": kratos_profitability_bridge if symbol_text == "KTOS" else None,
        "kratos_2027_horizon_lock": kratos_2027_horizon if symbol_text == "KTOS" else None,
        "kratos_cashflow_context": kratos_cashflow,
    }

    defense_v2 = specialist_model if isinstance(specialist_model, dict) else {}
    if symbol_text in {"RHM.DE", "RHM.F", "RNMBY", "RNMBF"} and defense_v2.get("applicable"):
        checks["defense_specialist_score"] = defense_v2.get("specialist_score") or {}
        checks["defense_earnings_basis"] = defense_v2.get("earnings_basis") or {}
        checks["defense_specialist_valuation"] = defense_v2.get("specialist_valuation") or {}

    core_statuses = [
        checks["backlog"]["status"],
        checks["revenue_coverage"]["status"],
        checks["fixed_orders"]["status"],
        checks["book_to_bill"]["status"],
        checks["margin_trend"]["overall_status"],
    ]

    insufficient_count = core_statuses.count("Daten unzureichend")
    weak_count = core_statuses.count("Schwach")
    strong_count = sum(
        status in ["Stark", "Sehr stark", "Positiv"]
        for status in core_statuses
    )

    if not snapshot_fresh:
        overall_status = "Daten veraltet"
        released = False
        confidence_cap = "Niedrig"
    elif insufficient_count >= 2:
        overall_status = "Nicht freigegeben"
        released = False
        confidence_cap = "Niedrig"
    elif weak_count >= 1:
        overall_status = "Warnung"
        released = True
        confidence_cap = "Mittel"
    elif strong_count >= 4:
        overall_status = "Stark"
        released = True
        confidence_cap = "Hoch"
    else:
        overall_status = "Ausreichend"
        released = True
        confidence_cap = "Mittel"

    # V2.20.114: Rheinmetall specialist score/earnings/multiple remain the frozen valuation path.
    if symbol_text in {"RHM.DE", "RHM.F", "RNMBY", "RNMBF"} and defense_v2.get("applicable"):
        if not snapshot_fresh or not defense_v2.get("valuation_anchor_complete"):
            overall_status = "Defense-V2 nicht freigegeben"
            released = False
            confidence_cap = "Niedrig"
        else:
            overall_status = "High-Growth Prime Specialist Model freigegeben"
            released = True
            confidence_cap = "Mittel"

    # KTOS V2.20.72: primary-source growth/visibility, owner-operating adjustment quality and the
    # FY26 profitability bridge are usable, but valuation remains deliberately fail-closed because
    # a 2027 operating earnings horizon is not yet company-guided. This does not alter Rheinmetall.
    if symbol_text == "KTOS":
        if not snapshot_fresh:
            overall_status = "Daten veraltet"
        else:
            overall_status = "FY26 Growth/Owner-Operating bestätigt · 2027 Earnings-Horizont gesperrt"
        released = False
        confidence_cap = "Niedrig"

    control.update({
        "implemented": True,
        "released": released,
        "confidence_cap": confidence_cap,
        "step3b_status": (
            f"{APP_BUILD_VERSION} Defense High-Growth Prime Specialist Model V2 vollständig – Fair Value freigegeben"
            if symbol_text in {"RHM.DE", "RHM.F", "RNMBY", "RNMBF"} and released
            else (
                "Kratos FY26 Primärdaten + Profitabilitätsbrücke vollständig – 2027 Earnings-Horizont noch gesperrt"
                if symbol_text == "KTOS" and snapshot_fresh
                else ("Schritt 3B vollständig – Fair Value freigegeben" if released else "Schritt 3B nicht freigegeben")
            )
        ),
        "overall_status": overall_status,
        "snapshot_fresh": snapshot_fresh,
        "snapshot": snapshot,
        "checks": checks,
        "note": (
            (
                "V2.20.72 klassifiziert Kratos als Defense-Tech-/Unmanned-&-Advanced-Systems-Anbieter und validiert Backlog/Funded Backlog, "
                "Book-to-Bill, H2-Revenue-Coverage, Margen-/Guidance-Entwicklung und den investitionsbelasteten FCF. Zusätzlich zerlegt das Owner-Operating Gate "
                "die Adjusted-EPS-Addbacks nach wirtschaftlicher Qualität und die FY26-Guidance-Brücke zeigt Operating Income, D&A, SBC und Adjusted EBITDA getrennt. "
                "Die Spezialkontrolle verändert den 100-Punkte-Multiple-Score nicht. Ein Kratos-Fair-Value bleibt gesperrt, bis eine belastbare operative 2027-Earnings-Basis aus vollständiger Unternehmensguidance ableitbar ist."
            )
            if symbol_text == "KTOS"
            else (
                f"{APP_BUILD_VERSION} Defense V2: Backlog/Fixed Orders, Revenue Coverage, organische Guidance, Operating Margin/Result, Same-Basis-Earnings-Trajectory, Cash Conversion, Bilanz und Execution bestimmen den eigenen Specialist Score und das Ziel-KGV. "
                "Generischer Umsatz-/Gewinnwachstums-, ROE-, Yahoo-FCF- und Net-Debt/FCF-Score bleiben ausschließlich Diagnosekontext."
                if symbol_text in {"RHM.DE", "RHM.F", "RNMBY", "RNMBF"}
                else "Die Defense-Spezialkontrolle prüft Backlog, Revenue Coverage, Fixed Orders, Book-to-Bill und Margentrend. Sie verändert den 100-Punkte-Multiple-Score nicht."
            )
        ),
    })

    return control


