def resolve_fundamental_symbol(selected_symbol, company_name=None):
    """
    Return a verified primary symbol for fundamentals when we have explicitly
    established one. Unknown secondary listings are NOT guessed.

    The selected symbol always remains the trading/price source.
    """
    symbol = str(selected_symbol or "").strip().upper()
    name = str(company_name or "").strip().upper()

    # V2.20.32 – verified ADR/share-unit routes. These must be handled
    # before the ordinary secondary-listing routes because the selected quote
    # unit is not one-for-one with the primary common share.
    share_unit_route = VERIFIED_SHARE_UNIT_ROUTES.get(symbol)
    if isinstance(share_unit_route, dict):
        target = str(share_unit_route.get("fundamental_symbol") or "").strip().upper()
        if target:
            return {
                "symbol": target,
                "separate_source": target != symbol,
                "reason": "Verifizierte ADR-/Primäraktien-Route",
                "share_unit_sensitive": True,
                "fundamental_shares_per_quote_unit": share_unit_route.get(
                    "fundamental_shares_per_quote_unit"
                ),
            }

    exact_routes = {
        # Cisco: German secondary listings -> Nasdaq primary fundamentals.
        "CIS.DE": "CSCO",
        "CIS.F": "CSCO",
        "CIS.BE": "CSCO",
        "CIS.MU": "CSCO",
        "CIS.DU": "CSCO",
        "CIS.HM": "CSCO",
        "CIS.HA": "CSCO",
        "CIS.SG": "CSCO",

        # Rheinmetall Frankfurt -> XETRA primary fundamentals.
        "RHM.F": "RHM.DE",

        # LVMH US OTC line -> Euronext Paris primary fundamentals.
        "LVMHF": "MC.PA",
    }

    if symbol in exact_routes:
        return {
            "symbol": exact_routes[symbol],
            "separate_source": exact_routes[symbol] != symbol,
            "reason": "Verifizierte Hauptnotierung"
        }

    # Conservative name safeguard for Cisco German listings.
    if (
        "CISCO SYSTEMS" in name
        and symbol.startswith("CIS.")
    ):
        return {
            "symbol": "CSCO",
            "separate_source": True,
            "reason": "Verifizierte Hauptnotierung"
        }

    return {
        "symbol": symbol,
        "separate_source": False,
        "reason": "Ausgewählte Notierung"
    }


def _fast_info_value(fast_info, *names):
    """Read one value from yfinance FastInfo without assuming one API shape."""
    if fast_info is None:
        return None

    for name in names:
        try:
            value = getattr(fast_info, name)
            if value is not None:
                return value
        except Exception:
            pass

        try:
            value = fast_info.get(name)
            if value is not None:
                return value
        except Exception:
            pass

        try:
            value = fast_info[name]
            if value is not None:
                return value
        except Exception:
            pass

    return None


def _info_payload_score(info):
    """Small completeness score used only to decide whether one retry is useful."""
    if not isinstance(info, dict):
        return 0

    keys = [
        "currency",
        "sector",
        "industry",
        "marketCap",
        "trailingEps",
        "forwardEps",
        "totalRevenue",
        "netIncomeToCommon"
    ]

    return sum(
        1
        for key in keys
        if info.get(key) is not None
    )


def load_yahoo_info_resilient(symbol, ticker=None):
    """
    V2.20.2 – resilient Yahoo/yfinance info loading.

    One incomplete Yahoo quote-summary response must not immediately poison the
    15-minute Streamlit cache. The function therefore performs at most one
    fresh retry and then fills only quote-level fields that FastInfo/history
    can verify. Missing fundamentals are never invented.
    """
    primary_ticker = ticker or yf.Ticker(symbol)
    candidates = [primary_ticker]

    # A fresh Ticker object can recover from a one-off cookie/crumb/session
    # problem inside yfinance. Keep the retry count deliberately small to
    # avoid causing rate-limit pressure.
    try:
        candidates.append(yf.Ticker(symbol))
    except Exception:
        pass

    merged = {}
    first_score = None
    retry_used = False

    for index, candidate in enumerate(candidates[:2]):
        payload = {}

        try:
            get_info = getattr(candidate, "get_info", None)
            if callable(get_info):
                value = get_info()
                if isinstance(value, dict):
                    payload = value
            else:
                value = candidate.info
                if isinstance(value, dict):
                    payload = value
        except Exception:
            try:
                value = candidate.info
                if isinstance(value, dict):
                    payload = value
            except Exception:
                payload = {}

        if index == 0:
            first_score = _info_payload_score(payload)

        for key, value in payload.items():
            if value is not None and merged.get(key) is None:
                merged[key] = value

        if _info_payload_score(merged) >= 5:
            break

        if index == 0:
            retry_used = True

    fast_info_used = False

    try:
        fast_info = primary_ticker.fast_info
    except Exception:
        fast_info = None

    fast_map = {
        "currentPrice": ("last_price", "lastPrice"),
        "regularMarketPrice": ("last_price", "lastPrice"),
        "previousClose": ("previous_close", "previousClose", "regularMarketPreviousClose"),
        "currency": ("currency",),
        "exchange": ("exchange",),
        "marketCap": ("market_cap", "marketCap"),
        "sharesOutstanding": ("shares", "shares_outstanding", "sharesOutstanding"),
        "quoteType": ("quote_type", "quoteType")
    }

    for target_key, source_names in fast_map.items():
        if merged.get(target_key) is None:
            value = _fast_info_value(
                fast_info,
                *source_names
            )
            if value is not None:
                merged[target_key] = value
                fast_info_used = True

    history_used = False

    if (
        merged.get("currentPrice") is None
        and merged.get("regularMarketPrice") is None
        and merged.get("previousClose") is None
    ):
        try:
            history = primary_ticker.history(
                period="5d",
                auto_adjust=False
            )
            if (
                history is not None
                and not history.empty
                and "Close" in history
            ):
                closes = history["Close"].dropna()
                if not closes.empty:
                    close_value = safe_float(
                        closes.iloc[-1]
                    )
                    if close_value is not None:
                        merged["regularMarketPrice"] = close_value
                        history_used = True
        except Exception:
            pass

    final_score = _info_payload_score(merged)
    incomplete = final_score < 5

    if incomplete:
        note = (
            "Yahoo/yfinance hat aktuell nur einen Teil der Fundamentaldaten "
            "geliefert. Die App hat einen frischen Abruf sowie sichere "
            "Quote-Fallbacks versucht. Weiter fehlende Werte werden nicht "
            "geschätzt; davon abhängige Bewertungsschritte bleiben gesperrt."
        )
    elif retry_used or fast_info_used or history_used or (first_score is not None and first_score < final_score):
        note = (
            "Yahoo-Daten-Recovery aktiv: Ein unvollständiger Erstabruf wurde "
            "durch einen frischen Yahoo/yfinance-Abruf bzw. sichere "
            "Quote-Fallbacks ergänzt."
        )
    else:
        note = None

    return {
        "info": merged,
        "incomplete": incomplete,
        "note": note,
        "retry_used": retry_used,
        "fast_info_used": fast_info_used,
        "history_used": history_used,
        "first_score": first_score,
        "final_score": final_score
    }


# =========================================================
# V2.20.4 – Yahoo Statement / Analyst Recovery
# =========================================================

def _safe_dataframe(value):
    """Return a DataFrame or an empty frame without propagating Yahoo errors."""
    return value if isinstance(value, pd.DataFrame) else pd.DataFrame()


def _ticker_frame(ticker, property_names, method_calls=None):
    """Load the first non-empty yfinance statement/analysis table available."""
    method_calls = method_calls or []

    for method_name, kwargs in method_calls:
        try:
            method = getattr(ticker, method_name, None)
            if callable(method):
                value = method(**kwargs)
                frame = _safe_dataframe(value)
                if not frame.empty:
                    return frame
        except Exception:
            pass

    for property_name in property_names:
        try:
            value = getattr(ticker, property_name, None)
            frame = _safe_dataframe(value)
            if not frame.empty:
                return frame
        except Exception:
            pass

    return pd.DataFrame()


def _statement_label_key(value):
    """Normalize Yahoo/yfinance statement labels across spacing/camel-case variants."""
    return "".join(
        char.lower()
        for char in str(value or "")
        if char.isalnum()
    )


def _statement_series(frame, row_names):
    """Return one numeric statement metric sorted newest to oldest.

    V2.20.6 is deliberately tolerant of Yahoo/yfinance label variants such as
    ``Total Revenue`` vs. ``TotalRevenue`` and of tables that arrive transposed.
    Only exact normalized-label matches are accepted; no fuzzy guessing is used.
    """
    if frame is None or getattr(frame, "empty", True):
        return []

    wanted = [_statement_label_key(name) for name in row_names]

    index_map = {
        _statement_label_key(index_value): index_value
        for index_value in frame.index
    }
    column_map = {
        _statement_label_key(column): column
        for column in frame.columns
    }

    series = None

    # Normal yfinance orientation: metrics are rows, dates are columns.
    for key in wanted:
        selected_index = index_map.get(key)
        if selected_index is None:
            continue
        try:
            series = frame.loc[selected_index]
        except Exception:
            series = None
        if isinstance(series, pd.DataFrame):
            if series.empty:
                series = None
            else:
                series = series.iloc[0]
        if series is not None:
            break

    # Defensive fallback: some intermediate/table variants can be transposed.
    if series is None:
        for key in wanted:
            selected_column = column_map.get(key)
            if selected_column is None:
                continue
            try:
                series = frame[selected_column]
            except Exception:
                series = None
            if isinstance(series, pd.DataFrame):
                if series.empty:
                    series = None
                else:
                    series = series.iloc[:, 0]
            if series is not None:
                break

    if series is None:
        return []

    values = []
    for date_label, raw_value in series.items():
        value = safe_float(raw_value)
        if value is None:
            continue

        try:
            date_value = pd.to_datetime(date_label)
        except Exception:
            date_value = date_label

        values.append({
            "date": date_value,
            "value": value,
        })

    def sort_key(item):
        date_value = item.get("date")
        try:
            return pd.Timestamp(date_value)
        except Exception:
            return pd.Timestamp.min

    values.sort(key=sort_key, reverse=True)
    return values


def _latest_statement_value(frame, row_names):
    values = _statement_series(frame, row_names)
    return values[0]["value"] if values else None


def _sum_latest_statement_values(frame, row_names, required=4):
    values = _statement_series(frame, row_names)
    numeric = [item["value"] for item in values[:required]]
    if len(numeric) < required:
        return None
    return float(sum(numeric))


def _yoy_from_quarterly_statement(frame, row_names):
    """Latest reported quarter versus the corresponding quarter one year ago."""
    values = _statement_series(frame, row_names)
    if len(values) < 5:
        return None

    current = safe_float(values[0].get("value"))
    prior = safe_float(values[4].get("value"))

    if current is None or prior is None or abs(prior) < 1e-12:
        return None

    # When the denominator is negative, a percentage growth number is often
    # economically misleading. Keep it missing rather than manufacture a score.
    if prior < 0:
        return None

    return current / prior - 1.0


def _estimate_row_value(frame, row_name, candidates=("avg", "average", "current", "currentestimate")):
    if frame is None or getattr(frame, "empty", True):
        return None
    index_lookup = {str(v).strip().lower(): v for v in frame.index}
    column_lookup = {str(c).strip().lower(): c for c in frame.columns}
    row_key = index_lookup.get(str(row_name).strip().lower())
    if row_key is None:
        return None
    for candidate in candidates:
        column_key = column_lookup.get(candidate)
        if column_key is None:
            continue
        try:
            value = safe_float(frame.loc[row_key, column_key])
        except Exception:
            value = None
        if value is not None and value > 0:
            return value
    return None


def _estimate_row_analyst_count(frame, row_name):
    if frame is None or getattr(frame, "empty", True):
        return None
    index_lookup = {str(v).strip().lower(): v for v in frame.index}
    column_lookup = {str(c).strip().lower(): c for c in frame.columns}
    row_key = index_lookup.get(str(row_name).strip().lower())
    if row_key is None:
        return None
    for candidate in ["numberofanalysts", "number of analysts", "analysts"]:
        column_key = column_lookup.get(candidate)
        if column_key is None:
            continue
        try:
            value = safe_float(frame.loc[row_key, column_key])
        except Exception:
            value = None
        if value is not None and value >= 0:
            return int(round(value))
    return None


def _analyst_eps_horizon_context(ticker):
    """V2.20.76 – load current-FY (0Y) and next-FY (+1Y) separately.

    The old recovery path deliberately preferred +1Y. That was useful as a
    forward consensus, but unsafe for generic TTM normalization because it can
    compare trailing GAAP earnings directly with a fiscal year two horizons
    away. Current-FY is now the generic valuation anchor; +1Y is context only.
    """
    estimate = _ticker_frame(
        ticker,
        ["earnings_estimate"],
        method_calls=[("get_earnings_estimate", {})],
    )
    current_fy = _estimate_row_value(estimate, "0y")
    next_fy = _estimate_row_value(estimate, "+1y")
    current_count = _estimate_row_analyst_count(estimate, "0y")
    next_count = _estimate_row_analyst_count(estimate, "+1y")

    if current_fy is None and next_fy is None:
        eps_trend = _ticker_frame(
            ticker,
            ["eps_trend"],
            method_calls=[("get_eps_trend", {})],
        )
        current_fy = _estimate_row_value(eps_trend, "0y")
        next_fy = _estimate_row_value(eps_trend, "+1y")
        current_count = current_count or _estimate_row_analyst_count(eps_trend, "0y")
        next_count = next_count or _estimate_row_analyst_count(eps_trend, "+1y")
        source = "Yahoo EPS Trend"
    else:
        source = "Yahoo Analyst Consensus"

    return {
        "current_fy_eps": current_fy,
        "next_fy_eps": next_fy,
        "current_fy_analyst_count": current_count,
        "next_fy_analyst_count": next_count,
        "source": source if (current_fy is not None or next_fy is not None) else None,
    }


def _analyst_forward_eps(ticker):
    """Compatibility recovery: prefer current fiscal-year consensus, not +1Y."""
    ctx = _analyst_eps_horizon_context(ticker)
    value = safe_float(ctx.get("current_fy_eps"))
    if value is not None and value > 0:
        return value, "Yahoo Analyst Consensus (0Y / aktuelles FY)"
    value = safe_float(ctx.get("next_fy_eps"))
    if value is not None and value > 0:
        return value, "Yahoo Analyst Consensus (+1Y Fallback; Horizontkontext)"
    return None, None


# Fresh, time-bounded company guidance already verified from official issuer
# releases during the V2.20.76 cross-company review. It is used only as a
# current-fiscal-year earnings anchor; it never creates a valuation corridor.
VERIFIED_CURRENT_FY_EPS_GUIDANCE = {
    "SYK": {"fiscal_year": 2026, "basis": "Adjusted EPS", "low": 14.95, "high": 15.10, "as_of": "2026-07-30", "valid_until": "2026-12-31", "source": "Stryker Q2 2026 / FY2026 guidance"},
    "CTVA": {"fiscal_year": 2026, "basis": "Operating EPS", "low": 3.60, "high": 3.80, "as_of": "2026-07-30", "valid_until": "2026-12-31", "source": "Corteva Q2 2026 / FY2026 guidance"},
    "EIX": {"fiscal_year": 2026, "basis": "Core EPS", "low": 5.90, "high": 6.20, "as_of": "2026-07-30", "valid_until": "2026-12-31", "source": "Edison International Q2 2026 guidance"},
    "TRU": {"fiscal_year": 2026, "basis": "Adjusted EPS", "low": 4.75, "high": 4.83, "as_of": "2026-07-23", "valid_until": "2026-12-31", "source": "TransUnion Q2 2026 guidance"},
    "IQV": {"fiscal_year": 2026, "basis": "Adjusted EPS", "low": 12.80, "high": 13.00, "as_of": "2026-07-28", "valid_until": "2026-12-31", "source": "IQVIA Q2 2026 guidance"},
    "UA": {"fiscal_year": 2027, "basis": "Adjusted EPS", "low": 0.08, "high": 0.12, "as_of": "2026-08-07", "valid_until": "2027-03-31", "source": "Under Armour Q1 FY2027 guidance"},
    "UAA": {"fiscal_year": 2027, "basis": "Adjusted EPS", "low": 0.08, "high": 0.12, "as_of": "2026-08-07", "valid_until": "2027-03-31", "source": "Under Armour Q1 FY2027 guidance"},
    "POR": {"fiscal_year": 2026, "basis": "Adjusted EPS", "low": 3.33, "high": 3.53, "as_of": "2026-07-31", "valid_until": "2026-12-31", "source": "Portland General Electric Q2 2026 guidance"},
}


def _verified_current_fy_eps_guidance(symbol):
    row = VERIFIED_CURRENT_FY_EPS_GUIDANCE.get(str(symbol or "").upper())
    if not isinstance(row, dict):
        return None
    today = datetime.now().date().isoformat()
    if row.get("valid_until") and today > str(row.get("valid_until")):
        return None
    low = safe_float(row.get("low"))
    high = safe_float(row.get("high"))
    if low is None or high is None or low <= 0 or high <= 0 or high < low:
        return None
    return {**row, "mid": (low + high) / 2.0}


def build_eps_horizon_alignment(symbol, raw_forward_eps, analyst_context):
    """Choose one explicit current-FY forward basis and keep +1Y separate.

    Priority: fresh official company EPS guidance -> Yahoo 0Y/current-FY
    consensus -> raw provider Forward-EPS fallback. Official guidance is not
    used to infer GAAP comparability; the existing comparability gate still
    decides whether TTM and the chosen current-FY basis may be blended.
    """
    raw = safe_float(raw_forward_eps)
    ctx = analyst_context if isinstance(analyst_context, dict) else {}
    current_fy = safe_float(ctx.get("current_fy_eps"))
    next_fy = safe_float(ctx.get("next_fy_eps"))
    guidance = _verified_current_fy_eps_guidance(symbol)

    used = raw
    source = "Yahoo Forward-EPS (Provider-Horizont nicht bestätigt)" if raw is not None else None
    official_override = False
    if guidance is not None:
        used = safe_float(guidance.get("mid"))
        source = f"Unternehmens-Guidance FY{guidance.get('fiscal_year')} ({guidance.get('basis')})"
        official_override = True
    elif current_fy is not None and current_fy > 0:
        used = current_fy
        source = "Yahoo Analyst Consensus 0Y / aktuelles FY"

    raw_matches_next = False
    if raw is not None and next_fy is not None and next_fy > 0:
        raw_matches_next = abs(raw / next_fy - 1.0) <= 0.06

    current_vs_raw_gap = None
    if raw is not None and used is not None and raw > 0:
        current_vs_raw_gap = abs(used / raw - 1.0)

    guidance_consensus_gap = None
    if guidance is not None and current_fy is not None and current_fy > 0:
        guidance_consensus_gap = abs(guidance["mid"] / current_fy - 1.0)

    active = bool(
        official_override
        or (current_fy is not None and raw is not None and abs(current_fy / raw - 1.0) >= 0.08)
        or raw_matches_next
    )

    note_parts = []
    if official_override:
        note_parts.append(
            f"Primär-Guidance-Guard: FY{guidance.get('fiscal_year')} {guidance.get('basis')} "
            f"{guidance.get('low'):.2f}–{guidance.get('high'):.2f}; Mittelpunkt wird als aktueller FY-Anker verwendet"
        )
    elif current_fy is not None:
        note_parts.append("Horizon Alignment: 0Y/current-FY Analystenkonsens wird als Forward-Bewertungsbasis verwendet")
    if raw_matches_next:
        note_parts.append("der rohe Provider-Forward-EPS entspricht näherungsweise dem +1Y-Konsens und bleibt deshalb nur Horizont-Kontext")
    if guidance_consensus_gap is not None and guidance_consensus_gap >= 0.20:
        note_parts.append(
            f"Unternehmens-Guidance und aktueller 0Y-Konsens weichen um {guidance_consensus_gap * 100:.1f} % ab; Datenbasis vor Bewertung prüfen"
        )

    return {
        "valuation_forward_eps": used,
        "raw_forward_eps": raw,
        "current_fy_eps": current_fy,
        "next_fy_eps": next_fy,
        "current_fy_analyst_count": ctx.get("current_fy_analyst_count"),
        "next_fy_analyst_count": ctx.get("next_fy_analyst_count"),
        "source": source,
        "analyst_source": ctx.get("source"),
        "active": active,
        "raw_matches_next_fy": raw_matches_next,
        "raw_vs_used_gap": current_vs_raw_gap,
        "primary_guidance_override": official_override,
        "guidance": guidance,
        "guidance_consensus_gap": guidance_consensus_gap,
        "attention_required": bool(
            (guidance_consensus_gap is not None and guidance_consensus_gap >= 0.20)
            or (used is not None and guidance is None and current_fy is None)
        ),
        "note": "; ".join(note_parts) if note_parts else None,
    }



# =========================================================
# V2.20.79 – Generic Primary-Source Adjusted-TTM Reconstructor
# =========================================================

def _generic_period_components(period):
    p = _clean_text(period).upper().replace("–", "-")
    m = re.fullmatch(r"FY\s*(20\d{2})", p)
    if m:
        return {"kind": "FY", "year": int(m.group(1)), "quarter": None}
    m = re.fullmatch(r"Q([1-4])\s*(20\d{2})", p)
    if m:
        return {"kind": "Q", "year": int(m.group(2)), "quarter": int(m.group(1))}
    return None


def _generic_eps_period_aliases(period):
    comp = _generic_period_components(period)
    if not comp:
        p = _clean_text(period).lower()
        return [p] if p else []
    year = comp["year"]
    yy = str(year)[-2:]
    if comp["kind"] == "FY":
        return [
            f"fy{yy}", f"fy {yy}", f"fy{year}", f"fy {year}",
            f"full year {year}", f"full-year {year}",
            f"fiscal year {year}", str(year),
        ]
    q = comp["quarter"]
    words = ["first", "second", "third", "fourth"]
    return [
        f"q{q}{yy}", f"q{q} {yy}", f"q{q}{year}", f"q{q} {year}",
        f"{q}q{yy}", f"{q}q {yy}", f"{q}q{year}", f"{q}q {year}",
        f"{words[q-1]} quarter {year}", f"{words[q-1]}-quarter {year}",
    ]


def _generic_parse_eps_number(value):
    raw = str(value or "").strip().replace("$", "").replace("€", "")
    raw = raw.replace("*", "").replace("†", "").replace("‡", "")
    negative = raw.startswith("(") and raw.endswith(")")
    raw = raw.strip("() ").replace(",", "")
    m = re.search(r"-?\d+(?:\.\d+)?", raw)
    if not m:
        return None
    try:
        out = float(m.group(0))
    except Exception:
        return None
    if negative:
        out = -abs(out)
    if abs(out) > 100:
        return None
    return out


def _generic_eps_basis_from_label(label):
    """Return only explicitly per-share non-GAAP earnings rows.

    Do not treat Adjusted EBIT/EBITDA or other adjusted metrics as EPS merely
    because the word 'adjusted' appears in the row label.
    """
    t = _clean_text(label).lower().replace("–", "-")
    per_share = any(x in t for x in [
        "eps", "earnings per share", "earnings per diluted share",
        "diluted earnings per share", "per diluted share",
    ])
    if not per_share:
        return None, None
    if "adjusted" in t or "non-gaap" in t or "non gaap" in t:
        return "Adjusted EPS", "adjusted"
    if "core" in t:
        return "Core EPS", "core"
    if "operating" in t:
        return "Operating EPS", "operating"
    return None, None


def _generic_title_period_context(title):
    """Best-effort period context from a release title/URL hint."""
    t = _clean_text(title).lower().replace("–", "-")
    if not t:
        return None
    year_match = re.search(r"\b(20\d{2})\b", t)
    year = int(year_match.group(1)) if year_match else None
    q = None
    for n, word in enumerate(["first", "second", "third", "fourth"], start=1):
        if re.search(rf"\b{word}[ -]quarter\b", t):
            q = n
            break
    if q is None:
        m = re.search(r"\bq([1-4])\s*[' -]?(?:20)?(\d{2})\b", t)
        if m:
            q = int(m.group(1))
            if year is None:
                year = 2000 + int(m.group(2))
    if q is None:
        m = re.search(r"\b([1-4])q\s*[' -]?(?:20)?(\d{2})\b", t)
        if m:
            q = int(m.group(1))
            if year is None:
                year = 2000 + int(m.group(2))
    full_year = bool(re.search(r"\bfull[ -]year\b|\bfy\s*[' -]?(?:20)?\d{2}\b", t))
    return {"year": year, "quarter": q, "full_year": full_year}


def _generic_periods_from_header_cell(cell_text, title=None):
    """Normalize common financial-table period headers to canonical labels."""
    t = _clean_text(cell_text).upper().replace("–", "-").replace("’", "'")
    if not t:
        return []
    out = []

    def add(label):
        if label and label not in out:
            out.append(label)

    # FY25 / FY 2025 / FY'25
    for m in re.finditer(r"\bFY\s*[' -]?(\d{2}|20\d{2})\b", t):
        raw = m.group(1)
        year = int(raw) if len(raw) == 4 else 2000 + int(raw)
        add(f"FY {year}")

    # 1Q26 / 1Q 2026 / Q1 26 / Q1'26
    for m in re.finditer(r"\b([1-4])Q\s*[' -]?(\d{2}|20\d{2})\b", t):
        raw = m.group(2)
        year = int(raw) if len(raw) == 4 else 2000 + int(raw)
        add(f"Q{int(m.group(1))} {year}")
    for m in re.finditer(r"\bQ([1-4])\s*[' -]?(\d{2}|20\d{2})\b", t):
        raw = m.group(2)
        year = int(raw) if len(raw) == 4 else 2000 + int(raw)
        add(f"Q{int(m.group(1))} {year}")

    # First/second/... quarter 2026.
    words = {"FIRST": 1, "SECOND": 2, "THIRD": 3, "FOURTH": 4}
    for word, q in words.items():
        m = re.search(rf"\b{word}[ -]QUARTER\b.*?\b(20\d{{2}})\b", t)
        if m:
            add(f"Q{q} {int(m.group(1))}")

    # Full year 2025 / fiscal year 2025.
    m = re.search(r"\b(?:FULL[ -]YEAR|FISCAL YEAR)\b.*?\b(20\d{2})\b", t)
    if m:
        add(f"FY {int(m.group(1))}")

    # Year-only table columns are common (2026 | 2025). They are safe only
    # when the release title fixes the period family (e.g. First Quarter 2026).
    if re.fullmatch(r"20\d{2}", t.strip()):
        year = int(t.strip())
        ctx = _generic_title_period_context(title)
        if ctx and ctx.get("quarter"):
            add(f"Q{ctx['quarter']} {year}")
        elif ctx and ctx.get("full_year"):
            add(f"FY {year}")

    return out


def _generic_table_period_map(rows, upto_row, title=None):
    """Map table column index -> canonical periods found anywhere above EPS row."""
    by_col = {}
    # Financial tables often place the period header many rows above EPS. Scan
    # all rows above the target line, but only retain cells that normalize to a
    # period; ordinary numeric data never enters this map.
    for hrow in rows[:max(0, upto_row)]:
        for cidx, cell in enumerate(hrow):
            periods = _generic_periods_from_header_cell(cell, title=title)
            if periods:
                bucket = by_col.setdefault(cidx, [])
                for p in periods:
                    if p not in bucket:
                        bucket.append(p)
    return by_col


def _generic_primary_eps_from_html(html, expected_period, title=None):
    """Extract one explicitly labelled adjusted/core/operating EPS table cell.

    Period matching is table-aware and accepts common issuer shorthand such as
    FY25, 1Q26 and year-only current/prior columns when the release title fixes
    the quarter. No numeric column is accepted without an explicit period map.
    """
    if not html or not expected_period:
        return None
    expected = _clean_text(expected_period).upper()
    if not _generic_period_components(expected):
        return None
    try:
        soup = BeautifulSoup(html, "html.parser")
    except Exception:
        return None

    candidates = []
    for table in soup.find_all("table"):
        rows = []
        for tr in table.find_all("tr"):
            cells = [_clean_text(c.get_text(" ", strip=True)) for c in tr.find_all(["th", "td"])]
            if cells:
                rows.append(cells)
        if not rows:
            continue

        for ridx, row in enumerate(rows):
            if not row:
                continue
            # Some issuers indent the metric into a second cell. Restrict the
            # label probe to the first two cells so values cannot become labels.
            label_candidates = [row[0]]
            if len(row) > 1 and _generic_parse_eps_number(row[1]) is None:
                label_candidates.append(_clean_text(f"{row[0]} {row[1]}"))
            basis_label = family = None
            row_label = row[0]
            for label in label_candidates:
                basis_label, family = _generic_eps_basis_from_label(label)
                if family:
                    row_label = label
                    break
            if not family or len(row) < 2:
                continue

            period_map = _generic_table_period_map(rows, ridx, title=title)
            exact_columns = [
                cidx for cidx in range(1, len(row))
                if expected in (period_map.get(cidx) or [])
            ]

            # Last-resort current-period fallback only for a simple two-value
            # release summary whose title exactly fixes the requested period.
            # Prior-period extraction still requires an explicit prior header.
            if not exact_columns:
                ctx = _generic_title_period_context(title)
                comp = _generic_period_components(expected)
                if (
                    comp and ctx and comp.get("kind") == "Q"
                    and ctx.get("quarter") == comp.get("quarter")
                    and ctx.get("year") == comp.get("year")
                    and len(row) in (2, 3)
                ):
                    exact_columns = [1]

            for cidx in exact_columns:
                value = _generic_parse_eps_number(row[cidx] if cidx < len(row) else None)
                if value is None or value <= 0:
                    continue
                header_periods = period_map.get(cidx) or []
                score = 100 + (50 if expected in header_periods else 0)
                if "diluted" in row_label.lower():
                    score += 10
                candidates.append({
                    "period": expected,
                    "eps": value,
                    "basis": basis_label,
                    "basis_family": family,
                    "row_label": row_label,
                    "column_header": " / ".join(header_periods),
                    "score": score,
                })

    if not candidates:
        return None
    candidates.sort(key=lambda r: r.get("score", 0), reverse=True)
    return candidates[0]

def _generic_primary_eps_from_rendered_text(page_text, expected_period, title=None):
    """Strict fallback for issuer pages whose rendered financial grid is not a literal HTML table.

    The fallback accepts only explicitly labelled Adjusted/Core/Operating EPS rows and
    only when a nearby ordered period-header sequence can be paired with the row's
    first numeric cells. It never infers a missing prior period from value order alone.
    """
    text = _clean_text(page_text)
    expected = _clean_text(expected_period).upper()
    if not text or not _generic_period_components(expected):
        return None

    # Match only per-share non-GAAP rows. Keep the expression short enough that an
    # unrelated adjusted metric cannot bridge into a later EPS phrase.
    label_re = re.compile(
        r"(?P<label>(?:adjusted|core|operating|non[- ]?gaap)\s+"
        r"(?:earnings\s+per\s+diluted\s+share|diluted\s+earnings\s+per\s+share|"
        r"earnings\s+per\s+share|diluted\s+eps|eps))\s*[*†‡]*",
        re.IGNORECASE,
    )

    def period_tokens(segment):
        found = []
        token_re = re.compile(
            r"\b(?:FY\s*[' -]?(?:\d{2}|20\d{2})|[1-4]Q\s*[' -]?(?:\d{2}|20\d{2})|"
            r"Q[1-4]\s*[' -]?(?:\d{2}|20\d{2}))\b",
            re.IGNORECASE,
        )
        for m in token_re.finditer(segment):
            labels = _generic_periods_from_header_cell(m.group(0), title=title)
            for label in labels:
                found.append((m.start(), label, m.group(0)))
        return found

    candidates = []
    for lm in label_re.finditer(text):
        label = _clean_text(lm.group("label"))
        basis_label, family = _generic_eps_basis_from_label(label)
        if not family:
            continue

        # Financial headers normally sit shortly before the EPS row. Restrict the
        # window so a quarter mentioned in narrative prose cannot become a header.
        pre = text[max(0, lm.start() - 900):lm.start()]
        tokens = period_tokens(pre)
        headers = []
        if tokens:
            # Prefer the most recent header cluster. A new cluster is assumed when
            # shorthand tokens are separated by more than 180 rendered characters.
            cluster = [tokens[-1]]
            for item in reversed(tokens[:-1]):
                if cluster[0][0] - item[0] > 180:
                    break
                cluster.insert(0, item)
            for _, canon, raw in cluster:
                if canon not in [h[0] for h in headers]:
                    headers.append((canon, raw))

        # Some renderers flatten a Q release to year-only columns (2026 | 2025).
        # Accept those only when the document title fixes the quarter/full-year family.
        if not headers:
            ctx = _generic_title_period_context(title)
            if ctx and (ctx.get("quarter") or ctx.get("full_year")):
                year_hits = list(re.finditer(r"\b20\d{2}\b", pre[-320:]))
                years = []
                for ym in year_hits[-4:]:
                    y = int(ym.group(0))
                    if y not in years:
                        years.append(y)
                for y in years[-2:]:
                    canon = f"Q{ctx['quarter']} {y}" if ctx.get("quarter") else f"FY {y}"
                    headers.append((canon, str(y)))

        if not headers or expected not in [h[0] for h in headers]:
            continue

        # Values immediately following the EPS label belong to the row in rendered
        # order. Limit both distance and count; do not scan into later metrics.
        after = text[lm.end():lm.end() + 220]
        num_re = re.compile(r"(?<![A-Za-z0-9])(?:\(\s*)?-?\$?\s*\d{1,2}(?:\.\d{1,4})?(?:\s*\))?")
        values = []
        for nm in num_re.finditer(after):
            val = _generic_parse_eps_number(nm.group(0))
            if val is None:
                continue
            values.append(val)
            if len(values) >= len(headers):
                break
        if len(values) < len(headers):
            continue

        for idx, (canon, raw_header) in enumerate(headers):
            if canon != expected:
                continue
            value = values[idx]
            if value <= 0 or value > 100:
                continue
            candidates.append({
                "period": expected,
                "eps": value,
                "basis": basis_label,
                "basis_family": family,
                "row_label": label,
                "column_header": raw_header,
                "score": 80 + (10 if "diluted" in label.lower() else 0),
                "parser_mode": "rendered-text-fallback",
            })

    if not candidates:
        return None
    candidates.sort(key=lambda r: r.get("score", 0), reverse=True)
    return candidates[0]


def _generic_period_search_phrases(period):
    p = str(period or "").strip().upper()
    fy = re.fullmatch(r"FY\s+(20\d{2})", p)
    if fy:
        y = fy.group(1)
        return [f'"full-year {y}"', f'"full year {y}"', f'"{y} results"']
    q = re.fullmatch(r"Q([1-4])\s+(20\d{2})", p)
    if q:
        n, y = int(q.group(1)), q.group(2)
        word = ["first", "second", "third", "fourth"][n - 1]
        return [f'"{word}-quarter {y}"', f'"{word} quarter {y}"', f'"Q{n} {y}"']
    return [f'"{period}"']


def _generic_period_year(period):
    m = re.search(r"(20\d{2})", str(period or ""))
    return int(m.group(1)) if m else None


def _generic_period_doc_score(row, period):
    """Rank one official-company link for a requested FY/quarter release.

    V2.20.84 strictly separates *results documents* from all other corporate-news pages and preview/scheduling
    pages. A title such as "Schedules full-year results release" can contain
    exactly the same period words as the real release but has no financial table;
    letting it outrank the actual result page wastes the bounded research budget.
    """
    if not isinstance(row, dict):
        return -10_000
    url = _clean_text(row.get("url"))
    title = _clean_text(row.get("title"))
    hay = _clean_text(f"{title} {unquote(url)}").lower().replace("–", "-")
    p = str(period or "").strip().upper()
    year = _generic_period_year(p)
    if not hay or year is None or str(year) not in hay:
        return -10_000

    # This parser consumes issuer HTML releases. PDFs, conference-call/event
    # pages and pre-release scheduling notices are not valid candidates here.
    if url.lower().split("?", 1)[0].endswith(".pdf"):
        return -10_000
    hard_reject = [
        "conference call", "webcast", "transcript", "prepared remarks",
        "presentation", "event-details", "events-and-presentations",
        "schedules ", "scheduled ", "release scheduled", "results release scheduled",
        "to announce", "will announce", "will report", "release date",
        "earnings date", "results date",
    ]
    if any(token in hay for token in hard_reject):
        return -10_000

    # V2.20.84: hard semantic allow-list. A corporate-news page that merely
    # carries the requested year in its URL must never become an EPS document.
    # Require both a reporting-period signal and a real earnings/results signal
    # in title/URL before any generic link_score can contribute.
    result_anchor = bool(
        re.search(r"\b(?:financial|earnings|quarterly|annual)\s+(?:results?|release)\b", hay)
        or re.search(r"\b(?:announces?|reports?|reported)\b.{0,120}\bresults?\b", hay)
        or re.search(r"\b(?:results?|earnings)\b.{0,80}\b(?:quarter|full[- ]year|fy\s*20\d{2})\b", hay)
    )
    period_anchor = False
    if p.startswith("FY "):
        period_anchor = bool(
            re.search(rf"\b(?:full[- ]year|fy)\s*[' -]?(?:{str(year)[-2:]}|{year})\b", hay)
            or (str(year) in hay and re.search(r"\bfourth[- ]quarter\b", hay))
        )
    else:
        qmatch = re.match(r"Q([1-4])", p)
        qn = int(qmatch.group(1)) if qmatch else None
        if qn:
            word = ["first", "second", "third", "fourth"][qn - 1]
            period_anchor = bool(
                re.search(rf"\b{word}[- ]quarter\b", hay)
                or re.search(rf"\bq{qn}\s*[' -]?(?:{str(year)[-2:]}|{year})\b", hay)
                or re.search(rf"\b{qn}q\s*[' -]?(?:{str(year)[-2:]}|{year})\b", hay)
            )
    if not (result_anchor and period_anchor):
        return -10_000

    score = float(row.get("link_score") or 0) * 0.05
    # Prefer actual result releases over generic archive/resource pages.
    if re.search(r"\b(?:announces?|reports?)\b.{0,90}\b(?:financial|earnings)\b.{0,45}\bresults?\b", hay):
        score += 260
    elif re.search(r"\b(?:financial|earnings|quarterly|annual)\b.{0,45}\bresults?\b", hay):
        score += 90
    if any(x in hay for x in ["news-stories", "news-release", "press-release"]):
        score += 35
    aliases = [a.lower().replace("–", "-") for a in _generic_eps_period_aliases(p)]
    if any(a and a in hay for a in aliases):
        score += 180
    title_period = _document_period_from_title(title)
    if title_period == p:
        score += 220
    if p.startswith("FY "):
        if any(x in hay for x in ["full-year", "full year", "fourth-quarter and full-year", "fourth quarter and full year"]):
            score += 170
        if re.search(r"\bq[123]\b|\b(?:first|second|third) quarter\b", hay):
            score -= 100
    else:
        q = re.match(r"Q([1-4])", p)
        qn = int(q.group(1)) if q else None
        if qn:
            word = ["first", "second", "third", "fourth"][qn - 1]
            if word + " quarter" in hay or word + "-quarter" in hay or f"q{qn}" in hay or f"{qn}q" in hay:
                score += 120
    if any(x in hay for x in ["financial results", "earnings results", "reports", "earnings release", "results release"]):
        score += 45
    if any(x in hay for x in ["press release", "news-stories", "news/", "news-release"]):
        score += 25
    # PDF/event/preview candidates were already fail-closed above.
    if any(x in hay for x in ["dividend", "sustainability", "career", "product launch"]):
        score -= 100
    return score


def _generic_router_period_candidates(ir_router, period, limit=5):
    router = ir_router if isinstance(ir_router, dict) else {}
    rows = []
    year = _generic_period_year(period)
    if year is not None:
        rows.extend((router.get("documents_by_year") or {}).get(year, []) or [])
    rows.extend(router.get("official_links") or [])
    rows.extend(router.get("entrypoints") or [])
    unique = {}
    for row in rows:
        if not isinstance(row, dict) or not row.get("url"):
            continue
        url = _clean_text(row.get("url"))
        score = _generic_period_doc_score(row, period)
        if score <= 0:
            continue
        item = dict(row)
        item["generic_period_score"] = score
        old = unique.get(url)
        if old is None or score > old.get("generic_period_score", -10_000):
            unique[url] = item
    ranked = sorted(unique.values(), key=lambda r: r.get("generic_period_score", 0), reverse=True)
    return ranked[:max(1, int(limit))]


def _generic_diag_attempt(diag, period, url, source, status, note=None, found_periods=None, title=None):
    if not isinstance(diag, dict):
        return
    item = {
        "period": period,
        "url": url,
        "source": source,
        "status": status,
        "note": note,
        "title": _clean_text(title),
        "found_periods": list(found_periods or []),
    }
    key = (
        _clean_text(period), _clean_text(url), _clean_text(source),
        _clean_text(status), _clean_text(note), _clean_text(item.get("title")), tuple(item["found_periods"]),
    )
    for existing in diag.setdefault("attempted_documents", []):
        existing_key = (
            _clean_text(existing.get("period")), _clean_text(existing.get("url")),
            _clean_text(existing.get("source")), _clean_text(existing.get("status")),
            _clean_text(existing.get("note")), _clean_text(existing.get("title")), tuple(existing.get("found_periods") or []),
        )
        if existing_key == key:
            return
    diag["attempted_documents"].append(item)


def _fetch_generic_period_records_from_candidate(
    row, company_domain, company_name, current_period, prior_period=None, deadline=None, diag=None,
    source="IR Year Navigator", document_cache=None
):
    url = _clean_text((row or {}).get("url"))
    candidate_title = _clean_text((row or {}).get("title"))
    if not url or not _host_belongs_to_company_family(url, company_domain):
        return []
    # V2.20.84 second guard: even a misclassified IR-router row cannot consume
    # parser/network budget unless its title/URL is a genuine period results release.
    semantic_score = _generic_period_doc_score(row or {}, current_period)
    if semantic_score <= 0:
        _generic_diag_attempt(
            diag, current_period, url, source, "verworfen",
            "Kein echter Earnings-/Financial-Results-Release für die angeforderte Periode",
            title=candidate_title,
        )
        return []
    cache = document_cache if isinstance(document_cache, dict) else None
    cached = cache.get(url) if cache is not None else None
    if cached is None:
        html, final_url = _fetch_html(url, timeout=2.8, deadline=deadline)
        final_url = final_url or url
        page_text = _html_to_text(html) if html else ""
        cached = {"html": html, "final_url": final_url, "page_text": page_text}
        if cache is not None:
            cache[url] = cached
    else:
        html = cached.get("html")
        final_url = cached.get("final_url") or url
        page_text = cached.get("page_text") or ""
    if not html:
        _generic_diag_attempt(diag, current_period, final_url, source, "nicht geladen", title=candidate_title)
        return []
    source_row = {"url": final_url, "title": (row or {}).get("title"), "snippet": (row or {}).get("snippet", "")}
    if not _source_matches_company(source_row, page_text, company_name, "", company_domain, True):
        _generic_diag_attempt(diag, current_period, final_url, source, "verworfen", "Unternehmenszuordnung nicht bestätigt", title=candidate_title)
        return []
    title = candidate_title or _historical_title_hint_from_url(final_url)
    found = []
    cur = _generic_primary_eps_from_html(html, expected_period=current_period, title=title)
    if cur:
        cur.setdefault("parser_mode", "html-table")
    elif page_text:
        cur = _generic_primary_eps_from_rendered_text(page_text, expected_period=current_period, title=title)
    if cur:
        found.append({**cur, "url": final_url, "title": title, "source": source})
    if prior_period:
        prev = _generic_primary_eps_from_html(html, expected_period=prior_period, title=title)
        if prev:
            prev.setdefault("parser_mode", "html-table")
        elif page_text:
            prev = _generic_primary_eps_from_rendered_text(page_text, expected_period=prior_period, title=title)
        if prev:
            found.append({**prev, "url": final_url, "title": title, "source": source})
    if prior_period and len(found) == 2 and found[0].get("basis_family") != found[1].get("basis_family"):
        _generic_diag_attempt(diag, current_period, final_url, source, "verworfen", "Current/Prior Accounting-Basis stimmt nicht überein", title=title)
        return []
    parser_modes = list(dict.fromkeys(r.get("parser_mode") for r in found if r.get("parser_mode")))
    diag_note = None
    if found:
        diag_note = "Parser: " + ", ".join(parser_modes or ["unbekannt"])
    elif page_text:
        diag_note = f"Seitentext vorhanden ({len(page_text)} Zeichen), aber keine periodenreine EPS-Zeile erkannt"
    else:
        diag_note = "Kein auswertbarer Seitentext"
    _generic_diag_attempt(
        diag, current_period, final_url, source,
        "EPS gefunden" if found else "keine passende EPS-Zeile",
        note=diag_note,
        found_periods=[r.get("period") for r in found],
        title=title,
    )
    return found


def _generic_search_release_candidates(company_domain, company_name, period, deadline=None, max_results=5):
    """Fallback discovery for one issuer earnings release, not one EPS cell.

    V2.20.86: discovery must not require an exact EPS-row phrase in the search
    engine. Search engines often index the release title/summary but not the
    financial-table row. We therefore discover by company + reporting period +
    results semantics, then let the primary-source parser validate the EPS row.
    """
    seen = set()
    out = []
    company_hint = _clean_text(company_name)
    # Progressively broaden only the *search* expression. Every returned URL is
    # still hard-validated afterwards by company-family, semantic release score,
    # reporting period and finally the primary-source EPS parser.
    query_templates = [
        'site:{domain} {company} {phrase} "financial results"',
        'site:{domain} {company} {phrase} results',
        'site:{domain} {phrase} "financial results"',
        'site:{domain} {phrase} "earnings results"',
        'site:{domain} {phrase} results',
    ]
    for phrase in _generic_period_search_phrases(period):
        for template in query_templates:
            if not _research_budget_ok(deadline, reserve=0.8):
                break
            query = template.format(domain=company_domain, phrase=phrase, company=company_hint)
            rows = _duckduckgo_html_search(query, max_results=max(max_results, 8), deadline=deadline)
            for item in rows[:max(max_results, 8)]:
                url = _clean_text(item.get("url"))
                if not url or url in seen or not _host_belongs_to_company_family(url, company_domain):
                    continue
                seen.add(url)
                item = dict(item)
                item["generic_period_score"] = _generic_period_doc_score(item, period)
                if item["generic_period_score"] <= 0:
                    continue
                item["search_query"] = query
                out.append(item)
            if out:
                break
        if out:
            break

    # Deterministic issuer-site fallback: if web search returns nothing, inspect
    # the company's own sitemap inventory for period/result URLs. This remains
    # primary-source only and passes through the same semantic guard.
    if not out and _research_budget_ok(deadline, reserve=1.2):
        year = _generic_period_year(period)
        if year is not None:
            sitemap_urls, _ = _discover_company_sitemap_inventory(
                company_domain, deadline=deadline, max_child_sitemaps=3
            )
            for url in sitemap_urls:
                if not _research_budget_ok(deadline, reserve=0.7):
                    break
                if url in seen:
                    continue
                seen.add(url)
                hint = _historical_title_hint_from_url(url)
                item = {
                    "title": hint,
                    "url": url,
                    "snippet": "Unternehmens-Sitemap / offizieller Release-Fallback",
                    "search_source": "Unternehmens-Sitemap",
                }
                score = _generic_period_doc_score(item, period)
                if score <= 0:
                    continue
                item["generic_period_score"] = score
                out.append(item)
                if len(out) >= max(max_results, 8):
                    break

    out.sort(key=lambda r: r.get("generic_period_score", 0), reverse=True)
    return out[:max_results]


def _discover_primary_adjusted_eps_period(company_domain, company_name, period, deadline=None):
    """Legacy single-period fallback retained for compatibility/tests."""
    if not company_domain or not period or not _research_budget_ok(deadline, reserve=0.8):
        return None
    for item in _generic_search_release_candidates(company_domain, company_name, period, deadline=deadline, max_results=4):
        rows = _fetch_generic_period_records_from_candidate(
            item, company_domain, company_name, period, deadline=deadline, source="Web-Fallback"
        )
        if rows:
            return rows[0]
    return None


def reconstruct_adjusted_ttm_from_period_records(records, current_fy, completed_quarters):
    """Pure period engine: FY(t-1) - Q1..Qn(t-1) + Q1..Qn(t).

    Every record must carry an explicit period, positive EPS and identical
    accounting-basis family. Missing periods or mixed basis families fail closed.
    """
    try:
        current_fy = int(current_fy)
        completed_quarters = int(completed_quarters)
    except Exception:
        return None
    if completed_quarters < 1 or completed_quarters > 3:
        return None
    rows = {str(r.get("period")): r for r in (records or []) if isinstance(r, dict)}
    required = [f"FY {current_fy - 1}"]
    required += [f"Q{q} {current_fy - 1}" for q in range(1, completed_quarters + 1)]
    required += [f"Q{q} {current_fy}" for q in range(1, completed_quarters + 1)]
    if any(p not in rows for p in required):
        return None

    families = {rows[p].get("basis_family") for p in required}
    if None in families or len(families) != 1:
        return None
    family = next(iter(families))
    basis_labels = [rows[p].get("basis") for p in required if rows[p].get("basis")]
    values = {p: safe_float(rows[p].get("eps")) for p in required}
    if any(v is None or v <= 0 for v in values.values()):
        return None

    fy_eps = values[f"FY {current_fy - 1}"]
    prior_partial = sum(values[f"Q{q} {current_fy - 1}"] for q in range(1, completed_quarters + 1))
    current_partial = sum(values[f"Q{q} {current_fy}"] for q in range(1, completed_quarters + 1))
    adjusted_ttm = fy_eps - prior_partial + current_partial
    if adjusted_ttm <= 0 or adjusted_ttm > 100:
        return None

    source_urls = list(dict.fromkeys(rows[p].get("url") for p in required if rows[p].get("url")))
    source_titles = list(dict.fromkeys(rows[p].get("title") for p in required if rows[p].get("title")))
    q_label = "+".join(f"Q{q}" for q in range(1, completed_quarters + 1))
    basis = basis_labels[0] if basis_labels else family.title() + " EPS"
    return {
        "basis": basis,
        "basis_family": family,
        "as_of": f"{current_fy}-Q{completed_quarters}",
        "method": (
            f"FY{current_fy - 1} {basis} - {q_label} {current_fy - 1} {basis} "
            f"+ {q_label} {current_fy} {basis}"
        ),
        "fy_prior": fy_eps,
        "prior_partial": prior_partial,
        "current_partial": current_partial,
        "adjusted_ttm_eps": adjusted_ttm,
        "source_name": " · ".join(source_titles[:3]) if source_titles else "Primärquellen-Rekonstruktion",
        "source_urls": source_urls,
        "period_records": [rows[p] for p in required],
        "generic_reconstructor": True,
        "completed_quarters": completed_quarters,
        "available": True,
    }


def _calendar_completed_quarter_hint(today=None):
    d = today or datetime.now().date()
    # Allow normal reporting lag: Q1 is usually available from May, Q2 from
    # August, Q3 from November. Q4 is handled by the next full-year report.
    if d.month >= 11:
        return 3
    if d.month >= 8:
        return 2
    if d.month >= 5:
        return 1
    return 0


def _generic_sibling_release_candidates(records, requested_period, company_domain, limit=4):
    """Derive a next-quarter release candidate from already validated sibling releases.

    This is a discovery shortcut only. Every synthesized URL still passes the normal
    same-company semantic release guard and primary-source EPS parser before any value
    can enter the reconstruction. It therefore cannot create data from a guessed URL.
    """
    comp = _generic_period_components(requested_period)
    if not comp or comp.get("kind") != "Q":
        return []
    qn = int(comp.get("quarter") or 0)
    year = int(comp.get("year") or 0)
    if qn < 1 or qn > 4 or year <= 0:
        return []

    words = {1: "first", 2: "second", 3: "third", 4: "fourth"}
    target_word = words[qn]
    unique = {}

    for rec in records or []:
        if not isinstance(rec, dict):
            continue
        src_period = _generic_period_components(rec.get("period"))
        if not src_period or src_period.get("kind") != "Q" or int(src_period.get("year") or 0) != year:
            continue
        src_q = int(src_period.get("quarter") or 0)
        if src_q == qn or src_q < 1 or src_q > 4:
            continue
        url = _clean_text(rec.get("url"))
        title = _clean_text(rec.get("title"))
        if not url or not _host_belongs_to_company_family(url, company_domain):
            continue
        src_word = words[src_q]

        def swap_period(text):
            out = str(text or "")
            out = re.sub(rf"(?i)\b{src_word}-quarter\b", f"{target_word}-quarter", out)
            out = re.sub(rf"(?i)\b{src_word} quarter\b", f"{target_word} quarter", out)
            out = re.sub(rf"(?i)\bq{src_q}\b", f"Q{qn}", out)
            out = re.sub(rf"(?i)\b{src_q}q\b", f"{qn}Q", out)
            return out

        candidate_url = swap_period(url)
        candidate_title = swap_period(title)
        if candidate_url == url:
            continue
        row = {
            "url": candidate_url,
            "title": candidate_title,
            "snippet": "Validated sibling earnings-release URL pattern",
            "search_source": "Sibling Release Pattern",
        }
        score = _generic_period_doc_score(row, requested_period)
        if score <= 0:
            continue
        row["generic_period_score"] = score + 40
        old = unique.get(candidate_url)
        if old is None or row["generic_period_score"] > old.get("generic_period_score", -10_000):
            unique[candidate_url] = row

    ranked = sorted(unique.values(), key=lambda r: r.get("generic_period_score", 0), reverse=True)
    return ranked[:max(1, int(limit))]


def _collect_ir_routed_period_records(ir_router, company_domain, company_name, current_fy, n, deadline, diag, document_cache=None):
    """Load prior FY plus Q1..Qn current releases; each current release supplies prior-year comparator too."""
    records = []
    fy_period = f"FY {current_fy - 1}"
    fy_candidates = _generic_router_period_candidates(ir_router, fy_period, limit=8)
    if isinstance(diag, dict):
        diag.setdefault("router_candidate_counts", {})[fy_period] = len(fy_candidates)
    loaded = False
    for row in fy_candidates:
        if not _research_budget_ok(deadline, reserve=1.0):
            break
        got = _fetch_generic_period_records_from_candidate(
            row, company_domain, company_name, fy_period, deadline=deadline, diag=diag, source="IR Year Navigator", document_cache=document_cache
        )
        if got:
            records.extend(got[:1])
            loaded = True
            break
    if not loaded:
        if isinstance(diag, dict):
            diag.setdefault("web_fallback_periods_attempted", []).append(fy_period)
        for row in _generic_search_release_candidates(company_domain, company_name, fy_period, deadline=deadline, max_results=6):
            if not _research_budget_ok(deadline, reserve=0.9):
                break
            got = _fetch_generic_period_records_from_candidate(
                row, company_domain, company_name, fy_period, deadline=deadline, diag=diag, source="Web-Fallback", document_cache=document_cache
            )
            if got:
                records.extend(got[:1])
                loaded = True
                break
    if not loaded:
        return records

    for q in range(1, n + 1):
        current_period = f"Q{q} {current_fy}"
        prior_period = f"Q{q} {current_fy - 1}"
        pair = []
        candidates = _generic_router_period_candidates(ir_router, current_period, limit=8)
        if isinstance(diag, dict):
            diag.setdefault("router_candidate_counts", {})[current_period] = len(candidates)
        for row in candidates:
            if not _research_budget_ok(deadline, reserve=1.0):
                break
            got = _fetch_generic_period_records_from_candidate(
                row, company_domain, company_name, current_period, prior_period=prior_period,
                deadline=deadline, diag=diag, source="IR Year Navigator", document_cache=document_cache
            )
            periods = {r.get("period") for r in got}
            if current_period in periods and prior_period in periods:
                pair = got
                break
        if not pair:
            sibling_candidates = _generic_sibling_release_candidates(
                records, current_period, company_domain, limit=4
            )
            if isinstance(diag, dict):
                diag.setdefault("sibling_candidate_counts", {})[current_period] = len(sibling_candidates)
            for row in sibling_candidates:
                if not _research_budget_ok(deadline, reserve=1.0):
                    break
                got = _fetch_generic_period_records_from_candidate(
                    row, company_domain, company_name, current_period, prior_period=prior_period,
                    deadline=deadline, diag=diag, source="Sibling Release Pattern", document_cache=document_cache
                )
                periods = {r.get("period") for r in got}
                if current_period in periods and prior_period in periods:
                    pair = got
                    break
        if not pair:
            if isinstance(diag, dict):
                diag.setdefault("web_fallback_periods_attempted", []).append(current_period)
            for row in _generic_search_release_candidates(company_domain, company_name, current_period, deadline=deadline, max_results=6):
                if not _research_budget_ok(deadline, reserve=0.8):
                    break
                got = _fetch_generic_period_records_from_candidate(
                    row, company_domain, company_name, current_period, prior_period=prior_period,
                    deadline=deadline, diag=diag, source="Web-Fallback", document_cache=document_cache
                )
                periods = {r.get("period") for r in got}
                if current_period in periods and prior_period in periods:
                    pair = got
                    break
        if not pair:
            break
        records.extend(pair)
    return records


@st.cache_data(ttl=21600, show_spinner=False)
def discover_generic_primary_adjusted_ttm(
    symbol,
    company_name,
    website,
    current_fy,
    cache_version="v22088",
):
    """IR-routed, bounded, fail-closed calendar-FY adjusted/core/operating TTM discovery."""
    _ = cache_version
    try:
        current_fy = int(current_fy)
    except Exception:
        return None
    today = datetime.now().date()
    domain = _extract_company_domain(website)
    diag = {
        "strategy": "IR Year Navigator → offizielle Release-Kandidaten → Current/Prior-Paar aus demselben Quartalsdokument → Web-Fallback",
        "router_available": False,
        "router_official_link_count": 0,
        "router_entrypoints": 0,
        "attempted_documents": [],
        "periods_required": [],
        "periods_found": [],
        "periods_missing": [],
        "router_candidate_counts": {},
        "sibling_candidate_counts": {},
        "web_fallback_periods_attempted": [],
        "router_budget_seconds": 7.0,
        "total_budget_seconds": 32.0,
        "status": "nicht gestartet",
        "cache_generation": str(cache_version),
    }
    if current_fy != today.year:
        diag["status"] = "Fiskalkalender nicht automatisch bestätigt"
        return {"available": False, "generic_reconstructor": True, "diagnostics": diag}
    completed = _calendar_completed_quarter_hint(today)
    if completed <= 0 or not domain:
        diag["status"] = "Keine abgeschlossene Quartalsbasis bzw. Unternehmensdomain verfügbar"
        return {"available": False, "generic_reconstructor": True, "diagnostics": diag}

    # V2.20.86: keep IR routing bounded and reserve time for exact release fallback.
    # Earlier builds passed one shared deadline into the router; on complex issuer sites
    # the router could consume nearly the whole budget before FY/Q1/Q2 fallback discovery.
    start_clock = time.monotonic()
    deadline = start_clock + 32.0
    router_deadline = min(deadline - 20.0, start_clock + 7.0)
    ir_router = _discover_company_ir_router(
        domain, company_name, target_years=[current_fy - 1], deadline=router_deadline, max_hubs=2
    )
    diag["router_elapsed_seconds"] = round(time.monotonic() - start_clock, 2)
    diag["fallback_budget_seconds_after_router"] = round(max(0.0, deadline - time.monotonic()), 2)
    diag["router_available"] = bool((ir_router or {}).get("available"))
    diag["router_official_link_count"] = int((ir_router or {}).get("official_link_count") or 0)
    diag["router_entrypoints"] = len((ir_router or {}).get("entrypoints") or [])
    diag["router_archives"] = list((ir_router or {}).get("archives") or [])[:3]
    document_cache = {}

    # V2.20.87 Latest Reported Period Completeness Guard:
    # The latest normally reported quarter is mandatory. Do not silently fall
    # back from Q2 to a Q1 bridge merely because Q1 is easier to discover.
    n = completed
    required = [f"FY {current_fy - 1}"]
    required += [f"Q{q} {current_fy - 1}" for q in range(1, n + 1)]
    required += [f"Q{q} {current_fy}" for q in range(1, n + 1)]
    diag["periods_required"] = required
    diag["latest_expected_quarter"] = n
    records = _collect_ir_routed_period_records(
        ir_router, domain, company_name, current_fy, n, deadline, diag, document_cache=document_cache
    )
    found = list(dict.fromkeys(str(r.get("period")) for r in records if r.get("period")))
    diag["periods_found"] = found
    diag["periods_missing"] = [p for p in required if p not in found]
    snapshot = reconstruct_adjusted_ttm_from_period_records(records, current_fy, n)
    if snapshot:
        diag["status"] = "Rekonstruktion erfolgreich – jüngste Berichtsperiode vollständig"
        diag["completed_quarters"] = n
        diag["documents_loaded"] = len({r.get("url") for r in records if r.get("url")})
        snapshot["valid_until"] = f"{current_fy}-12-31"
        snapshot["symbol"] = str(symbol or "").upper()
        snapshot["company_domain"] = domain
        snapshot["diagnostics"] = diag
        return snapshot

    # An older bridge may be useful for diagnostics, but never for valuation
    # substitution when a newer quarter is already expected by the reporting lag.
    partial = None
    for lower_n in range(n - 1, 0, -1):
        partial = reconstruct_adjusted_ttm_from_period_records(records, current_fy, lower_n)
        if partial:
            diag["partial_completed_quarters"] = lower_n
            diag["partial_adjusted_ttm_eps"] = safe_float(partial.get("adjusted_ttm_eps"))
            diag["partial_method"] = partial.get("method")
            break

    if partial:
        diag["status"] = "Jüngste Berichtsperiode unvollständig – ältere Teilbrücke nur Diagnose, keine Bewertungsfreigabe"
    else:
        diag["status"] = "Rekonstruktion unvollständig"
    diag["documents_loaded"] = len({
        a.get("url") for a in diag.get("attempted_documents", [])
        if a.get("url") and a.get("status") == "EPS gefunden"
    })
    return {"available": False, "generic_reconstructor": True, "company_domain": domain, "diagnostics": diag}

def _should_try_generic_adjusted_ttm(company_type, raw_ttm, current_fy_eps, website, symbol):
    if _verified_adjusted_ttm_snapshot(symbol) is not None:
        return False
    # V2.20.122 – Branded Consumer Staples has an explicit issuer-specific owner
    # path. Running the generic IR Adjusted-TTM reconstructor for Nestlé (or
    # calibrated MDLZ/PEP/KO) is both unnecessary and unsafe: the generic bridge is
    # diagnosis for ordinary companies, while this family must either use its
    # own primary-source snapshot or fail closed without substitution.
    if is_branded_consumer_staples_specialist_type(company_type, symbol):
        return False
    # V2.20.129 – Oilfield Services/Energy Technology uses issuer-primary Adjusted-EPS bridges.
    if is_oilfield_services_energy_tech_specialist_type(company_type, symbol):
        return False
    # V2.20.126 – Integrated majors use a frozen issuer-primary Through-Cycle / Structural bridge
    # Adjusted-EPS bridge; generic Adjusted-TTM reconstruction must not substitute it.
    if is_integrated_oil_gas_specialist_type(company_type, symbol):
        return False
    raw = safe_float(raw_ttm)
    fwd = safe_float(current_fy_eps)
    if raw is None or fwd is None or raw <= 0 or fwd <= 0 or not website:
        return False
    gap = abs(fwd / raw - 1.0)
    if gap < 0.25:
        return False
    name = normalized_company_type_name(company_type)
    # Existing dedicated owner-earnings models retain their own frozen paths.
    frozen_tokens = [
        "bank", "versicherung", "reit", "immobilien", "autohersteller",
        "halbleiterausrüstung", "halbleiter / fabless / ai-wachstum",
        "defense technology", "energy technology",
    ]
    return not any(token in name for token in frozen_tokens)


